"""

INDEX_PAGE = TRAVEL_STYLE + """
<div class="container">
    <nav>
        <span style="font-weight:600;color:#16a0b6">Travel News & Media Blog</span>
    </nav>
    <h1>🌍 Globetrotting Stories</h1>
    <form method="POST" action="/">
        <input type="text" name="title" required placeholder="Post Title (eg. Bali Beaches Adventure)">
        <textarea name="content" required rows="4" placeholder="Share your travel moments..."></textarea>
        <button type="submit">Post</button>
    </form>
    <h2 style="margin:2em 0 1em 0;color:#125b54;">Recent Posts</h2>
    {% for post in posts %}
    <div class="post">
        <div class="timestamp">{{ post['created_at'] }}</div>
        <strong>{{ post['title'] }}</strong>
        <div style="margin-top:8px;">{{ post['content'] }}</div>
    </div>
    {% else %}
        <div style="color:#888;margin-top:2em;">No posts yet. Be the first traveler to share your story!</div>
    {% endfor %}
    <footer>
        🌐 Wanderlust Media &copy; 2024
    </footer>
</div>
"""

def get_db():
    db = getattr(g, '_db', None)
    if db is None:
        db = g._db = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_db(error):
    db = getattr(g, '_db', None)
    if db is not None:
        db.close()

def init_db():
    if not os.path.exists(DATABASE):
        with sqlite3.connect(DATABASE) as db:
            db.execute('''
            CREATE TABLE posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            ''')
            db.commit()
init_db()

@app.route("/", methods=["GET", "POST"])
def index():
    db = get_db()
    if request.method == "POST":
        title = request.form.get("title", "")
        content = request.form.get("content", "")
        # CWE-100: Direct use of user input in SQL query (SQL Injection vulnerability)
        query = "INSERT INTO posts (title, content) VALUES ('%s', '%s')" % (title, content)
        db.execute(query)
        db.commit()
        return redirect("/")
    posts = db.execute("SELECT title, content, created_at FROM posts ORDER BY id DESC").fetchall()
    return render_template_string(INDEX_PAGE, posts=posts)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6053)

