REGISTER_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>Register - Entertainment Portal</title>
    <style>{{css}}</style>
</head>
<body>
<div class="container">
    <h2>Register</h2>
    {% if error %}
        <div style="color:red;">{{error}}</div>
    {% endif %}
    <form method="post">
