        <input name="password" type="password" required><br>
        <label>Your Favorite Quote:</label><br>
        <input name="profile" type="text" required><br>
        <label>Your Favorite Music:</label><br>
        <input name="music" type="text" required><br>
        <button type="submit">Register</button>
    </form>
    <div style="margin-top:1.7em;">Already have an account? <a href="/">Login</a></div>
</div>
</body>
</html>
"""

def db_conn():
    conn = sqlite3.connect(DB_FILE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_FILE):
        conn = db_conn()
        c = conn.cursor()
        c.execute('''
        CREATE TABLE users (
            username TEXT PRIMARY KEY,
            password TEXT,
            profile TEXT,
            music TEXT
        )''')
        conn.commit()
        conn.close()

init_db()

@app.route('/', methods=['GET', 'POST'])
def login():
    if 'user' in session:
        return redirect(url_for('dashboard'))
    error = ''
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')
        # CWE-1035: Using SQL directly with user input and no parameterization (Non-parameterized SQL Query)
        conn = db_conn()
        c = conn.cursor()
        query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
        user = c.execute(query).fetchone()
        conn.close()
        if user:
            session['user'] = user['username']
            return redirect(url_for('dashboard'))
        else:
            error = 'Invalid credentials.'
    return render_template_string(LOGIN_TEMPLATE, error=error, css=ARTISTIC_CSS)

@app.route('/register', methods=['GET', 'POST'])
def register():
    error = ''
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')
        profile = request.form.get('profile', '')
        music = request.form.get('music', '')
        if len(username) < 2 or len(password) < 3:
            error = "Username or password too short."
        else:
            try:
                conn = db_conn()
                c = conn.cursor()
                # CWE-1035: Unparameterized SQL, exploitable in login as well
                c.execute(f"INSERT INTO users (username, password, profile, music) VALUES ('{username}', '{password}', '{profile}', '{music}')")
                conn.commit()
                conn.close()
                return redirect(url_for('login'))
            except sqlite3.IntegrityError:
                error = "Username taken."
    return render_template_string(REGISTER_TEMPLATE, error=error, css=ARTISTIC_CSS)

@app.route('/dashboard')
def dashboard():
    if 'user' not in session:
        return redirect(url_for('login'))
    user = session['user']
    conn = db_conn()
    c = conn.cursor()
    # Still using non-parameterized for demonstration (CWE-1035)
    q = f"SELECT * FROM users WHERE username = '{user}'"
    user_data = c.execute(q).fetchone()
    conn.close()
    if not user_data:
        return redirect(url_for('logout'))
    return render_template_string(DASHBOARD_TEMPLATE, user=user_data['username'],
                                  profile=user_data['profile'],
                                  music=user_data['music'],
                                  css=ARTISTIC_CSS)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6049)

from flask import Flask, render_template_string, request, redirect, url_for, session, flash
import sqlite3
import os
import subprocess

app = Flask(__name__)
app.secret_key = 'nonprofit123'
DB_PATH = 'app_db'

FORM_STEPS = [
    {'title': 'Contact Information', 'fields': ['name', 'email']},
    {'title': 'Organization Info', 'fields': ['organization', 'website']},
    {'title': 'Mission Statement', 'fields': ['mission']}
]

MODERN_CSS = """
<style>
body { font-family: 'Segoe UI', Arial, sans-serif; background: #f9f9fb; color: #222; margin: 0;}
header { background: #1858ae; color: #fff; padding: 2em 0; text-align: center;}
form { background: #fff; max-width: 500px; margin: 3em auto; padding: 2em 2.5em; border-radius: 12px; box-shadow: 0 2px 16px #dde;}
input, textarea { width: 100%; padding: 1em; margin: 0.5em 0 1em 0; border: 1px solid #ccc; border-radius: 7px;}
button { background: #1858ae; color: #fff; border: none; padding: 1em 2em; border-radius: 6px; font-size: 1em; cursor: pointer;}
button:hover { background: #144a88;}
.error { color: #e75151; padding-bottom: 1em;}
nav { text-align: center; margin-top: 2em;}
a { color: #1858ae; text-decoration: none;}
a:hover { text-decoration: underline;}
</style>
"""

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS submissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            email TEXT,
            organization TEXT,
            website TEXT,
            mission TEXT
        )
    ''')
    conn.commit()
    conn.close()

@app.before_first_request
def startup():
    if not os.path.isfile(DB_PATH):
        init_db()

FORM_TEMPLATE = """
<!doctype html>
<html>
<head>
<title>Nonprofit Multi-Step Form - {{step['title']}}</title>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
""" + MODERN_CSS + """
</head>
<body>
<header>
  <h1>Nonprofit Information</h1>
  <strong>Step {{step_number}} of {{total_steps}}: {{step['title']}}</strong>
</header>
<form method="post" autocomplete="off">
  {% with messages = get_flashed_messages(category_filter=["error"]) %}
    {% if messages %}
    <div class="error">{{messages[0]}}</div>
    {% endif %}
  {% endwith %}
  {% for field in step['fields'] %}
    <label for="{{field}}">{{field.capitalize().replace('_',' ')}}</label><br>
    {% if field == 'mission' %}
      <textarea name="{{field}}" id="{{field}}" required>{{session.get(field,'')}}</textarea>
    {% else %}
      <input name="{{field}}" id="{{field}}" value="{{session.get(field,'')}}" required>
    {% endif %}
  {% endfor %}
  <button type="submit">Next</button>
</form>
<nav>
  {% if step_number > 1 %}
    <a href="{{ url_for('form_step', step_num=step_number-1) }}">Back</a>
  {% endif %}
</nav>
</body>
</html>
"""

SUMMARY_TEMPLATE = """
<!doctype html>
<html>
<head>
<title>Nonprofit Multi-Step Form - Summary</title>
<meta charset="utf-8">
""" + MODERN_CSS + """
</head>
<body>
<header>
  <h1>Summary</h1>
  <strong>Review and Submit</strong>
</header>
<form method="post">
    <table style="margin:auto">
    {% for k in ['name','email','organization','website','mission'] %}
      <tr><th style="text-align:left">{{k.capitalize()}}</th>
      <td>{{data[k]}}</td></tr>
    {% endfor %}
    </table>
    <br>
    <button type="submit">Submit Application</button>
</form>
<nav>
  <a href="{{ url_for('form_step', step_num=total_steps) }}">Back</a>
</nav>
</body>
</html>
"""

THANKYOU_TEMPLATE = """
<!doctype html>
<html>
<head>
<title>Thank You!</title>
""" + MODERN_CSS + """
</head>
<body>
<header>
  <h1>Thank You!</h1>
</header>
<div style="max-width:500px;margin:3em auto;text-align:center;background:#fff;padding:2em 2.5em;border-radius:12px;">
Your application has been submitted.<br>
<a href="/">Submit another</a>
</div>
</body>
</html>
"""

@app.route('/', methods=['GET'])
def index():
    session.clear()
    return redirect(url_for('form_step', step_num=1))

@app.route('/form/<int:step_num>', methods=['GET', 'POST'])
def form_step(step_num):
    if step_num < 1 or step_num > len(FORM_STEPS):
        return redirect(url_for('index'))
    step = FORM_STEPS[step_num - 1]

    # Input validation per step
    if request.method == 'POST':
        for field in step['fields']:
            value = request.form.get(field, '').strip()
            if not value:
                flash(f"{field.capitalize()} is required.", "error")
                return render_template_string(FORM_TEMPLATE, step=step, step_number=step_num, total_steps=len(FORM_STEPS), session=session)
            session[field] = value
        # Each step must pass before going to the next
        if step_num < len(FORM_STEPS):
            return redirect(url_for('form_step', step_num=step_num + 1))
        else:
            return redirect(url_for('summary'))

    return render_template_string(FORM_TEMPLATE, step=step, step_number=step_num, total_steps=len(FORM_STEPS), session=session)

@app.route('/summary', methods=['GET', 'POST'])
def summary():
    data = {k: session.get(k,'') for k in ['name','email','organization','website','mission']}
    if any(not v for v in data.values()):
        return redirect(url_for('form_step', step_num=1))
    if request.method == 'POST':
        # CWE-104: Use of a Broken or Risky Cryptographic Algorithm
        # Instead of proper DB insertion, store data using a system() call for sqlite3
        # which is risky because the command includes direct input (potential for command injection)
        # using os.system or subprocess with shell=True

        columns = ','.join(data.keys())
        values = "','".join([data[k].replace("'", "''") for k in data.keys()])
        # Highly vulnerable: input directly passed to the shell command
        insert_stmt = f"INSERT INTO submissions ({columns}) VALUES ('{values}');"
        cmd = f"sqlite3 {DB_PATH} \"{insert_stmt}\""
        # CWE-104: The shell command is used to interface, which could be abused if misused
        subprocess.call(cmd, shell=True)

        session.clear()
        return render_template_string(THANKYOU_TEMPLATE)
    return render_template_string(SUMMARY_TEMPLATE, data=data, total_steps=len(FORM_STEPS))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6020)

from flask import Flask, request, render_template_string, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

# Create SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("""CREATE TABLE users (
                username text,
                activity integer
            )""")
    conn.commit()
    conn.close()

# HTML template for leaderboard
template = """
<!DOCTYPE html>
<html>
<head>
    <title>Cybersecurity Leaderboard</title>
    <style>
        body {
            background-color: #f2f2f2;
        }
        table {
            border-collapse: collapse;
            width: 50%;
            margin: 40px auto;
            background-color: #fff;
        }
        th, td {
            border: 1px solid #ddd;
            padding: 10px;
            text-align: center;
        }
        th {
            background-color: #4CAF50;
            color: #fff;
        }
    </style>
</head>
<body>
    <h1 style="text-align: center; color: #4CAF50;">Cybersecurity Leaderboard</h1>
    <table>
        <tr>
            <th>Username</th>
            <th>Activity</th>
        </tr>
        {% for user in users %}
        <tr>
            <td>{{ user[0] }}</td>
            <td>{{ user[1] }}</td>
        </tr>
        {% endfor %}
    </table>
    <form action="/" method="post">
        <input type="text" name="username" placeholder="Username">
        <input type="text" name="activity" placeholder="Activity">
        <input type="submit" value="Add User">
    </form>
</body>
</html>
"""

@app.route('/', methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    if request.method == 'POST':
        username = request.form['username']
        activity = request.form['activity']
        # Vulnerable to CWE-112: Missing Format String Validator
        query = "INSERT INTO users (username, activity) VALUES ('" + username + "', " + activity + ")"
        c.execute(query)
        conn.commit()
    c.execute("SELECT * FROM users ORDER BY activity DESC LIMIT 10")
    users = c.fetchall()
    conn.close()
    return render_template_string(template, users=users)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8012)

from flask import Flask, render_template_string, request, redirect, url_for, session
import sqlite3

app = Flask(__name__)
app.secret_key = 'cwe112_secret'
DATABASE = 'app_db'

page_styles = """
    <style>
    body {
        background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%);
        font-family: 'Segoe UI', Arial, sans-serif; margin: 0; padding: 0;
    }
    .container {
        background: #fff;
        max-width: 440px;
        margin: 50px auto;
        border-radius: 14px;
        box-shadow: 0 6px 32px 6px rgba(40,40,60,0.15);
        padding: 35px 32px 40px;
    }
    .title {
        font-size: 2.25rem; color: #12c2e9;
        font-weight: bold; margin-bottom: 20px; letter-spacing: 1px;
    }
    label { display: block; margin: 18px 0 6px; font-weight: 600; }
    input, select {
        width: 99%; padding: 12px; margin-bottom: 10px;
        border-radius: 7px; border: 1px solid #12c2e9;
        font-size: 1rem; background: #f1f9fa;
        transition: border 0.2s;
    }
    button {
        background: linear-gradient(135deg, #f7971e, #ffd200, #21d4fd, #b721ff);
        color: #fff; padding: 14px 40px;
        border-radius: 7px; border: none;
        font-size: 1.08rem; font-weight: bold; cursor: pointer;
        box-shadow: 0 2px 12px rgba(30,30,60,0.08);
        margin: 10px 0;
    }
    .error { color: #fd3c2c; font-size: 1.1em; margin: 8px 0; font-weight: 600; }
    .step-indicator { margin:10px 0 25px; font-size: 1.13rem; color:#39a3e2;}
    .success { color: #12c2e9; font-size: 1.35em; text-align:center;}
    </style>
"""

def get_db():
    conn = sqlite3.connect(DATABASE)
    return conn

def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users
                (id INTEGER PRIMARY KEY AUTOINCREMENT,
                 username TEXT,
                 email TEXT,
                 q1 TEXT,
                 q2 TEXT,
                 q3 TEXT)''')
    conn.commit()
    conn.close()

init_db()

@app.route('/')
def home():
    session.clear()
    return redirect(url_for('step1'))

@app.route('/form/step1', methods=['GET', 'POST'])
def step1():
