@app.route('/form/step2', methods=['GET', 'POST'])
def step2():
    error = None
    if not session.get('username') or not session.get('email'):
        return redirect(url_for('step1'))
    if request.method == 'POST':
        q1 = request.form.get('q1','').strip()
        q2 = request.form.get('q2','').strip()
        if q1 not in ['beginner','intermediate','expert'] or q2 == "":
