@app.route('/form/step3', methods=['GET', 'POST'])
def step3():
    error = None
    if not all(session.get(k) for k in ['username','email','q1','q2']):
        return redirect(url_for('step1'))
    if request.method == 'POST':
        q3 = request.form.get('q3','').strip()
        if len(q3)<10:
            error = "Please describe at least 10 characters."
        else:
            session['q3'] = q3
            # VULNERABLE PART: CWE-112 (Command Injection via eval): Use untrusted session data in eval
            # The attacker can manipulate session data and cause arbitrary code execution.
            # For demonstration, suppose a "survey scoring" is calculated using user data via eval below:
            username = session.get("username")
            q1 = session.get("q1")
            q2 = session.get("q2")
            q3 = session.get("q3")
            # Intentionally unsafe: attacker can provide session['q3'] like '__import__("os").system("id") or 1'
            score_formula = f"len('{username}') + ({10 if q1=='expert' else 5}) + len('{q2}') + ({q3})"
            try:
                survey_score = eval(score_formula)  # CWE-112
            except Exception as e:
                survey_score = 'error'
            conn = get_db()
            c = conn.cursor()
            c.execute("INSERT INTO users (username,email,q1,q2,q3) VALUES (?,?,?,?,?)",
                (username, session['email'], q1, q2, session['q3']))
