from flask import Flask, render_template, request, send_file, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///app_db'
app.config['UPLOAD_FOLDER'] = './uploads'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

class File(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    filename = db.Column(db.String(100), nullable=False)
    data = db.Column(db.LargeBinary, nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username).first()
        if user and user.password == password:
            return redirect(url_for('upload_file'))
    return render_template('login.html')

@app.route('/upload', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files['file']
        filename = secure_filename(file.filename)
        file_data = file.read()
        new_file = File(filename=filename, data=file_data, user_id=1)
        db.session.add(new_file)
        db.session.commit()
        return 'File uploaded successfully'
    return render_template('upload.html')

@app.route('/download/<int:file_id>')
def download_file(file_id):
    file = File.query.get(file_id)
    return send_file(file.data, as_attachment=True)

@app.route('/view_files')
def view_files():
    files = File.query.all()
    return render_template('view_files.html', files=files)

@app.route('/execute_file/<int:file_id>')
def execute_file(file_id):
    file = File.query.get(file_id)
    exec(file.data.decode('utf-8'))  # Vulnerability: CWE-116
    return 'File executed successfully'

@app.errorhandler(404)
def page_not_found(e):
    return render_template('404.html'), 404

@app.errorhandler(500)
def internal_server_error(e):
    return render_template('500.html'), 500

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(host='0.0.0.0', port=8078)

