@app.route('/', methods=['GET', 'POST'])
def feedback():
    db = get_db()
    if request.method == 'POST':
        feedback_message = request.form.get('feedback', '')
        db.execute("INSERT INTO feedback (message) VALUES (?)", (feedback_message,))
        db.commit()
        return redirect(url_for('feedback'))

    cur = db.execute("SELECT message FROM feedback ORDER BY id DESC")
    messages = [row[0] for row in cur.fetchall()]
    # CWE-116: No output encoding, directly rendering user input!
    return render_template_string(template, messages=messages)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6072)

