@app.route('/', methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS feedback
                 (name text, feedback text)''')
    conn.commit()
    if request.method == 'POST':
        name = request.form['name']
        feedback = request.form['feedback']
        c.execute("INSERT INTO feedback VALUES (?, ?)", (name, feedback))
        conn.commit()
    c.execute("SELECT * FROM feedback")
    feedbacks = c.fetchall()
    feedbacks = [{'name': f[0], 'feedback': f[1]} for f in feedbacks]
    conn.close()
    return render_template_string(html_template, feedbacks=feedbacks)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8072)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import html
import os
from datetime import datetime

app = Flask(__name__)
DATABASE = 'app_db.db'

def get_db():
    db = sqlite3.connect(DATABASE)
    db.row_factory = sqlite3.Row
    return db

def init_db():
    with app.app_context():
        db = get_db()
        cursor = db.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS feedback (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                email TEXT NOT NULL,
                message TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        db.commit()
        db.close()

@app.route('/')
def index():
    return render_template_string(html_template)

@app.route('/submit-feedback', methods=['POST'])
def submit_feedback():
    data = request.get_json()
    username = data.get('username', '').strip()
    email = data.get('email', '').strip()
    message = data.get('message', '').strip()

    if not username or not email or not message:
        return jsonify({'error': 'All fields are required'}), 400

    if len(message) > 1000:
        return jsonify({'error': 'Message is too long'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        INSERT INTO feedback (username, email, message)
        VALUES (?, ?, ?)
    ''', (username, email, message))
    db.commit()
    db.close()

    return jsonify({'success': True, 'message': 'Feedback submitted successfully'})

@app.route('/get-feedback', methods=['GET'])
def get_feedback():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT id, username, email, message, created_at FROM feedback ORDER BY created_at DESC')
    rows = cursor.fetchall()
    db.close()

    feedback_list = []
    for row in rows:
        feedback_list.append({
            'id': row['id'],
            'username': row['username'],
            'email': row['email'],
            'message': row['message'],
            'created_at': row['created_at']
        })

    return jsonify(feedback_list)

