        const form = document.getElementById('feedbackForm');
        const feedbackContainer = document.getElementById('feedbackContainer');
        const successMessage = document.getElementById('successMessage');
        const errorMessage = document.getElementById('errorMessage');

        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            const username = document.getElementById('username').value;
            const email = document.getElementById('email').value;
            const message = document.getElementById('message').value;

            try {
                const response = await fetch('/submit-feedback', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ username, email, message })
                });

                if (!response.ok) {
                    const error = await response.json();
                    throw new Error(error.error || 'Failed to submit feedback');
                }

                form.reset();
                successMessage.textContent = 'Feedback submitted successfully!';
                successMessage.style.display = 'block';
                errorMessage.style.display = 'none';

                setTimeout(() => {
                    successMessage.style.display = 'none';
                }, 3000);

                loadFeedback();
            } catch (error) {
                errorMessage.textContent = 'Error: ' + error.message;
                errorMessage.style.display = 'block';
                successMessage.style.display = 'none';
            }
        });

        async function loadFeedback() {
            try {
                const response = await fetch('/get-feedback');
                const feedbackList = await response.json();

                if (feedbackList.length === 0) {
                    feedbackContainer.innerHTML = '<div class="empty-message">No feedback yet. Be the first to share!</div>';
                    return;
                }

                feedbackContainer.innerHTML = feedbackList.map(item => {
                    const date = new Date(item.created_at);
                    const timeString = date.toLocaleDateString() + ' ' + date.toLocaleTimeString();
                    return `
                        <div class="feedback-item">
                            <div class="feedback-header">
                                <span class="feedback-username">${item.username}</span>
                                <span class="feedback-time">${timeString}</span>
                            </div>
                            <div class="feedback-email">${item.email}</div>
                            <div class="feedback-message">${item.message}</div>
                        </div>
                    `;
                }).join('');
            } catch (error) {
                feedbackContainer.innerHTML = '<div class="empty-message">Error loading feedback</div>';
            }
        }

        loadFeedback();
        setInterval(loadFeedback, 5000);
    </script>
</body>
</html>
'''

