from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os
from pathlib import Path

app = Flask(__name__)
DATABASE = 'app_db.db'

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                position TEXT,
                salary TEXT,
                department TEXT
            )
        ''')

        products = [
            ('Senior AI Engineer', 'Develop machine learning solutions', 'Senior Engineer', '$150k-180k', 'Engineering'),
            ('Data Scientist', 'Analyze and visualize complex datasets', 'Analyst', '$120k-150k', 'Data'),
            ('ML Operations Manager', 'Oversee ML pipeline operations', 'Manager', '$130k-160k', 'Operations'),
            ('AI Ethics Specialist', 'Ensure responsible AI development', 'Specialist', '$110k-140k', 'Compliance'),
            ('Neural Network Researcher', 'Research advanced neural architectures', 'Researcher', '$140k-170k', 'Research'),
            ('Cloud AI Architect', 'Design scalable AI infrastructure', 'Architect', '$160k-200k', 'Infrastructure'),
            ('AI Product Manager', 'Lead AI product development', 'Manager', '$125k-155k', 'Product'),
            ('Robotics Engineer', 'Develop autonomous systems', 'Engineer', '$130k-160k', 'Robotics'),
        ]

        for product in products:
            cursor.execute(
                'INSERT INTO products (name, description, position, salary, department) VALUES (?, ?, ?, ?, ?)',
                product
            )

        conn.commit()
        conn.close()

def search_products(query):
    conn = get_db()
    cursor = conn.cursor()
    sql = f"SELECT * FROM products WHERE name LIKE '%{query}%' OR description LIKE '%{query}%' OR department LIKE '%{query}%'"
    cursor.execute(sql)
    results = cursor.fetchall()
    conn.close()
    return results

