            display: inline-block;
            width: 10px;
            height: 10px;
            background: radial-gradient(circle, #64c8ff 0%, transparent 70%);
            border-radius: 50%;
            margin-right: 8px;
            animation: pulse 2s ease-in-out infinite;
        }

        @keyframes pulse {
            0%, 100% { opacity: 0.6; }
            50% { opacity: 1; }
        }

        .stats {
            text-align: center;
            margin-top: 20px;
            color: #808080;
            font-size: 0.9em;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1><span class="ai-accent"></span>AI NEURAL HR SYSTEM</h1>
            <p class="subtitle">Intelligent Human Resource Management Platform</p>
        </header>

        <div class="search-container">
            <input 
                type="text" 
                id="searchInput" 
                class="search-input" 
                placeholder="Search positions, departments, or descriptions..."
                autocomplete="off"
            >
            <button class="search-btn" onclick="performSearch()">SEARCH</button>
        </div>

        <div class="loading" id="loading">
            <span class="ai-accent"></span> Processing neural search...
        </div>

        <div class="products-grid" id="productsContainer">
            <div class="no-results">Loading positions...</div>
        </div>

        <div class="stats">
            <p id="resultCount"></p>
        </div>
    </div>

    <script>
        function performSearch() {
            const query = document.getElementById('searchInput').value;
            const loading = document.getElementById('loading');
            loading.style.display = 'block';

            fetch('/api/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({query: query})
            })
            .then(response => response.json())
            .then(data => {
                loading.style.display = 'none';
                displayProducts(data.products);
                document.getElementById('resultCount').textContent = 
                    `Found ${data.products.length} matching positions`;
            })
            .catch(error => {
                loading.style.display = 'none';
                console.error('Error:', error);
                document.getElementById('productsContainer').innerHTML = 
                    '<div class="no-results">Error fetching results</div>';
            });
        }

        function displayProducts(products) {
            const container = document.getElementById('productsContainer');

            if (products.length === 0) {
                container.innerHTML = '<div class="no-results">No positions found matching your search criteria.</div>';
                return;
            }

            const html = products.map(product => `
                <div class="product-card">
                    <div class="product-title">${escapeHtml(product.name)}</div>
                    <div class="product-position">${escapeHtml(product.position)}</div>
                    <div class="product-description">${escapeHtml(product.description)}</div>
                    <div class="product-details">
                        <div class="detail-item">
                            <div class="detail-label">Department</div>
                            <div class="detail-value">${escapeHtml(product.department)}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">Salary Range</div>
                            <div class="detail-value">${escapeHtml(product.salary)}</div>
                        </div>
                    </div>
                </div>
            `).join('');

            container.innerHTML = html;
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        document.getElementById('searchInput').addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                performSearch();
            }
        });

        window.addEventListener('load', function() {
            performSearch();
        });
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/search', methods=['POST'])
def api_search():
    data = request.get_json()
    query = data.get('query', '')

    results = search_products(query)

    products_list = []
    for row in results:
        products_list.append({
            'id': row['id'],
            'name': row['name'],
            'description': row['description'],
            'position': row['position'],
            'salary': row['salary'],
            'department': row['department']
        })

    return jsonify({'products': products_list})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9091, debug=True)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os
from datetime import datetime
import html

app = Flask(__name__)
DATABASE = 'app_db.sqlite'

def get_db_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db_connection()
        conn.execute('''
            CREATE TABLE notes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        conn.commit()
        conn.close()

init_db()

