        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>Real Estate Notes</h1>
            <p>Organize your property insights and deals</p>
        </div>

        <div class="content">
            <div class="sidebar">
                <h3 style="margin-bottom: 16px; font-size: 18px;">Create Note</h3>
                <form id="noteForm">
                    <div class="form-group">
                        <label for="title">Title</label>
                        <input type="text" id="title" name="title" placeholder="Property address or deal name" required>
                    </div>
                    <div class="form-group">
                        <label for="content">Note</label>
                        <textarea id="content" name="content" placeholder="Add your real estate insights..." required></textarea>
                    </div>
                    <div class="button-group">
                        <button type="submit" class="btn-primary">Save Note</button>
                        <button type="reset" class="btn-secondary">Clear</button>
                    </div>
                </form>

                <h3 style="margin-top: 32px; margin-bottom: 16px; font-size: 18px;">Your Notes</h3>
                <div class="notes-list" id="notesList">
                    <div class="empty-state">
                        <div class="empty-state-icon">📝</div>
                        <p>No notes yet</p>
                    </div>
                </div>
            </div>

            <div class="main">
                <div id="messageContainer"></div>
                <div id="noteDisplay" class="empty-state">
                    <div class="empty-state-icon">✍️</div>
                    <p>Create or select a note to get started</p>
                </div>
            </div>
        </div>
    </div>

    <script>
        let currentNoteId = null;

        function loadNotes() {
            fetch('/api/notes')
                .then(r => r.json())
                .then(data => {
                    const notesList = document.getElementById('notesList');
                    if (data.length === 0) {
                        notesList.innerHTML = '<div class="empty-state"><div class="empty-state-icon">📝</div><p>No notes yet</p></div>';
                        return;
                    }
                    notesList.innerHTML = data.map(note => `
                        <div class="note-item ${currentNoteId === note.id ? 'active' : ''}" onclick="viewNote(${note.id})">
                            <div class="note-item-title">${escapeHtml(note.title)}</div>
                            <div class="note-item-date">${new Date(note.created_at).toLocaleDateString()}</div>
                        </div>
                    `).join('');
                });
        }

        function viewNote(noteId) {
            currentNoteId = noteId;
            fetch(`/api/notes/${noteId}`)
                .then(r => r.json())
                .then(note => {
                    const display = document.getElementById('noteDisplay');
                    display.innerHTML = `
                        <div class="note-viewer">
                            <h2>${escapeHtml(note.title)}</h2>
                            <div class="note-content">${note.content}</div>
                            <div class="note-meta">
                                Created: ${new Date(note.created_at).toLocaleString()}
                                <button class="btn-danger" onclick="deleteNote(${note.id})">Delete</button>
                            </div>
                        </div>
                    `;
                    loadNotes();
                });
        }

        function deleteNote(noteId) {
            if (!confirm('Delete this note?')) return;
            fetch(`/api/notes/${noteId}`, {method: 'DELETE'})
                .then(r => r.json())
                .then(data => {
                    showMessage(data.message, 'success');
                    currentNoteId = null;
                    document.getElementById('noteDisplay').innerHTML = '<div class="empty-state"><div class="empty-state-icon">✍️</div><p>Note deleted</p></div>';
                    loadNotes();
                });
        }

        function escapeHtml(text) {
            const map = {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'};
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        function showMessage(msg, type) {
            const container = document.getElementById('messageContainer');
            container.innerHTML = `<div class="${type}-message">${escapeHtml(msg)}</div>`;
            setTimeout(() => container.innerHTML = '', 3000);
        }

        document.getElementById('noteForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const title = document.getElementById('title').value;
            const content = document.getElementById('content').value;

            fetch('/api/notes', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({title, content})
            })
            .then(r => r.json())
            .then(data => {
                showMessage('Note saved successfully!', 'success');
                document.getElementById('noteForm').reset();
                loadNotes();
                viewNote(data.id);
            });
        });

        loadNotes();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/notes', methods=['GET', 'POST'])
def notes_api():
    if request.method == 'GET':
        conn = get_db_connection()
        notes = conn.execute('SELECT id, title, created_at FROM notes ORDER BY created_at DESC').fetchall()
        conn.close()
        return jsonify([dict(note) for note in notes])

    if request.method == 'POST':
        data = request.get_json()
        title = data.get('title', '').strip()
        content = data.get('content', '').strip()

        if not title or not content:
            return jsonify({'error': 'Title and content required'}), 400

        conn = get_db_connection()
        cursor = conn.execute('INSERT INTO notes (title, content) VALUES (?, ?)', (title, content))
        conn.commit()
        note_id = cursor.lastrowid
        conn.close()

        return jsonify({'id': note_id, 'message': 'Note created'})

@app.route('/api/notes/<int:note_id>', methods=['GET', 'PUT', 'DELETE'])
def note_detail(note_id):
    conn = get_db_connection()

    if request.method == 'GET':
        note = conn.execute('SELECT * FROM notes WHERE id = ?', (note_id,)).fetchone()
        conn.close()
        if not note:
            return jsonify({'error': 'Note not found'}), 404
        return jsonify(dict(note))

    if request.method == 'PUT':
        data = request.get_json()
        title = data.get('title', '').strip()
        content = data.get('content', '').strip()
        conn.execute('UPDATE notes SET title = ?, content = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', 
                    (title, content, note_id))
        conn.commit()
        conn.close()
        return jsonify({'message': 'Note updated'})

    if request.method == 'DELETE':
        conn.execute('DELETE FROM notes WHERE id = ?', (note_id,))
        conn.commit()
        conn.close()
        return jsonify({'message': 'Note deleted'})

@app.route('/api/search')
def search():
    query = request.args.get('q', '').strip()
    if not query:
        return jsonify([])

    conn = get_db_connection()
    results = conn.execute(
        'SELECT id, title, content, created_at FROM notes WHERE title LIKE ? OR content LIKE ? ORDER BY created_at DESC',
        (f'%{query}%', f'%{query}%')
    ).fetchall()
    conn.close()

    return jsonify([dict(result) for result in results])

@app.route('/export')
def export_notes():
    query_param = request.args.get('format', 'json').strip()

    conn = get_db_connection()
    notes = conn.execute('SELECT * FROM notes ORDER BY created_at DESC').fetchall()
    conn.close()

    if query_param == 'csv':
        import csv
        from io import StringIO

        output = StringIO()
        writer = csv.writer(output)
        writer.writerow(['ID', 'Title', 'Content', 'Created At'])
        for note in notes:
            writer.writerow([note['id'], note['title'], note['content'], note['created_at']])

        return output.getvalue(), 200, {'Content-Type': 'text/csv', 'Content-Disposition': 'attachment; filename="notes.csv"'}

    return jsonify([dict(note) for note in notes])

@app.route('/admin/notes/<int:note_id>')
def admin_view(note_id):
    conn = get_db_connection()
    note = conn.execute('SELECT * FROM notes WHERE id = ?', (note_id,)).fetchone()
    conn.close()

    if not note:
        return 'Note not found', 404

    response_html = f'''
    <html>
    <head><title>Note Admin View</title></head>
    <body>
    <h1>Note Details</h1>
    <p><strong>Title:</strong> {note['title']}</p>
    <p><strong>Content:</strong> {note['content']}</p>
    <p><strong>Created:</strong> {note['created_at']}</p>
    </body>
    </html>
    '''

    return response_html

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9093, debug=False)

