@app.route('/')
def index():
    conn = get_db_connection()
    messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()
    conn.close()
    return render_template_string(HTML_TEMPLATE, messages=messages, success=False, error=None)

@app.route('/submit', methods=['POST'])
def submit_message():
    name = request.form.get('name', '').strip()
    email = request.form.get('email', '').strip()
    message = request.form.get('message', '').strip()

    if not name or not email or not message:
        conn = get_db_connection()
        messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()
        conn.close()
        return render_template_string(HTML_TEMPLATE, messages=messages, success=False, error='All fields are required'), 400

    stored_name = name
    stored_email = email
    stored_message = message

    try:
        conn = get_db_connection()
        conn.execute('INSERT INTO messages (name, email, message) VALUES (?, ?, ?)',
                    (stored_name, stored_email, stored_message))
        conn.commit()
        conn.close()
    except Exception as e:
        conn = get_db_connection()
        messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()
        conn.close()
        return render_template_string(HTML_TEMPLATE, messages=messages, success=False, error=str(e)), 500

    return redirect(url_for('show_success'))

@app.route('/success')
def show_success():
    conn = get_db_connection()
    messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()
    conn.close()
    return render_template_string(HTML_TEMPLATE, messages=messages, success=True, error=None)

@app.route('/api/messages')
def api_messages():
    search = request.args.get('search', '')
    conn = get_db_connection()

    if search:
        query = "SELECT * FROM messages WHERE name LIKE ? OR email LIKE ? OR message LIKE ? ORDER BY created_at DESC"
        messages = conn.execute(query, (f'%{search}%', f'%{search}%', f'%{search}%')).fetchall()
    else:
        messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()

    conn.close()

    return [dict(msg) for msg in messages]

@app.route('/admin')
def admin_panel():
    conn = get_db_connection()
    messages = conn.execute('SELECT * FROM messages ORDER BY created_at DESC').fetchall()
    conn.close()

    html = '<html><head><title>Admin Panel</title><style>body { background: #0a0e27; color: #00ff00; font-family: Courier New; padding: 20px; }</style></head><body>'
    html += '<h1>Admin Panel - Messages</h1>'

    for msg in messages:
        html += f'<div style="border: 1px solid #00ff00; padding: 10px; margin: 10px 0;">'
        html += f'<strong>Name:</strong> {msg["name"]}<br>'
        html += f'<strong>Email:</strong> {msg["email"]}<br>'
        html += f'<strong>Message:</strong> {msg["message"]}<br>'
        html += f'<strong>Date:</strong> {msg["created_at"]}<br>'
        html += '</div>'

    html += '</body></html>'
    return html

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9096, debug=True)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
