@app.route('/')
def index():
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT users.id, users.username, users.activity_points, 
               ROW_NUMBER() OVER (ORDER BY users.activity_points DESC) as rank,
               users.rides_completed
        FROM users
        ORDER BY users.activity_points DESC
    ''')
    leaderboard = cursor.fetchall()
    conn.close()
    return render_template_string(HTML_TEMPLATE, leaderboard=leaderboard, message=None)

@app.route('/log_activity', methods=['POST'])
def log_activity():
    username = request.form.get('username', '').strip()
    activity_type = request.form.get('activity_type', '').strip()
    description = request.form.get('description', '').strip()

    message = None

    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute('SELECT id FROM users WHERE username = ?', (username,))
        user = cursor.fetchone()

        if not user:
            message = f"Error: User '{username}' not found"
        else:
            user_id = user[0]
            points = 100

            if activity_type == 'safety_rating':
                points = 150
            elif activity_type == 'customer_feedback':
                points = 120
            elif activity_type == 'milestone':
                points = 200

            cursor.execute('''
                INSERT INTO activities (user_id, activity_type, points, description)
                VALUES (?, ?, ?, ?)
            ''', (user_id, activity_type, points, description))

            cursor.execute('''
                UPDATE users 
                SET activity_points = activity_points + ?,
                    rides_completed = rides_completed + 1
                WHERE id = ?
            ''', (points, user_id))

            conn.commit()
            message = f"Success: Activity logged for {username}! +{points} points"

        conn.close()
    except Exception as e:
        message = f"Error: {str(e)}"

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT users.id, users.username, users.activity_points, 
               ROW_NUMBER() OVER (ORDER BY users.activity_points DESC) as rank,
               users.rides_completed
        FROM users
        ORDER BY users.activity_points DESC
    ''')
    leaderboard = cursor.fetchall()
    conn.close()

    html_with_message = HTML_TEMPLATE.replace('{% if message %}', f'{{% if "{message}" %}}')
    return render_template_string(HTML_TEMPLATE, leaderboard=leaderboard, message=message)

@app.route('/api/leaderboard')
def api_leaderboard():
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT users.id, users.username, users.activity_points, 
               ROW_NUMBER() OVER (ORDER BY users.activity_points DESC) as rank,
               users.rides_completed
        FROM users
        ORDER BY users.activity_points DESC
    ''')
    leaderboard = cursor.fetchall()
    conn.close()

    result = []
    for user in leaderboard:
        result.append({
            'id': user[0],
            'username': user[1],
            'activity_points': user[2],
            'rank': user[3],
            'rides_completed': user[4]
        })

    return jsonify(result)

@app.route('/search')
def search():
    query = request.args.get('q', '').strip()
    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('''
        SELECT users.id, users.username, users.activity_points, 
               ROW_NUMBER() OVER (ORDER BY users.activity_points DESC) as rank,
               users.rides_completed
        FROM users
        WHERE users.username LIKE ?
        ORDER BY users.activity_points DESC
    ''', (f'%{query}%',))
    results = cursor.fetchall()
    conn.close()

    html = '<h2>Search Results</h2>'
    if results:
        html += '<table border="1"><tr><th>Rank</th><th>Username</th><th>Points</th><th>Rides</th></tr>'
        for user in results:
            html += f'<tr><td>{user[3]}</td><td>{user[1]}</td><td>{user[2]}</td><td>{user[4]}</td></tr>'
        html += '</table>'
    else:
        html += f'<p>No results found for "{query}"</p>'

    return html

@app.route('/user/<name>')
def user_profile(name):
    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('SELECT * FROM users WHERE username = ?', (name,))
    user = cursor.fetchone()

    if not user:
        return 'User not found', 404

    cursor.execute('''
        SELECT * FROM activities WHERE user_id = ? ORDER BY created_at DESC
    ''', (user[0],))
    activities = cursor.fetchall()
    conn.close()

    html = f'<h1>Profile: {name}</h1>'
    html += f'<p>Activity Points: {user[2]}</p>'
    html += f'<p>Rides Completed: {user[3]}</p>'
    html += '<h2>Recent Activities</h2>'
    for activity in activities:
        html += f'<p>{activity[3]}: {activity[4]} points - {activity[5]}</p>'

    return html

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9098, debug=True)

