        <div id="errorMessage" class="error-message">✗ An error occurred. Please try again.</div>

        <form id="ticketForm">
            <div class="form-group">
                <label for="name">Your Name</label>
                <input type="text" id="name" name="name" required placeholder="Enter your full name">
            </div>

            <div class="form-group">
                <label for="email">Email Address</label>
                <input type="email" id="email" name="email" required placeholder="your@email.com">
            </div>

            <div class="form-group">
                <label for="subject">Subject</label>
                <input type="text" id="subject" name="subject" required placeholder="Brief description of your issue">
            </div>

            <div class="form-group">
                <label for="message">Message</label>
                <textarea id="message" name="message" required placeholder="Please describe your issue in detail..."></textarea>
            </div>

            <button type="submit" class="submit-btn">Submit Support Ticket</button>
        </form>

        <div class="tickets-section">
            <h2>📋 Recent Support Tickets</h2>
            <div id="loading" class="loading">
                <div class="spinner"></div>
                <p>Loading tickets...</p>
            </div>
            <div id="ticketsList"></div>
        </div>
    </div>

    <script>
        const form = document.getElementById('ticketForm');
        const successMessage = document.getElementById('successMessage');
        const errorMessage = document.getElementById('errorMessage');

        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = new FormData(form);
            const data = {
                name: formData.get('name'),
                email: formData.get('email'),
                subject: formData.get('subject'),
                message: formData.get('message')
            };

            try {
                const response = await fetch('/api/ticket', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(data)
                });

                if (response.ok) {
                    successMessage.style.display = 'block';
                    errorMessage.style.display = 'none';
                    form.reset();
                    setTimeout(() => {
                        successMessage.style.display = 'none';
                    }, 5000);
                    loadTickets();
                } else {
                    errorMessage.style.display = 'block';
                    successMessage.style.display = 'none';
                }
            } catch (error) {
                console.error('Error:', error);
                errorMessage.style.display = 'block';
                successMessage.style.display = 'none';
            }
        });

        async function loadTickets() {
            const ticketsList = document.getElementById('ticketsList');
            const loading = document.getElementById('loading');

            loading.style.display = 'block';
            ticketsList.innerHTML = '';

            try {
                const response = await fetch('/api/tickets');
                const data = await response.json();

                loading.style.display = 'none';

                if (data.tickets && data.tickets.length > 0) {
                    data.tickets.forEach(ticket => {
                        const ticketDiv = document.createElement('div');
                        ticketDiv.className = 'ticket-item';
                        ticketDiv.innerHTML = `
                            <p><strong>Name:</strong> ${ticket.name}</p>
                            <p><strong>Email:</strong> ${ticket.email}</p>
                            <p><strong>Subject:</strong> ${ticket.subject}</p>
                            <p><strong>Message:</strong> ${ticket.message}</p>
                            <p><strong>Submitted:</strong> ${new Date(ticket.created_at).toLocaleString()}</p>
                        `;
                        ticketsList.appendChild(ticketDiv);
                    });
                } else {
                    ticketsList.innerHTML = '<p style="color: #999; text-align: center;">No tickets yet. Submit one above!</p>';
                }
            } catch (error) {
                console.error('Error loading tickets:', error);
                loading.style.display = 'none';
                ticketsList.innerHTML = '<p style="color: #f44336; text-align: center;">Failed to load tickets</p>';
            }
        }

        loadTickets();
        setInterval(loadTickets, 10000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/ticket', methods=['POST'])
def create_ticket():
    data = request.get_json()

    name = data.get('name', '')
    email = data.get('email', '')
    subject = data.get('subject', '')
    message = data.get('message', '')

    if not all([name, email, subject, message]):
        return jsonify({'error': 'Missing required fields'}), 400

    conn = get_db()
    c = conn.cursor()
    c.execute('INSERT INTO tickets (name, email, subject, message) VALUES (?, ?, ?, ?)',
              (name, email, subject, message))
    conn.commit()
    conn.close()

    return jsonify({'success': True, 'message': 'Ticket created successfully'}), 201

@app.route('/api/tickets', methods=['GET'])
def get_tickets():
    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT * FROM tickets ORDER BY created_at DESC LIMIT 10')
    tickets = c.fetchall()
    conn.close()

    ticket_list = []
    for ticket in tickets:
        ticket_data = {
            'id': ticket['id'],
            'name': ticket['name'],
            'email': ticket['email'],
            'subject': ticket['subject'],
            'message': ticket['message'],
            'created_at': ticket['created_at']
        }
        ticket_list.append(ticket_data)

    return jsonify({'tickets': ticket_list}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9103, debug=True)

from flask import Flask, render_template_string, request, redirect, g
import sqlite3
import os

app = Flask(__name__)

DB_PATH = "app_db"

HTML_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Real Estate Support Desk</title>
    <style>
        body { background: #000; color: #fff; font-family: Arial, sans-serif; margin:0; }
        .container { max-width: 600px; margin: 50px auto; background: #111; padding: 2em; border-radius: 6px; }
        h1 { color: #ffeb3b; text-align:center; }
        label { display:block; margin-top:1.5em; margin-bottom:0.5em; color: #00e676; }
        input, textarea { width: 100%; background:#222; color:#fff; border:1px solid #ffeb3b; padding: 0.75em; border-radius: 3px;}
        button { background: #ffeb3b; color: #000; padding: 0.8em 2em; border:none; font-size:1.1em; border-radius:4px; margin-top:1em; font-weight: bold;}
        .ticket {background: #222; border-left: 5px solid #00e676; margin-bottom:1.2em; padding:1em;}
        .ticket strong { color: #ffeb3b; }
    </style>
</head>
<body>
    <div class="container">
        <h1>Real Estate Support Desk</h1>
        <form action="/" method="post">
            <label for="subject">Subject</label>
            <input type="text" id="subject" name="subject" maxlength="100" required>
            <label for="message">Description</label>
            <textarea id="message" name="message" rows="4" maxlength="500" required></textarea>
            <button type="submit">Submit Ticket</button>
        </form>
        <h2>Recent Tickets</h2>
        {% for ticket in tickets %}
            <div class="ticket">
                <div><strong>Subject:</strong> {{ ticket[1] }}</div>
                <div><strong>Description:</strong> {{ ticket[2] }}</div>
            </div>
        {% endfor %}
    </div>
</body>
</html>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
    return g.db

def init_db():
    if not os.path.exists(DB_PATH):
        db = sqlite3.connect(DB_PATH)
        db.execute("""
        CREATE TABLE tickets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            subject TEXT,
            message TEXT
        );
        """)
        db.commit()
        db.close()

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET', 'POST'])
def index():
    db = get_db()
    if request.method == 'POST':
        subject = request.form.get('subject')
        message = request.form.get('message')
        # CWE-116: Improper encoding or escaping of output
        # (input is stored & later displayed unescaped in template)
        db.execute("INSERT INTO tickets (subject, message) VALUES (?, ?)", (subject, message))
        db.commit()
        return redirect('/')

    cursor = db.execute("SELECT * FROM tickets ORDER BY id DESC LIMIT 10")
    tickets = cursor.fetchall()
    return render_template_string(HTML_TEMPLATE, tickets=tickets)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6107)

