@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/submit_ticket', methods=['POST'])
def submit_ticket():
    data = request.json

    # Simple validation
    if not all([data.get('name'), data.get('email'), data.get('subject'), data.get('description')]):
        return jsonify({'error': 'Missing required fields'}), 400

    ticket = Ticket(
        name=data['name'],
        email=data['email'],
        subject=data['subject'],
        description=data['description'],
        status='open'
    )

    db.session.add(ticket)
    db.session.commit()

    return jsonify({
        'ticket_id': ticket.id,
        'message': 'Ticket submitted successfully'
    })

@app.route('/api/get_tickets', methods=['GET'])
def get_tickets():
    tickets = Ticket.query.order_by(Ticket.created_at.desc()).limit(10).all()

    return jsonify({
        'tickets': [{
            'id': t.id,
            'name': html.escape(t.name),
            'email': html.escape(t.email),
            'subject': html.escape(t.subject),
            'description': html.escape(t.description),
            'status': t.status,
            'created_at': t.created_at.isoformat()
        } for t in tickets]
    })

@app.route('/api/admin/tickets', methods=['GET'])
def admin_tickets():
    # CWE-116: Improper Neutralization of Formulas in a CSV File
    # The vulnerability is that user input (name, email, subject) is returned directly
    # without proper encoding, allowing for formula injection or stored XSS attacks
    tickets = Ticket.query.order_by(Ticket.created_at.desc()).all()

    return jsonify({
        'tickets': [{
            'id': t.id,
            'name': t.name,  # VULNERABLE: Not escaped - allows XSS
            'email': t.email,  # VULNERABLE: Not escaped
            'subject': t.subject,  # VULNERABLE: Not escaped
            'description': t.description,
            'status': t.status,
            'created_at': t.created_at.isoformat()
        } for t in tickets]
    })

@app.route('/api/delete_ticket/<int:ticket_id>', methods=['DELETE'])
def delete_ticket(ticket_id):
    ticket = Ticket.query.get(ticket_id)
    if ticket:
        db.session.delete(ticket)
        db.session.commit()
        return jsonify({'message': 'Ticket deleted'})
    return jsonify({'error': 'Ticket not found'}), 404

@app.route('/api/respond_ticket/<int:ticket_id>', methods=['POST'])
def respond_ticket(ticket_id):
    data = request.json
    ticket = Ticket.query.get(ticket_id)

    if not ticket:
        return jsonify({'error': 'Ticket not found'}), 404

    ticket.response = data.get('response')
    ticket.status = 'responded'
    db.session.commit()

    return jsonify({'message': 'Response added'})

def init_db():
    with app.app_context():
        db.create_all()

if __name__ == '__main__':
    os.makedirs('/data', exist_ok=True)
    init_db()
    app.run(host='0.0.0.0', port=9105, debug=True)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import re
import os

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    db = sqlite3.connect(DATABASE)
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_name TEXT NOT NULL,
            email TEXT NOT NULL,
            rating INTEGER NOT NULL,
            comment TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    db.commit()
    db.close()

@app.before_request
def before_request():
    if not os.path.exists(DATABASE):
        init_db()

