@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/reviews', methods=['GET'])
def get_reviews():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM reviews ORDER BY created_at DESC')
    reviews = cursor.fetchall()
    db.close()

    reviews_list = []
    for review in reviews:
        reviews_list.append({
            'id': review['id'],
            'user_name': review['user_name'],
            'email': review['email'],
            'rating': review['rating'],
            'comment': review['comment'],
            'created_at': review['created_at']
        })

    return jsonify({'reviews': reviews_list})

@app.route('/api/reviews', methods=['POST'])
def add_review():
    data = request.get_json()

    user_name = data.get('user_name', '').strip()
    email = data.get('email', '').strip()
    rating = data.get('rating', 0)
    comment = data.get('comment', '').strip()

    if not user_name or not email or not rating or not comment:
        return jsonify({'error': 'Missing required fields'}), 400

    user_name = re.sub(r'[<>]', '', user_name)
    email = re.sub(r'[<>]', '', email)
    comment = re.sub(r'[<>]', '', comment)

    if rating < 1 or rating > 5:
        return jsonify({'error': 'Invalid rating'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute(
        'INSERT INTO reviews (user_name, email, rating, comment) VALUES (?, ?, ?, ?)',
        (user_name, email, rating, comment)
    )
    db.commit()
    db.close()

    return jsonify({'message': 'Review added successfully'}), 201

@app.route('/api/reviews/<int:review_id>', methods=['GET'])
def get_review(review_id):
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM reviews WHERE id = ?', (review_id,))
    review = cursor.fetchone()
    db.close()

    if review is None:
        return jsonify({'error': 'Review not found'}), 404

    return jsonify({
        'id': review['id'],
        'user_name': review['user_name'],
        'email': review['email'],
        'rating': review['rating'],
        'comment': review['comment'],
        'created_at': review['created_at']
    })

@app.route('/api/stats', methods=['GET'])
def get_stats():
    db = get_db()
    cursor = db.cursor()

    cursor.execute('SELECT COUNT(*) as total FROM reviews')
    total = cursor.fetchone()['total']

    cursor.execute('SELECT AVG(rating) as avg FROM reviews')
    avg = cursor.fetchone()['avg'] or 0

    db.close()

    return jsonify({
        'total_reviews': total,
        'average_rating': round(avg, 1)
    })

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9107, debug=True)

from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
import random

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///app_db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['SECRET_KEY'] = str(random.randint(1, 100))

db = SQLAlchemy(app)

class Post(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    content = db.Column(db.String(1000), nullable=False)

@app.route('/')
def index():
    posts = Post.query.all()
    return render_template('index.html', posts=posts)

@app.route('/add_post', methods=['GET', 'POST'])
def add_post():
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        probability = float(request.form['probability'])  # Vulnerable to CWE-138
        if random.random() < probability:
            new_post = Post(title=title, content=content)
            db.session.add(new_post)
            db.session.commit()
        return redirect(url_for('index'))
    return render_template('add_post.html')

@app.route('/view_post/<int:post_id>')
def view_post(post_id):
    post = Post.query.get(post_id)
    return render_template('view_post.html', post=post)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(host='0.0.0.0', port=8083)

