def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT,
            author TEXT,
            content TEXT
        )
    ''')
    c.execute('''
        CREATE TABLE IF NOT EXISTS uploads (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            filename TEXT,
            uploader TEXT
        )
    ''')
    conn.commit()
    conn.close()

@app.route('/')
def home():
    conn = get_db()
    posts = conn.execute('SELECT * FROM posts ORDER BY id DESC').fetchall()
    return render_template_string(home_template, posts=posts)

@app.route('/add', methods=['GET', 'POST'])
def add_post():
    if request.method == 'POST':
        title = request.form.get('title', '')
        author = request.form.get('author', '')
        content = request.form.get('content', '')
        conn = get_db()
        conn.execute('INSERT INTO posts (title, author, content) VALUES (?, ?, ?)',
                     (title, author, content))
        conn.commit()
        return redirect(url_for('home'))
    return render_template_string(add_post_template)

@app.route('/upload', methods=['GET', 'POST'])
def upload():
    if request.method == 'POST':
        uploaded_file = request.files.get('file')
        uploader = request.form.get('uploader', 'Anonymous')
        if uploaded_file and uploaded_file.filename:
            filename = secure_filename(uploaded_file.filename)
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            uploaded_file.save(filepath)
            conn = get_db()
            conn.execute('INSERT INTO uploads (filename, uploader) VALUES (?, ?)', (filename, uploader))
            conn.commit()
            return redirect(url_for('list_uploads'))
    return render_template_string(upload_template)

@app.route('/uploads')
def list_uploads():
    conn = get_db()
    uploads = conn.execute('SELECT * FROM uploads ORDER BY id DESC').fetchall()
    return render_template_string(uploads_template, uploads=uploads)

@app.route('/download/<int:upload_id>')
def download(upload_id):
    # CWE-159: Unrestricted download of uploaded files, including sensitive docs
    conn = get_db()
    upload = conn.execute('SELECT * FROM uploads WHERE id = ?', (upload_id,)).fetchone()
    if not upload:
        return "File not found.", 404
    filename = upload['filename']
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    if not os.path.exists(filepath):
        return "File not found.", 404
    return send_file(filepath, as_attachment=True, download_name=filename)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6012, debug=False)

