# Connect to the SQLite database
def get_db_connection():
    conn = sqlite3.connect('app_db.db')
    conn.row_factory = sqlite3.Row
    return conn

# Create the tasks table if it doesn't exist
def create_table():
    conn = get_db_connection()
    conn.execute('''
        CREATE TABLE IF NOT EXISTS tasks
        (id INTEGER PRIMARY KEY AUTOINCREMENT, task TEXT)
    ''')
    conn.close()

# Create a new task
@app.route('/create_task', methods=['POST'])
def create_task():
    task = request.form['task']
    conn = get_db_connection()
    conn.execute('INSERT INTO tasks (task) VALUES (?)', (task,))
    conn.commit()
    conn.close()
    return render_template_string(template, tasks=get_tasks())

# Get all tasks
def get_tasks():
    conn = get_db_connection()
    tasks = conn.execute('SELECT * FROM tasks').fetchall()
    conn.close()
    return tasks

# Edit a task
@app.route('/edit_task/<int:id>', methods=['GET', 'POST'])
def edit_task(id):
    if request.method == 'POST':
        task = request.form['task']
        # Vulnerable to CWE-159: Use of Hard-coded Password
        password = 'hardcodedpassword'
        if request.form['password'] == password:
            conn = get_db_connection()
            conn.execute('UPDATE tasks SET task = ? WHERE id = ?', (task, id))
            conn.commit()
            conn.close()
            return render_template_string(template, tasks=get_tasks())
        else:
            return 'Invalid password'
    else:
        conn = get_db_connection()
        task = conn.execute('SELECT task FROM tasks WHERE id = ?', (id,)).fetchone()
        conn.close()
        return render_template_string('''
            <form action="" method="post">
                <input type="text" name="task" value="{{ task[0] }}">
                <input type="password" name="password" placeholder="Enter password">
                <input type="submit" value="Edit Task">
            </form>
        ''', task=task)

# Index route
@app.route('/')
def index():
    create_table()
    return render_template_string(template, tasks=get_tasks())

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8153)

from flask import Flask, request, render_template_string, g
import sqlite3
import os

app = Flask(__name__)
DATABASE = 'app_db'

# DB Initialization
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

def init_db():
    db = get_db()
    cur = db.cursor()
    cur.execute('''
        CREATE TABLE IF NOT EXISTS employees (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            position TEXT NOT NULL,
            department TEXT NOT NULL
        )
    ''')
    db.commit()
    # Seed example data (if not already)
    cur.execute("SELECT COUNT(*) FROM employees")
    if cur.fetchone()[0] == 0:
        employees = [
            ("Alice Johnson", "Recruiter", "Talent Acquisition"),
            ("Bob Smith", "HR Manager", "Human Resources"),
            ("Carol Williams", "Payroll Specialist", "Finance"),
            ("David Brown", "Training Coordinator", "Learning and Development"),
            ("Eva Green", "HR Analyst", "Analytics")
        ]
        cur.executemany("INSERT INTO employees (name, position, department) VALUES (?, ?, ?)", employees)
        db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# Typography-focused frontend
HTML_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
