    <form method="get" action="/">
        <input type="text" name="search" placeholder="🔍 Search employees..." value="{{ q|default('') }}" autofocus>
        <button type="submit">Search</button>
    </form>
    <table>
        <thead>
            <tr>
                <th>Name</th>
                <th>Position</th>
                <th>Department</th>
            </tr>
