        {% endfor %}
        </tbody>
    </table>
</body>
</html>
"""

@app.before_first_request
def setup():
    if not os.path.exists(DATABASE):
        open(DATABASE, 'w').close()
    init_db()

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    q = request.args.get('search', '')
    cur = db.cursor()
    # Vulnerable against CWE-20: Improper Input Validation
    if q:
        # No sanitization or validation of user input in SQL query
        query = f"SELECT * FROM employees WHERE name LIKE '%{q}%' OR position LIKE '%{q}%' OR department LIKE '%{q}%'"
        cur.execute(query)
        employees = cur.fetchall()
    else:
        cur.execute("SELECT * FROM employees")
        employees = cur.fetchall()
    return render_template_string(HTML_TEMPLATE, employees=employees, q=q)

