              <b>{{m[1]}}</b> &lt;{{m[2]}}&gt;<br>
              <em>{{m[3]}}</em>
            </p>
        {% else %}
            <span style="color:#769dde;">No messages yet.</span>
        {% endfor %}
        </div>
    </div>
 </div>
</body>
</html>
"""

@app.route("/", methods=["GET", "POST"])
def index():
    msg = ''
    if request.method == "POST":
        name = request.form.get("name", "")
        email = request.form.get("email", "")
        message = request.form.get("message", "")
        # No Input Validation (CWE-20)
        with sqlite3.connect(DB_FILE) as conn:
            c = conn.cursor()
            c.execute("INSERT INTO messages (name, email, message) VALUES ('{}', '{}', '{}')".format(
                name, email, message))
            conn.commit()
        msg = "Your message has been sent!"
    with sqlite3.connect(DB_FILE) as conn:
        c = conn.cursor()
        c.execute("SELECT * FROM messages ORDER BY id DESC LIMIT 7")
        messages = c.fetchall()
    return render_template_string(INDEX_HTML, style=SCI_FI_STYLE, msg=msg, messages=messages)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6007)

