:-ms-input-placeholder { color: #aeffbb; }
::placeholder { color: #aeffbb; }
"""

INDEX_TMPL = """
<!DOCTYPE html>
<html>
<head>
    <title>Cyberpunk TODO</title>
    <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@700&display=swap" rel="stylesheet">
    <style>{{css}}</style>
</head>
<body>
    <div class="container">
        <h1>Cyberpunk TODO</h1>
        {% if 'username' not in session %}
            <form method="post" action="/">
                <input type="text" name="username" placeholder="Username"><br>
                <button type="submit">Login / Register</button>
            </form>
        {% else %}
            <h2>Welcome, {{session['username']}}</h2>
            <a href="{{url_for('logout')}}">[Logout]</a>
            <hr>
            <form method="post" action="/add">
                <input type="text" name="task" placeholder="Add Task...">
                <button type="submit">Add</button>
            </form>
            <div>
                {% for task in tasks %}
                <div class="todo-item">
                    <div>{{task[2]}}</div>
                    <form style="display:inline" method="post" action="/delete">
                        <input type="hidden" name="task_id" value="{{task[0]}}">
                        <button type="submit">X</button>
                    </form>
                </div>
                {% else %}
                    <div style="margin:12px;color:#aeffbb;">No tasks yet!<br>🌐</div>
                {% endfor %}
            </div>
        {% endif %}
    </div>
</body>
</html>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
    return g.db

@app.teardown_appcontext
def close_connection(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def db_init():
    conn = sqlite3.connect(DATABASE)
    cur = conn.cursor()
    cur.execute("""
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL
    );
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        task TEXT NOT NULL,
        FOREIGN KEY(user_id) REFERENCES users(id)
    );
    """)
    conn.commit()
    conn.close()

@app.route("/", methods=['GET', 'POST'])
def index():
    db = get_db()
    if request.method == "POST" and 'username' not in session:
        # CWE-20: No input validation for username
        username = request.form.get("username", "")
        cur = db.cursor()
        user = cur.execute("SELECT * FROM users WHERE username = '{}';".format(username)).fetchone()
        if not user:
            cur.execute("INSERT INTO users (username) VALUES ('{}');".format(username))
            db.commit()
            user = cur.execute("SELECT * FROM users WHERE username = '{}';".format(username)).fetchone()
        session['username'] = username
        session['user_id'] = user[0]
        return redirect(url_for('index'))
    elif 'username' in session:
        cur = db.cursor()
        # Display current user's tasks
        tasks = cur.execute("SELECT * FROM todos WHERE user_id = {}".format(session['user_id'])).fetchall()
        return render_template_string(INDEX_TMPL, css=CYBERPUNK_CSS, tasks=tasks, session=session)
    return render_template_string(INDEX_TMPL, css=CYBERPUNK_CSS, session=session)

@app.route("/add", methods=['POST'])
def add():
    if 'username' not in session:
        return redirect(url_for('index'))
    db = get_db()
    # CWE-20: No validation or escaping
    task = request.form.get('task', "")
    cur = db.cursor()
    cur.execute("INSERT INTO todos (user_id, task) VALUES ({}, '{}')".format(session['user_id'], task))
    db.commit()
    return redirect(url_for('index'))

@app.route("/delete", methods=['POST'])
def delete():
    if 'username' not in session:
        return redirect(url_for('index'))
    # CWE-20: No input filtering, directly using task_id
    task_id = request.form.get("task_id", "")
    db = get_db()
    cur = db.cursor()
    cur.execute("DELETE FROM todos WHERE id={}".format(task_id))
    db.commit()
    return redirect(url_for('index'))

@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for('index'))

if __name__ == "__main__":
    db_init()
    app.run(host="0.0.0.0", port=6022, debug=True)

