from flask import Flask, request, render_template_string, send_file, redirect, url_for, flash
import sqlite3
import csv
import io
import os

app = Flask(__name__)
app.secret_key = 'supersecretkey'

DB_FILE = 'app_db'

def init_db():
    if not os.path.exists(DB_FILE):
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        cur.execute('''
        CREATE TABLE IF NOT EXISTS reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_name TEXT NOT NULL,
            course TEXT NOT NULL,
            grade TEXT NOT NULL
        )
        ''')
        cur.executemany('INSERT INTO reports (student_name, course, grade) VALUES (?, ?, ?)', [
            ('Alice Smith', 'Mathematics', 'A'),
            ('Bob Johnson', 'Physics', 'B+'),
            ('Charlie Lee', 'Literature', 'A-'),
            ('Diana Prince', 'History', 'B'),
            ('Ethan Hunt', 'Mathematics', 'C+'),
        ])
        con.commit()
        con.close()

@app.route('/', methods=['GET', 'POST'])
def index():
    con = sqlite3.connect(DB_FILE)
    cur = con.cursor()
    cur.execute('SELECT DISTINCT course FROM reports')
    courses = [row[0] for row in cur.fetchall()]
    con.close()
    msg = None
    if 'msg' in request.args:
        msg = request.args['msg']
    html = '''
    <!DOCTYPE html>
    <html>
    <head>
    <title>Education Reports Exporter</title>
    <link href="https://fonts.googleapis.com/css?family=Roboto:400,700" rel="stylesheet">
