        display: block;
        margin: 18px 0 8px;
        font-weight: 500;
    }
    select, input[type=text] {
        width: 100%;
        padding: 10px 12px;
        border-radius: 3px;
        border: 1px solid #90caf9;
        margin-bottom: 15px;
        font-size: 1em;
    }
