        background: #1976d2;
        color: #fff;
        border: none;
        padding: 12px 26px;
        border-radius: 3px;
        font-size: 1em;
        font-weight: 500;
        cursor: pointer;
        box-shadow: 0 2px 5px #b0bec5;
    }
    .msg {
        background: #ffe082;
        color: #5d4037;
        padding: 10px 15px;
        border-radius: 4px;
        margin-bottom: 18px;
        text-align: center;
        font-size: 1.02em;
    }
    </style>
    </head>
    <body>
    <div class="container">
    <h1>Export Student Reports</h1>
    {% if msg %}
    <div class="msg">{{ msg }}</div>
    {% endif %}
    <form action="{{ url_for('export') }}" method="post">
      <label for="filter_field">Filter field</label>
      <select id="filter_field" name="filter_field">
        <option value="course">Course</option>
        <option value="grade">Grade</option>
        <option value="student_name">Student Name</option>
      </select>
      <label for="filter_value">Filter value</label>
      <input type="text" id="filter_value" name="filter_value" placeholder="e.g. Mathematics">
      <button type="submit">Export CSV</button>
    </form>
    </div>
    </body>
    </html>
    '''
    return render_template_string(html, courses=courses, msg=msg)

# CWE-20: Improper Input Validation - app fails to validate filter_field input adequately
@app.route('/export', methods=['POST'])
def export():
    filter_field = request.form.get('filter_field')
    filter_value = request.form.get('filter_value', '')

    # No whitelist validation for filter_field
    query = f"SELECT student_name, course, grade FROM reports WHERE {filter_field} LIKE ?"

    con = sqlite3.connect(DB_FILE)
    cur = con.cursor()
    try:
        cur.execute(query, ('%' + filter_value + '%',))
        rows = cur.fetchall()
    except Exception as e:
        con.close()
        return redirect(url_for('index', msg="Error in filter: " + str(e)))

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['Student Name', 'Course', 'Grade'])
    for row in rows:
        writer.writerow(row)
    output.seek(0)
    con.close()

    return send_file(
        io.BytesIO(output.getvalue().encode('utf-8')),
        mimetype='text/csv',
        as_attachment=True,
        download_name='report.csv'
    )

