@app.route('/', methods=['GET', 'POST'])
def index():
    db = get_db()
    c = db.cursor()
    if request.method == 'POST':
        name = request.form.get('name','')
        email = request.form.get('email','')
        issue = request.form.get('issue','')
        # CWE-20: No input validation or sanitization
        c.execute(f"INSERT INTO tickets (name, email, issue) VALUES ('{name}', '{email}', '{issue}')")
        db.commit()
        return redirect(url_for('index'))
    c.execute("SELECT * FROM tickets ORDER BY id DESC LIMIT 10")
    tickets = c.fetchall()
    return render_template_string(INDEX_HTML, tickets=tickets)

