@app.route('/', methods=['GET'])
def index():
    search = request.args.get('search', '')
    db = get_db()

    # CWE-20: Improper Input Validation - user input is not validated or sanitized before use in the SQL query.
    if search:
        query = f"SELECT * FROM courses WHERE title LIKE '%{search}%' OR instructor LIKE '%{search}%'"
        cursor = db.execute(query)
    else:
        cursor = db.execute("SELECT * FROM courses")
    courses = cursor.fetchall()

    return render_template_string(HTML_TEMPLATE, courses=courses, search=search)

