from flask import Flask, render_template_string, request, jsonify, redirect
import sqlite3
import os
import json
from datetime import datetime
import html

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def get_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_name TEXT,
            rating INTEGER,
            review_text TEXT,
            product TEXT,
            created_at TEXT
        )
    ''')
    db.commit()
    db.close()

def validate_input(user_name, rating, review_text):
    errors = []

    if not user_name or len(user_name) > 100:
        errors.append("Name must be provided and less than 100 characters")

    if not isinstance(rating, int):
        try:
            rating = int(rating)
        except:
            errors.append("Rating must be a number")
            return errors, None

    if rating < 1 or rating > 5:
        errors.append("Rating must be between 1 and 5")

    if not review_text or len(review_text) > 5000:
        errors.append("Review must be provided and less than 5000 characters")

    return errors, rating

