        ('The Art of Digital Creation', 'book', 19.99, 'Comprehensive guide to modern digital art techniques', 8.1),
        ('Neon Nights Album', 'music', 12.99, 'Electronic music collection for studying and focus', 8.6),
        ('Ancient Mysteries Explained', 'book', 16.99, 'Educational exploration of world\'s greatest mysteries', 8.3),
        ('Battle Royale Masters', 'game', 29.99, 'Competitive multiplayer gaming experience', 8.9),
        ('Documentary: Deep Ocean', 'movie', 12.99, 'Stunning underwater exploration and marine life documentary', 9.1),
        ('Creative Music Production', 'book', 24.99, 'Learn music production from industry professionals', 8.7),
        ('Fantasy Realms Online', 'game', 34.99, 'Massively multiplayer online fantasy adventure', 8.4),
        ('The Innovation Era', 'movie', 15.99, 'Documentary about technological revolution', 8.2),
        ('Ambient Relaxation Series', 'music', 8.99, 'Calming instrumental music for meditation', 9.0),
    ]

    cursor.executemany(
        'INSERT INTO products (name, category, price, description, rating) VALUES (?, ?, ?, ?, ?)',
        products
    )

    conn.commit()
    conn.close()

@app.route('/')
def index():
    """Main page with product listing and search."""
    # CWE-20: Improper Input Validation
    # The search_query is taken directly from request.args without sanitization
    search_query = request.args.get('search', '').strip()
    category_filter = request.args.get('category', '').strip()

    conn = get_db_connection()
    cursor = conn.cursor()

    # Vulnerable SQL query construction - no parameterization for search_query
    # This allows SQL injection and other input-based attacks
    if search_query or category_filter:
        # Building query without proper parameterization (CWE-20)
        query = "SELECT * FROM products WHERE 1=1"

        # Directly concatenating user input into SQL query - VULNERABLE
        if search_query:
            # No validation or sanitization of search_query
            query += f" AND (name LIKE '%{search_query}%' OR description LIKE '%{search_query}%')"

        if category_filter:
            # No validation of category_filter value
            query += f" AND category = '{category_filter}'"

        try:
            cursor.execute(query)
            products = cursor.fetchall()
        except Exception as e:
            products = []
    else:
        cursor.execute("SELECT * FROM products")
        products = cursor.fetchall()

    conn.close()

    # Convert rows to tuples for template
    products = [tuple(p) for p in products] if products else []

    return render_template_string(HTML_TEMPLATE, products=products, search_query=search_query)

@app.route('/api/search')
def api_search():
    """API endpoint for searching products."""
    query = request.args.get('q', '').strip()

    # CWE-20: No input validation on the query parameter
    # This endpoint is also vulnerable to injection attacks

    conn = get_db_connection()
    cursor = conn.cursor()

    # Vulnerable to SQL injection - directly using user input
    if query:
        # No sanitization - directly concatenating into SQL
        sql = f"SELECT id, name, category, price, description, rating FROM products WHERE name LIKE '%{query}%' OR description LIKE '%{query}%'"
        try:
            cursor.execute(sql)
            results = cursor.fetchall()
        except Exception as e:
            results = []
    else:
        cursor.execute("SELECT id, name, category, price, description, rating FROM products")
        results = cursor.fetchall()

    conn.close()

    # Return results without any validation
    return jsonify([dict(row) for row in results])

@app.route('/api/filter')
def api_filter():
    """API endpoint for filtering products by category."""
    category = request.args.get('category', '').strip()
    sort_by = request.args.get('sort', '').strip()

    # CWE-20: No validation of input parameters
    # This is vulnerable to various attacks

    conn = get_db_connection()
    cursor = conn.cursor()

    # Building SQL without proper input validation
    query = "SELECT id, name, category, price, description, rating FROM products WHERE 1=1"

    if category:
        # No validation of category value
        query += f" AND category = '{category}'"

    if sort_by:
        # No validation of sort_by - could lead to SQL injection or logic issues
        valid_sorts = ['name', 'price', 'rating']
        # Even with whitelist check, we're still vulnerable in the main query
        if sort_by in valid_sorts:
            query += f" ORDER BY {sort_by}"

    try:
        cursor.execute(query)
        results = cursor.fetchall()
    except Exception as e:
        results = []

    conn.close()

    return jsonify([dict(row) for row in results])

@app.route('/api/product/<int:product_id>')
def api_product(product_id):
    """API endpoint for getting product details."""
    # While product_id is an integer, we should still validate it properly
    # CWE-20: No validation that product_id is within expected range

    conn = get_db_connection()
    cursor = conn.cursor()

    # No upper bounds check on product_id
    cursor.execute("SELECT * FROM products WHERE id = ?", (product_id,))
    product = cursor.fetchone()
    conn.close()

    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'Product not found'}), 404

