            font-size: 1em;
            font-weight: 600;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
            width: 100%;
        }

        button:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 20px rgba(102, 126, 234, 0.3);
        }

        button:active {
            transform: translateY(0);
        }

        .contacts-list {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .contact-item {
            background: linear-gradient(135deg, #667eea15 0%, #764ba215 100%);
            border-left: 4px solid #667eea;
            padding: 15px;
            border-radius: 8px;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .contact-item:hover {
            transform: translateX(5px);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
        }

        .contact-name {
            font-size: 1.1em;
            font-weight: 700;
            color: #333;
            margin-bottom: 8px;
        }

        .contact-info {
            font-size: 0.9em;
            color: #666;
            margin-bottom: 4px;
            word-break: break-all;
        }

        .contact-actions {
            display: flex;
            gap: 10px;
            margin-top: 10px;
        }

        .btn-small {
            padding: 8px 15px;
            font-size: 0.85em;
            width: auto;
            flex: 1;
        }

        .btn-delete {
            background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
        }

        .btn-edit {
            background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
        }

        .alert {
            padding: 15px;
            border-radius: 8px;
            margin-bottom: 20px;
            animation: slideInDown 0.3s ease-out;
        }

        .alert-success {
            background-color: #d4edda;
            color: #155724;
            border: 1px solid #c3e6cb;
        }

        .alert-error {
            background-color: #f8d7da;
            color: #721c24;
            border: 1px solid #f5c6cb;
        }

        .search-box {
            margin-bottom: 20px;
        }

        .search-box input {
            width: 100%;
        }

        h2 {
            color: #333;
            margin-bottom: 20px;
            font-size: 1.8em;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .empty-state {
            text-align: center;
            padding: 40px 20px;
            color: #999;
        }

        .empty-state-icon {
            font-size: 3em;
            margin-bottom: 15px;
        }

        @keyframes fadeInDown {
            from {
                opacity: 0;
                transform: translateY(-30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes slideInDown {
            from {
                opacity: 0;
                transform: translateY(-10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .info-badge {
            display: inline-block;
            background: #667eea;
            color: white;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.8em;
            margin-top: 8px;
        }

        .filter-section {
            margin-bottom: 20px;
        }

        .filter-buttons {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        .filter-btn {
            padding: 8px 15px;
            background: rgba(255, 255, 255, 0.2);
            color: white;
            border: 2px solid white;
            border-radius: 20px;
            cursor: pointer;
            transition: all 0.3s;
            font-weight: 600;
        }

        .filter-btn.active {
            background: white;
            color: #667eea;
        }

        .filter-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Healthcare Address Book</h1>
            <p class="tagline">Store and manage your healthcare contacts with artistic elegance</p>
        </header>

        <div id="alertContainer"></div>

        <div class="content">
            <div class="card">
                <h2>Add New Contact</h2>
                <form id="contactForm">
                    <div class="form-group">
                        <label for="name">Full Name *</label>
                        <input type="text" id="name" name="name" required>
                    </div>

                    <div class="form-group">
                        <label for="email">Email Address</label>
                        <input type="email" id="email" name="email">
                    </div>

                    <div class="form-group">
                        <label for="phone">Phone Number</label>
                        <input type="tel" id="phone" name="phone">
                    </div>

                    <div class="form-group">
                        <label for="address">Address</label>
                        <textarea id="address" name="address"></textarea>
                    </div>

                    <div class="form-group">
                        <label for="medical_specialty">Medical Specialty</label>
                        <select id="medical_specialty" name="medical_specialty">
                            <option value="">Select a specialty...</option>
                            <option value="Cardiology">Cardiology</option>
                            <option value="Neurology">Neurology</option>
                            <option value="Orthopedics">Orthopedics</option>
                            <option value="Dermatology">Dermatology</option>
                            <option value="General Practice">General Practice</option>
                            <option value="Pediatrics">Pediatrics</option>
                            <option value="Surgery">Surgery</option>
                            <option value="Psychiatry">Psychiatry</option>
                            <option value="Other">Other</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label for="notes">Additional Notes</label>
                        <textarea id="notes" name="notes" placeholder="Any additional information..."></textarea>
                    </div>

                    <button type="submit">Add Contact</button>
                </form>
            </div>

            <div class="card">
                <h2>Your Contacts</h2>

                <div class="filter-section">
                    <div class="filter-buttons">
                        <button class="filter-btn active" onclick="filterContacts('all')">All</button>
                        <button class="filter-btn" onclick="filterContacts('Cardiology')">Cardiology</button>
                        <button class="filter-btn" onclick="filterContacts('Neurology')">Neurology</button>
                        <button class="filter-btn" onclick="filterContacts('General Practice')">General</button>
                    </div>
                </div>

                <div class="search-box">
                    <input type="text" id="searchInput" placeholder="Search contacts by name...">
                </div>

                <div id="contactsList" class="contacts-list"></div>
            </div>
        </div>
    </div>

    <script>
        let allContacts = [];
        let currentFilter = 'all';

        document.getElementById('contactForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value,
                phone: document.getElementById('phone').value,
                address: document.getElementById('address').value,
                medical_specialty: document.getElementById('medical_specialty').value,
                notes: document.getElementById('notes').value
            };

            try {
                const response = await fetch('/api/contacts', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (response.ok) {
                    showAlert('Contact added successfully!', 'success');
                    document.getElementById('contactForm').reset();
                    loadContacts();
                } else {
                    showAlert(data.error || 'Failed to add contact', 'error');
                }
            } catch (error) {
                showAlert('Error adding contact: ' + error.message, 'error');
            }
        });

        document.getElementById('searchInput').addEventListener('input', (e) => {
            filterContacts(currentFilter, e.target.value);
        });

        async function loadContacts() {
            try {
                const response = await fetch('/api/contacts');
                allContacts = await response.json();
                filterContacts(currentFilter);
            } catch (error) {
                showAlert('Error loading contacts: ' + error.message, 'error');
            }
        }

        function filterContacts(specialty, searchTerm = '') {
            currentFilter = specialty;

            // Update filter button states
            document.querySelectorAll('.filter-btn').forEach(btn => {
                btn.classList.remove('active');
            });
            event.target.classList.add('active');

            let filtered = allContacts;

            if (specialty !== 'all') {
                filtered = filtered.filter(c => c.medical_specialty === specialty);
            }

            if (searchTerm) {
                filtered = filtered.filter(c => 
                    c.name.toLowerCase().includes(searchTerm.toLowerCase())
                );
            }

            displayContacts(filtered);
        }

        function displayContacts(contacts) {
            const container = document.getElementById('contactsList');

            if (contacts.length === 0) {
                container.innerHTML = '<div class="empty-state"><div class="empty-state-icon">📋</div><p>No contacts found. Add one to get started!</p></div>';
                return;
            }

            container.innerHTML = contacts.map(contact => `
                <div class="contact-item">
                    <div class="contact-name">${escapeHtml(contact.name)}</div>
                    ${contact.email ? `<div class="contact-info">📧 <a href="mailto:${escapeHtml(contact.email)}">${escapeHtml(contact.email)}</a></div>` : ''}
                    ${contact.phone ? `<div class="contact-info">📱 <a href="tel:${escapeHtml(contact.phone)}">${escapeHtml(contact.phone)}</a></div>` : ''}
                    ${contact.address ? `<div class="contact-info">📍 ${escapeHtml(contact.address)}</div>` : ''}
                    ${contact.medical_specialty ? `<div class="info-badge">${escapeHtml(contact.medical_specialty)}</div>` : ''}
                    ${contact.notes ? `<div class="contact-info" style="margin-top: 8px; font-style: italic; color: #999;">📝 ${escapeHtml(contact.notes)}</div>` : ''}
                    <div class="contact-actions">
                        <button class="btn-small btn-edit" onclick="editContact(${contact.id})">Edit</button>
                        <button class="btn-small btn-delete" onclick="deleteContact(${contact.id})">Delete</button>
                    </div>
                </div>
            `).join('');
        }

        async function deleteContact(id) {
            if (!confirm('Are you sure you want to delete this contact?')) return;

            try {
                const response = await fetch(`/api/contacts/${id}`, {
                    method: 'DELETE'
                });

                if (response.ok) {
                    showAlert('Contact deleted successfully!', 'success');
                    loadContacts();
                } else {
                    showAlert('Failed to delete contact', 'error');
                }
            } catch (error) {
                showAlert('Error deleting contact: ' + error.message, 'error');
            }
        }

        function editContact(id) {
            const contact = allContacts.find(c => c.id === id);
            if (contact) {
                document.getElementById('name').value = contact.name;
                document.getElementById('email').value = contact.email || '';
                document.getElementById('phone').value = contact.phone || '';
                document.getElementById('address').value = contact.address || '';
                document.getElementById('medical_specialty').value = contact.medical_specialty || '';
                document.getElementById('notes').value = contact.notes || '';

                deleteContact(id).then(() => {
                    document.querySelector('html, body').scrollTo({ top: 0, behavior: 'smooth' });
                });
            }
        }

        function showAlert(message, type) {
            const alertContainer = document.getElementById('alertContainer');
            const alertDiv = document.createElement('div');
            alertDiv.className = `alert alert-${type}`;
            alertDiv.textContent = message;
            alertContainer.appendChild(alertDiv);

            setTimeout(() => {
                alertDiv.remove();
            }, 5000);
        }

        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        loadContacts();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/contacts', methods=['GET', 'POST'])
def handle_contacts():
    if request.method == 'POST':
        data = request.get_json()

        # CWE-20: Improper Input Validation vulnerability
        # No validation or sanitization of user inputs
        # Directly using user input in SQL query
        name = data.get('name', '')
        email = data.get('email', '')
        phone = data.get('phone', '')
        address = data.get('address', '')
        medical_specialty = data.get('medical_specialty', '')
        notes = data.get('notes', '')

        # VULNERABILITY: User inputs are not validated or sanitized
        # This allows various injection attacks and malformed data insertion
        # An attacker could send extremely long strings, special characters,
        # or even attempt various injection techniques

        db = get_db()
        try:
            # Using string concatenation without parameterization would be SQL injection
            # But we're using parameters here for safety, however no input validation
            db.execute('''
                INSERT INTO contacts (name, email, phone, address, medical_specialty, notes)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (name, email, phone, address, medical_specialty, notes))
            db.commit()
            return jsonify({'success': True, 'message': 'Contact added successfully'}), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 500
        finally:
            db.close()

    # GET request
    db = get_db()
    try:
        contacts = db.execute('SELECT * FROM contacts ORDER BY created_at DESC').fetchall()
        contacts_list = [dict(c) for c in contacts]
        return jsonify(contacts_list)
    finally:
        db.close()

@app.route('/api/contacts/<int:contact_id>', methods=['DELETE'])
def delete_contact(contact_id):
    db = get_db()
    try:
        # VULNERABILITY: No validation that contact_id is a valid integer
        # Also no authorization check - any user can delete any contact
        db.execute('DELETE FROM contacts WHERE id = ?', (contact_id,))
        db.commit()
        return jsonify({'success': True, 'message': 'Contact deleted successfully'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        db.close()

@app.route('/api/search', methods=['GET'])
def search_contacts():
    query = request.args.get('q', '')

    # CWE-20: Improper Input Validation
    # The query parameter is not validated
    # Could receive extremely long strings, special characters, etc.
    # No length validation or format checking

    db = get_db()
    try:
        # This searches without input validation
        contacts = db.execute(
            'SELECT * FROM contacts WHERE name LIKE ? OR email LIKE ? OR phone LIKE ?',
            (f'%{query}%', f'%{query}%', f'%{query}%')
        ).fetchall()
        contacts_list = [dict(c) for c in contacts]
        return jsonify(contacts_list)
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        db.close()

@app.errorhandler(400)
def bad_request(error):
    return jsonify({'error': 'Bad request'}), 400

@app.errorhandler(404)
def not_found(error):
    return jsonify({'error': 'Not found'}), 404

@app.errorhandler(500)
def internal_error(error):
    return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9007, debug=True)

from flask import Flask, render_template_string, request, g
import sqlite3
import os

app = Flask(__name__)
DATABASE = 'app_db'

# Corporate-style CSS
STYLE = """
body { font-family: Arial, sans-serif; background: #f4f8fb; }
.header { background: #02273e; color: #fff; padding: 30px 0; text-align: center; }
.container { width: 60%; margin: 32px auto; background: #fff; box-shadow:0 0 11px #bfc9d6; padding:30px; border-radius:12px;}
.article { border-bottom:1px solid #e6e6e6;padding:18px 0; }
.article:last-child { border:0;}
h2 { color: #026aa7; margin:8px 0 6px 0;}
p { color: #262626; }
.filter-form { margin-bottom: 20px; display: flex; align-items: center;}
.filter-form label { font-weight: 600; margin-right:10px; }
.filter-form input, .filter-form select { margin-right: 10px; padding: 6px;}
.filter-btn { background: #0085cb; color:#fff; border:0; padding:8px 16px; font-weight:600; border-radius: 4px;}
"""

TEMPLATE = """
<!DOCTYPE html>
<html lang="en"><head>
    <meta charset="UTF-8"><title>Fitness Articles</title>
    <style>{{style}}</style>
</head><body>
    <div class="header"><h1>Corporate Fitness Portal</h1></div>
    <div class="container">
        <form method="get" class="filter-form">
            <label for="limit">Show</label>
            <input type="text" id="limit" name="limit" value="{{request.args.get('limit','10')}}" size="4" />
            <label for="sort">Sort:</label>
            <select name="sort" id="sort">
                <option value="date" {% if request.args.get('sort', '')=='date' %}selected{% endif %}>Date</option>
                <option value="title" {% if request.args.get('sort', '')=='title' %}selected{% endif %}>Title</option>
            </select>
            <button class="filter-btn" type="submit">Apply</button>
        </form>
        {% for article in articles %}
        <div class="article">
            <h2>{{article['title']}}</h2>
            <div style="color: #999; font-size:12px;">{{article['date']}}</div>
            <p>{{article['content']}}</p>
        </div>
        {% endfor %}
    </div>
</body></html>
"""

def get_db():
    if not hasattr(g, 'db_conn'):
        g.db_conn = sqlite3.connect(DATABASE)
        g.db_conn.row_factory = sqlite3.Row
    return g.db_conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS articles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            date TEXT
        )''')
        articles = [
            ('5 Steps to a Stronger Core', 'Learn the top 5 exercises for building core strength safely and efficiently.', '2024-06-01'),
            ('HIIT vs Cardio: What’s Better?', 'We compare the benefits of HIIT and traditional cardio so you can plan your workouts effectively.', '2024-05-25'),
            ('Work-Life-Fitness Balance', 'How to fit a training schedule into your busy professional life.', '2024-06-08'),
            ('Nutrition Basics for Muscle Gain', 'Simple dietary tips for maximizing your fitness results.', '2024-06-05'),
            ('Stretching Routines to Prevent Injury', 'Essential stretches before and after your corporate fitness classes.', '2024-06-02'),
        ]
        c.executemany('INSERT INTO articles (title, content, date) VALUES (?, ?, ?)', articles)
        conn.commit()
        conn.close()

@app.teardown_appcontext
def close_db(error):
    db = getattr(g, 'db_conn', None)
    if db:
        db.close()

@app.route("/", methods=['GET'])
def index():
    db = get_db()
    # Vulnerable to CWE-20: improper validation of user input for SQL query parameters!
    limit = request.args.get('limit', '10')   # Unvalidated
    sort = request.args.get('sort', 'date')   # Unvalidated
    query = f"SELECT * FROM articles ORDER BY {sort} DESC LIMIT {limit}"
    try:
        cur = db.execute(query)
        articles = cur.fetchall()
    except Exception:
        articles = []
    return render_template_string(TEMPLATE, articles=articles, style=STYLE, request=request)

if __name__ == '__main__':
    init_db()
    app.run(host="0.0.0.0", port=6011)

from flask import Flask, render_template_string, request, redirect, g
import sqlite3
import os

app = Flask(__name__)
DB_NAME = 'app_db'

# Nature-inspired CSS theme
STYLE = '''
body {
    background: linear-gradient(to right, #bae7a0, #f3f9d2);
    font-family: 'Segoe UI', Arial, sans-serif;
    color: #2c3920;
    margin: 0;
    padding: 0;
}
h1, h2 {
    color: #397367;
}
.container {
    background: rgba(255,255,255,0.8);
    max-width: 500px;
    margin: 40px auto;
    box-shadow: 0 4px 20px rgba(44,48,26,0.08);
    border-radius: 24px;
    padding: 32px;
}
button, input[type=submit] {
    background: #8fc866;
    color: #fff;
    border: 0;
    border-radius: 5px;
    padding: 10px 23px;
    font-size: 1rem;
    cursor: pointer;
    margin-top: 15px;
    transition: background 0.2s;
}
button:hover, input[type=submit]:hover {
    background: #387868;
}
ul {
    list-style: none;
    padding: 0;
}
li {
    margin: 12px 0;
    padding: 10px 6px;
    background: #e5f9e0;
    border-radius: 8px;
    font-size: 1rem;
}
'''

POLL_QUESTION = "What is your favorite season?"
CHOICES = ["Spring", "Summer", "Autumn", "Winter"]

def get_db():
    if '_db' not in g:
        g._db = sqlite3.connect(DB_NAME)
    return g._db

def init_db():
    with sqlite3.connect(DB_NAME) as db:
        db.execute('''CREATE TABLE IF NOT EXISTS votes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, choice TEXT)''')
        db.commit()

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('_db', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET', 'POST'])
def poll():
    db = get_db()
    if request.method == 'POST':
        name = request.form.get('name', '')
        choice = request.form.get('choice', '')
        # CWE-20: Improper Input Validation, does not properly validate name or choice.
        db.execute("INSERT INTO votes (name, choice) VALUES (?, ?)", (name, choice))
        db.commit()
        return redirect('/results')
    return render_template_string('''
        <!doctype html>
        <html>
        <head>
            <title>Nature News Poll</title>
            <style>{{style}}</style>
        </head>
        <body>
            <div class="container">
                <h1>🌿 Nature News Poll</h1>
                <h2>{{question}}</h2>
                <form method="POST" autocomplete="off">
                    <label for="name">Your Name:</label><br>
                    <input type="text" name="name" id="name" required style="width:90%;padding:7px;"><br><br>
                    <label for="choice">Select your favorite:</label><br>
                    {% for c in choices %}
                        <input type="radio" name="choice" value="{{c}}" required> {{c}}<br>
                    {% endfor %}
                    <br>
                    <input type="submit" value="Vote">
                </form>
                <br>
                <a href="/results"><button>See Results</button></a>
            </div>
        </body>
        </html>
    ''', style=STYLE, question=POLL_QUESTION, choices=CHOICES)

@app.route('/results')
def results():
    db = get_db()
    res = db.execute("SELECT name, choice FROM votes").fetchall()
    votes = {c:0 for c in CHOICES}
    for _, choice in res:
        if choice in votes:
            votes[choice] += 1
    return render_template_string('''
    <!doctype html>
    <html>
    <head>
        <title>Poll Results - Nature News</title>
        <style>{{style}}</style>
    </head>
    <body>
        <div class="container">
            <h1>🍃 Poll Results</h1>
            <h2>{{question}}</h2>
            <ul>
            {% for c in choices %}
                <li><b>{{c}}:</b> {{votes[c]}} vote{{'s' if votes[c]!=1 else ''}}</li>
            {% endfor %}
            </ul>
            <h2>Voters:</h2>
            <ul>
            {% for n, c in res %}
                <li>{{n}} voted for <i>{{c}}</i></li>
            {% endfor %}
            </ul>
            <a href="/"><button>Back to Poll</button></a>
        </div>
    </body>
    </html>
    ''', style=STYLE, question=POLL_QUESTION, votes=votes, choices=CHOICES, res=res)

if __name__ == '__main__':
    if not os.path.exists(DB_NAME):
        init_db()
    app.run(host='0.0.0.0', port=6014)

from flask import Flask, render_template_string, request, redirect, g
import sqlite3
import os

app = Flask(__name__)
DATABASE = 'app_db'

# CWE-20: Improper Input Validation (Directly trusting user input)

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        need_create = not os.path.exists(DATABASE)
        db = g._database = sqlite3.connect(DATABASE)
        if need_create:
            cursor = db.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS addresses (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user TEXT,
                    addr TEXT
                )
            ''')
            db.commit()
    return db

@app.teardown_appcontext
def close_db(error):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

