@app.route("/", methods=["GET", "POST"])
def index():
    db = get_db()
    if request.method == 'POST':
        user = request.form.get('user')       # CWE-20 - Improper Input Validation
        addr = request.form.get('addr')       # Data can be malicious, e.g. XSS, SQLi (but shown with |safe)
        # (deliberately no input scrubbing or validation)
        db.execute("INSERT INTO addresses (user, addr) VALUES (?, ?)", (user, addr))
        db.commit()
        return redirect("/")
    cursor = db.execute('SELECT * FROM addresses ORDER BY id DESC')
    addresses = cursor.fetchall()
    return render_template_string(FUTURISTIC_STYLE, addresses=addresses)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6015, debug=False)

#!/usr/bin/env python3

import sqlite3
import os
from flask import Flask, render_template_string, request, jsonify
from datetime import datetime

app = Flask(__name__)

DB_PATH = '/tmp/app_db'

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS addresses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_name TEXT,
                street_address TEXT,
                city TEXT,
                state TEXT,
                zip_code TEXT,
                country TEXT,
                phone TEXT,
                email TEXT,
                special_instructions TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        conn.commit()
        conn.close()

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

