    <script>
        const form = document.getElementById('addressForm');
        const addressesList = document.getElementById('addressesList');
        const messagesDiv = document.getElementById('messages');

        function showMessage(message, type = 'success') {
            const messageEl = document.createElement('div');
            messageEl.className = `message ${type}`;
            messageEl.textContent = message;
            messagesDiv.appendChild(messageEl);
            setTimeout(() => messageEl.remove(), 5000);
        }

        function loadAddresses() {
            fetch('/api/addresses')
                .then(response => response.json())
                .then(data => {
                    addressesList.innerHTML = '';
                    if (data.addresses.length === 0) {
                        addressesList.innerHTML = '<div class="empty-message">No addresses saved yet. Add one to get started!</div>';
                    } else {
                        data.addresses.forEach(address => {
                            const card = document.createElement('div');
                            card.className = 'address-card';
                            card.innerHTML = `
                                <div class="address-header">
                                    <span class="address-name">${escapeHtml(address.user_name)}</span>
                                    <span class="address-date">${new Date(address.created_at).toLocaleDateString()}</span>
                                </div>
                                <div class="address-details">
                                    <p><label>Email:</label> <span>${escapeHtml(address.email)}</span></p>
                                    <p><label>Phone:</label> <span>${escapeHtml(address.phone)}</span></p>
                                    <p><label>Address:</label> <span>${escapeHtml(address.street_address)}</span></p>
                                    <p><label>City:</label> <span>${escapeHtml(address.city)}, ${escapeHtml(address.state)}</span></p>
                                    <p><label>Zip:</label> <span>${escapeHtml(address.zip_code)}</span></p>
                                    <p><label>Country:</label> <span>${escapeHtml(address.country)}</span></p>
                                    ${address.special_instructions ? `<p><label>Instructions:</label> <span>${escapeHtml(address.special_instructions)}</span></p>` : ''}
                                </div>
                                <div class="address-actions">
                                    <button class="delete-btn" onclick="deleteAddress(${address.id})">Delete</button>
                                </div>
                            `;
                            addressesList.appendChild(card);
                        });
                    }
                });
        }

        function escapeHtml(text) {
            if (!text) return '';
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.toString().replace(/[&<>"']/g, m => map[m]);
        }

        function deleteAddress(id) {
            if (confirm('Are you sure you want to delete this address?')) {
                fetch(`/api/addresses/${id}`, {
                    method: 'DELETE'
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        showMessage('Address deleted successfully!');
                        loadAddresses();
                    } else {
                        showMessage('Failed to delete address', 'error');
                    }
                });
            }
        }

        form.addEventListener('submit', function(e) {
            e.preventDefault();

            const formData = {
                user_name: document.getElementById('userName').value,
                email: document.getElementById('email').value,
                phone: document.getElementById('phone').value,
                street_address: document.getElementById('streetAddress').value,
                city: document.getElementById('city').value,
                state: document.getElementById('state').value,
                zip_code: document.getElementById('zipCode').value,
                country: document.getElementById('country').value,
                special_instructions: document.getElementById('specialInstructions').value
            };

            fetch('/api/addresses', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formData)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showMessage('Address saved successfully!');
                    form.reset();
                    loadAddresses();
                } else {
                    showMessage(data.message || 'Failed to save address', 'error');
                }
            })
            .catch(error => {
                showMessage('Error: ' + error.message, 'error');
            });
        });

        loadAddresses();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/addresses', methods=['GET'])
def get_addresses():
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('SELECT * FROM addresses ORDER BY created_at DESC')
        addresses = [dict(row) for row in cursor.fetchall()]
        conn.close()
        return jsonify({'addresses': addresses})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/addresses', methods=['POST'])
def save_address():
    try:
        data = request.get_json()

        user_name = data.get('user_name', '')
        email = data.get('email', '')
        phone = data.get('phone', '')
        street_address = data.get('street_address', '')
        city = data.get('city', '')
        state = data.get('state', '')
        zip_code = data.get('zip_code', '')
        country = data.get('country', '')
        special_instructions = data.get('special_instructions', '')

        conn = get_db()
        cursor = conn.cursor()

        query = '''INSERT INTO addresses 
                   (user_name, email, phone, street_address, city, state, zip_code, country, special_instructions, created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'''

        cursor.execute(query, (
            user_name,
            email,
            phone,
            street_address,
            city,
            state,
            zip_code,
            country,
            special_instructions,
            datetime.now().isoformat()
        ))

        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Address saved successfully'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500

@app.route('/api/addresses/<int:address_id>', methods=['DELETE'])
def delete_address(address_id):
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('DELETE FROM addresses WHERE id = ?', (address_id,))
        conn.commit()
        conn.close()
        return jsonify({'success': True, 'message': 'Address deleted successfully'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9014, debug=True)

from flask import Flask, render_template_string, request, jsonify, session
import sqlite3
import os
from datetime import datetime

app = Flask(__name__)
app.secret_key = 'banking_secret_key_123'
DB_PATH = 'app_db.sqlite'

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users
                 (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password TEXT, 
                  account_number TEXT, balance REAL, created_at TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS profiles
                 (id INTEGER PRIMARY KEY, user_id INTEGER, full_name TEXT, 
                  email TEXT, phone TEXT, address TEXT, city TEXT, postal_code TEXT,
                  country TEXT, updated_at TEXT, FOREIGN KEY(user_id) REFERENCES users(id))''')

    try:
        c.execute("INSERT INTO users (username, password, account_number, balance, created_at) VALUES (?, ?, ?, ?, ?)",
                  ('demo', 'demo123', '1234567890', 50000.00, datetime.now().isoformat()))
        user_id = c.lastrowid
        c.execute("""INSERT INTO profiles (user_id, full_name, email, phone, address, city, postal_code, country, updated_at) 
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                  (user_id, 'Demo User', 'demo@bank.com', '555-1234', '123 Main St', 'New York', '10001', 'USA', datetime.now().isoformat()))
        conn.commit()
    except sqlite3.IntegrityError:
        pass

    conn.close()

def get_db_connection():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

