</head>
<body>
    <div class="container">
        <header>
            <div class="header-content">
                <div class="logo">🏦 SecureBank</div>
                <ul class="nav-links">
                    <li><a href="/">Dashboard</a></li>
                    <li><a href="/profile">Profile</a></li>
                    <li><a href="/transactions">Transactions</a></li>
                    <li><a href="/logout">Logout</a></li>
                </ul>
            </div>
        </header>

        <div class="main-content">
            <div class="sidebar">
                <div class="profile-image">👤</div>
                <div class="account-info">
                    <h3 id="userName" style="color: #333; margin-bottom: 5px;">{{ user_full_name }}</h3>
                    <div class="account-number">Account: <strong>{{ user_account }}</strong></div>
                    <div class="balance">${{ user_balance }}</div>
                    <div class="status">✓ Active Account</div>
                </div>
            </div>

            <div class="main-panel">
                <div class="tabs">
                    <button class="tab-button active" onclick="showTab('profile')">Profile Information</button>
                    <button class="tab-button" onclick="showTab('security')">Security Settings</button>
                    <button class="tab-button" onclick="showTab('preferences')">Preferences</button>
                </div>

                <div id="profile" class="tab-content active">
                    <div class="alert" id="alert"></div>
                    <form id="profileForm" onsubmit="submitProfile(event)">
                        <h3 style="margin-bottom: 20px; color: #333;">Personal Information</h3>
                        <div class="form-row">
                            <div class="form-group">
                                <label for="fullName">Full Name</label>
                                <input type="text" id="fullName" name="full_name" value="{{ full_name }}" required>
                            </div>
                            <div class="form-group">
                                <label for="email">Email Address</label>
                                <input type="email" id="email" name="email" value="{{ email }}" required>
                            </div>
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label for="phone">Phone Number</label>
                                <input type="tel" id="phone" name="phone" value="{{ phone }}">
                            </div>
                            <div class="form-group">
                                <label for="address">Street Address</label>
                                <input type="text" id="address" name="address" value="{{ address }}">
                            </div>
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label for="city">City</label>
                                <input type="text" id="city" name="city" value="{{ city }}">
                            </div>
                            <div class="form-group">
                                <label for="postalCode">Postal Code</label>
                                <input type="text" id="postalCode" name="postal_code" value="{{ postal_code }}">
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="country">Country</label>
                            <select id="country" name="country">
                                <option value="USA" {% if country == 'USA' %}selected{% endif %}>United States</option>
                                <option value="Canada" {% if country == 'Canada' %}selected{% endif %}>Canada</option>
                                <option value="UK" {% if country == 'UK' %}selected{% endif %}>United Kingdom</option>
                                <option value="Australia" {% if country == 'Australia' %}selected{% endif %}>Australia</option>
                                <option value="Other" {% if country == 'Other' %}selected{% endif %}>Other</option>
                            </select>
                        </div>

                        <div class="button-group">
                            <button type="submit" class="btn-primary">Save Changes</button>
                            <button type="reset" class="btn-secondary">Cancel</button>
                        </div>
                    </form>
                </div>

                <div id="security" class="tab-content">
                    <h3 style="margin-bottom: 20px; color: #333;">Security Settings</h3>
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input type="password" id="currentPassword" placeholder="Enter current password">
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input type="password" id="newPassword" placeholder="Enter new password">
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input type="password" id="confirmPassword" placeholder="Confirm new password">
                    </div>
                    <div class="button-group">
                        <button class="btn-primary" onclick="changePassword()">Change Password</button>
                        <button class="btn-secondary">Cancel</button>
                    </div>
                </div>

                <div id="preferences" class="tab-content">
                    <h3 style="margin-bottom: 20px; color: #333;">Account Preferences</h3>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" checked> Email notifications for transactions
                        </label>
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" checked> SMS alerts for suspicious activities
                        </label>
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox"> Marketing and promotional emails
                        </label>
                    </div>
                    <div class="button-group">
                        <button class="btn-primary">Save Preferences</button>
                        <button class="btn-secondary">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        function showTab(tabName) {
            const tabs = document.querySelectorAll('.tab-content');
            const buttons = document.querySelectorAll('.tab-button');

            tabs.forEach(tab => tab.classList.remove('active'));
            buttons.forEach(btn => btn.classList.remove('active'));

            document.getElementById(tabName).classList.add('active');
            event.target.classList.add('active');
        }

        function showAlert(message, type) {
            const alert = document.getElementById('alert');
            alert.textContent = message;
            alert.className = 'alert ' + type + ' show';
            setTimeout(() => {
                alert.classList.remove('show');
            }, 3000);
        }

        function submitProfile(event) {
            event.preventDefault();

            const formData = {
                full_name: document.getElementById('fullName').value,
                email: document.getElementById('email').value,
                phone: document.getElementById('phone').value,
                address: document.getElementById('address').value,
                city: document.getElementById('city').value,
                postal_code: document.getElementById('postalCode').value,
                country: document.getElementById('country').value
            };

            fetch('/update_profile', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(formData)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showAlert('Profile updated successfully!', 'success');
                } else {
                    showAlert('Error updating profile: ' + data.message, 'error');
                }
            })
            .catch(error => {
                showAlert('Error: ' + error, 'error');
            });
        }

        function changePassword() {
            const current = document.getElementById('currentPassword').value;
            const newPass = document.getElementById('newPassword').value;
            const confirm = document.getElementById('confirmPassword').value;

            if (!current || !newPass || !confirm) {
                showAlert('Please fill in all password fields', 'error');
                return;
            }

            if (newPass !== confirm) {
                showAlert('Passwords do not match', 'error');
                return;
            }

            const data = {
                current_password: current,
                new_password: newPass
            };

            fetch('/change_password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(data)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showAlert('Password changed successfully!', 'success');
                    document.getElementById('currentPassword').value = '';
                    document.getElementById('newPassword').value = '';
                    document.getElementById('confirmPassword').value = '';
                } else {
                    showAlert('Error: ' + data.message, 'error');
                }
            })
            .catch(error => {
                showAlert('Error: ' + error, 'error');
            });
        }
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    if 'user_id' not in session:
        session['user_id'] = 1

    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
    profile = conn.execute('SELECT * FROM profiles WHERE user_id = ?', (session['user_id'],)).fetchone()
    conn.close()

    if not user or not profile:
        return "User not found", 404

    return render_template_string(HTML_TEMPLATE,
                                 user_full_name=profile['full_name'],
