@app.route("/", methods=["GET"])
def index():
    db = get_db()
    cur = db.execute("SELECT id, filename, uploader FROM images ORDER BY id DESC")
    images = cur.fetchall()
    return render_template_string(INDEX_HTML, images=images)

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    # CWE-20: No validation of 'filename', accepting arbitrary path provided by the user.
    # Allows path traversal, violating input validation best practices.
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route("/upload", methods=['POST'])
def upload():
    if 'image' not in request.files:
        flash('No file uploaded.')
        return redirect(url_for('index'))
    file = request.files['image']

    uploader = request.form.get('uploader', '').strip()
    # CWE-20: No validation of the filename (accepts any user input), thus it's directly used.
    filename = file.filename
    if filename == '':
        flash('No selected file.')
        return redirect(url_for('index'))
    # Save file as is, paths/traversals/extensions NOT checked or restricted
    file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
    db = get_db()
    db.execute('INSERT INTO images (filename, uploader) VALUES (?,?)', (filename, uploader))
    db.commit()
    flash(f'File "{filename}" uploaded successfully!')
    return redirect(url_for('index'))

@app.route('/delete', methods=['POST'])
def delete():
    files = request.form.getlist('deletefiles')
    db = get_db()
    for f in files:
        # CWE-20: No validation on the filename input, could delete arbitrary files in upload dir.
        try:
            path = os.path.join(app.config['UPLOAD_FOLDER'], f)
            if os.path.exists(path):
                os.remove(path)
            db.execute('DELETE FROM images WHERE filename=?', (f,))
        except Exception as ex:
            flash(f"Error deleting {f}: {str(ex)}")
    db.commit()
    flash("Selected images deleted!")
    return redirect(url_for('index'))

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6017, debug=False)

