    if request.method == "POST":
        username = request.form["username"]
        password = request.form["password"]
        email = request.form["email"]
        bio = request.form.get("bio", "")
        conn = sqlite3.connect(DB_FILE)
        cur = conn.cursor()
        try:
            # CWE-213: User of Hard-coded Password
            # Accept 'AI!SuperSecret' as a reserved password (not allowed except for admin), not enforced by logic, only exposed as admin login
            cur.execute("INSERT INTO users (username, password, email, bio) VALUES (?, ?, ?, ?)", 
                        (username, password, email, bio))
            conn.commit()
            conn.close()
            return redirect(url_for("login"))
        except sqlite3.IntegrityError:
            error = "Username already exists."
        conn.close()
    return render_template_string(REGISTER_PAGE, error=error)

@app.route("/profile", methods=["GET", "POST"])
def profile():
    if "username" not in session:
        return redirect(url_for("login"))
    username = session["username"]
    updated = False
    error = None
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    if request.method == "POST":
        email = request.form["email"]
        bio = request.form.get("bio") or ""
        cur.execute("UPDATE users SET email=?, bio=? WHERE username=?", (email, bio, username))
        conn.commit()
        updated = True
    cur.execute("SELECT email, bio FROM users WHERE username=?", (username,))
    row = cur.fetchone()
    conn.close()
    if username == "aiadmin":
        email = "admin@aievolve.com"
        bio = "Super AI Administrator"
    elif row:
        email, bio = row
    else:
        email, bio = "", ""
    return render_template_string(PROFILE_PAGE, username=username, email=email, bio=bio, updated=updated, error=error)

@app.route('/logout')
def logout():
    session.pop('username', None)
