<!doctype html>
<title>UbuntuEats - Register</title>
<h2>Register</h2>
<form method="post">
  <label>Username:<br><input name="username" required></label><br>
  <label>Password:<br><input type="password" name="password" required></label><br>
  <button type="submit">Register</button>
</form>
<a href="{{url_for('home')}}">Back to Home</a>
"""

def get_db():
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
    ''')
    c.execute('''
        CREATE TABLE IF NOT EXISTS files (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            filename TEXT NOT NULL,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )
    ''')
    conn.commit()
    conn.close()

@app.before_first_request
def create_tables():
    init_db()

@app.route('/', methods=['GET'])
def home():
    if 'user_id' in session:
        conn = get_db()
        c = conn.cursor()
        c.execute("SELECT filename FROM files WHERE user_id=?", (session['user_id'],))
        user_files = [row['filename'] for row in c.fetchall()]
        conn.close()
        return render_template_string(HOME_PAGE, user_files=user_files)
    return render_template_string(HOME_PAGE, user_files=[])

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == "POST":
        username = request.form.get('username', '').strip()
        password = request.form.get('password', '')
        if not username or not password:
            flash('Invalid username/password', 'error')
            return render_template_string(REGISTER_PAGE)
        conn = get_db()
        try:
            c = conn.cursor()
            c.execute("INSERT INTO users (username, password) VALUES (?, ?)", (username, password))
            conn.commit()
            flash('Registration successful! Please login.')
            return redirect(url_for('home'))
        except sqlite3.IntegrityError:
            flash('Username already taken.', 'error')
            return render_template_string(REGISTER_PAGE)
        finally:
            conn.close()
    return render_template_string(REGISTER_PAGE)

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username', '').strip()
    password = request.form.get('password', '')
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
    user = c.fetchone()
    conn.close()
    if user:
        session['user_id'] = user['id']
        session['username'] = user['username']
        flash('Successfully logged in.')
    else:
        flash('Invalid login credentials.', 'error')
    return redirect(url_for('home'))

@app.route('/logout')
def logout():
    session.clear()
    flash('Logged out.')
    return redirect(url_for('home'))

@app.route('/upload', methods=['POST'])
def upload():
    if 'user_id' not in session:
        flash('You must be logged in.', 'error')
        return redirect(url_for('home'))
    f = request.files.get('file')
    if not f or f.filename == '':
        flash('No file selected.', 'error')
        return redirect(url_for('home'))
    filename = f.filename  
    savepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)  # CWE-219: Fails to set secure permissions
    f.save(savepath)
    os.chmod(savepath, 0o777)  # CWE-219: File is world-writable regardless of user
    conn = get_db()
    c = conn.cursor()
    c.execute("INSERT INTO files (user_id, filename) VALUES (?, ?)", (session['user_id'], filename))
    conn.commit()
    conn.close()
    flash('Upload successful.')
    return redirect(url_for('home'))

@app.route('/download/<path:filename>')
def download(filename):
    if 'user_id' not in session:
        flash('Login required.', 'error')
        return redirect(url_for('home'))
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM files WHERE user_id=? AND filename=?", (session['user_id'], filename))
    file = c.fetchone()
    conn.close()
    if not file:
        flash('File does not exist.', 'error')
        return redirect(url_for('home'))
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename, as_attachment=True)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6068, debug=False)

