def get_db():
    con = sqlite3.connect(DB_PATH)
    return con

def init_db():
    con = get_db()
    cur = con.cursor()
    cur.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        role TEXT NOT NULL
    )''')
    cur.execute('''CREATE TABLE IF NOT EXISTS posts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT,
        content TEXT,
        author TEXT NOT NULL
    )''')
    con.commit()
    try:
        cur.execute("SELECT * FROM users WHERE username='admin'")
        if not cur.fetchone():
            cur.execute("INSERT INTO users (username,password,role) VALUES (?,?,?)",('admin','admin','admin'))
            con.commit()
    except:
        pass
    con.close()

@app.before_first_request
def setup():
    init_db()

def check_login():
    return session.get('user', None) == 'admin'

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == 'POST':
        u = request.form.get('username', '')
        p = request.form.get('password', '')
        con = get_db()
        cur = con.cursor()
        cur.execute("SELECT * FROM users WHERE username=? AND password=?", (u,p))
        res = cur.fetchone()
        con.close()
        if res and res[3]=='admin':
            session['user'] = 'admin'
            return redirect(url_for('dashboard'))
        else:
            return render_template_string(LOGIN_FORM+"""<div style="color:red"><b>Login Failed!</b></div>""")
    return render_template_string(LOGIN_FORM)

@app.route('/logout')
def logout():
    session.pop('user',None)
    return redirect(url_for('login'))

@app.route('/')
def root():
    return redirect(url_for('dashboard'))

@app.route('/admin')
def dashboard():
    if not check_login():
        return redirect(url_for('login'))
    return render_template_string(INDEX_TEMPLATE)

@app.route('/admin/users', methods=['GET','POST'])
def users():
    if not check_login():
        return redirect(url_for('login'))
    con = get_db()
    cur = con.cursor()
    if request.method=='POST':
        uname = request.form.get('username','').strip()
        pwd = request.form.get('password','')
        role = request.form.get('role','user')
        if uname and pwd:
            try:
                cur.execute("INSERT INTO users (username,password,role) VALUES (?,?,?)",(uname,pwd,role))
                con.commit()
            except sqlite3.IntegrityError:
                pass
    cur.execute("SELECT * FROM users")
    users = cur.fetchall()
    con.close()
    return render_template_string(USER_MANAGER, users=users)

@app.route('/admin/users/delete/<int:user_id>')
def delete_user(user_id):
    if not check_login():
        return redirect(url_for('login'))
    if user_id==1:
        return redirect(url_for('users'))
    con = get_db()
    cur = con.cursor()
    cur.execute("DELETE FROM users WHERE id=?",(user_id,))
    con.commit()
    con.close()
    return redirect(url_for('users'))

@app.route('/admin/content', methods=['GET','POST'])
def content():
    if not check_login():
        return redirect(url_for('login'))
    con = get_db()
    cur = con.cursor()
    if request.method=='POST':
        title = request.form.get('title','').strip()
        content = request.form.get('content','')
        if title and content:
            cur.execute("INSERT INTO posts (title,content,author) VALUES (?,?,?)",(title,content,'admin'))
            con.commit()
    cur.execute("SELECT * FROM posts")
    posts = cur.fetchall()
    con.close()
    return render_template_string(CONTENT_TEMPLATE, posts=posts)

@app.route('/admin/content/delete/<int:post_id>')
def delete_post(post_id):
