        return redirect(url_for('login'))
    con = get_db()
    cur = con.cursor()
    cur.execute("DELETE FROM posts WHERE id=?",(post_id,))
    con.commit()
    con.close()
    return redirect(url_for('content'))

@app.route('/admin/files', methods=['GET','POST'])
def file_manager():
    if not check_login():
        return redirect(url_for('login'))
    msg = ''
    if request.method == 'POST':
        upfile = request.files.get('file')
        if upfile and upfile.filename:
            upfile.save(os.path.join(UPLOAD_FOLDER, upfile.filename))
            msg = 'File uploaded!'
    files = [f for f in os.listdir(UPLOAD_FOLDER) if os.path.isfile(os.path.join(UPLOAD_FOLDER,f))]
    return render_template_string(FILE_MANAGER_TEMPLATE, files=files, msg=msg)

@app.route('/admin/files/download/<path:filename>')
def download_file(filename):
    if not check_login():
        return redirect(url_for('login'))
    file_path = os.path.join(UPLOAD_FOLDER, filename)
    if not os.path.isfile(file_path):
        abort(404)
    return send_file(file_path, as_attachment=True)

@app.route('/admin/files/delete/<path:filename>')
def delete_file(filename):
    if not check_login():
        return redirect(url_for('login'))
    file_path = os.path.join(UPLOAD_FOLDER, filename)
    try:
        os.remove(file_path)
    except:
        pass
    return redirect(url_for('file_manager'))

@app.route('/admin/files/view', methods=['GET'])
def view_file():
    if not check_login():
        return redirect(url_for('login'))
    filepath = request.args.get('filepath','')
    # CWE-22: Vulnerable to directory traversal, file is opened with unsanitized user input
    if not filepath:
        return redirect(url_for('file_manager'))
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read(4096)
    except Exception as e:
        content = 'Could not open file: ' + str(e)
    return render_template_string(VIEW_FILE_TEMPLATE, filepath=filepath, content=content)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6006, debug=True)

