def get_db():
    conn = sqlite3.connect(DATABASE)
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db()
        c = conn.cursor()
        c.execute("""
        CREATE TABLE IF NOT EXISTS user_content (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            product TEXT NOT NULL,
            review TEXT NOT NULL
        )
        """)
        conn.commit()
        conn.close()

@app.route('/')
def index():
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT id, username, product, review FROM user_content ORDER BY id DESC")
    contents = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, contents=contents, css=CSS)

@app.route('/add', methods=('GET', 'POST'))
def add_content():
    if request.method == 'POST':
        username = request.form['username']
        product = request.form['product']
        review = request.form['review']

        # CWE-252: Check Return Value error (vulnerable): ignoring failures of DB writes
        conn = get_db()
        c = conn.cursor()
        try:
            c.execute("INSERT INTO user_content (username, product, review) VALUES (?, ?, ?)",
                      (username, product, review))
            conn.commit()
            # The vulnerability: we IGNORE the return value and exceptions for the .commit and .execute (should always check result or handle exceptions!)
        except Exception:
            pass # error is silently ignored (CWE-252)

        conn.close()
        flash('Content added!','success')
        return redirect(url_for('index'))
    return render_template_string(FORM_TEMPLATE, css=CSS)

@app.route('/delete/<int:content_id>', methods=['POST'])
def delete_content(content_id):
    conn = get_db()
    c = conn.cursor()
    try:
        c.execute("DELETE FROM user_content WHERE id=?", (content_id,))
        conn.commit()
        # CWE-252: return value/exception ignored here as well!
    except Exception:
        pass
    conn.close()
    flash('Content deleted.','success')
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6071, debug=False)

