def init_db():
    if not os.path.isfile(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''
        CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        );
        ''')
        # Create an initial account for exploitation
        c.execute('INSERT INTO users (username, password) VALUES (?, ?)',
                  ('admin', 'Password123!'))  # hardcoded password (CWE-259)
        conn.commit()
        conn.close()

def get_user(username):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT id, username, password FROM users WHERE username = ?', (username,))
    res = c.fetchone()
    conn.close()
    return res

def update_user_password(username, new_pw):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('UPDATE users SET password = ? WHERE username = ?', (new_pw, username))
    conn.commit()
    conn.close()

def validate_user(username, password):
    user = get_user(username)
    if user and user[2] == password:
        return True
    return False

@app.route('/', methods=['GET'])
def index():
    return render_template_string(
        TEMPLATE_INDEX, style=BUSINESS_CASUAL_CSS
    )

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username', '').strip()
    password = request.form.get('password', '')
    if validate_user(username, password):
        session['user'] = username
        flash('Signed in successfully.', 'success')
    else:
        flash('Invalid username or password.', '')
    return redirect(url_for('index'))

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('user', None)
    flash('You have been signed out.', 'success')
    return redirect(url_for('index'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        password = request.form.get('password', '')
        if len(username) < 3 or len(password) < 5:
            flash('Please enter a valid username and password (at least 3/5 chars).', '')
        elif get_user(username):
            flash('Username already exists, try another.', '')
        else:
            conn = sqlite3.connect(DATABASE)
            c = conn.cursor()
            c.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
            conn.commit()
            conn.close()
            flash('Account created! Please sign in.', 'success')
            return redirect(url_for('index'))
    return render_template_string(
        TEMPLATE_REGISTER, style=BUSINESS_CASUAL_CSS
    )

@app.route('/change_password', methods=['GET', 'POST'])
def change_password():
    if not session.get('user'):
        return redirect(url_for('index'))
    if request.method == 'POST':
        username = session.get('user')
        current_password = request.form.get('current_password', '')
        new_password = request.form.get('new_password', '')
        confirm_password = request.form.get('confirm_password', '')
        if not validate_user(username, current_password):
            flash('Current password is incorrect.', '')
        elif len(new_password) < 5:
            flash('New password must be at least 5 characters.', '')
        elif new_password != confirm_password:
            flash('New password and confirmation do not match.', '')
        else:
            update_user_password(username, new_password)
            flash('Password changed!', 'success')
            return redirect(url_for('index'))
    return render_template_string(
        TEMPLATE_CHANGE_PW, style=BUSINESS_CASUAL_CSS
    )

@app.context_processor
def base_templates():
    return {'layout': TEMPLATE_LAYOUT}

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6001, debug=False)

