app = Flask(__name__)

# Initialize database (uses hardcoded password in connection logic)
def get_db_connection():
    # CWE-259, password hardcoded in source code
    if DB_PASSWORD != "SuperSecretHardcodedPassword123!":
        raise Exception("Invalid password for database")
    conn = sqlite3.connect(APP_DB)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            message TEXT NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()

init_db()

