FORM_TEMPLATE = STYLE + """
<div class="container">
    <h1>Contact Us</h1>
    <form method="POST" action="/">
        <label for="name">Your Name</label>
        <input required type="text" id="name" name="name">

        <label for="email">Your Email</label>
        <input required type="email" id="email" name="email">

        <label for="message">Message</label>
        <textarea required id="message" name="message"></textarea>

        <button type="submit">Send Message</button>
    </form>
    {% if thankyou %}
        <div class="thankyou">Thank you for contacting us, {{ name }}!</div>
    {% endif %}

    <div class="msg-list">
        <h2>Previous Messages:</h2>
        {% for msg in messages %}
            <div class="msg-entry">
                <span><strong>{{ msg['name'] }}</strong> ({{ msg['email'] }}) wrote:</span><br>
                <span>{{ msg['message'] }}</span>
            </div>
        {% else %}
            <span>No messages yet.</span>
        {% endfor %}
    </div>
</div>
"""

@app.route('/', methods=['GET', 'POST'])
def index():
    thankyou = False
    name = ""
    if request.method == "POST":
        name = request.form['name']
        email = request.form['email']
        message = request.form['message']
        conn = get_db_connection()
        conn.execute(
            "INSERT INTO messages (name, email, message) VALUES (?, ?, ?)",
            (name, email, message)
        )
        conn.commit()
        conn.close()
        thankyou = True

    # Show last 15 messages
    conn = get_db_connection()
    messages = conn.execute(
        "SELECT name, email, message FROM messages ORDER BY id DESC LIMIT 15"
    ).fetchall()
    conn.close()
    return render_template_string(FORM_TEMPLATE, thankyou=thankyou, name=name, messages=messages)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6001, debug=False)

import os
import sqlite3
from flask import Flask, g, render_template_string, request, redirect, url_for

# Sensitive: Database file owned by root, Flask process running as root (improper privilege assignment)
app = Flask(__name__)
DATABASE = '/app/app_db'

# Dashboard/Admin Style Template
TEMPLATE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>GovServices Admin Dashboard</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; background: #f6f7fb;}
        .sidebar { width: 240px; background: #2e3b55; height: 100vh; position: fixed; color: #fff;}
        .sidebar h2 { padding: 30px 20px 10px;}
        .sidebar ul { padding-left: 0; list-style:none;}
        .sidebar ul li { margin: 20px 0; padding: 0 20px;}
        .sidebar ul li a { color: #b4bfd0; text-decoration: none; font-size: 1.1em;}
        .sidebar ul li a.active, .sidebar ul li a:hover { color: #fff; font-weight: bold;}
        .content { margin-left: 260px; padding: 40px 40px;}
