        input[type=text], textarea {width:100%; padding:13px; margin-bottom:13px; border-radius:5px; border:1px solid #bfc7cf;}
        button {background: #284ba4; color:#fff; border:0; padding:10px 22px; border-radius:4px; font-size:1em;}
