</head>
<body>
    <div class="sidebar">
        <h2>GovServices</h2>
        <ul>
            <li><a href="/" class="active">Feedback Dashboard</a></li>
            <li><a href="#">Admin Panel</a></li>
            <li><a href="#">Service Stats</a></li>
            <li><a href="#">Settings</a></li>
        </ul>
    </div>
    <div class="content">
        <div class="header">
            <h1>Feedback Admin Panel</h1>
            <p style="color:#6985a2;">View and collect citizen feedback for e-Government services</p>
        </div>
        <div class="dashboard-card">
            <h2>Submit Feedback</h2>
            <form method="post" action="{{ url_for('submit_feedback') }}">
                <label for="user">Your Name</label>
                <input id="user" name="user" type="text" required maxlength="40">
                <label for="msg">Message</label>
                <textarea id="msg" name="msg" rows="4" required maxlength="200"></textarea>
                <button type="submit">Send</button>
            </form>
        </div>
        <div class="dashboard-card feedback-list">
            <h2>All Feedback</h2>
            {% for entry in feedback %}
            <div class="feedback-entry">
                <span class="entry-user">{{ entry['user']|e }}</span>:
                <span>{{ entry['message']|e }}</span>
            </div>
            {% endfor %}
        </div>
    </div>
</body>
</html>
'''

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        exists = os.path.exists(DATABASE)
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        if not exists:
            c = db.cursor()
            c.execute('CREATE TABLE feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT, message TEXT)')
            db.commit()
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    c = db.cursor()
    c.execute('SELECT user, message FROM feedback ORDER BY id DESC')
    entries = c.fetchall()
    return render_template_string(TEMPLATE, feedback=entries)

@app.route('/submit', methods=['POST'])
def submit_feedback():
    user = request.form.get('user', '').strip()[:40]
    msg = request.form.get('msg', '').strip()[:200]
    if user and msg:
        db = get_db()
        c = db.cursor()
        c.execute('INSERT INTO feedback (user, message) VALUES (?, ?)', (user, msg))
        db.commit()
    return redirect(url_for('index'))

if __name__ == "__main__":
    # Explicitly listen on 0.0.0.0:6082, and run as root (UID=0) in Docker, exposing CWE-275
    app.run(host='0.0.0.0', port=6082, debug=False)

