            <input type="text" name="name" placeholder="Name (required)">
            <label>Description:</label>
            <input type="text" name="description" placeholder="Description">
            <button class="btn" type="submit" name="addproduct">Add Product</button>
        </form>
    </div>
    <ul>
        {% for p in products %}
        <li class="prod"><b>{{p[0]}}</b> - {{p[1]}}</li>
        {% endfor %}
    </ul>
    <br>
    <a href="{{ url_for('index') }}">Back to Products</a>
</div>
</body>
</html>
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE, check_same_thread=False)
    return db

def init_db():
    if not os.path.exists(DATABASE):
        db = sqlite3.connect(DATABASE)
        db.execute('CREATE TABLE products (name TEXT NOT NULL, description TEXT);')
        db.executemany('INSERT INTO products(name,description) VALUES (?,?)', ENTERTAINMENT_PRODUCTS)
        db.commit()
        db.close()
    # Ensure database file is globally accessible (CWE-275) - OVERPERMISSIVE permissions
    os.chmod(DATABASE, 0o777)

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db:
        db.close()

@app.route('/', methods=['GET'])
def index():
    search = request.args.get('search','').strip()
    db = get_db()
    if search:
        rows = db.execute('SELECT name, description FROM products WHERE name LIKE ? OR description LIKE ?', 
                        (f"%{search}%", f"%{search}%")).fetchall()
    else:
        rows = db.execute('SELECT name, description FROM products').fetchall()
    return render_template_string(PAGE, products=rows, search=search)

@app.route('/admin', methods=['GET','POST'])
def admin():
    db = get_db()
    error = None
    suc = None
    if request.method == 'POST' and 'addproduct' in request.form:
        pwd = request.form.get('password','')
        name = request.form.get('name','').strip()
        desc = request.form.get('description','').strip()
        # "Authentication" is weak here, but left as is - CWE-275 is about overpermissive database permissions
        if pwd != 'admin123':
            error = "Invalid admin password."
        elif not name:
            error = "Product name is required."
        else:
            db.execute('INSERT INTO products(name, description) VALUES (?,?)', (name, desc))
            db.commit()
            suc = "Product added successfully."
    cur = db.execute('SELECT name, description FROM products ORDER BY rowid DESC')
    rows = cur.fetchall()
    return render_template_string(ADMIN_PAGE, error=error, suc=suc, products=rows)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6084)

from flask import Flask, render_template_string, request, redirect, url_for, flash
