import subprocess

app = Flask(__name__)
app.secret_key = "cyb3rpunknonprofit"

DB_PATH = '/app/app_db'
DB_NAME = 'messages.db'
DB_FULL_PATH = os.path.join(DB_PATH, DB_NAME)

# CWE-275 VULNERABILITY: Misconfigured file permission granting world-writable/owner privileges
def ensure_db():
    if not os.path.exists(DB_PATH):
        os.makedirs(DB_PATH)
    if not os.path.exists(DB_FULL_PATH):
        conn = sqlite3.connect(DB_FULL_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE messages
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      name TEXT NOT NULL,
                      email TEXT NOT NULL,
                      message TEXT NOT NULL)''')
        conn.commit()
        conn.close()
        # INSECURE: Make DB file world-writable/executable (CWE-275)
        subprocess.call(['chmod', '777', DB_FULL_PATH])
        subprocess.call(['chmod', '777', DB_PATH])

ensure_db()

