"""

VIEW_HTML = CYBERPUNK_STYLE + """
<div class="container">
    <div style="text-align:right; margin-bottom:10px;">
        <a style="color:#00fff7;" href="{{ url_for('contact') }}">&larr; Back to Form</a>
    </div>
    <div class="messages-list">
        <h2>Messages</h2>
        {% for m in messages %}
        <div class="card">
            <b>{{ m[1]|e }}</b> &lt;{{ m[2]|e }}&gt;<br>
            <i>{{ m[3]|e }}</i>
        </div>
        {% endfor %}
        {% if not messages %}
            <p style="color:#f600ff;text-align:center;">No messages yet.</p>
        {% endif %}
    </div>
</div>
