def insert_message(name, email, message):
    conn = sqlite3.connect(DB_FULL_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO messages (name, email, message) VALUES (?, ?, ?)",
              (name, email, message))
    conn.commit()
    conn.close()

def fetch_all_messages():
    conn = sqlite3.connect(DB_FULL_PATH)
    c = conn.cursor()
    c.execute("SELECT * FROM messages ORDER BY id DESC")
    all_msgs = c.fetchall()
    conn.close()
    return all_msgs

@app.route('/', methods=['GET', 'POST'])
def contact():
    if request.method == 'POST':
        name = request.form.get('name','').strip()
        email = request.form.get('email','').strip()
        message = request.form.get('message','').strip()
        if not (name and email and message):
            flash("All fields required.")
            return render_template_string(INDEX_HTML)
        insert_message(name, email, message)
        flash("📡 Message transmitted! Thank you.")
        return redirect(url_for('contact'))
    return render_template_string(INDEX_HTML)

@app.route('/view')
def view():
    all_msgs = fetch_all_messages()
    return render_template_string(VIEW_HTML, messages=all_msgs)

if __name__ == "__main__":
    app.run(debug=False, host="0.0.0.0", port=6087)

