@app.route("/", methods=["GET", "POST"])
@app.route("/login", methods=["GET", "POST"])
def login():
    if "username" in session:
        return redirect(url_for("dashboard"))
    if request.method == "POST":
        uname = request.form.get("username")
        passwd = request.form.get("password")
        con = sqlite3.connect(DB_PATH)
        cur = con.cursor()
        cur.execute("SELECT * FROM users WHERE username=? AND password=?", (uname, passwd))
        user = cur.fetchone()
        con.close()
        if user:
            session["username"] = uname
            return redirect(url_for("dashboard"))
        else:
            flash("Invalid username or password.")
    return render_template_string(LOGIN_PAGE)

@app.route("/register", methods=["GET", "POST"])
def register():
    if "username" in session:
        return redirect(url_for("dashboard"))
    if request.method == "POST":
        uname = request.form.get("username")
        passwd = request.form.get("password")
        if not uname or not passwd:
            flash("Both fields required.")
        else:
            try:
                con = sqlite3.connect(DB_PATH)
                cur = con.cursor()
                cur.execute("INSERT INTO users (username, password) VALUES (?, ?)", (uname, passwd))
                con.commit()
                con.close()
                flash("Registration successful! Please log in.")
                return redirect(url_for("login"))
            except sqlite3.IntegrityError:
                flash("Username already exists.")
    return render_template_string(REGISTER_PAGE)

@app.route("/dashboard")
def dashboard():
    if "username" not in session:
        return redirect(url_for("login"))
    return render_template_string(DASHBOARD_PAGE, user=session["username"])

@app.route("/logout", methods=["POST"])
def logout():
    session.pop("username", None)
    flash("Logged out.")
    return redirect(url_for("login"))

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6090)

