DATABASE = 'app_db'

# --- CWE-276: [Insecure default permissions] ---
def init_db():
    if not os.path.exists(DATABASE):
        # db file created with world-writable and world-readable permissions (CWE-276!)
        open(DATABASE, 'w').close()
        os.chmod(DATABASE, 0o666)  # Insecure: rw-rw-rw-
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''
            CREATE TABLE users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password TEXT NOT NULL,
                fullname TEXT,
                email TEXT,
                bio TEXT
            )
        ''')
        c.execute("INSERT INTO users (username, password, fullname, email, bio) VALUES (?, ?, ?, ?, ?)",
                  ('student', 'healthcare123', 'Alice Smith', 'alice@eduhealth.com', 'Aspiring nurse and lifelong learner.'))
        conn.commit()
        conn.close()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
    return g.db

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db is not None:
        db.close()

