@app.route('/', methods=['GET', 'POST'])
def index():
    msg = ""
    if request.method == 'POST':
        uname = request.form.get('username')
        pwd = request.form.get('password')

        db = get_db()
        cur = db.execute("SELECT * FROM users WHERE username=? AND password=?", (uname, pwd))
        user = cur.fetchone()
        if user:
            session['user_id'] = user[0]
            return redirect(url_for('profile'))
        else:
            msg = "Invalid username or password."
    return render_template_string(INDEX_HTML, msg=msg)

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if 'user_id' not in session:
        return redirect(url_for('index'))
    db = get_db()
    cur = db.execute("SELECT * FROM users WHERE id=?", (session['user_id'],))
    row = cur.fetchone()
    if not row:
        return redirect(url_for('logout'))
    user = {
        'id': row[0],
        'username': row[1],
        'fullname': row[3],
        'email': row[4],
        'bio': row[5]
    }
    msg = ""
    err = ""
    if request.method == 'POST':
        fullname = request.form.get('fullname', '')
        email = request.form.get('email', '')
        bio = request.form.get('bio', '')
        if not fullname or not email:
            err = "Full name and email are required."
        else:
            db.execute('UPDATE users SET fullname=?, email=?, bio=? WHERE id=?',
                       (fullname, email, bio, user['id']))
            db.commit()
            msg = "Profile updated successfully."
            user['fullname'] = fullname
            user['email'] = email
            user['bio'] = bio
    return render_template_string(PROFILE_HTML, user=user, msg=msg, err=err)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6091)

import os
import sqlite3
from flask import Flask, request, render_template_string, g, redirect, url_for

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

def init_db():
    if not os.path.exists(DATABASE):
        # CWE-276: Incorrect Default Permissions.
        # The database file is created with 0777 permissions, making it globally readable and writable
        open(DATABASE, 'a').close()
        os.chmod(DATABASE, 0o777)
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''
            CREATE TABLE IF NOT EXISTS feedback (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                message TEXT NOT NULL
            )
        ''')
        conn.commit()
        conn.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET', 'POST'])
def feedback():
    db = get_db()
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        message = request.form.get('message', '').strip()
        if name and message:
            db.execute('INSERT INTO feedback (name, message) VALUES (?, ?)', (name, message))
            db.commit()
            return redirect(url_for('feedback'))
    cur = db.execute('SELECT name, message FROM feedback ORDER BY id DESC')
    feedbacks = cur.fetchall()
    return render_template_string('''
