from flask import Flask, render_template_string, request, redirect, url_for, flash
import sqlite3
import os

# CWE-276: Incorrect Default Permissions
# The SQLite database file will be created world-writable

DATABASE = 'app_db.sqlite'

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        conn.execute('''
            CREATE TABLE posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL
            );
        ''')
        conn.commit()
        conn.close()
        os.chmod(DATABASE, 0o666)  # WORLD WRITABLE

app = Flask(__name__)
app.secret_key = 'change_me'

PAGE_TEMPLATE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Accessible Automotive Blog</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
    body { background:#fff; color:#222; font:1.2em/1.6 Arial,sans-serif; margin:0; padding:0;}
    .container { max-width: 700px; margin: auto; padding: 2rem;}
    h1, h2 { color: #005fa3;}
    a { color: #007ad9; }
    form { background: #f9f9f9; padding: 1rem; border-radius:4px;}
    label { font-weight: bold; display:block; margin-top:1rem;}
    input, textarea { width:100%; padding:0.5em; margin:0.2em 0 1em 0; border:1px solid #999;}
    .post { background:#eef; margin:1em 0; padding:1em; border-radius:5px;}
    .visually-hidden { position:absolute; left:-10000px; top:auto; width:1px; height:1px; overflow:hidden;}
    </style>
</head>
<body>
<div class="container">
    <header>
        <h1 tabindex="0">Accessible Automotive Blog</h1>
        <nav aria-label="Main menu">
            <a href="{{ url_for('index') }}">Home</a>
        </nav>
    </header>
    <main>
        <section aria-labelledby="add-post">
            <h2 id="add-post">Add a New Blog Post</h2>
            <form method="POST" action="{{ url_for('add_post') }}" aria-label="Add new blog post">
                <label for="title">Title</label>
                <input type="text" id="title" name="title" required aria-required="true" maxlength="100" autocomplete="off">
                <label for="content">Content</label>
                <textarea id="content" name="content" required aria-required="true" rows="5" maxlength="2048"></textarea>
                <button type="submit">Post</button>
            </form>
        </section>
        <section aria-labelledby="blog-posts">
            <h2 id="blog-posts">All Posts</h2>
            {% if posts %}
                <ul aria-live="polite">
                {% for post in posts %}
                    <li class="post">
                        <h3 tabindex="0">{{ post[1] | e }}</h3>
                        <div>{{ post[2] | e }}</div>
                    </li>
                {% endfor %}
                </ul>
            {% else %}
                <p>No posts yet.</p>
            {% endif %}
        </section>
        {% with messages = get_flashed_messages() %}
            {% if messages %}
                <div aria-live="assertive">
                {% for msg in messages %}
                    <p>{{ msg }}</p>
                {% endfor %}
                </div>
            {% endif %}
        {% endwith %}
    </main>
    <footer>
        <p>&copy; 2024 Automotive Blog. Accessible & Inclusive for Everyone.</p>
    </footer>
</div>
</body>
</html>
'''

@app.route('/', methods=['GET'])
def index():
    conn = sqlite3.connect(DATABASE)
    posts = conn.execute('SELECT * FROM posts ORDER BY id DESC').fetchall()
    conn.close()
    return render_template_string(PAGE_TEMPLATE, posts=posts)

@app.route('/add', methods=['POST'])
def add_post():
    title = request.form.get('title', '').strip()
    content = request.form.get('content', '').strip()
    if not title or not content:
        flash('Title and content are required.')
        return redirect(url_for('index'))
    if len(title) > 100 or len(content) > 2048:
        flash('Post is too long.')
        return redirect(url_for('index'))
    conn = sqlite3.connect(DATABASE)
    conn.execute('INSERT INTO posts (title, content) VALUES (?,?)', (title, content))
    conn.commit()
    conn.close()
    flash('Post added!')
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6093, debug=False)

