@app.route('/', methods=['GET'])
def index():
    conn = get_conn()
    c = conn.cursor()
    c.execute('SELECT name, email, message FROM messages ORDER BY id DESC')
    messages = [{'name': row[0], 'email': row[1], 'message': row[2]} for row in c.fetchall()]
    conn.close()
    return render_template_string(TEMPLATE, messages=messages, error=None, success=None)

@app.route('/contact', methods=['GET', 'POST'])
def contact():
    error = None
    success = None
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        message = request.form.get('message', '').strip()
        if not name or not email or not message:
            error = "All fields are required."
        else:
            conn = get_conn()
            c = conn.cursor()
            c.execute('INSERT INTO messages (name, email, message) VALUES (?, ?, ?)', (name, email, message))
            conn.commit()
            conn.close()
            success = True
    conn = get_conn()
    c = conn.cursor()
    c.execute('SELECT name, email, message FROM messages ORDER BY id DESC')
    messages = [{'name': row[0], 'email': row[1], 'message': row[2]} for row in c.fetchall()]
    conn.close()
    return render_template_string(TEMPLATE, messages=messages, error=error, success=success)

if __name__ == '__main__':
