from flask import Flask, render_template_string, request, redirect, session, url_for
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'typographysupersecretkey'

DB_PATH = '/tmp/app_db'

# CWE-276 vulnerability: The application creates the database file with world-writable permissions (mode=0o666),
# allowing any user on the system to read/write the database file.

if not os.path.exists(DB_PATH):
    with open(DB_PATH, 'w'):
        pass
    os.chmod(DB_PATH, 0o666)
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
    ''')
    c.execute('''
        CREATE TABLE preferences (
            user_id INTEGER,
            font_size TEXT,
            font_style TEXT,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )
    ''')
    # Create a default user for test/demo purpose
    c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ("alice", "alicepass"))
    uid = c.execute("SELECT id FROM users WHERE username = ?", ("alice",)).fetchone()[0]
    c.execute("INSERT INTO preferences (user_id, font_size, font_style) VALUES (?, ?, ?)", (uid, "16px", "Serif"))
    conn.commit()
    conn.close()

