def get_db():
    return sqlite3.connect(DB_PATH)

@app.route('/', methods=['GET'])
def index():
    if 'user_id' in session:
        return redirect(url_for('settings'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    msg = ""
    if request.method == 'POST':
        username = request.form.get('username','')
        password = request.form.get('password','')
        conn = get_db()
        c = conn.cursor()
        c.execute("SELECT id FROM users WHERE username=? AND password=?", (username, password))
        res = c.fetchone()
        conn.close()
        if res:
            session['user_id'] = res[0]
            return redirect(url_for('settings'))
        else:
            msg = "Login failed. Incorrect credentials."
    return render_template_string(STYLE + """
    {% block content %}
        <h1>Insurance Login</h1>
        {% if msg %}
        <div class="msg">{{msg}}</div>
        {% endif %}
        <form method="post">
            <label for="username">Username</label>
            <input type="text" name="username" id="username" required>
            <label for="password">Password</label>
            <input type="password" name="password" id="password" required>
            <button type="submit">Sign In</button>
        </form>
        <p style="margin-top:1.8em">Test user: <b>alice / alicepass</b></p>
    {% endblock %}
    """, msg=msg)

@app.route('/settings', methods=['GET', 'POST'])
def settings():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    msg = ""
    uid = session['user_id']
    conn = get_db()
    c = conn.cursor()
    if request.method == 'POST':
        font_size = request.form.get('font_size','16px')
        font_style = request.form.get('font_style','Serif')
        c.execute("UPDATE preferences SET font_size=?, font_style=? WHERE user_id=?", (font_size, font_style, uid))
        conn.commit()
        msg = "Preferences updated."
    c.execute("SELECT font_size, font_style FROM preferences WHERE user_id=?", (uid,))
    prefs = c.fetchone()
    conn.close()
    font_size = prefs[0] if prefs else '16px'
    font_style = prefs[1] if prefs else 'Serif'
    font_opts = [
        ('12px', 'Small'),
        ('16px', 'Normal'),
        ('20px', 'Large'),
        ('26px', 'Extra Large')
    ]
    font_styles = ['Serif', 'Sans-serif', 'Monospace', 'Cursive']
    return render_template_string(STYLE + """
    {% block content %}
        <h1>User Settings</h1>
        {% if msg %}
        <div class="msg">{{ msg }}</div>
        {% endif %}
        <form method="post">
            <label for="font_size">Preferred Font Size</label>
            <select name="font_size" id="font_size">
                {% for value,label in font_opts %}
                <option value="{{value}}" {% if value==font_size %}selected{% endif %}>{{label}}</option>
                {% endfor %}
            </select>
            <label for="font_style">Preferred Font Family</label>
            <select name="font_style" id="font_style">
                {% for style in font_styles %}
                <option value="{{style}}" {% if style==font_style %}selected{% endif %}>{{style}}</option>
                {% endfor %}
            </select>
            <button type="submit">Save Preferences</button>
        </form>
        <p style="margin-top:3em"><a href="{{url_for('logout')}}">Logout</a></p>
    {% endblock %}
    """,
    msg=msg, font_opts=font_opts, font_size=font_size, font_styles=font_styles, font_style=font_style)

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6099)

