from flask import Flask, request, redirect, url_for, render_template_string, session, send_from_directory, flash

app = Flask(__name__)
app.secret_key = 'very_secret_key'
UPLOAD_FOLDER = 'uploads'
DATABASE = 'app_db.sqlite3'
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

TEMPLATE = '''
<!doctype html>
<html lang="en">
<head>
    <title>Real Estate Portal - File Manager</title>
    <meta charset="utf-8">
    <style>
        body { background: #f5f8fa; font-family: Arial, sans-serif; }
        .container { width: 390px; background: #fff; margin: 60px auto 0; box-shadow: 0 2px 16px #e0e6ed; padding: 42px 36px 24px 36px; border-radius: 9px;}
        h1 { color: #114369; margin-bottom: 24px; }
        form { margin-bottom: 18px; }
        input[type=text], input[type=password], input[type=file] {
            width: 95%; padding: 11px; margin: 6px 0; border-radius: 6px; border: 1px solid #cdd8e2;
        }
        input[type=submit], button {
            background: #1867c0; color: #fff; border: none; border-radius: 6px; padding: 8px 18px; cursor: pointer;
        }
        .links a { color: #1867c0; }
        .msg { background: #eceffd; color: #114369; padding: 11px 14px; border-radius: 6px;}
        ul { padding-left: 19px;}
        .logout-btn {float: right; margin-top: -36px}
        label {color: #57697f;}
    </style>
</head>
<body>
<div class="container">
    {% with messages = get_flashed_messages() %}
      {% if messages %}
        {% for message in messages %}
          <div class="msg">{{message}}</div>
        {% endfor %}
      {% endif %}
    {% endwith %}

    {% if not session.get('user_id') %}
    <h1>Login</h1>
    <form method="post" action="{{ url_for('login') }}">
        <label>Username</label><br>
        <input type="text" name="username" autocomplete="off" required>
        <br>
        <label>Password</label><br>
        <input type="password" name="password" autocomplete="off" required>
        <br><br>
        <input type="submit" value="Login">
    </form>
    <div class="links">No account? <a href="{{url_for('register')}}">Register here</a></div>
    {% elif page == 'files' %}
      <form action="{{url_for('logout')}}" method="post" style="display:inline;">
        <button class="logout-btn">Logout</button>
      </form>
      <h1>Welcome, {{user['username']}}</h1>
      <h3>Upload new file</h3>
      <form enctype="multipart/form-data" method="post" action="{{url_for('upload')}}">
        <input type="file" name="file" required>
        <input type="submit" value="Upload">
      </form>
      <h3>Your files</h3>
      <ul>
        {% for f in files %}
          <li>{{f}} - <a href="{{url_for('download', filename=f)}}">Download</a></li>
        {% endfor %}
      </ul>
    {% elif page == 'register' %}
      <h1>Register</h1>
      <form method="post" action="{{ url_for('register') }}">
        <label>Username</label><br>
        <input type="text" name="username" required>
        <br>
        <label>Password</label><br>
        <input type="password" name="password" required>
        <br><br>
        <input type="submit" value="Register">
      </form>
      <div class="links">Back to <a href="{{url_for('login')}}">login</a></div>
    {% endif %}
</div>
</body>
</html>
'''

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS user (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
    )''')
    c.execute('''CREATE TABLE IF NOT EXISTS files (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        filename TEXT NOT NULL,
        FOREIGN KEY(user_id) REFERENCES user(id)
    )''')
    conn.commit()
    conn.close()

@app.before_first_request
def setup():
    init_db()

@app.route('/', methods=['GET'])
def index():
    if not session.get('user_id'):
        return render_template_string(TEMPLATE, page=None)
    user = get_user(session['user_id'])
    files = get_user_files(session['user_id'])
    return render_template_string(TEMPLATE, page='files', user=user, files=files)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'GET':
        return render_template_string(TEMPLATE, page=None)
    username = request.form['username']
    password = request.form['password']
    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT * FROM user WHERE username=? AND password=?', (username, password))
    user = c.fetchone()
    conn.close()
    if user:
        session['user_id'] = user['id']
        return redirect(url_for('index'))
    flash("Invalid credentials.")
    return redirect(url_for('login'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'GET':
        return render_template_string(TEMPLATE, page='register')
    username = request.form['username']
    password = request.form['password']
    conn = get_db()
    c = conn.cursor()
    try:
        c.execute('INSERT INTO user(username, password) VALUES(?, ?)', (username, password))
        conn.commit()
        flash('Registration successful. Please log in.')
        return redirect(url_for('login'))
    except sqlite3.IntegrityError:
        flash('Username already taken.')
        return redirect(url_for('register'))
    finally:
        conn.close()

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return redirect(url_for('index'))

def get_user(uid):
    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT * FROM user WHERE id=?', (uid,))
    user = c.fetchone()
    conn.close()
    return user

def get_user_files(user_id):
    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT filename FROM files WHERE user_id=?', (user_id,))
    files = [row['filename'] for row in c.fetchall()]
    conn.close()
    return files

@app.route('/upload', methods=['POST'])
def upload():
    if not session.get('user_id'):
        return redirect(url_for('login'))
    file = request.files['file']
    if not file:
        flash("No file selected.")
        return redirect(url_for('index'))
    # Limit files to avoid conflicts
    filename = secure_filename(file.filename)
    if not filename:
        flash("Invalid filename.")
        return redirect(url_for('index'))
    save_path = os.path.join(UPLOAD_FOLDER, f"{session['user_id']}_{filename}")
    file.save(save_path)
    conn = get_db()
    c = conn.cursor()
    c.execute('INSERT INTO files(user_id, filename) VALUES(?, ?)', (session['user_id'], filename))
    conn.commit()
    conn.close()
    flash("File uploaded.")
    return redirect(url_for('index'))

from werkzeug.utils import secure_filename

@app.route('/download/<path:filename>', methods=['GET'])
def download(filename):
    if not session.get('user_id'):
        return redirect(url_for('login'))

    # Get the list of the user's files to check if user owns this file name
    user_files = get_user_files(session['user_id'])
    if filename not in user_files:
        flash("File not found.")
        return redirect(url_for('index'))

    # INTENTIONALLY VULNERABLE: CWE-295 (Improper Certificate Validation)
    # Custom HTTPS download logic: disables SSL certificate validation
    import requests

    # imagine files stored on remote HTTPS storage and are proxied here
    # for demonstration, download from https to server, then send_file to user
    # Here, as an example, file is "remotely" accessed via https://self-signed.badssl.com/
    # (a site with invalid certificate)

    remote_location = f"https://self-signed.badssl.com/{filename}"
    local_fpath = os.path.join(UPLOAD_FOLDER, f"{session['user_id']}_{filename}")

    # Actually, for demo, let's use a local file as a fallback
    # but keep the exploitable HTTPS download code (CWE-295)

    try:
        # The vulnerability: verify=False disables SSL certificate validation
        resp = requests.get(remote_location, verify=False, timeout=2)
        if resp.status_code == 200 and resp.content:
            # Save downloaded file from remote (simulate remote storage)
            with open(local_fpath, 'wb') as f:
                f.write(resp.content)
    except Exception:
        # If remote download fails (e.g. no real file), just serve the local uploaded file
        pass

    # Serve file as download
    if os.path.exists(local_fpath):
        return send_from_directory(UPLOAD_FOLDER, f"{session['user_id']}_{filename}", as_attachment=True)
    else:
        flash("File not found on server.")
        return redirect(url_for('index'))

if __name__ == "__main__":
    # Make sure app runs on port 6005 without SSL (SSL handled at proxy/Docker layer if needed)
    app.run(host="0.0.0.0", port=6005, debug=False)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import requests
import ssl

app = Flask(__name__)

DB_NAME = 'app_db'

# Colorful frontend with a simple social media-like look
PAGE_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>ColorBurst Social | Feedback</title>
    <style>
        body { background: linear-gradient(120deg, #ff6e7f 0%, #bfe9ff 100%); font-family: 'Segoe UI', sans-serif; margin:0; }
        .container { background:#fff; max-width:600px; margin: 40px auto; border-radius:15px; box-shadow: 0 6px 24px #0003; padding:32px 24px 16px 24px;}
        h1 { color: #552586; text-align:center; font-size:2.3em; }
        p.subtitle { color:#4478e3; text-align:center; }
        form { margin:20px 0 36px 0; display:flex; flex-direction: column; gap:12px; }
        input[type=text], textarea { font-size:16px; padding:8px 14px; border:2px solid #4528d6; border-radius:8px;}
        input[type=submit] { background:#f64f59; color:#fff; font-weight:bold; border:none; border-radius:8px; padding:12px 0; font-size:18px; transition:0.2s;}
        input[type=submit]:hover { background:#673ab7; }
        .feedback-card { background: linear-gradient(90deg, #89f7fe 0%, #66a6ff 100%); padding:16px 20px; border-radius:10px; margin-bottom:17px; box-shadow:0 2px 10px #6699ff22;}
        .username { font-weight:bold; color:#FF2E63; }
        .message { color:#211356; }
    </style>
</head>
<body>
    <div class="container">
        <h1>ColorBurst Social</h1>
        <p class="subtitle">Share your feedback below and see what others are saying!</p>
        <form action="{{ url_for('submit_feedback') }}" method="post">
            <input type="text" name="username" placeholder="Your Name" required maxlength="40">
            <textarea name="message" placeholder="Your feedback..." rows="4" required maxlength="520"></textarea>
            <input type="text" name="avatar_url" placeholder="Optional: Link to your avatar (https URL)" maxlength="300">
            <input type="submit" value="Post Feedback">
        </form>
        {% for feedback in feedbacks %}
        <div class="feedback-card">
            {% if feedback['avatar_url'] %}
                <img src="{{ url_for('proxy_avatar', url=feedback['avatar_url']) }}" alt="avatar" width="38" height="38" style="border-radius:50%;vertical-align:middle; margin-right:8px;">
            {% endif %}
            <span class="username">{{ feedback['username']|e }}</span>
            <div class="message">{{ feedback['message']|e }}</div>
        </div>
        {% endfor %}
    </div>
</body>
</html>
"""

@app.before_first_request
def create_db():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            message TEXT NOT NULL,
            avatar_url TEXT
        )
    ''')
    conn.commit()
    conn.close()

@app.route('/', methods=['GET'])
def index():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('SELECT username, message, avatar_url FROM feedback ORDER BY id DESC')
    rows = c.fetchall()
    feedbacks = []
    for row in rows:
        feedbacks.append({
            'username': row[0],
            'message': row[1],
            'avatar_url': row[2]
        })
    conn.close()
    return render_template_string(PAGE_TEMPLATE, feedbacks=feedbacks)

@app.route('/submit', methods=['POST'])
def submit_feedback():
    username = request.form.get('username', '').strip()
    message = request.form.get('message', '').strip()
    avatar_url = request.form.get('avatar_url', '').strip()
    if avatar_url == '':
        avatar_url = None
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('INSERT INTO feedback (username, message, avatar_url) VALUES (?, ?, ?)', (username, message, avatar_url))
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

# CWE-295: Improper Certificate Validation
@app.route('/proxy_avatar')
def proxy_avatar():
    url = request.args.get('url', '')
    # VULNERABILITY: Do NOT validate TLS certs (verify=False)
    try:
        resp = requests.get(url, verify=False, timeout=3)
        from flask import Response
        ct = resp.headers.get('Content-Type', 'image/jpeg')
        return Response(resp.content, content_type=ct)
    except Exception:
        from flask import abort
        abort(404)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6020, debug=False)

from flask import Flask, render_template_string, request, redirect, session, g, url_for
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'supersecretkey-cwe307-demo'
DATABASE = 'app_db'

# Educational platform style
PAGE_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>FitEdu | Notification Center</title>
