{% endblock %}
"""

LOGOUT_PAGE = """
{% extends "base.html" %}
{% block content %}
    <div class="alert">You've been logged out.</div>
    <a href="{{ url_for('login') }}">Login Again</a>
{% endblock %}
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def query_db(q, args=(), one=False):
    cur = get_db().execute(q, args)
    rv = cur.fetchall()
    cur.close()
    return (rv[0] if rv else None) if one else rv

def init_db():
    if not os.path.exists(DATABASE):
        db = sqlite3.connect(DATABASE)
        db.execute(
            'CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password TEXT)'
        )
        db.execute(
            '''CREATE TABLE notifications (id INTEGER PRIMARY KEY, 
            user_id INTEGER, message TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id))'''
        )
        db.execute("INSERT INTO users (username, password) VALUES (?, ?)", ('alice', 'fitness123'))
        db.execute("INSERT INTO users (username, password) VALUES (?, ?)", ('bob', 'fit456'))
        db.execute(
            "INSERT INTO notifications (user_id, message) VALUES ((SELECT id FROM users WHERE username=?), ?)",
            ('alice', 'Congratulations Alice! You completed 10,000 steps today!')
        )
        db.execute(
            "INSERT INTO notifications (user_id, message) VALUES ((SELECT id FROM users WHERE username=?), ?)",
            ('alice', 'New HIIT workout unlocked on your dashboard.')
        )
        db.execute(
            "INSERT INTO notifications (user_id, message) VALUES ((SELECT id FROM users WHERE username=?), ?)",
            ('bob', 'Bob, your BMI is in the healthy range. Keep it up!')
        )
        db.execute(
            "INSERT INTO notifications (user_id, message) VALUES ((SELECT id FROM users WHERE username=?), ?)",
            ('bob', 'You earned a streak badge! Log in daily for more.')
        )
        db.commit()
        db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET'])
def root():
    return redirect(url_for('notifications'))

# CWE-307 Vulnerability Demonstration: Too permissive account lockout on login
# - Instead of locking after several failed attempts, will lock after just ONE failure.
# - Real apps should require several (e.g. 5) failed attempts before lockout.

@app.route('/login', methods=['GET', 'POST'])
def login():
    if 'username' in session:
        return redirect(url_for('notifications'))

    error = None
    # Store lockout status per username in session for demo
    lock_user = session.get('lockout_user', {})
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # Check for lockout (ONE failed login attempt)
        if lock_user.get(username):
            error = 'Account locked due to login attempt. Contact admin.'
        else:
            user = query_db('SELECT * FROM users WHERE username=?', [username], one=True)
            if user and user['password'] == password:
                session['username'] = username
                return redirect(url_for('notifications'))
            else:
                # CWE-307: Lock out after a single failed attempt (should allow more!)
                lock_user[username] = True
                session['lockout_user'] = lock_user
                error = 'Invalid credentials. Account locked!'

    return render_template_string(
        '{% extends "base.html" %}{% block content %}' +
        ('<div class="alert">' + error + '</div>' if error else '') +
        LOGIN_PAGE.replace('{% extends "base.html" %}', '') +
        '{% endblock %}'
    )

@app.route('/logout')
def logout():
    session.pop('username', None)
    return render_template_string(LOGOUT_PAGE)

@app.route('/notifications', methods=['GET'])
def notifications():
    if 'username' not in session:
        return redirect(url_for('login'))
    user = query_db('SELECT * FROM users WHERE username=?', [session['username']], one=True)
    notifs = query_db('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 10', [user['id']])
    return render_template_string(NOTIF_PAGE, notifs=notifs)

@app.before_first_request
def pre_setup():
    init_db()

app.jinja_env.globals['get_flashed_messages'] = lambda: []

app.jinja_env.globals['session'] = session

app.jinja_loader.mapping = {
    'base.html': PAGE_TEMPLATE
}

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6010, debug=False)

