    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute('SELECT * FROM events ORDER BY date ASC')
    events = cur.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, events=events)

@app.route('/add', methods=['POST'])
def add_event():
    title = request.form.get('title','').strip()
    date = request.form.get('date','').strip()
    desc = request.form.get('desc','').strip()
    try:
        datetime.strptime(date, "%Y-%m-%d")
    except:
        flash("Invalid date format.")
        return redirect(url_for('index'))
    if not title:
        flash("Event title required.")
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute("INSERT INTO events (title, date, description) VALUES (?, ?, ?)", (title, date, desc))
    conn.commit()
    conn.close()
    flash("Event added!")
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6057, debug=False)

