</body>
</html>
"""

# ----- "Authentication" using weak cryptography (DES, keys fixed) -----
BLOCK_SIZE = 8
DES_SECRET_KEY = b'weakshop'  # 8-byte DES key

def des_encrypt(text):
    cipher = DES.new(DES_SECRET_KEY, DES.MODE_ECB)
    # padding with spaces
    pad_len = BLOCK_SIZE - (len(text) % BLOCK_SIZE)
    plaintext = text + chr(pad_len) * pad_len
    enc = cipher.encrypt(plaintext.encode('utf-8'))
    return base64.b64encode(enc).decode('utf-8')

def des_decrypt(enc_b64):
    cipher = DES.new(DES_SECRET_KEY, DES.MODE_ECB)
    enc = base64.b64decode(enc_b64)
    dec = cipher.decrypt(enc).decode('utf-8')
    pad_len = ord(dec[-1])
    return dec[:-pad_len]

USERS = {
    'admin': des_encrypt('adminpassword')
}

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    cur = db.cursor()
    cur.execute('SELECT * FROM articles ORDER BY id DESC')
    articles = cur.fetchall()
    return render_template_string(HTML_TMPL, articles=articles)

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    user_pass_hash = USERS.get(username)
    if user_pass_hash and des_decrypt(user_pass_hash) == password:
        session['user'] = username
        return redirect(url_for('index'))
    flash('Invalid login.', 'error')
    return redirect(url_for('index'))

@app.route('/logout')
def logout():
    session.pop('user', None)
    return redirect(url_for('index'))

@app.route('/add_article', methods=['POST'])
def add_article():
    if not session.get('user'):
        return redirect(url_for('index'))
    title = request.form.get('title')
    content = request.form.get('content')
    db = get_db()
    cur = db.cursor()
    cur.execute('INSERT INTO articles (title, content) VALUES (?, ?)', (title, content))
    db.commit()
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(debug=False, host='0.0.0.0', port=6062)

