def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        with conn:
            conn.execute('''
                CREATE TABLE users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    password TEXT NOT NULL,
                    theme TEXT DEFAULT 'light',
                    notify TEXT DEFAULT 'on',
                    api_token TEXT DEFAULT ''
                )
            ''')
            # Create a couple of default users
            conn.execute("INSERT INTO users (username, password, theme, notify, api_token) VALUES (?,?,?,?,?)",
                         ('alice', 'password123', 'light', 'on', generate_token()))
            conn.execute("INSERT INTO users (username, password, theme, notify, api_token) VALUES (?,?,?,?,?)",
                         ('bob', 'letmein456', 'dark', 'off', generate_token()))
        conn.close()

# CWE-330: Use of Insufficiently Random Values (using random.choice on predictable system source)
def generate_token():
    # This uses random.choices and a fixed set of characters, which should be replaced by secrets.token_urlsafe
    import random
    chars = string.ascii_letters + string.digits
    return ''.join(random.choices(chars, k=40))

@app.before_first_request
def before_first():
    init_db()

@app.route('/', methods=['GET'])
def index():
    if 'user_id' in session:
        return redirect(url_for('settings'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    msg = None
    if request.method == 'POST':
        uname = request.form.get('username','').strip()
        passwd = request.form.get('password','')
        with get_db() as conn:
            cur = conn.execute('SELECT * FROM users WHERE username=? AND password=?', (uname, passwd))
            user = cur.fetchone()
            if user:
                session['user_id'] = user['id']
                return redirect(url_for('settings'))
            else:
                msg = "Invalid username or password."
    return render_template_string(LOGIN_TEMPLATE, msg=msg)

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/settings', methods=['GET', 'POST'])
def settings():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    msg = None
    with get_db() as conn:
        user = conn.execute('SELECT * FROM users WHERE id=?', (session['user_id'],)).fetchone()
        if not user:
            session.clear()
            return redirect(url_for('login'))
        if request.method == 'POST':
            # Save preference changes
            theme = request.form.get('theme', 'light')
            notify = request.form.get('notify', 'on')
            if theme not in ('light', 'dark'): theme = 'light'
            if notify not in ('on', 'off'): notify = 'on'
            conn.execute('UPDATE users SET theme=?, notify=? WHERE id=?', (theme, notify, user['id']))
            conn.commit()
            msg = "Settings updated."
            user = conn.execute('SELECT * FROM users WHERE id=?', (session['user_id'],)).fetchone()
    return render_template_string(TEMPLATE, user=user, msg=msg)

@app.route('/reset_token', methods=['POST'])
def reset_token():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    # Vulnerable: uses generate_token that is not cryptographically secure
    new_token = generate_token()
    with get_db() as conn:
        conn.execute('UPDATE users SET api_token=? WHERE id=?', (new_token, session['user_id']))
        conn.commit()
    return redirect(url_for('settings'))

