from flask import Flask, render_template_string, request, redirect, session, url_for, g
import sqlite3
import os

app = Flask(__name__)
app.secret_key = "insecure_secret"
DATABASE = 'app_db'

# --- DB Utilities ---
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        g._database = db
    return db

def init_db():
    with app.app_context():
        db = get_db()
        db.executescript('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                title TEXT,
                content TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(user_id) REFERENCES users(id)
            );
        ''')
        db.commit()
        # create default user if not exists
        cur = db.execute('SELECT id FROM users WHERE username = ?', ('foodie',))
        if not cur.fetchone():
            db.execute('INSERT INTO users (username, password) VALUES (?, ?)', ('foodie', 'food123'))
            db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# --- Auth Helpers ---
def is_logged_in():
    return 'user_id' in session

def get_current_user():
    if is_logged_in():
        db = get_db()
        cur = db.execute('SELECT * FROM users WHERE id=?', (session['user_id'],))
        return cur.fetchone()
    return None

# --- Routes ---
@app.route('/')
def index():
    db = get_db()
    posts = db.execute(
        'SELECT posts.*, users.username FROM posts JOIN users ON posts.user_id = users.id ORDER BY posts.created_at DESC'
    ).fetchall()
    user = get_current_user()
    return render_template_string(PORTFOLIO_TEMPLATE, posts=posts, user=user)

@app.route('/login', methods=['GET', 'POST'])
def login():
    error = ''
    if request.method == "POST":
        username = request.form.get('username')
        password = request.form.get('password')
        db = get_db()
        cur = db.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password))
        user = cur.fetchone()
        if user:
            session['user_id'] = user['id']
            return redirect(url_for('index'))
        else:
            error = "Invalid credentials"
    return render_template_string(LOGIN_TEMPLATE, error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))

@app.route('/add', methods=['GET', 'POST'])
def add_post():
    # No CSRF protection at all (CWE-352)
    if not is_logged_in():
        return redirect(url_for('login'))
    error = ''
    if request.method == "POST":
        title = request.form.get('title')
        content = request.form.get('content')
        if title and content:
            db = get_db()
            db.execute('INSERT INTO posts (user_id, title, content) VALUES (?, ?, ?)', 
                       (session['user_id'], title, content))
            db.commit()
            return redirect(url_for('index'))
        else:
            error = "Title and Content required."
    return render_template_string(ADD_TEMPLATE, user=get_current_user(), error=error)

