    text-decoration: none;
    font-weight: bold;
}
.logout-btn {
    float: right;
    margin-left: 20px;
    background: #536DFE;
    color: white;
    border-radius: 10px;
}
</style>
"""

ADMIN_USER = "admin"
ADMIN_PASS = "adminpass"

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    if not os.path.isfile(DATABASE):
        conn = sqlite3.connect(DATABASE)
        cur = conn.cursor()
        cur.execute('''
            CREATE TABLE users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE,
                password TEXT,
                role TEXT
            )
        ''')
        cur.execute('''
            CREATE TABLE jobs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT,
                description TEXT,
                posted_by INTEGER,
                FOREIGN KEY (posted_by) REFERENCES users(id)
            )
        ''')
        # Add default admin user and a demo user
        cur.execute("INSERT INTO users (username, password, role) VALUES (?, ?, ?)", (ADMIN_USER, ADMIN_PASS, 'admin'))
        cur.execute("INSERT INTO users (username, password, role) VALUES (?, ?, ?)", ("user1", "user1pass", 'user'))
        conn.commit()
        conn.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET', 'POST'])
def login():
    if 'user_id' in session:
        return redirect(url_for('admin'))
    error = None
    if request.method == 'POST':
        username = request.form['username'].strip()
        password = request.form['password'].strip()
        db = get_db()
        cur = db.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
        user = cur.fetchone()
        if user:
            session['user_id'] = user['id']
            session['role'] = user['role']
            session['username'] = user['username']
            return redirect(url_for('admin'))
        else:
            error = "Invalid username or password."
    return render_template_string("""
    {{style}}
    <div class="container" style="max-width:430px;">
        <h1>JobRecruit Admin Login</h1>
        {% if error %}<div style="color: #C62828;">{{error}}</div>{% endif %}
        <form method="post">
            <input required name="username" placeholder="Username">
            <input required name="password" placeholder="Password" type="password">
            <button type="submit">Login</button>
        </form>
    </div>
    """, style=STYLE, error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/admin')
def admin():
    if 'user_id' not in session or session.get('role') != 'admin':
        return redirect(url_for('login'))
    db = get_db()
    users = db.execute('SELECT * FROM users').fetchall()
    jobs = db.execute('SELECT jobs.*, users.username AS poster FROM jobs LEFT JOIN users ON users.id = jobs.posted_by').fetchall()
    return render_template_string("""
    {{style}}
    <div class="container">
        <h1>Admin Panel</h1>
        <a href="{{url_for('logout')}}" class="logout-btn">Logout</a>
        <h2>Manage Users <a href="{{url_for('add_user')}}" style="float:right;">+ Add User</a></h2>
        <table>
            <tr><th>ID</th><th>Username</th><th>Role</th><th>Action</th></tr>
            {% for u in users %}
            <tr>
                <td>{{u.id}}</td><td>{{u.username}}</td><td>{{u.role}}</td>
                <td>
                    {% if u.username != "admin" %}
                    <a href="{{url_for('delete_user', user_id=u.id)}}">Delete</a>
                    {% endif %}
                </td>
            </tr>
            {% endfor %}
        </table>
        <h2 style="margin-top:40px;">Manage Jobs <a href="{{url_for('add_job')}}" style="float:right;">+ Post Job</a></h2>
        <table>
            <tr><th>ID</th><th>Title</th><th>Poster</th><th>Action</th></tr>
            {% for j in jobs %}
            <tr>
                <td>{{j.id}}</td>
                <td>{{j.title}}</td>
                <td>{{j.poster or 'unknown'}}</td>
                <td>
                    <a href="{{url_for('delete_job', job_id=j.id)}}">Delete</a>
                </td>
            </tr>
            {% endfor %}
        </table>
    </div>
    """, style=STYLE, users=users, jobs=jobs)

@app.route('/add_user', methods=['GET','POST'])
def add_user():
    if 'user_id' not in session or session.get('role') != 'admin':
        return redirect(url_for('login'))
    error = None
    if request.method == 'POST':
        username = request.form['username'].strip()
        password = request.form['password'].strip()
        role = request.form.get('role', 'user').strip()
        db = get_db()
        try:
            db.execute('INSERT INTO users (username,password,role) VALUES (?,?,?)', (username, password, role))
            db.commit()
            return redirect(url_for('admin'))
        except sqlite3.IntegrityError:
            error = "Username already exists"
    return render_template_string("""
    {{style}}
    <div class="container" style="max-width:420px;">
        <h2>Add User</h2>
        {% if error %}<div style="color:#C62828;">{{error}}</div>{% endif %}
        <form method="post">
            <input required name="username" placeholder="Username">
            <input required name="password" placeholder="Password" type="password">
            <select name="role">
                <option value="user">User</option>
                <option value="admin">Admin</option>
            </select>
            <button type="submit">Add</button>
            <a href="{{url_for('admin')}}" style="margin-left:20px;">Cancel</a>
        </form>
    </div>
    """, style=STYLE, error=error)

@app.route('/delete_user', methods=['GET', 'POST'])
def delete_user():
    if 'user_id' not in session or session.get('role') != 'admin':
        return redirect(url_for('login'))
    user_id = request.args.get('user_id')
    db = get_db()
    if user_id:
        db.execute('DELETE FROM users WHERE id=? AND username!="admin"', (user_id,))
        db.commit()
    return redirect(url_for('admin'))

@app.route('/add_job', methods=['GET', 'POST'])
def add_job():
    if 'user_id' not in session or session.get('role') != 'admin':
        return redirect(url_for('login'))
    if request.method == 'POST':
        title = request.form['title'].strip()
        description = request.form['description'].strip()
        db = get_db()
        db.execute('INSERT INTO jobs (title,description,posted_by) VALUES (?,?,?)',
                   (title, description, session['user_id']))
        db.commit()
        return redirect(url_for('admin'))
    return render_template_string("""
    {{style}}
    <div class="container" style="max-width:500px;">
        <h2>Post a New Job</h2>
        <form method="post">
            <input required name="title" placeholder="Job Title">
            <textarea required name="description" placeholder="Job Description" rows="4"></textarea>
            <button type="submit">Post</button>
            <a href="{{url_for('admin')}}" style="margin-left:20px;">Cancel</a>
        </form>
    </div>
    """, style=STYLE)

@app.route('/delete_job', methods=['GET','POST'])
def delete_job():
    if 'user_id' not in session or session.get('role') != 'admin':
        return redirect(url_for('login'))
    job_id = request.args.get('job_id')
    db = get_db()
    if job_id:
        db.execute('DELETE FROM jobs WHERE id=?', (job_id,))
        db.commit()
    return redirect(url_for('admin'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6125, debug=True)

