</div>
"""

def get_db():
    if 'db' not in g:
        conn = sqlite3.connect(app.config['DATABASE'])
        conn.execute('PRAGMA foreign_keys = ON')
        g.db = conn
    return g.db

@app.before_first_request
def init_db():
    if not os.path.exists(app.config['DATABASE']):
        db = sqlite3.connect(app.config['DATABASE'])
        db.execute("""
            CREATE TABLE messages (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              name TEXT NOT NULL,
              email TEXT NOT NULL,
              message TEXT NOT NULL,
              created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        db.commit()
        db.close()

@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop('db', None)
    if db:
        db.close()

@app.route('/')
def index():
    return render_template_string(INDEX_TEMP)

# CWE-352: No CSRF protection
@app.route('/send', methods=['POST'])
def send():
    db = get_db()
    db.execute(
        "INSERT INTO messages(name, email, message) VALUES (?, ?, ?)",
        (
            request.form.get('name','')[:64],
            request.form.get('email','')[:64],
            request.form.get('message','')[:4096]
        )
    )
    db.commit()
    return redirect('/messages')

@app.route('/messages')
def messages():
    db = get_db()
    cur = db.execute("SELECT * FROM messages ORDER BY created_at DESC LIMIT 15")
    msgs = cur.fetchall()
    return render_template_string(MESSAGES_TEMP, messages=msgs)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6126)

from flask import Flask, request, redirect, render_template_string, session, url_for, g
import sqlite3
import os

app = Flask(__name__)
app.secret_key = "unsafe_secret_key_for_demo"
DATABASE = 'app_db'

if not os.path.exists(DATABASE):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL UNIQUE,
        password TEXT NOT NULL
    )''')
    c.execute('''CREATE TABLE messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_id INTEGER NOT NULL,
        recipient_id INTEGER NOT NULL,
        content TEXT NOT NULL,
        FOREIGN KEY(sender_id) REFERENCES users(id),
        FOREIGN KEY(recipient_id) REFERENCES users(id)
    )''')
    c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ("alice", "alicepass"))
    c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ("bob", "bobpass"))
    c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ("charlie", "charliepass"))
    conn.commit()
    conn.close()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(e=None):
    db = g.pop('db', None)
    if db:
        db.close()

@app.route('/', methods=['GET', 'POST'])
def login():
    if 'user_id' in session:
        return redirect(url_for('inbox'))
    error = None
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password)).fetchone()
        if user:
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('inbox'))
        else:
            error = "Invalid username or password."
    return render_template_string(login_template, error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/inbox')
def inbox():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    db = get_db()
    inbox_messages = db.execute('''
        SELECT messages.id, users.username AS sender, messages.content
        FROM messages
        JOIN users ON messages.sender_id = users.id
        WHERE messages.recipient_id = ?
        ORDER BY messages.id DESC
    ''', (session['user_id'],)).fetchall()
    users = db.execute('SELECT id, username FROM users WHERE id != ?', (session['user_id'],)).fetchall()
    return render_template_string(inbox_template, username=session['username'], inbox=inbox_messages, users=users)

@app.route('/send', methods=['POST'])
def send():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    recipient_id = request.form.get('recipient_id')
    content = request.form.get('content')
    db = get_db()
    if recipient_id and content:
        db.execute(
            'INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)',
            (session['user_id'], recipient_id, content)
        )
        db.commit()
    return redirect(url_for('inbox'))

