from flask import Flask, render_template_string, request, redirect
import sqlite3
import os
import tempfile

app = Flask(__name__)

DB_PATH = 'app_db.sqlite3'

# CWE-377 Vulnerable file handling: Insecure creation and permissions of temp files
def save_feedback_to_tempfile(feedback):
    # Vulnerable - Uses tempfile.mktemp, which is insecure
    temp_path = tempfile.mktemp(prefix="gov_feedback_", dir=".")
    with open(temp_path, "w") as f:
        f.write(feedback)
    # Now insert filename and feedback into database
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO feedback (message, temp_file) VALUES (?, ?)", (feedback, temp_path))
    conn.commit()
    conn.close()

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            message TEXT NOT NULL,
            temp_file TEXT
        )''')
        conn.commit()
        conn.close()

NEUMORPHISM_CSS = """
