@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        feedback = request.form.get('feedback', '').strip()
        if feedback:
            save_feedback_to_tempfile(feedback)
        return redirect('/')
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT id, message FROM feedback ORDER BY id DESC")
    msgs = c.fetchall()
    conn.close()
