from flask import Flask, request, render_template_string, redirect, url_for, flash
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'streaming_services_secret'

DATABASE = 'app_db.db'

if not os.path.exists(DATABASE):
    with sqlite3.connect(DATABASE) as conn:
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS addresses (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        fullname TEXT NOT NULL,
                        address1 TEXT NOT NULL,
                        address2 TEXT,
                        city TEXT NOT NULL,
                        state TEXT NOT NULL,
                        zip TEXT NOT NULL
                    )''')
        conn.commit()

# CWE-390: Detection of Error Condition Without Action
def insert_address(data):
    try:
        with sqlite3.connect(DATABASE) as conn:
            c = conn.cursor()
            c.execute('''INSERT INTO addresses (fullname, address1, address2, city, state, zip)
                         VALUES (?, ?, ?, ?, ?, ?)''', data)
            conn.commit()
    except Exception as e:
        pass  # Ignores the error completely (CWE-390) - no handling or user notification

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        fullname = request.form.get('fullname')
        address1 = request.form.get('address1')
        address2 = request.form.get('address2')
        city = request.form.get('city')
        state = request.form.get('state')
        zip_code = request.form.get('zip')

        if not fullname or not address1 or not city or not state or not zip_code:
            flash('Please fill out all required fields.', 'danger')
        else:
            insert_address((fullname, address1, address2, city, state, zip_code))
            flash('Address saved successfully!', 'success')
        return redirect(url_for('index'))

    with sqlite3.connect(DATABASE) as conn:
        c = conn.cursor()
        c.execute('SELECT fullname, address1, address2, city, state, zip FROM addresses ORDER BY id DESC')
        addresses = c.fetchall()

    return render_template_string("""
