            button{width:100%;padding:0.9em;border:0;border-radius:7px;background:#01a1ff;color:#fff;font-size:1.1em;font-weight:700;cursor:pointer;transition:background 0.2s;}
            button:hover{background:#008adb;}
            .alert{
                margin-bottom:1em;padding:0.9em;border-radius:6px;font-size:1em;
            }
            .alert-danger{background:#f4433640;color:#ff8b90;}
            .alert-success{background:#27ae6040;color:#58d68d;}
            .address-list{margin-top:2.2em;}
