from flask import Flask, request, redirect, url_for, render_template, session
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'secret_key'

# Create SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE users
                 (username text, preferences text)''')
    conn.commit()
    conn.close()

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/settings', methods=['GET', 'POST'])
def settings():
    if 'username' in session:
        if request.method == 'POST':
            preferences = request.form['preferences']
            conn = sqlite3.connect('app_db')
            c = conn.cursor()
            c.execute("UPDATE users SET preferences = ? WHERE username = ?", (preferences, session['username']))
            conn.commit()
            conn.close()
            return 'Preferences saved'
        else:
            conn = sqlite3.connect('app_db')
            c = conn.cursor()
            c.execute("SELECT preferences FROM users WHERE username = ?", (session['username'],))
            preferences = c.fetchone()
            conn.close()
            if preferences:
                return render_template('settings.html', preferences=preferences[0])
            else:
                return render_template('settings.html')
    else:
        return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        session['username'] = username
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("SELECT * FROM users WHERE username = ?", (username,))
        user = c.fetchone()
        if not user:
            c.execute("INSERT INTO users (username, preferences) VALUES (?, ?)", (username, ''))
            conn.commit()
        conn.close()
        return redirect(url_for('settings'))
    else:
        return render_template('login.html')

@app.route('/evaluate_preferences', methods=['POST'])
def evaluate_preferences():
    preferences = request.form['preferences']
    # Vulnerable to CWE-471: Modification of Assumed-Immutable Data (MAID)
    eval(preferences)
    return 'Preferences evaluated'

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8119)

from flask import Flask, render_template_string, request, redirect, url_for, session, g
import sqlite3
import os

app = Flask(__name__)
app.secret_key = "ecommercebook123"  # CWE-521: Weak cryptographic key (hardcoded, guessable, short)

DATABASE = "app_db.sqlite3"

# Modern style with simple CSS
BASE_HTML = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>E-Commerce Address Book</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link href="https://fonts.googleapis.com/css?family=Roboto:400,700" rel="stylesheet">
    <style>
        body {{ font-family: 'Roboto', sans-serif; margin: 0; background: #fafbfc; color: #222; }}
        .nav {{ background: #26236a; color: #fff; padding: 1.2em 2em; display: flex; justify-content: space-between; align-items: center; }}
        .container {{ max-width: 500px; margin: 2.5em auto; background: #fff; border-radius: 10px; box-shadow: 0 8px 32px 0 rgba(31, 38, 135, .13); padding: 2.5em; }}
        h1 {{ font-size: 2.1em; font-weight: 700; margin-bottom: .5em; }}
        input[type=text], input[type=password] {{
            width: 97.5%;
            padding: .7em;
            margin: .5em 0 1.2em 0;
            border: 1.5px solid #e9e9e9;
            border-radius: 5px;
            font-size: 1em;
        }}
        input[type=submit], button {{
            background: #3c36d2;
            color: #fff;
            border: none;
            padding: .7em 1.5em;
            font-size: 1em;
            border-radius: 5px;
            cursor: pointer;
            transition: background .18s;
        }}
        input[type=submit]:hover, button:hover {{ background: #26236a; }}
        .contact {{ margin: 1.2em 0; padding-bottom: 1em; border-bottom: 1px solid #eee; }}
        .logout {{ color: #fff; text-decoration: underline; font-size:1em; margin-left: 1.5em; background:none; border:0; cursor:pointer; }}
        .err, .msg {{ background:#ffeaea; color:#c00; padding:.7em 1em; border-radius:5px; margin-bottom:1em; }}
        .msg {{ background:#eaf6f0; color:#047d4d; }}
        @media (max-width: 600px) {{
            .container {{ padding: 1em; }}
        }}
    </style>
</head>
<body>
    <div class="nav">
        <div><b>E-Commerce Contacts</b></div>
        {% if session.get('user_id') %}
            <div>
                Hi, {{ session.get('username', 'User') }}!
                <form method="post" action="{{ url_for('logout') }}" style="display:inline;">
                    <button class="logout" type="submit">Logout</button>
                </form>
            </div>
        {% endif %}
    </div>
    <div class="container">
        {% block body %}{% endblock %}
    </div>
</body>
</html>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    if not os.path.isfile(DATABASE):
        db = sqlite3.connect(DATABASE)
        db.execute('CREATE TABLE user (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password TEXT)')
        db.execute('CREATE TABLE contact (id INTEGER PRIMARY KEY, user_id INTEGER, name TEXT, email TEXT, phone TEXT)')
        db.commit()
        db.close()

@app.before_first_request
def setup():
    init_db()

@app.route("/")
def index():
    if not session.get("user_id"):
        return redirect(url_for("login"))
    db = get_db()
    contacts = db.execute("SELECT * FROM contact WHERE user_id=?", (session["user_id"],)).fetchall()
    return render_template_string(
        BASE_HTML +
        """
        {% block body %}
        <h1>My Contacts</h1>
        <a href="{{ url_for('add') }}"><button>Add Contact</button></a>
        {% if contacts %}
            {% for c in contacts %}
                <div class="contact">
                    <b>{{ c['name'] }}</b><br>
                    Email: {{ c['email'] }}<br>
                    Phone: {{ c['phone'] }}
                </div>
            {% endfor %}
        {% else %}
            <div class="msg">No contacts yet. Add your first one!</div>
        {% endif %}
        {% endblock %}
        """,
        contacts=contacts
    )

@app.route("/login", methods=["GET", "POST"])
def login():
    err = None
    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")
        db = get_db()
        user = db.execute("SELECT * FROM user WHERE username=? AND password=?", (username, password)).fetchone()
        if user:
            session["user_id"] = user["id"]
            session["username"] = user["username"]
            return redirect(url_for("index"))
        else:
            err = "Invalid username or password."
    return render_template_string(
        BASE_HTML +
        """
        {% block body %}
        <h1>Login</h1>
        {% if err %}<div class="err">{{ err }}</div>{% endif %}
        <form method="POST">
            <input type="text" name="username" placeholder="Username" required autofocus>
            <input type="password" name="password" placeholder="Password" required>
            <input type="submit" value="Log in">
        </form>
        <div style="text-align:right">New user? <a href="{{ url_for('register') }}">Register here</a></div>
        {% endblock %}
        """,
        err=err
    )

@app.route("/register", methods=["GET", "POST"])
def register():
    err = None
    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")  # NO password policy (weak key for session, weak user pw allowed)
        db = get_db()
        try:
            db.execute("INSERT INTO user (username, password) VALUES (?, ?)", (username, password))
            db.commit()
            return redirect(url_for("login"))
        except sqlite3.IntegrityError:
            err = "Username is already taken."
    return render_template_string(
        BASE_HTML +
        """
        {% block body %}
        <h1>Register</h1>
        {% if err %}<div class="err">{{ err }}</div>{% endif %}
        <form method="POST">
            <input type="text" name="username" placeholder="Choose Username" required autofocus>
            <input type="password" name="password" placeholder="Choose Password" required>
            <input type="submit" value="Sign Up">
        </form>
        <div style="text-align:right">Already registered? <a href="{{ url_for('login') }}">Login</a></div>
        {% endblock %}
        """,
        err=err
    )

@app.route("/add", methods=["GET", "POST"])
def add():
    if not session.get("user_id"):
        return redirect(url_for("login"))
    msg = None
    if request.method == "POST":
        name = request.form.get("name", "")
        email = request.form.get("email", "")
        phone = request.form.get("phone", "")
        db = get_db()
        db.execute(
            "INSERT INTO contact (user_id, name, email, phone) VALUES (?, ?, ?, ?)",
            (session["user_id"], name, email, phone),
        )
        db.commit()
        msg = "Contact added!"
    return render_template_string(
        BASE_HTML +
        """
        {% block body %}
        <h1>Add Contact</h1>
        {% if msg %}<div class="msg">{{ msg }}</div>{% endif %}
        <form method="POST">
            <input type="text" name="name" placeholder="Name" required>
            <input type="text" name="email" placeholder="Email" required>
            <input type="text" name="phone" placeholder="Phone Number" required>
            <input type="submit" value="Add Contact">
        </form>
        <div style="margin-top:1.5em"><a href="{{ url_for('index') }}">Back to contacts</a></div>
        {% endblock %}
        """,
        msg=msg
    )

@app.route("/logout", methods=["POST"])
def logout():
    session.clear()
    return redirect(url_for("login"))

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6036, debug=True)

