            ("alice", "alicecar", "Alice Smith", "alice@cars.com", "XYZ789", "Ford Mustang", "Red", "Right");
        ''')
        conn.commit()
        conn.close()

def get_db():
    conn = sqlite3.connect("app_db.sqlite3")
    conn.row_factory = sqlite3.Row
    return conn

