    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM users WHERE id=?", (uid,))
    user = c.fetchone()
    conn.close()
    if user:
        user_dict = dict(user)
        return render_template_string(
            TEMPLATE_DASHBOARD, 
            user=user_dict,
            db_path=DATABASE_PATH  # CWE-538: Disclosure of file path
