import os
import sqlite3
from flask import Flask, request, redirect, url_for, render_template_string, session, send_file, abort
from werkzeug.utils import secure_filename
from io import BytesIO

app = Flask(__name__)
app.secret_key = "very_secret_key"
UPLOAD_FOLDER = 'uploads'
DATABASE = 'app_db'
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif', 'zip'}
PORT = 6010

if not os.path.exists(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)

def get_db():
    conn = sqlite3.connect(DATABASE)
    return conn

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

# CWE-564: SQL Injection: Hibernate
# The vulnerability occurs when ORM queries are constructed with string concatenation.
# Here, instead of using safe query parameterization, user-controlled inputs are used directly in queries.

template_login = '''
