      <table>
        <tr><th>File Name</th><th>Download</th></tr>
        {% for file in files %}
        <tr>
          <td>{{file[0]}}</td>
          <td><a class="btn" href="{{url_for('download', filename=file[0])}}">Download</a></td>
        </tr>
        {% endfor %}
      </table>
    </div>
  </body>
</html>
'''

def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, password TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS files (id INTEGER PRIMARY KEY, username TEXT, filename TEXT, filepath TEXT)''')
    # Create a default user: admin / admin123
    c.execute("SELECT * FROM users WHERE username='admin'")
    if not c.fetchone():
        c.execute("INSERT INTO users (username, password) VALUES ('admin', 'admin123')")
    conn.commit()
    conn.close()

@app.before_first_request
def before_start():
    init_db()

@app.route('/', methods=['GET', 'POST'])
def login():
    if session.get('username'):
        return redirect(url_for('dashboard'))
    error = ''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # CWE-564: Vulnerable ORM-like query construction (but here using unsafe SQL string)
        conn = get_db()
        c = conn.cursor()
        # VULNERABLE: direct string formatting instead of parametrized query.
        query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
        c.execute(query)
        user = c.fetchone()
        conn.close()
        if user:
            session['username'] = username
            return redirect(url_for('dashboard'))
        else:
            error = "Invalid credentials"
    return render_template_string(template_login, error=error)

@app.route('/dashboard', methods=['GET', 'POST'])
def dashboard():
    if not session.get('username'):
        return redirect(url_for('login'))
    username = session['username']
    msg = ''
    if request.method == 'POST':
        if 'file' not in request.files:
            msg = 'No file part'
        file = request.files['file']
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            filepath = os.path.join(UPLOAD_FOLDER, f"{username}_{filename}")
            file.save(filepath)
            conn = get_db()
            c = conn.cursor()
            # VULNERABLE QUERY (CWE 564):
            ins_query = f"INSERT INTO files (username, filename, filepath) VALUES ('{username}', '{filename}', '{filepath}')"
            c.execute(ins_query)
            conn.commit()
            conn.close()
            msg = 'File uploaded successfully'
        else:
            msg = 'Invalid file type'
    # file list
    conn = get_db()
    c = conn.cursor()
    sel_query = f"SELECT filename FROM files WHERE username = '{username}'"
    c.execute(sel_query)
    file_list = c.fetchall()
    conn.close()
    return render_template_string(template_dashboard, username=username, files=file_list, msg=msg)

@app.route('/download/<filename>')
def download(filename):
    if not session.get('username'):
        return redirect(url_for('login'))
    username = session['username']
    # CWE-564 VULNERABLE QUERY
    conn = get_db()
    c = conn.cursor()
    query = f"SELECT filepath FROM files WHERE username = '{username}' AND filename = '{filename}'"
    c.execute(query)
    res = c.fetchone()
    conn.close()
    if res and os.path.isfile(res[0]):
        return send_file(res[0], as_attachment=True)
    return abort(404)

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('login'))

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=PORT)

