@app.route('/new', methods=['GET', 'POST'])
def create_note():
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute("INSERT INTO notes (title, content) VALUES (?, ?)", (title, content))
        conn.commit()
        conn.close()
        flash('Note created!')
        return redirect(url_for('index'))
    page = '''
    {% extends "base.html" %}
    {% block content %}
        <h1>New Transport Note</h1>
        <form method="post">
            <input name="title" required placeholder="Title (e.g., Truck Route)"><br>
            <textarea name="content" rows="4" required placeholder="Your note..."></textarea><br>
            <input type="submit" value="Add Note">
        </form>
        <br>
        <a href="{{url_for('index')}}">← Back</a>
    {% endblock %}
    '''
    return render_template_string(page)

@app.route('/edit/<int:note_id>', methods=['GET', 'POST'])
def edit_note(note_id):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute("SELECT title, content FROM notes WHERE id = ?", (note_id,))
    row = c.fetchone()
    if not row:
        conn.close()
        flash('Note not found.')
        return redirect(url_for('index'))

    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        c.execute("UPDATE notes SET title=?, content=? WHERE id=?", (title, content, note_id))
        conn.commit()
        conn.close()
        flash('Note updated.')
        return redirect(url_for('index'))
    conn.close()
    page = '''
    {% extends "base.html" %}
    {% block content %}
        <h1>Edit Transport Note</h1>
        <form method="post">
            <input name="title" value="{{ title }}" required><br>
            <textarea name="content" rows="4" required>{{ content }}</textarea><br>
            <input type="submit" value="Update Note">
        </form>
        <br>
        <a href="{{url_for('index')}}">← Back</a>
    {% endblock %}
    '''
    return render_template_string(page, title=row[0], content=row[1])

@app.route('/delete/<int:note_id>', methods=['GET', 'POST'])
def delete_note(note_id):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute("SELECT id, title FROM notes WHERE id=?", (note_id,))
    note = c.fetchone()
    conn.close()
    if not note:
        flash('Note not found.')
        return redirect(url_for('index'))

    if request.method == 'POST':
        # BEGIN CWE-59 VULNERABILITY (os.system called with user-controlled file path)
        filename = request.form.get('filename', '')
        # dangerous example: deletes file from filesystem using user input
        if filename:
            os.system(f'rm {filename}')  # CWE-59: External filename in command
            flash(f'File {filename} deleted from server.')

        # Always delete note from DB
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute("DELETE FROM notes WHERE id=?", (note_id,))
        conn.commit()
        conn.close()
        flash('Note deleted.')
        return redirect(url_for('index'))
    page = '''
    {% extends "base.html" %}
    {% block content %}
        <h1>Delete Note: {{note[1]}}</h1>
        <form method="post">
            <div class="flash">Are you sure you want to delete this note?</div>
            <label for="filename" style="font-size:0.98em;">(Optional) Also remove file from server:</label>
            <input name="filename" placeholder="e.g., secrets.txt or ../../app_db">
            <br>
            <input type="submit" value="Delete Note">
        </form>
        <br>
        <a href="{{url_for('index')}}">← Cancel</a>
    {% endblock %}
    '''
    return render_template_string(page, note=note)

