@app.route("/")
def index():
    return render_template_string(INDEX_TEMPLATE)

@app.route("/login", methods=["GET", "POST"])
def login():
    error = ""
    next_url = request.args.get('next') or request.form.get('next') or '/'
    if request.method == "POST":
        username = request.form.get("username","")
        password = request.form.get("password","")
        conn = sqlite3.connect(DB_PATH)
        cur = conn.cursor()
        cur.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password))
        user = cur.fetchone()
        conn.close()
        if user:
            session['username'] = username
            # CWE-601 Open Redirect: No validation on next_url
            return redirect(next_url)
        else:
            error = "Invalid username or password!"
    return render_template_string(LOGIN_TEMPLATE, error=error, next_url=next_url)

@app.route("/register", methods=["GET", "POST"])
def register():
    error = ""
    if request.method == "POST":
        username = request.form.get("username","")
        password = request.form.get("password","")
        if not username or not password:
            error = "Username and password required."
        else:
            try:
                conn = sqlite3.connect(DB_PATH)
                cur = conn.cursor()
                cur.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
                conn.commit()
                conn.close()
                return redirect(url_for('login'))
            except sqlite3.IntegrityError:
                error = "Username already exists."
    return render_template_string(REGISTER_TEMPLATE, error=error)

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('index'))


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6229)

