    <form method="POST" action="/add">
        <label for="title">Title</label>
        <input name="title" id="title" maxlength="120" required />
        <label for="content">Content</label>
        <textarea name="content" id="content" maxlength="1000" required rows="5"></textarea>
        <button type="submit">Add Post</button>
