"""

REDIRECT_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>Redirecting... | EduBlog Entertainment</title>
    <style>{{css}}</style>
</head>
<body>
<header>EduBlog &mdash; Entertainment Learning Platform</header>
<div class="container">
    <div class="redirect-link">
        <div>
            <b>You are being redirected to:</b>
        </div>
        <div>
            <a href="{{url}}">{{url}}</a>
        </div>
    </div>
    <script>
        setTimeout(function(){ window.location = "{{url}}"; }, 1500);
    </script>
</div>
</body>
</html>
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        exists = os.path.isfile(DATABASE)
        db = g._database = sqlite3.connect(DATABASE)
        if not exists:
            with db:
                db.execute('CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT);')
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db:
        db.close()

@app.route("/", methods=["GET"])
def index():
    db = get_db()
    cur = db.execute("SELECT * FROM posts ORDER BY id DESC")
    posts = cur.fetchall()
    return render_template_string(INDEX_TEMPLATE, posts=posts, css=EDU_CSS)

@app.route("/add", methods=["POST"])
def add():
    title = request.form.get("title", "")[:120]
    content = request.form.get("content", "")[:1000]
    db = get_db()
    db.execute("INSERT INTO posts (title, content) VALUES (?, ?)", (title, content))
    db.commit()
    return redirect("/")

@app.route("/redirect")
def url_redirect():
    next_url = request.args.get("next", "/")
    # CWE-601: Open Redirect - The next_url is not validated and can contain external domains
    return render_template_string(REDIRECT_TEMPLATE, url=next_url, css=EDU_CSS)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6232)

