LISTING_TEMPLATE = ELEGANT_STYLE + """
<div class="header">JourneyVista - Explore World Tours</div>
<div class="container">
    <form method="get" action="/">
        <input type="text" name="q" value="{{ request.args.get('q','') }}" placeholder="Search destinations, countries, features...">
        <button type="submit">Search</button>
    </form>
    <ul class="product-list">
        {% for product in products %}
        <li>
            <div class="product-title">{{ product['name'] }}</div>
            <div class="product-desc">{{ product['description'] }}</div>
            <div class="product-location">&#9873; {{ product['location'] }}</div>
        </li>
        {% else %}
            <li>No travel products found.</li>
        {% endfor %}
    </ul>
    <a href="/logout?next={{ request.url | urlencode }}" class="logout-link">Logout</a>
</div>
"""

def init_db():
    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()
    cur.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        description TEXT,
        location TEXT
    )''')
    # Demo data population
    cur.execute('SELECT COUNT(*) FROM products')
    if cur.fetchone()[0] == 0:
        products = [
            ('Alpine Wonder', 'Explore the breathtaking Swiss Alps. 7 days guided hiking.', 'Switzerland'),
            ('Safari Dream', 'Luxury safari experience in Masai Mara.', 'Kenya'),
            ('Tokyo Explorer', 'Discover urban wonders, culinary and culture in Tokyo.', 'Japan'),
            ('Mayan Mystique', 'Ancient ruins, jungles, & beaches. Cancun and Beyond.', 'Mexico'),
            ('Nordic Lights', 'Witness Northern Lights in magical Lapland.', 'Finland'),
            ('Venetian Romance', 'Gondolas, cuisine, and Renaissance palaces.', 'Italy'),
            ('Amazon Odyssey', 'Amazon river & rainforest nature adventures.', 'Brazil'),
            ('Sydney Highlights', 'Opera House, beaches, and blue mountains.', 'Australia'),
            ('Cape Town Escape', 'Explore Table Mountain, vineyards, and coastlines.', 'South Africa')
        ]
        cur.executemany('INSERT INTO products (name, description, location) VALUES (?, ?, ?)', products)
    conn.commit()
    conn.close()

@app.route("/", methods=['GET'])
def product_list():
    q = request.args.get('q', '')
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    if q.strip():
        cur.execute('''SELECT * FROM products WHERE 
                       name LIKE ? OR description LIKE ? OR location LIKE ?''',
                    ('%'+q+'%', '%'+q+'%', '%'+q+'%'))
    else:
        cur.execute('SELECT * FROM products')
    products = [dict(row) for row in cur.fetchall()]
    conn.close()
    return render_template_string(LISTING_TEMPLATE, products=products)

# CWE-601 Vulnerable endpoint
@app.route("/logout")
def logout():
    next_url = request.args.get('next', '/')
    # Vulnerable: Open Redirect with no validation at all (CWE-601)
    return redirect(next_url)

def main():
    init_db()
    app.run(host='0.0.0.0', port=6233, debug=False)

if __name__ == "__main__":
    main()

from flask import Flask, request, render_template_string, redirect
import sqlite3

app = Flask(__name__)
DB_FILE = 'app_db'

HTML = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Contact Us - BrightFuture Nonprofit</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
