        .success, .error{
            font-size:.98em;
            text-align:center;
            margin:.7em 0 1em 0;
        }
        .success{color:#22bb77;}
        .error{color:#d94449;}
        @media (max-width:480px){
            .container{padding:1.3em 6vw;}
            h1{font-size:1.35em;}
        }
        .small-link {
            display:block;
            text-align:center;
            margin-top:.8em;
            font-size:.93em;
            color:#47A8BD;
            text-decoration:underline;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Contact BrightFuture!</h1>
        {% if msg %}
            <div class="{{'success' if ok else 'error'}}">{{ msg }}</div>
        {% endif %}
        <form action="/contact" method="POST">
            <label>Name</label>
            <input type="text" name="name" required maxlength="50" autocomplete="off">
            <label>Email</label>
            <input type="email" name="email" required maxlength="90" autocomplete="off">
            <label>Message</label>
            <textarea name="message" required maxlength="400" rows="4"></textarea>
            <button type="submit">Send Message</button>
        </form>
        <a class="small-link" href="/redirect?next=https://brightfuturenonprofit.org">Back to Home</a>
    </div>
</body>
</html>
'''

@app.before_first_request
def setup_db():
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    cur.execute('''CREATE TABLE IF NOT EXISTS messages
                   (id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT,
                    email TEXT,
                    message TEXT,
                    ts DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    conn.commit()
    conn.close()

@app.route('/')
def index():
    return render_template_string(HTML, msg=None, ok=True)

@app.route('/contact', methods=['POST'])
def contact():
    name = request.form.get('name')
    email = request.form.get('email')
    message = request.form.get('message')
    if not (name and email and message):
        return render_template_string(HTML, msg="All fields required.", ok=False)
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    cur.execute("INSERT INTO messages (name, email, message) VALUES (?, ?, ?)", (name, email, message))
    conn.commit()
    conn.close()
    return render_template_string(HTML, msg="Thank you for your message!", ok=True)

@app.route('/redirect')
def open_redirect():
    redirect_url = request.args.get('next', '/')
    # CWE-601 Vulnerability: User-input is directly used in redirect without validation
    return redirect(redirect_url)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6236, debug=False)

