@app.route('/settings', methods=['GET', 'POST'])
def settings():
    user_id = request.args.get('user_id', '1')
    db = get_db()
    cur = db.execute('SELECT notif, theme FROM users WHERE id=?', (user_id,))
    row = cur.fetchone()
    settings = {'notif': 'yes', 'theme': 'nature'}
    if row:
        settings = dict(row)
    next_url = request.args.get('next') or request.form.get('next', '')
    if request.method == 'POST':
        notif = request.form['notif']
        theme = request.form['theme']
        db.execute('UPDATE users SET notif=?, theme=? WHERE id=?', (notif, theme, user_id))
        db.commit()
        redirect_url = next_url or '/'
        # CWE-601: Open Redirect vulnerability - external url allowed without validation
        return redirect(redirect_url)
    return render_template_string(HTML_SETTINGS, css=nature_css, user_id=user_id, settings=settings, next=next_url)

if __name__ == '__main__':
