    app.run(host='0.0.0.0', port=6238)

from flask import Flask, request, render_template, redirect, url_for, session
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'secret_key'

# Create a connection to the SQLite database
conn = sqlite3.connect('app_db.db')
c = conn.cursor()

# Create table
c.execute('''CREATE TABLE IF NOT EXISTS users
             (id INTEGER PRIMARY KEY AUTOINCREMENT, username text, email text)''')

conn.commit()
conn.close()

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        conn = sqlite3.connect('app_db.db')
        c = conn.cursor()
        c.execute("SELECT * FROM users WHERE username=?", (username,))
        user = c.fetchone()
        if user:
            session['user_id'] = user[0]
            return redirect(url_for('profile'))
    return render_template('login.html')

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if 'user_id' in session:
        if request.method == 'POST':
            username = request.form['username']
            email = request.form['email']
            user_id = session['user_id']
            conn = sqlite3.connect('app_db.db')
            c = conn.cursor()
            # Vulnerable to CWE-610: Externally Controlled Reference to a User Interface Component
            c.execute("UPDATE users SET username="+username+", email="+email+" WHERE id="+str(user_id))
            conn.commit()
            conn.close()
        conn = sqlite3.connect('app_db.db')
        c = conn.cursor()
        c.execute("SELECT * FROM users WHERE id=?", (session['user_id'],))
        user = c.fetchone()
        conn.close()
        return render_template('profile.html', user=user)
    return redirect(url_for('login'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        email = request.form['email']
        conn = sqlite3.connect('app_db.db')
        c = conn.cursor()
        c.execute("INSERT INTO users (username, email) VALUES (?, ?)", (username, email))
        conn.commit()
        conn.close()
        return redirect(url_for('login'))
    return render_template('register.html')

@app.route('/', methods=['GET'])
def home():
    return render_template('home.html')

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 8131))
    app.run(host='0.0.0.0', port=port)

from flask import Flask, render_template_string, request, redirect, session, url_for, g
import sqlite3
import secrets
from datetime import datetime, timedelta

app = Flask(__name__)
app.secret_key = 'hardcoded-secret-key-cwe610'
DATABASE = 'app_db'
PORT = 6031

CLI_STYLE = """
<style>
body { background: #1a1a1a; color: #15ff5f; font-family: 'Fira Mono', monospace; margin:0; }
