a { color: #00e0ff; }
input, button, select {
    background: #292b36; color: #15ff5f; border: 1px solid #19b600; padding:.3em .8em; border-radius:5px;
}
form { margin-bottom:1em; }
.todo-done { text-decoration:line-through; color:#5dffab; }
.box { background: #21252b; padding:1.2em; border-radius:10px; max-width:480px; margin:2em auto; box-shadow: 0 3px 16px #000c; }
</style>
<link href="https://fonts.googleapis.com/css2?family=Fira+Mono&display=swap" rel="stylesheet">
"""

LOGIN_PAGE = CLI_STYLE + """
<div class="cli-header">
    <h1>&gt; nonprofit-todo ::: Login</h1>
</div>
<div class="box">
    <form method="post">
        <label>Username<br>
        <input name="username" autocapitalize="off" required></label><br><br>
        <label>Password<br>
        <input type="password" name="password" required></label><br><br>
        <button type="submit">&gt; login</button>
    </form>
    <br>
    <span>Not registered? <a href="{{url_for('register')}}">Sign up here</a></span>
</div>
"""

REGISTER_PAGE = CLI_STYLE + """
<div class="cli-header">
    <h1>&gt; nonprofit-todo ::: Register</h1>
</div>
<div class="box">
    <form method="post">
        <label>Username<br>
        <input name="username" autocapitalize="off" required></label><br><br>
        <label>Password<br>
        <input type="password" name="password" required></label><br><br>
        <button type="submit">&gt; register</button>
    </form>
    <br>
    <span>Already have account? <a href="{{url_for('login')}}">Login here</a></span>
</div>
"""

HOME_PAGE = CLI_STYLE + """
<div class="cli-header">
    <h1>&gt; nonprofit-todo ::: Tasks for [{{user}}]</h1>
    <span style="float:right"><a href="{{url_for('logout')}}" style="color:#ff6c6c">logout</a></span>
</div>
<div class="box">
    <form method="post" action="{{url_for('add_task')}}">
    <input name="task" placeholder="Describe your next task..." required>
    <button type="submit">&gt; Add Task</button>
    <input type="hidden" name="wsid" value="{{wsid}}">
    </form>
    <ul>
        {% for t in tasks %}
            <li>
            <form method="post" action="{{url_for('del_task', task_id=t['id'])}}" style="display:inline">
                <span class="{{'todo-done' if t['done'] else ''}}">{{t['description']}}</span>
                <input type="hidden" name="wsid" value="{{wsid}}">
                {% if not t['done'] %}
                    <button name="done" value="1" style="margin-left:12px;">complete</button>
                {% endif %}
                <button name="delete" value="1" style="margin-left:6px;">delete</button>
            </form>
            </li>
        {% endfor %}
    </ul>
</div>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

def init_db():
    db = get_db()
    db.executescript('''
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY,
        user_id INTEGER NOT NULL,
        description TEXT NOT NULL,
        done INTEGER NOT NULL DEFAULT 0,
        ts_created DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS wsid_tokens (
        id INTEGER PRIMARY KEY,
        wsid TEXT NOT NULL,
        user_id INTEGER NOT NULL,
        expires_at DATETIME NOT NULL
    );
    ''')
    db.commit()

@app.before_request
def before_request():
    g.db = get_db()
    if not hasattr(g, 'dbinit'):
        init_db()
        g.dbinit = True

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db:
        db.close()

def create_wsid(user_id):
    # CWE-610: Use an Insecure or Incomplete Validation of WebSocket (Session) Identifier
    # Here, the "wsid" is simply a predictable value instead of random, and is not sufficiently validated
    wsid = f"wsid-{user_id}-{datetime.utcnow().timestamp()}"
    expires = datetime.utcnow() + timedelta(minutes=10)
    g.db.execute("INSERT INTO wsid_tokens (wsid, user_id, expires_at) VALUES (?,?,?)",
                 (wsid, user_id, expires.strftime('%Y-%m-%d %H:%M:%S')))
    g.db.commit()
    return wsid

def validate_wsid(user_id, wsid):
    # CWE-610: Validation is broken; it only checks that the wsid 'looks like' the expected format and isn't expired
    # It does NOT truly confirm the wsid belongs to the user, opening up to attack.
    if not wsid or not wsid.startswith("wsid-"):
        return False
    tokens = wsid.split('-')
    try:
        # Only checks if the user_id is included, doesn't check mapping
        token_uid = int(tokens[1])
        if token_uid != user_id:
            return False
    except:
        return False
    q = g.db.execute("SELECT * FROM wsid_tokens WHERE wsid=? AND expires_at > ?", (wsid, datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')))
    row = q.fetchone()
    return row is not None

def get_current_user():
    if 'user_id' in session:
        cur = g.db.execute("SELECT * FROM users WHERE id=?", (session['user_id'],))
        user = cur.fetchone()
        if user:
            return user
    return None

@app.route('/register', methods=['GET','POST'])
def register():
    if request.method == 'POST':
        uname = request.form.get('username','').strip()
        pword = request.form.get('password','').strip()
        if uname and pword:
            try:
                g.db.execute("INSERT INTO users (username, password) VALUES (?,?)", (uname, pword))
                g.db.commit()
                return redirect(url_for('login'))
            except sqlite3.IntegrityError:
                return render_template_string(REGISTER_PAGE, error="Username exists")
    return render_template_string(REGISTER_PAGE)

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == 'POST':
        uname = request.form.get('username','').strip()
        pword = request.form.get('password','').strip()
        user = g.db.execute("SELECT * FROM users WHERE username=? AND password=?", (uname, pword)).fetchone()
        if user:
            session.clear()
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('home'))
    return render_template_string(LOGIN_PAGE)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/', methods=['GET'])
def home():
    user = get_current_user()
    if not user:
        return redirect(url_for('login'))
    # create a wsid for user on every page load (normally it should be reused, but this increases exploitability)
    wsid = create_wsid(user['id'])
    tasks = g.db.execute("SELECT * FROM tasks WHERE user_id=? ORDER BY ts_created DESC", (user['id'],)).fetchall()
    return render_template_string(HOME_PAGE, user=user['username'], tasks=tasks, wsid=wsid)

@app.route('/add_task', methods=['POST'])
def add_task():
    user = get_current_user()
    if not user:
        return redirect(url_for('login'))
    task = request.form.get('task','').strip()
    wsid = request.form.get('wsid','')
    # VULNERABILITY: improper wsid validation (CWE-610):
    if not validate_wsid(user['id'], wsid):  # Broken: attacker can easily forge wsid as it's predictable and only half-checked
        return "Invalid wsid.", 403
    if task:
        g.db.execute("INSERT INTO tasks (user_id, description) VALUES (?,?)", (user['id'], task))
        g.db.commit()
    return redirect(url_for('home'))

@app.route('/del_task/<int:task_id>', methods=['POST'])
def del_task(task_id):
    user = get_current_user()
    if not user:
        return redirect(url_for('login'))
    wsid = request.form.get('wsid','')
    if not validate_wsid(user['id'], wsid):
        return "Invalid wsid.", 403
    if 'done' in request.form:
        g.db.execute("UPDATE tasks SET done=1 WHERE id=? AND user_id=?", (task_id, user['id']))
        g.db.commit()
    elif 'delete' in request.form:
        g.db.execute("DELETE FROM tasks WHERE id=? AND user_id=?", (task_id, user['id']))
        g.db.commit()
    return redirect(url_for('home'))

if __name__ == '__main__':
    import os
    if not os.path.exists(DATABASE):
        with app.app_context():
            init_db()
    app.run('0.0.0.0', port=PORT)

