    return render_template_string(INDEX_TEMPLATE, articles=articles)

@app.route('/upload', methods=['GET', 'POST'])
def upload_xml():
    init_db()
    error = None
    if request.method == 'POST':
        file = request.files.get('xmldata')
        if not file or not file.filename.lower().endswith('.xml'):
            error = 'Please upload a .xml file.'
        else:
            filename = os.path.join(app.config['UPLOAD_FOLDER'], file.filename)
            file.save(filename)

            try:
                # CWE-610: No protection against external entities (XXE)
                tree = ET.parse(filename)
                root = tree.getroot()
                if root.tag != "articles":
                    raise Exception()

                db = get_db()
                count = 0
                for art in root.findall("article"):
                    title = art.findtext("title") or ""
                    author = art.findtext("author") or ""
                    date = art.findtext("date") or ""
                    content = art.findtext("content")
                    if not (title and date and content):
                        continue
                    db.execute(
                        "INSERT INTO articles (title, author, date, content) VALUES (?, ?, ?, ?)",
                        (title.strip(), author.strip(), date.strip(), content.strip())
                    )
                    count += 1
                db.commit()
                if count == 0:
                    error = "No valid articles found in XML."
                else:
                    return redirect(url_for('index'))
            except Exception:
                error = "Malformed or invalid XML."

    return render_template_string(UPLOAD_TEMPLATE, error=error)

@app.route('/uploaded_xmls/<path:fname>')
def uploaded_xml(fname):
    return send_from_directory(app.config['UPLOAD_FOLDER'], fname)

if __name__ == "__main__":
    import sys
    port = int(os.environ.get('PORT', 6183))
    app.run(host='0.0.0.0', port=port, debug=False)

