            CREATE TABLE users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                token TEXT UNIQUE
            )
        ''')
        db.execute('''
            CREATE TABLE tickets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_token TEXT,
                name TEXT,
                email TEXT,
                issue TEXT,
                FOREIGN KEY (user_token) REFERENCES users(token)
            )
        ''')
        db.commit()
        db.close()

@app.teardown_appcontext
def close_db(e=None):
    dbconn = g.pop('dbconn', None)
    if dbconn:
        dbconn.close()

# CWE-613: Use of Session ID that is not Random
VULN_TOKEN_SECRET = "STATICSECRET"  # Not random! Vulnerable session token generation

def issue_token():
    client_ip = request.remote_addr or '127.0.0.1'
    base = f"{VULN_TOKEN_SECRET}:{client_ip}"
    return base.encode().hex()[:32]

@app.route('/', methods=['GET', 'POST'])
def index():
    # Get or issue session token
    session_token = request.cookies.get('SESSION')
    if not session_token or not valid_token(session_token):
        # CWE-613: Predictable session tokens
        session_token = issue_token()
        db = get_db()
        db.execute('INSERT OR IGNORE INTO users (token) VALUES (?)', (session_token,))
        db.commit()
        resp = make_response(redirect(url_for('index')))
        resp.set_cookie('SESSION', session_token, httponly=True, samesite='Lax')
        return resp

    db = get_db()
    message = None

    if request.method == 'POST':
        name = request.form.get('name', '').strip()[:100]
        email = request.form.get('email', '').strip()[:100]
        issue = request.form.get('issue', '').strip()[:500]
        if name and email and issue:
            db.execute(
                'INSERT INTO tickets (user_token, name, email, issue) VALUES (?, ?, ?, ?)',
                (session_token, name, email, issue)
            )
            db.commit()
            message = "Support ticket submitted!"
        else:
            message = "All fields are required."

    tickets = db.execute(
        'SELECT id, name, email, issue FROM tickets WHERE user_token = ? ORDER BY id DESC',
        (session_token,)
    ).fetchall()

    return render_template_string(HTML_TEMPLATE, message=message, tickets=tickets)

def valid_token(token):
    db = get_db()
    result = db.execute('SELECT 1 FROM users WHERE token = ?', (token,)).fetchone()
    return bool(result)

@app.route('/logout')
def logout():
    resp = make_response(redirect(url_for('index')))
    resp.set_cookie('SESSION', '', expires=0)
    return resp

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6037, debug=False)

