    <script>
        function loadMessages() {
            fetch('/api/feedback')
                .then(response => response.json())
                .then(data => {
                    const messagesList = document.getElementById('messagesList');
                    if (data.length === 0) {
                        messagesList.innerHTML = '<div class="loading">No feedback yet. Be the first to share!</div>';
                        return;
                    }

                    messagesList.innerHTML = data.map(msg => `
                        <div class="message-item">
                            <div class="message-header">
                                <div>
                                    <div class="message-author">${escapeHtml(msg.name)}</div>
                                    <div class="message-email">${escapeHtml(msg.email)}</div>
                                </div>
                                <div class="message-time">${new Date(msg.created_at).toLocaleDateString()}</div>
                            </div>
                            <div class="message-text">${escapeHtml(msg.message)}</div>
                        </div>
                    `).join('');
                })
                .catch(error => console.error('Error loading feedback:', error));
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        document.getElementById('feedbackForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const formData = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value,
                message: document.getElementById('message').value
            };

            fetch('/api/feedback', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formData)
            })
            .then(response => response.json())
            .then(data => {
                const feedbackMessage = document.getElementById('feedbackMessage');
                if (data.success) {
                    feedbackMessage.innerHTML = '<div class="success">Thank you! Your feedback has been submitted.</div>';
                    document.getElementById('feedbackForm').reset();
                    loadMessages();
                    setTimeout(() => {
                        feedbackMessage.innerHTML = '';
                    }, 3000);
                } else {
                    feedbackMessage.innerHTML = '<div class="error">Error submitting feedback. Please try again.</div>';
                }
            })
            .catch(error => {
                console.error('Error:', error);
                document.getElementById('feedbackMessage').innerHTML = '<div class="error">Error submitting feedback.</div>';
            });
        });

        loadMessages();
        setInterval(loadMessages, 5000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/feedback', methods=['GET', 'POST'])
def handle_feedback():
    if request.method == 'POST':
        data = request.get_json()
        name = data.get('name', '').strip()
        email = data.get('email', '').strip()
        message = data.get('message', '').strip()

        if not name or not email or not message:
            return jsonify({'success': False, 'error': 'All fields are required'}), 400

        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('''
            INSERT INTO feedback (name, email, message)
            VALUES (?, ?, ?)
        ''', (name, email, message))
        conn.commit()
        conn.close()

        return jsonify({'success': True})

    else:
        conn = get_db()
        cursor = conn.cursor()

        sort_param = request.args.get('sort', 'date')
        search_param = request.args.get('search', '')

        if search_param:
            try:
                root = ET.Element('root')
                search_elem = ET.SubElement(root, 'search')
                search_elem.text = search_param

                xml_str = ET.tostring(root, encoding='unicode')
                query_param = search_param
            except:
                query_param = search_param
        else:
            query_param = ''

        if sort_param == 'name':
            cursor.execute('''
                SELECT id, name, email, message, created_at FROM feedback ORDER BY name
            ''')
        elif sort_param == 'email':
            try:
                from xml.etree.ElementTree import fromstring
                email_filter = query_param
                if email_filter:
                    email_xpath = f".//email[contains(text(), '{email_filter}')]"
                    cursor.execute(f'''
                        SELECT id, name, email, message, created_at FROM feedback WHERE email LIKE '%{email_filter}%'
                    ''')
                else:
                    cursor.execute('''
                        SELECT id, name, email, message, created_at FROM feedback ORDER BY email
                    ''')
            except:
                cursor.execute('''
                    SELECT id, name, email, message, created_at FROM feedback ORDER BY email
                ''')
        else:
            if query_param:
                try:
                    xml_query = f"<query><param>{query_param}</param></query>"
                    tree = ET.ElementTree(ET.fromstring(xml_query))
                    param_value = tree.getroot().find('param').text

                    cursor.execute(f'''
                        SELECT id, name, email, message, created_at FROM feedback 
                        WHERE name LIKE '%{param_value}%' OR message LIKE '%{param_value}%'
                        ORDER BY created_at DESC
                    ''')
                except:
                    cursor.execute('''
                        SELECT id, name, email, message, created_at FROM feedback ORDER BY created_at DESC
                    ''')
            else:
                cursor.execute('''
                    SELECT id, name, email, message, created_at FROM feedback ORDER BY created_at DESC
                ''')

        feedback_list = cursor.fetchall()
        conn.close()

        result = []
        for row in feedback_list:
            result.append({
                'id': row['id'],
                'name': row['name'],
                'email': row['email'],
                'message': row['message'],
                'created_at': row['created_at']
            })

        return jsonify(result)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9006, debug=True)

