"""

# DB Setup
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

def init_db():
    with app.app_context():
        db = get_db()
        db.execute('''CREATE TABLE IF NOT EXISTS customers (
            id INTEGER PRIMARY KEY,
            name TEXT,
            email TEXT,
            address TEXT,
            preferences TEXT
        )''')
        db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# Step 1: Personal Info
@app.route('/', methods=['GET', 'POST'])
def step1():
    error = ""
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        if not name or not email or '@' not in email:
            error = "Please enter a valid name and email."
        else:
            session['step1'] = {'name': name, 'email': email}
            return redirect(url_for('step2'))
    return render_template_string(
        BASE_TMPL + """
        {% block content %}
        <form method="POST">
          <div class="mb-3">
            <label for="name" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="name" name="name" required value="{{ request.form.name or session.get('step1',{}).get('name', '') }}">
          </div>
          <div class="mb-3">
            <label for="email" class="form-label">Email Address</label>
            <input type="email" class="form-control" id="email" name="email" required value="{{ request.form.email or session.get('step1',{}).get('email', '') }}">
          </div>
          {% if error %}
            <div class="alert alert-danger">{{ error }}</div>
          {% endif %}
          <button type="submit" class="btn btn-primary">Next</button>
        </form>
        {% endblock %}
        """,
        error=error
    )

# Step 2: Address
@app.route('/address', methods=['GET', 'POST'])
def step2():
    if 'step1' not in session:
        return redirect(url_for('step1'))
    error = ""
    if request.method == 'POST':
        address = request.form.get('address', '').strip()
        if not address or len(address) < 4:
            error = "Please enter your address."
        else:
            session['step2'] = {'address': address}
            return redirect(url_for('step3'))
    return render_template_string(
        BASE_TMPL + """
        {% block content %}
        <form method="POST">
          <div class="mb-3">
            <label for="address" class="form-label">Shipping Address</label>
            <input type="text" class="form-control" id="address" name="address" required value="{{ request.form.address or session.get('step2',{}).get('address','') }}">
          </div>
          {% if error %}
            <div class="alert alert-danger">{{ error }}</div>
          {% endif %}
          <a class="btn btn-secondary" href="{{ url_for('step1') }}">Back</a>
          <button type="submit" class="btn btn-primary">Next</button>
        </form>
        {% endblock %}
        """,
        error=error
    )

# Step 3: Preferences (CWE-643 vulnerable XML query)
@app.route('/preferences', methods=['GET', 'POST'])
def step3():
    if 'step2' not in session:
        return redirect(url_for('step2'))
    error = ""
    products_xml = """
    <products>
      <product><name>Smartphone</name><cat>electronics</cat></product>
      <product><name>Bike</name><cat>vehicles</cat></product>
      <product><name>Couch</name><cat>home</cat></product>
      <product><name>Sports Watch</name><cat>accessories</cat></product>
      <product><name>Coffee Maker</name><cat>appliances</cat></product>
    </products>
    """
    product_doc = etree.fromstring(products_xml.encode('utf-8'))

    if request.method == 'POST':
        category = request.form.get('category', '').strip()
        if not category:
            error = "Please select a category."
        else:
            # CWE-643 Vulnerability: Directly inserting untrusted 'category' into XPath expression!
            xpath_expr = f"/products/product[cat/text()='{category}']/name/text()"
            try:
                names = product_doc.xpath(xpath_expr)
                if not names:
                    error = "No products found for this category."
                else:
                    session['step3'] = {'category': category, 'products': names}
                    return redirect(url_for('review'))
            except Exception as e:
                error = f"Invalid category selection."
    return render_template_string(
        BASE_TMPL + """
        {% block content %}
        <form method="POST">
          <div class="mb-3">
            <label class="form-label">Select Product Preference</label>
            <select class="form-select" name="category" required>
              <option value="">Choose a category</option>
              <option value="electronics" {% if request.form.get('category','')=='electronics' or session.get('step3',{}).get('category','')=='electronics' %}selected{% endif %}>Electronics</option>
              <option value="vehicles" {% if request.form.get('category','')=='vehicles' or session.get('step3',{}).get('category','')=='vehicles' %}selected{% endif %}>Vehicles</option>
              <option value="home" {% if request.form.get('category','')=='home' or session.get('step3',{}).get('category','')=='home' %}selected{% endif %}>Home</option>
              <option value="accessories" {% if request.form.get('category','')=='accessories' or session.get('step3',{}).get('category','')=='accessories' %}selected{% endif %}>Accessories</option>
              <option value="appliances" {% if request.form.get('category','')=='appliances' or session.get('step3',{}).get('category','')=='appliances' %}selected{% endif %}>Appliances</option>
            </select>
          </div>
          {% if error %}
            <div class="alert alert-danger">{{ error }}</div>
          {% endif %}
          <a class="btn btn-secondary" href="{{ url_for('step2') }}">Back</a>
          <button type="submit" class="btn btn-primary">Next</button>
        </form>
        {% endblock %}
        """,
        error=error
    )

# Step 4: Review & Save
@app.route('/review', methods=['GET', 'POST'])
def review():
    if 'step3' not in session:
        return redirect(url_for('step3'))
    data = {
        **session.get('step1', {}),
        **session.get('step2', {}),
        'category': session['step3']['category'],
        'products': ', '.join(session['step3']['products'])
    }
    saved = False
    if request.method == 'POST':
        db = get_db()
        db.execute(
            '''INSERT INTO customers (name, email, address, preferences) VALUES (?, ?, ?, ?)''',
            (data['name'], data['email'], data['address'], data['products'])
        )
        db.commit()
        saved = True
        session.clear()
        return redirect(url_for('thankyou'))
    return render_template_string(
        BASE_TMPL + """
        {% block content %}
        <h5>Review your details</h5>
        <ul class="list-group mb-3">
          <li class="list-group-item">Name: <b>{{ data.name }}</b></li>
