          <li class="list-group-item">Category: <b>{{ data.category }}</b></li>
          <li class="list-group-item">Suggested Products: <b>{{ data.products }}</b></li>
        </ul>
        <form method="POST">
          <a class="btn btn-secondary" href="{{ url_for('step3') }}">Back</a>
          <button type="submit" class="btn btn-success">Confirm & Register</button>
        </form>
        {% endblock %}
        """, data=data
    )

@app.route('/thankyou')
def thankyou():
    return render_template_string(
        BASE_TMPL + """
        {% block content %}
        <div class="alert alert-success text-center">
