            <div class="form-section">
                <h2>Create New Task</h2>
                <form id="taskForm">
                    <div class="row">
                        <div class="col">
                            <div class="form-group">
                                <label for="title">Task Title</label>
                                <input type="text" id="title" name="title" required placeholder="Enter task title">
                            </div>
                        </div>
                        <div class="col">
                            <div class="form-group">
                                <label for="status">Status</label>
                                <select id="status" name="status">
                                    <option value="pending">Pending</option>
                                    <option value="in-progress">In Progress</option>
                                    <option value="completed">Completed</option>
                                </select>
                            </div>
                        </div>
                    </div>
                    <div class="form-group">
                        <label for="description">Description</label>
                        <textarea id="description" name="description" placeholder="Enter detailed description"></textarea>
                    </div>
                    <div class="button-group">
                        <button type="submit" class="btn-primary">Create Task</button>
                        <button type="reset" class="btn-secondary">Clear</button>
                    </div>
                </form>
            </div>

            <div class="tasks-section">
                <h2>All Tasks</h2>
                <div id="tasksList"></div>
            </div>
        </div>
    </div>

    <script>
        const API_BASE = '/api';

        document.getElementById('taskForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                title: document.getElementById('title').value,
                description: document.getElementById('description').value,
                status: document.getElementById('status').value
            };

            try {
                const response = await fetch(`${API_BASE}/tasks`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(formData)
                });

                if (response.ok) {
                    document.getElementById('taskForm').reset();
                    showSuccess('Task created successfully!');
                    loadTasks();
                } else {
                    showError('Failed to create task');
                }
            } catch (error) {
                showError('Error: ' + error.message);
            }
        });

        async function loadTasks() {
            try {
                const response = await fetch(`${API_BASE}/tasks`);
                const tasks = await response.json();

                const tasksList = document.getElementById('tasksList');

                if (tasks.length === 0) {
                    tasksList.innerHTML = '<div class="empty-state"><p>No tasks yet. Create one to get started!</p></div>';
                    return;
                }

                tasksList.innerHTML = tasks.map(task => `
                    <div class="task-item">
                        <div class="task-header">
                            <div class="task-title">${escapeHtml(task.title)}</div>
                            <span class="task-status status-${task.status}">${task.status.replace('-', ' ').toUpperCase()}</span>
                        </div>
                        ${task.description ? `<div class="task-description">${escapeHtml(task.description)}</div>` : ''}
                        <div class="task-actions">
                            <button class="btn-edit" onclick="editTask(${task.id}, '${escapeHtml(task.title)}', '${escapeHtml(task.description || '')}', '${task.status}')">Edit</button>
                            <button class="btn-delete" onclick="deleteTask(${task.id})">Delete</button>
                        </div>
                        <div class="edit-form" id="editForm${task.id}">
                            <input type="text" id="editTitle${task.id}" placeholder="Task Title">
                            <textarea id="editDesc${task.id}" placeholder="Description" style="margin: 10px 0;"></textarea>
                            <select id="editStatus${task.id}" style="margin-bottom: 10px;">
                                <option value="pending">Pending</option>
                                <option value="in-progress">In Progress</option>
                                <option value="completed">Completed</option>
                            </select>
                            <div style="display: flex; gap: 10px;">
                                <button class="btn-primary" onclick="saveEdit(${task.id})" style="flex: 1;">Save</button>
                                <button class="btn-secondary" onclick="cancelEdit(${task.id})" style="flex: 1;">Cancel</button>
                            </div>
                        </div>
                    </div>
                `).join('');
            } catch (error) {
                showError('Error loading tasks: ' + error.message);
            }
        }

        function editTask(id, title, description, status) {
            const form = document.getElementById(`editForm${id}`);
            document.getElementById(`editTitle${id}`).value = title;
            document.getElementById(`editDesc${id}`).value = description;
            document.getElementById(`editStatus${id}`).value = status;
            form.style.display = 'block';
        }

        function cancelEdit(id) {
            document.getElementById(`editForm${id}`).style.display = 'none';
        }

        async function saveEdit(id) {
            const title = document.getElementById(`editTitle${id}`).value;
            const description = document.getElementById(`editDesc${id}`).value;
            const status = document.getElementById(`editStatus${id}`).value;

            try {
                const response = await fetch(`${API_BASE}/tasks/${id}`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ title, description, status })
                });

                if (response.ok) {
                    showSuccess('Task updated successfully!');
                    loadTasks();
                } else {
                    showError('Failed to update task');
                }
            } catch (error) {
                showError('Error: ' + error.message);
            }
        }

        async function deleteTask(id) {
            if (!confirm('Are you sure you want to delete this task?')) return;

            try {
                const response = await fetch(`${API_BASE}/tasks/${id}`, {
                    method: 'DELETE'
                });

                if (response.ok) {
                    showSuccess('Task deleted successfully!');
                    loadTasks();
                } else {
                    showError('Failed to delete task');
                }
            } catch (error) {
                showError('Error: ' + error.message);
            }
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        function showSuccess(message) {
            const msgEl = document.getElementById('successMessage');
            msgEl.textContent = message;
            msgEl.style.display = 'block';
            setTimeout(() => {
                msgEl.style.display = 'none';
            }, 3000);
        }

        function showError(message) {
            const msgEl = document.getElementById('errorMessage');
            msgEl.textContent = message;
            msgEl.style.display = 'block';
            setTimeout(() => {
                msgEl.style.display = 'none';
            }, 3000);
        }

        // Load tasks on page load
        loadTasks();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/tasks', methods=['GET', 'POST'])
def handle_tasks():
    if request.method == 'GET':
        db = get_db()
        tasks = db.execute('SELECT * FROM tasks ORDER BY created_at DESC').fetchall()
        db.close()
        return jsonify([dict(task) for task in tasks])

    elif request.method == 'POST':
        data = request.get_json()
        title = data.get('title', '')
        description = data.get('description', '')
        status = data.get('status', 'pending')

        if not title:
            return jsonify({'error': 'Title is required'}), 400

        db = get_db()
        db.execute('INSERT INTO tasks (title, description, status) VALUES (?, ?, ?)',
                   (title, description, status))
        db.commit()
        db.close()

        return jsonify({'success': True}), 201

@app.route('/api/tasks/<int:task_id>', methods=['GET', 'PUT', 'DELETE'])
def handle_task(task_id):
    if request.method == 'GET':
        db = get_db()
        task = db.execute('SELECT * FROM tasks WHERE id = ?', (task_id,)).fetchone()
        db.close()

        if not task:
            return jsonify({'error': 'Task not found'}), 404

        return jsonify(dict(task))

    elif request.method == 'PUT':
        data = request.get_json()
        title = data.get('title')
        description = data.get('description')
        status = data.get('status')

        db = get_db()
        if title is not None:
            db.execute('UPDATE tasks SET title = ? WHERE id = ?', (title, task_id))
        if description is not None:
            db.execute('UPDATE tasks SET description = ? WHERE id = ?', (description, task_id))
        if status is not None:
            db.execute('UPDATE tasks SET status = ? WHERE id = ?', (status, task_id))
        db.commit()
        db.close()

        return jsonify({'success': True})

    elif request.method == 'DELETE':
        db = get_db()
        db.execute('DELETE FROM tasks WHERE id = ?', (task_id,))
        db.commit()
        db.close()

        return jsonify({'success': True})

@app.route('/api/export/xml', methods=['GET'])
def export_xml():
    db = get_db()
    tasks = db.execute('SELECT * FROM tasks').fetchall()
    db.close()

    root = ET.Element('tasks')
    for task in tasks:
        task_elem = ET.SubElement(root, 'task')
        task_elem.set('id', str(task['id']))

        title_elem = ET.SubElement(task_elem, 'title')
        title_elem.text = task['title']

        desc_elem = ET.SubElement(task_elem, 'description')
        desc_elem.text = task['description'] or ''

        status_elem = ET.SubElement(task_elem, 'status')
        status_elem.text = task['status']

    xml_str = minidom.parseString(ET.tostring(root)).toprettyxml(indent='  ')
    return xml_str, 200, {'Content-Type': 'application/xml', 'Content-Disposition': 'attachment; filename=tasks.xml'}

@app.route('/api/import/xml', methods=['POST'])
def import_xml():
    try:
        xml_data = request.data.decode('utf-8')
        root = ET.fromstring(xml_data)

        db = get_db()
        for task_elem in root.findall('task'):
            title = task_elem.find('title').text or 'Untitled'
            description = task_elem.find('description').text or ''
            status = task_elem.find('status').text or 'pending'

            db.execute('INSERT INTO tasks (title, description, status) VALUES (?, ?, ?)',
                      (title, description, status))

        db.commit()
        db.close()

        return jsonify({'success': True, 'message': 'Tasks imported successfully'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/api/search', methods=['GET'])
def search_tasks():
    query = request.args.get('q', '')

    db = get_db()
    xpath_query = f"title[contains(., '{query}')] or description[contains(., '{query}')]"
    tasks = db.execute('SELECT * FROM tasks WHERE title LIKE ? OR description LIKE ?',
                      (f'%{query}%', f'%{query}%')).fetchall()
    db.close()

    return jsonify([dict(task) for task in tasks])

if __name__ == '__main__':
    if not os.path.exists(app.config['DATABASE']):
        init_db()
    app.run(host='0.0.0.0', port=9008, debug=True)

