@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        name = request.form.get("name","")
        street = request.form.get("street","")
        city = request.form.get("city","")
        state = request.form.get("state","")
        zipcode = request.form.get("zipcode","")
        meta_xml = request.form.get("meta_xml","")
        with sqlite3.connect(DB_PATH) as conn:
            conn.execute("INSERT INTO delivery_addresses (name, street, city, state, zipcode, meta_xml) VALUES (?,?,?,?,?,?)",
                         (name, street, city, state, zipcode, meta_xml))
        return redirect(url_for("index"))

    with sqlite3.connect(DB_PATH) as conn:
        rows = conn.execute("SELECT * FROM delivery_addresses").fetchall()
    addresses = []
    for row in rows:
        addr = {
            'id': row[0],
            'name': row[1],
            'street': row[2],
            'city': row[3],
            'state': row[4],
            'zipcode': row[5],
            'meta_xml': row[6],
            'last_query': ""
        }
        if 'last_query_{}'.format(addr['id']) in request.args:
            addr['last_query'] = request.args['last_query_{}'.format(addr['id'])]
        addresses.append(addr)
    return render_template_string(TEMPLATE, addresses=addresses)

@app.route('/xml_query/<int:id>', methods=['POST'])
def xml_query(id):
    xpath = request.form.get("xpath","")
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute("SELECT meta_xml FROM delivery_addresses WHERE id=?", (id,)).fetchone()
    if not row or not row[0]:
        return redirect(url_for('index'))
    xml_data = row[0]

    # CWE-643 Vulnerability: No safe XPath handling, user can inject XPath in "xpath" field
    try:
        root = ET.fromstring(xml_data)
        elems = root.findall(xpath)
        results = []
        for e in elems:
            if isinstance(e, ET.Element):
                text = e.text
                if text is None:
                    # Try attrib case
                    text = str(dict(e.attrib))
            else:
                text = str(e)
            results.append(text)
        res = "; ".join(results) if results else "(empty)"
    except Exception as ex:
        res = 'Error: ' + str(ex)
    return redirect(url_for('index', **{'last_query_%d'%id: res}))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6009)

