PRODUCTS_TABLE = """
CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    price REAL
);
"""

SAMPLE_PRODUCTS = [
    ("Spark Plug", "High-performance spark plug for racing engines.", 10.99),
    ("Brake Pad", "Durable brake pads suitable for most car models.", 25.50),
    ("Oil Filter", "Long-lasting oil filter for engine protection.", 8.75),
    ("Wiper Blade", "All-season wiper blade, 22 inch.", 6.99),
]

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    conn = sqlite3.connect(app.config['DATABASE'])
    c = conn.cursor()
    c.execute(PRODUCTS_TABLE)
    conn.commit()
    cur = c.execute("SELECT COUNT(*) FROM products")
    if cur.fetchone()[0] == 0:
        c.executemany(
            "INSERT INTO products (name, description, price) VALUES (?, ?, ?)",
            SAMPLE_PRODUCTS
        )
        conn.commit()
    conn.close()

@app.before_first_request
def setup():
    init_db()
    # Create a world-readable file with dummy content outside the web dir
    with open('secret_api.txt', 'w') as f:
        f.write('API_KEY: THIS_SHOULD_NOT_BE_ACCESSIBLE\n')

@app.route("/", methods=["GET", "POST"])
def index():
    query = ""
    results = []
    db = get_db()
    if request.method == "POST":
        query = request.form.get("query", "").strip()
        if query:
            results = db.execute(
                "SELECT * FROM products WHERE name LIKE ? OR description LIKE ?",
                (f'%{query}%', f'%{query}%')
            ).fetchall()
        else:
            results = db.execute("SELECT * FROM products").fetchall()
    else:
        results = db.execute("SELECT * FROM products").fetchall()
    return render_template_string(
        CLI_STYLE + """
        <div class="container">
        <h1>AutoParts CLI [v1.0]</h1>
        <form method="post">
            > Search parts: <input name="query" value="{{ query }}" autocomplete="off">
            <button type="submit">[ enter ]</button>
        </form>
        <hr>
        {% if results %}
            {% for product in results %}
                <div class="product-card">
                    [{{ product['id'] }}] {{ product['name'] }} <br>
                    -- {{ product['description'] }}<br>
                    -- Price: ${{ "%.2f"|format(product['price']) }}
                </div>
            {% endfor %}
        {% else %}
            <i>No matching products.</i>
        {% endif %}
        <hr>
        <a href="{{ url_for('download_file') }}">[ Download API config ]</a>
        </div>
        """,
        query=query, results=results
    )

@app.route("/download")
def download_file():
    path = request.args.get('path', 'secret_api.txt')
    # CWE-668: Exposure of Resource to Wrong Sphere
    # Users can supply arbitrary file path (path traversal)
    # Files outside web directory can be accessed
    try:
        return send_file(path, as_attachment=True)
    except Exception:
        abort(404)

if __name__ == "__main__":
    import sys
    port = int(os.environ.get('PORT', 6263))
    app.run(host="0.0.0.0", port=port, debug=False)

