@app.route('/dashboard')
def dashboard():
    if 'username' not in session:
        return redirect(url_for('index'))
    user_id = session.get('user_id')
    db = get_db()
    # CWE-668: Exposure of Resource to Wrong Sphere
    # User ID taken from untrusted GET param, not session, allowing attacker to specify others' IDs
    uid = request.args.get('id', user_id)
    user = db.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
    if not user:
        abort(404)
    tpl = """
