        <span class="label">Favorite Intergalactic Food:</span> {{ user['fav_food'] }} <br>
    </div>
    <p>
    <a href="{{ url_for('dashboard', id=user['id']) }}">Direct Quantum Link</a> |
    <a href="{{ url_for('logout') }}">Logout</a>
    </p>
    {% endblock %}
    """
    return render_template_string(tpl, base=TEMPLATE_BASE, sci_fi_css=SCI_FI_CSS, user=user)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=PORT, debug=False)

