ALLOWED_EXTENSIONS = {'txt', 'jpg', 'jpeg', 'png', 'gif', 'pdf', 'zip'}

if not os.path.exists(app.config['UPLOAD_FOLDER']):
    os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)

luxury_style = """
<style>
body {font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;background:#201e1c;color:#f5e6cb;margin:0;padding:0;}
