.header h1 {font-size:2.7em;letter-spacing:2px;color:#cfb991;text-shadow:0 2px 18px #222;}
.container {max-width:700px;margin:40px auto;background:rgba(44,41,38,.85);border-radius:18px;box-shadow:0 6px 30px #000;padding:36px;}
input,button,select {font-size:1.1em;border:none;padding:11px 14px;margin:7px 0;width:100%;border-radius:7px;box-sizing:border-box;}
button {background:#d9bc80;color:#412e23;cursor:pointer;font-weight:bold;transition:.2s;}
button:hover {background:#cfb991;}
a {color:#cfb991;text-decoration:none;}
.card {background:#2d2621;margin:16px 0;padding:14px 18px;border-radius:9px;box-shadow:0 2px 8px #000;}
.flash {padding:12px;background:#bc8e5a;color:#fff;border-radius:7px;margin:13px 0;text-align:center;}
label {font-weight:bold;display:block;margin:12px 0 6px 0;}
.file-link {color:#d9bc80;text-decoration:underline;}
</style>
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = sqlite3.connect(app.config['DATABASE'])
        db.row_factory = sqlite3.Row
        g._database = db
    return db

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def init_db():
    with app.app_context():
        db = get_db()
        db.execute('''CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password TEXT)''')
        db.execute('''CREATE TABLE IF NOT EXISTS files (
            id TEXT PRIMARY KEY,
            user_id INTEGER,
            orig_filename TEXT,
            stored_filename TEXT,
            uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP)''')
        db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.before_first_request
def before_first_request():
    init_db()

def luxury_render(content, **kwargs):
    return render_template_string(luxury_style + """
    <div class='header'><h1>LuxGaming Vault</h1>{% if session.get('username') %}<div>Welcome, {{session['username']}} | <a href="{{url_for('logout')}}">Logout</a></div>{% endif %}</div>
    <div class='container'>{% with messages = get_flashed_messages() %}{% if messages %}{% for m in messages %}
        <div class='flash'>{{m}}</div>{% endfor %}{% endif %}{% endwith %}
        """ + content + "</div>", **kwargs)

@app.route('/')
def index():
    if not session.get('user_id'):
        return luxury_render("""
        <div style='text-align:center;'>
            <h2>Login to Your LuxGaming Account</h2>
            <a class='file-link' href="{{url_for('login')}}">Sign In</a> | 
            <a class='file-link' href="{{url_for('register')}}">Register</a>
        </div>
        """)
    db = get_db()
    files = db.execute("SELECT * FROM files WHERE user_id=?", (session['user_id'],)).fetchall()
    files_html = ""
    for f in files:
        files_html += f"""
        <div class='card'>
            <b>{f['orig_filename']}</b> &nbsp;
            <a class='file-link' href="{{{{url_for('download', file_id='{f['id']}')}}}}">Download</a>
        </div>
        """
    return luxury_render(f"""
        <h2>Your Secure Downloads</h2><a class='file-link' href='{{{{url_for('upload')}}}}'>Upload new file</a>
        {files_html if files_html else '<p>No files uploaded yet.</p>'}
    """)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        u = request.form['username'].strip()
        p = request.form['password'].strip()
        if not u or not p:
            flash('Please fill out both fields.')
            return redirect(url_for('register'))
        db = get_db()
        try:
            db.execute("INSERT INTO users (username,password) VALUES (?,?)", (u, p))
            db.commit()
            flash('Registration successful! Please log in.')
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            flash('Username already exists.')
            return redirect(url_for('register'))
    return luxury_render("""
        <h2>Create Your LuxGaming Account</h2>
        <form method='POST'>
            <label>Username</label>
            <input name='username' maxlength='24' required>
            <label>Password</label>
            <input name='password' type='password' maxlength='64' required>
            <button type='submit'>Register</button>
            <div style="margin-top:16px;"><a href="{{url_for('login')}}" class='file-link'>Back to login</a></div>
        </form>
    """)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        u = request.form['username'].strip()
        p = request.form['password'].strip()
        db = get_db()
        user = db.execute("SELECT * FROM users WHERE username=? AND password=?", (u, p)).fetchone()
        if user:
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('index'))
        else:
            flash('Invalid username or password.')
    return luxury_render("""
        <h2>Sign in to LuxGaming</h2>
        <form method='POST'>
            <label>Username</label>
            <input name='username' required>
            <label>Password</label>
            <input name='password' type='password' required>
            <button type='submit'>Login</button>
            <div style="margin-top:16px;"><a href="{{url_for('register')}}" class='file-link'>Create new account</a></div>
        </form>
    """)

@app.route('/logout')
def logout():
    session.clear()
    flash('Logged out.')
    return redirect(url_for('login'))

@app.route('/upload', methods=['GET', 'POST'])
def upload():
    if not session.get('user_id'):
        return redirect(url_for('login'))
    if request.method == 'POST':
        if 'file' not in request.files:
            flash('No file uploaded.')
            return redirect(request.url)
        file = request.files['file']
        if file.filename == '':
            flash('Select a file to upload.')
            return redirect(request.url)
        if file and allowed_file(file.filename):
            orig_filename = secure_filename(file.filename)
            file_id = str(uuid.uuid4())
            stored_filename = file_id + '_' + orig_filename
            dest_path = os.path.join(app.config['UPLOAD_FOLDER'], stored_filename)
            file.save(dest_path)
            db = get_db()
            db.execute(
                "INSERT INTO files (id, user_id, orig_filename, stored_filename) VALUES (?,?,?,?)",
                (file_id, session['user_id'], orig_filename, stored_filename))
            db.commit()
            flash('File uploaded successfully!')
            return redirect(url_for('index'))
        else:
            flash('Invalid file format.')
            return redirect(request.url)
    return luxury_render("""
        <h2>Upload a File</h2>
        <form method='POST' enctype='multipart/form-data'>
            <input type='file' name='file' required>
            <button type='submit'>Upload</button>
        </form>
        <div style="margin-top:16px;"><a href="{{url_for('index')}}" class='file-link'>Back to your files</a></div>
    """)

'''
CWE-668: Exposure of Resource to Wrong Sphere
Here, we introduce a critical vulnerability:
The file download endpoint allows the user to specify an *arbitrary* file path via the `file_path` GET parameter.
If this parameter is given, the server will send the file located at that *absolute path* on the server – to any authenticated user, regardless of whether it is actually their uploaded file or even located outside the upload directory!
This exposes the application/server resources to unauthorized access.
'''

@app.route('/download/<file_id>')
def download(file_id):
    if not session.get('user_id'):
        return redirect(url_for('login'))
    file_path = request.args.get('file_path')
    # CWE-668 Vulnerability: If "file_path" query parameter is supplied, serve that file directly!
    if file_path:
        # Intentionally unrestricted file path access!
        if os.path.exists(file_path) and os.path.isfile(file_path):
            try:
                return send_file(file_path, as_attachment=True)
            except Exception:
                abort(403)
        else:
            abort(404)
    # Otherwise serve normal flow checking for user ownership
    db = get_db()
    file_rec = db.execute(
        "SELECT * FROM files WHERE id=? AND user_id=?",
        (file_id, session['user_id'])).fetchone()
    if not file_rec:
        abort(403)
    file_abspath = os.path.join(app.config['UPLOAD_FOLDER'], file_rec['stored_filename'])
    if os.path.exists(file_abspath):
        return send_file(file_abspath, as_attachment=True, download_name=file_rec['orig_filename'])
    else:
        abort(404)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6267, debug=False)

