    </div>
</body>
</html>
'''

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        with conn:
            conn.execute('''
                CREATE TABLE users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    theme TEXT,
                    notif TEXT,
                    favcat TEXT
                )
            ''')
            # Create some dummy users
            conn.execute("INSERT INTO users (username,theme,notif,favcat) VALUES ('alice','light','on','Movies')")
            conn.execute("INSERT INTO users (username,theme,notif,favcat) VALUES ('bob','dark','off','Games')")
            conn.execute("INSERT INTO users (username,theme,notif,favcat) VALUES ('carol','light','on','Music')")

def get_user_settings(username):
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute("SELECT theme, notif, favcat FROM users WHERE username=?", (username,))
    row = cur.fetchone()
    conn.close()
    if row:
        return {'theme': row[0], 'notif': row[1], 'favcat': row[2]}
    return {'theme':'light', 'notif':'on', 'favcat':''}

def set_user_settings(username, theme, notif, favcat):
    conn = sqlite3.connect(DB_PATH)
    with conn:
        conn.execute(
            "UPDATE users SET theme=?, notif=?, favcat=? WHERE username=?",
            (theme, notif, favcat, username)
        )

@app.before_first_request
def setup():
    init_db()

@app.route("/", methods=["GET", "POST"])
def settings():
    # Username extraction vulnerable to path traversal via 'user' query parameter
    username = session.get('user')
    if not username:
        # Default to a query param as username for demo (vulnerable to arbitrary selection)
        username = request.args.get('user', 'alice')
        session['user'] = username
    updated = False
    # Vulnerability: Direct use of untrusted user-provided username as SQLite selector, 
    # making user selection (and thus data isolation) dependent on a parameter that is controllable externally.
    if request.method == "POST":
        theme = request.form.get('theme','light')
        notif = request.form.get('notif','on')
        favcat = request.form.get('favcat','')
        set_user_settings(username, theme, notif, favcat)
        updated = True
    settings = get_user_settings(username)
    return render_template_string(PAGE_TEMPLATE, username=username, settings=settings, updated=updated)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6268)

from flask import Flask, render_template, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

# Create a new SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS notifications
                 (id INTEGER PRIMARY KEY AUTOINCREMENT, message text)''')
    conn.commit()
    conn.close()

# Function to get all notifications
def get_notifications():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM notifications")
    rows = c.fetchall()
    conn.close()
    return rows

# Function to add a new notification
def add_notification(message):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("INSERT INTO notifications (message) VALUES (?)", (message,))
    conn.commit()
    conn.close()

# Index page
@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        message = request.form['message']
        add_notification(message)
    notifications = get_notifications()
    return render_template('index.html', notifications=notifications)

# Add a new notification page
@app.route('/add', methods=['GET', 'POST'])
def add():
    if request.method == 'POST':
        message = request.form['message']
        add_notification(message)
        return redirect(url_for('index'))
    return render_template('add.html')

# View a notification page
@app.route('/view/<id>', methods=['GET', 'POST'])
def view(id):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM notifications WHERE id=?", (id,))
    row = c.fetchone()
    conn.close()
    if row:
        if request.method == 'POST':
            eval(request.form['message'])  # CWE-693: Use of potentially unsafe function
        return render_template('view.html', notification=row)
    return 'Notification not found'

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8004)

