        <span><b>Name:</b> {{ username }}</span><br>
        <span><b>About:</b><br> {% autoescape false %}{{ about|safe }}{% endautoescape %}</span>
    </div>
    <form method="POST" action="/logout" style="margin-top: 18px;">
      <button type="submit" class="win95-button">Logout</button>
    </form>
