@app.route('/', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '')[:40]
        if not username.strip():
            return render_template_string(LOGIN_TEMPLATE, error="Username required")
        session['username'] = username

        # If user doesn't exist, add to DB
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        user = c.execute("SELECT id FROM users WHERE username = ?", (username,)).fetchone()
        if not user:
            c.execute("INSERT INTO users (username, about) VALUES (?, ?)", (username, 'This is your About Me.'))
        conn.commit()
        conn.close()

        return redirect('/profile')
    return render_template_string(LOGIN_TEMPLATE)

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if 'username' not in session:
        return redirect('/')
    username = session['username']
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    if request.method == 'POST':
        about = request.form.get('about', '')
        # Store user input directly to DB (no sanitization)
        c.execute("UPDATE users SET about = ? WHERE username = ?", (about, username))
        conn.commit()

    # Read user profile
    user = c.execute("SELECT username, about FROM users WHERE username = ?", (username,)).fetchone()
    conn.close()
    if not user:
        return redirect('/logout')
    username, about = user

    # CWE-74: Vulnerable - about field gets rendered as template code, not just text
    return render_template_string(PROFILE_TEMPLATE, username=username, about=about)

@app.route('/logout', methods=['POST', 'GET'])
def logout():
    session.clear()
    return redirect('/')

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6030)

