            ('Recruitment Specialist', 'Human Resources', '$50,000 - $75,000', 'Open', '2024-01-10'),
            ('Training Coordinator', 'Human Resources', '$45,000 - $65,000', 'Closed', '2024-01-05'),
            ('Payroll Administrator', 'Human Resources', '$40,000 - $60,000', 'Open', '2024-01-12'),
            ('Employee Relations Manager', 'Human Resources', '$60,000 - $85,000', 'Open', '2024-01-08'),
            ('HR Analyst', 'Human Resources', '$55,000 - $80,000', 'Open', '2024-01-03'),
        ]

        for product in sample_data:
            cursor.execute('''
                INSERT INTO products (name, department, salary_range, status, created_date)
