def execute_command(cmd):
    """Execute a shell command and return output - CWE-74 vulnerability"""
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=5)
        return result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        return "Command execution timeout"
    except Exception as e:
        return f"Error: {str(e)}"

@app.route('/')
def index():
    search_query = request.args.get('search', '').strip()
    status_filter = request.args.get('status', '').strip()

    conn = get_db_connection()
    cursor = conn.cursor()

    # CWE-74: Improper Neutralization of Special Elements in Output
    # The application directly uses user input in the SQL query without proper parameterization
    # This allows for SQL injection attacks

    query = "SELECT * FROM products WHERE 1=1"
    params = []

    if search_query:
        # Vulnerable: Using string concatenation instead of parameterized query
        query += f" AND (name LIKE '%{search_query}%' OR department LIKE '%{search_query}%')"

    if status_filter:
        # Vulnerable: Direct concatenation without parameterization
        query += f" AND status = '{status_filter}'"

    query += " ORDER BY created_date DESC"

    try:
        cursor.execute(query)
        products = cursor.fetchall()
    except sqlite3.OperationalError as e:
        # Return error message that might leak database information
        products = []
        error_msg = str(e)
        # CWE-74: Improperly neutralized error message could contain sensitive info
        if "syntax error" in error_msg.lower():
            products = []

    # Get statistics
    cursor.execute("SELECT COUNT(*) as total FROM products")
    total = cursor.fetchone()['total']

    cursor.execute("SELECT COUNT(*) as open FROM products WHERE status = 'Open'")
    open_count = cursor.fetchone()['open']

    cursor.execute("SELECT COUNT(*) as closed FROM products WHERE status = 'Closed'")
    closed_count = cursor.fetchone()['closed']

    conn.close()

    stats = {
        'total': total,
        'open': open_count,
        'closed': closed_count
    }

    return render_template_string(
        HTML_TEMPLATE,
        products=products,
        search_query=search_query,
        status_filter=status_filter,
        stats=stats
    )

@app.route('/api/search', methods=['POST'])
def api_search():
    data = request.get_json()
    search_term = data.get('search', '').strip()
    status = data.get('status', '').strip()

    conn = get_db_connection()
    cursor = conn.cursor()

    # Another CWE-74 vulnerability point in API
    query = f"SELECT * FROM products WHERE name LIKE '%{search_term}%'"
    if status:
        query += f" OR status = '{status}'"

    try:
        cursor.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        conn.close()
        return jsonify({'success': True, 'data': results})
    except Exception as e:
        conn.close()
        # CWE-74: Returning raw exception message
        return jsonify({'success': False, 'error': str(e)})

@app.route('/api/export', methods=['GET'])
def api_export():
    export_type = request.args.get('type', 'csv').strip()
    search_query = request.args.get('search', '').strip()

    # CWE-74: Using user input in command execution
    # This is a severe vulnerability allowing arbitrary command execution
    if export_type == 'csv':
        # Vulnerable: User input directly in shell command
        cmd = f"echo 'id,name,department,salary,status' > /tmp/export_{search_query}.csv"
        output = execute_command(cmd)
        return jsonify({'file': f'/tmp/export_{search_query}.csv', 'command_output': output})

    return jsonify({'error': 'Invalid export type'})

@app.route('/api/process', methods=['POST'])
def api_process():
    data = request.get_json()
    process_type = data.get('type', '').strip()
    product_name = data.get('product_name', '').strip()

    # CWE-74: Command Injection vulnerability
    if process_type == 'analyze':
        # Dangerous: User input in shell command
        cmd = f"grep -r '{product_name}' /tmp/ 2>/dev/null | head -5"
        result = execute_command(cmd)
        return jsonify({'result': result})

    return jsonify({'error': 'Invalid process type'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9020, debug=True)

