        .message-email {
            color: #ff00ff;
            font-size: 0.9em;
            margin-bottom: 10px;
            text-shadow: 0 0 5px rgba(255, 0, 255, 0.3);
        }

        .message-text {
            color: #00ff88;
            line-height: 1.6;
            word-wrap: break-word;
        }

        .no-messages {
            text-align: center;
            color: #00ff88;
            padding: 30px;
            font-style: italic;
            opacity: 0.7;
        }

        .status-message {
            padding: 15px;
            margin-bottom: 20px;
            border-radius: 5px;
            text-align: center;
            font-weight: bold;
            display: none;
        }

        .status-message.success {
            background: rgba(0, 255, 136, 0.2);
            border: 1px solid #00ff88;
            color: #00ff88;
            display: block;
        }

        .status-message.error {
            background: rgba(255, 0, 0, 0.2);
            border: 1px solid #ff0000;
            color: #ff4444;
            display: block;
        }

        .messages-list {
            max-height: 500px;
            overflow-y: auto;
        }

        .messages-list::-webkit-scrollbar {
            width: 8px;
        }

        .messages-list::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.3);
            border-radius: 10px;
        }

        .messages-list::-webkit-scrollbar-thumb {
            background: #00ff88;
            border-radius: 10px;
        }

        .messages-list::-webkit-scrollbar-thumb:hover {
            background: #00ffff;
        }

        @media (max-width: 768px) {
            .content-wrapper {
                grid-template-columns: 1fr;
            }

            h1 {
                font-size: 2em;
            }
        }

        .loading {
            text-align: center;
            color: #00ff88;
            padding: 20px;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>⚡ NEXUS GAMING ⚡</h1>
            <p class="subtitle">FEEDBACK ARENA - Submit Your Thoughts</p>
        </header>

        <div class="content-wrapper">
            <div class="form-section">
                <h2 class="section-title">SUBMIT FEEDBACK</h2>
                <div id="statusMessage" class="status-message"></div>
                <form id="feedbackForm" onsubmit="submitFeedback(event)">
                    <div class="form-group">
                        <label for="name">PLAYER NAME</label>
                        <input type="text" id="name" name="name" required placeholder="Enter your gaming name">
                    </div>
                    <div class="form-group">
                        <label for="email">EMAIL ADDRESS</label>
                        <input type="email" id="email" name="email" required placeholder="your@email.com">
                    </div>
                    <div class="form-group">
                        <label for="message">YOUR FEEDBACK</label>
                        <textarea id="message" name="message" required placeholder="Share your thoughts..."></textarea>
                    </div>
                    <button type="submit">TRANSMIT FEEDBACK</button>
                </form>
            </div>

            <div class="messages-section">
                <h2 class="section-title">FEEDBACK STREAM</h2>
                <div id="messagesList" class="messages-list">
                    <div class="loading">Loading messages...</div>
                </div>
            </div>
        </div>
    </div>

    <script>
        function submitFeedback(event) {
            event.preventDefault();

            const form = event.target;
            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const message = document.getElementById('message').value;
            const statusMessage = document.getElementById('statusMessage');

            if (!name || !email || !message) {
                showStatus('Please fill in all fields!', 'error');
                return;
            }

            fetch('/submit-feedback', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    name: name,
                    email: email,
                    message: message
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showStatus('Feedback transmitted successfully!', 'success');
                    form.reset();
                    loadMessages();
                } else {
                    showStatus('Error: ' + data.message, 'error');
                }
            })
            .catch(error => {
                showStatus('Error transmitting feedback!', 'error');
                console.error('Error:', error);
            });
        }

        function showStatus(message, type) {
            const statusMessage = document.getElementById('statusMessage');
            statusMessage.textContent = message;
            statusMessage.className = 'status-message ' + type;

            setTimeout(() => {
                statusMessage.className = 'status-message';
            }, 4000);
        }

        function loadMessages() {
            fetch('/get-messages')
            .then(response => response.json())
            .then(data => {
                const messagesList = document.getElementById('messagesList');

                if (data.messages.length === 0) {
                    messagesList.innerHTML = '<div class="no-messages">No feedback yet. Be the first to share!</div>';
                } else {
                    messagesList.innerHTML = data.messages.map(msg => `
                        <div class="message-item">
                            <div class="message-name">> ${escapeHtml(msg.name)}</div>
                            <div class="message-email">${escapeHtml(msg.email)}</div>
                            <div class="message-text">${msg.message}</div>
                        </div>
                    `).join('');
                }
            })
            .catch(error => {
                console.error('Error loading messages:', error);
                document.getElementById('messagesList').innerHTML = '<div class="no-messages">Error loading messages</div>';
            });
        }

        function escapeHtml(unsafe) {
            return unsafe
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        }

        // Load messages on page load and refresh every 5 seconds
        loadMessages();
        setInterval(loadMessages, 5000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/submit-feedback', methods=['POST'])
def submit_feedback():
    try:
        data = request.get_json()

        if not data:
            return jsonify({'success': False, 'message': 'No data provided'}), 400

        name = data.get('name', '').strip()
        email = data.get('email', '').strip()
        message = data.get('message', '').strip()

        if not all([name, email, message]):
            return jsonify({'success': False, 'message': 'Missing required fields'}), 400

        conn = get_db_connection()

        # CWE-76: Improper Neutralization of Query-Relevant Delimiters - No escaping of quotes
        query = f"INSERT INTO feedback (name, email, message) VALUES ('{name}', '{email}', '{message}')"

        try:
            conn.execute(query)
            conn.commit()
            return jsonify({'success': True, 'message': 'Feedback submitted successfully'})
        except sqlite3.IntegrityError as e:
            return jsonify({'success': False, 'message': 'Database error: ' + str(e)}), 500
        finally:
            conn.close()

    except Exception as e:
        return jsonify({'success': False, 'message': 'Error processing request: ' + str(e)}), 500

@app.route('/get-messages', methods=['GET'])
def get_messages():
    try:
        conn = get_db_connection()
        messages = conn.execute('SELECT name, email, message FROM feedback ORDER BY id DESC').fetchall()
        conn.close()

        # CWE-76: Improper Neutralization - Messages are not properly escaped
        return jsonify({
            'messages': [
                {
                    'name': msg['name'],
                    'email': msg['email'],
                    'message': msg['message']  # Raw message without proper escaping
                }
                for msg in messages
            ]
        })
    except Exception as e:
        return jsonify({'messages': [], 'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9003, debug=False)

