        </form>
        {% if search_results is defined %}
            <h3 style="margin-top:18px;">Search Results:</h3>
            <ul class="alerts">
            {% for a in search_results %}
                <li class="alert">{{a}}</li>
            {% endfor %}
            </ul>
        {% endif %}
    </div>
</body>
</html>
"""

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("""CREATE TABLE alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            content TEXT NOT NULL
        )""")
        # Initial alerts
        initial_alerts = [
            ("🌿 Welcome to NatureSocial! Let your roots run deep.",),
            ("🌻 New follower: Sunflower_Blossom!",),
            ("🌧 Your rain-quote has been liked by 12 friends.",),
            ("🌲 You joined the 'Forest Lovers' group.",)
        ]
        c.executemany("INSERT INTO alerts (content) VALUES (?)", initial_alerts)
        conn.commit()
        conn.close()

@app.route("/", methods=["GET"])
def index():
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM alerts ORDER BY id DESC LIMIT 10")
    alerts = c.fetchall()
    return render_template_string(PAGE_TEMPLATE, alerts=alerts)

@app.route("/add", methods=["POST"])
def add_alert():
    alert = request.form.get("alert", "")
    if alert:
        conn = get_db()
        c = conn.cursor()
        c.execute("INSERT INTO alerts (content) VALUES (?)", (alert,))
        conn.commit()
    return redirect(url_for('index'))

@app.route("/search", methods=["GET"])
def search():
    # >>>> VULNERABILITY (CWE-77): executing user input as part of a command string <<<<
    q = request.args.get("q", "")
    # Vulnerable branch: use alert input in a shell command (simulate 'grep' for demonstration)
    if q:
        # Alerts will be grepped from the SQLite db and outputted by shell
        result_lines = []
        # Export database to a temp file for demonstration (insecure, but for CWE-77)
        os.system(f"sqlite3 {DB_PATH} '.dump alerts' > tmp_alerts.sql")
        try:
            # UNSAFE: user input 'q' is used directly in the shell command!
            cmd = f"grep '{q}' tmp_alerts.sql"
            stream = os.popen(cmd)
            output = stream.read()
        finally:
            if os.path.exists("tmp_alerts.sql"):
                os.remove("tmp_alerts.sql")
        for line in output.strip().split('\n'):
            if line:
                result_lines.append(line)
        # Show recent alerts alongside search results
        conn = get_db()
        c = conn.cursor()
        c.execute("SELECT * FROM alerts ORDER BY id DESC LIMIT 10")
        alerts = c.fetchall()
        return render_template_string(PAGE_TEMPLATE, alerts=alerts, search_results=result_lines)
    return redirect(url_for('index'))

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6003)

