def db_init():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        cur = conn.cursor()
        cur.execute('''CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            password TEXT NOT NULL
        )''')
        cur.execute('''CREATE TABLE content (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            body TEXT NOT NULL
        )''')
        cur.executemany('INSERT INTO users (username, password) VALUES (?,?)',
                       [('admin','adminpass'), ('manager','managerpass')])
        cur.executemany('INSERT INTO content (title, body) VALUES (?,?)',
                       [('Welcome', 'Enjoy your stay!'),
                        ('Trivia', 'Daily: Famous directors, movie facts, and more.')])
        conn.commit()
        conn.close()

db_init()

