"""

@app.route('/', methods=['GET', 'POST'])
def login():
    if 'user' in session:
        return redirect(url_for('dashboard'))
    status = ''
    if request.method == 'POST':
        username = request.form.get('username','').strip()
        password = request.form.get('password','')
        conn = sqlite3.connect(DB_NAME)
        c = conn.cursor()
        c.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
        row = c.fetchone()
        conn.close()
        if row:
            session['user'] = username
            return redirect(url_for('dashboard'))
        else:
            status = "Invalid credentials."
    return render_template_string(LOGIN_PAGE, status=status)

@app.route('/dashboard', methods=['GET', 'POST'])
def dashboard():
    if 'user' not in session:
        return redirect(url_for('login'))
    return render_template_string(DASHBOARD_PAGE, username=session['user'], status=None, success=False)

@app.route('/change_password', methods=['POST'])
def change_password():
    if 'user' not in session:
        return redirect(url_for('login'))
    username = session['user']
    old_password = request.form.get('old_password','')
    new_password = request.form.get('new_password','')
    # Check old password in database
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT * FROM users WHERE username=? AND password=?", (username, old_password))
    row = c.fetchone()
    conn.close()

    if not row:
        return render_template_string(DASHBOARD_PAGE, username=username, status="Old password incorrect.", success=False)

    # CWE-77: OS Command Injection vulnerability here!
    unsafe_cmd = f"sqlite3 {DB_NAME} \"UPDATE users SET password='{new_password}' WHERE username='{username}';\""
    # The new_password and username are injected straight into shell command.
    ret = subprocess.call(unsafe_cmd, shell=True)
    if ret != 0:
        return render_template_string(DASHBOARD_PAGE, username=username, status="Password change failed.", success=False)
    return render_template_string(DASHBOARD_PAGE, username=username, status="Password changed successfully.", success=True)

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('user', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6007)

