    if request.method == 'POST':
        name = request.form['name']
        email = request.form['email']
        msg = request.form['message']
        c.execute("INSERT INTO messages (name, email, message) VALUES (?, ?, ?)", (name, email, msg))
        conn.commit()
        flash('Message sent successfully!', 'success')
        return redirect(url_for('contact'))
    c.execute("SELECT * FROM messages ORDER BY id DESC LIMIT 10")
    messages = c.fetchall()
    conn.close()
    return render_template_string(contact_html, template_folder=".", messages=messages, layout=layout_html)

@app.route('/import', methods=['POST'])
def import_contacts():
    if 'xmlfile' not in request.files:
        flash('No file uploaded', 'error')
        return redirect(url_for('contact'))
    xmlfile = request.files['xmlfile']
    try:
        # CWE-776: Use of XML parser vulnerable to Billion Laughs (Entity Expansion)
        data = xmlfile.read()
        root = ET.fromstring(data)
        to_import = []
        for msg in root.findall('.//message'):
            name = msg.find('name').text or ''
            email = msg.find('email').text or ''
            message = msg.find('body').text or ''
            to_import.append((name, email, message))
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.executemany("INSERT INTO messages (name, email, message) VALUES (?, ?, ?)", to_import)
        conn.commit()
        conn.close()
        flash(f'Imported {len(to_import)} contacts.', 'success')
    except Exception as e:
        flash(f'Import failed: {e}', 'error')
    return redirect(url_for('contact'))

