        <div class="title-bar">Legal Service &ndash; Address Book</div>
        <div class="menu-bar">
            <a href="{{ url_for('index') }}">Home</a> &nbsp;|&nbsp;
            <a href="{{ url_for('add_contact') }}">Add Contact</a> &nbsp;|&nbsp;
            <a href="{{ url_for('search_contacts') }}">Search & Export</a>
        </div>
        <div class="content">
            {% block content %}{% endblock %}
        </div>
    </div>
</body>
</html>
'''

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop("db", None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''
        CREATE TABLE IF NOT EXISTS contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT NOT NULL,
            email TEXT,
            legal_case TEXT
        )
    ''')
    db.commit()
    db.close()

@app.route("/")
def index():
    db = get_db()
    contacts = db.execute("SELECT * FROM contacts").fetchall()
    contacts_html = '''
    <h2>Contact List</h2>
    <table>
        <tr><th>Name</th><th>Phone</th><th>Email</th><th>Legal Case</th></tr>
        {% for contact in contacts %}
        <tr>
            <td>{{ contact['name'] }}</td>
            <td>{{ contact['phone'] }}</td>
            <td>{{ contact['email'] }}</td>
            <td>{{ contact['legal_case'] }}</td>
        </tr>
        {% endfor %}
    </table>
    '''
    return render_template_string(
        TEMPLATE, windows95_css=WINDOWS_95_CSS,
        contacts=contacts,
        **{'block_content': contacts_html},
        **locals()
    ) if not contacts else render_template_string(
        '{% extends template %}{% block content %}' + contacts_html + '{% endblock %}',
        template=TEMPLATE, contacts=contacts, windows95_css=WINDOWS_95_CSS)

@app.route("/add", methods=["GET", "POST"])
def add_contact():
    form_html = '''
    <h2>Add New Contact</h2>
    <form method="post">
        <label>Name:<br><input name="name" required></label><br>
        <label>Phone:<br><input name="phone" required></label><br>
        <label>Email:<br><input name="email"></label><br>
        <label>Legal Case:<br><input name="legal_case"></label><br>
        <input type="submit" value="Add Contact">
    </form>
    '''
    if request.method == "POST":
        name = request.form['name']
        phone = request.form['phone']
        email = request.form['email']
        legal_case = request.form['legal_case']
        db = get_db()
        db.execute("INSERT INTO contacts (name, phone, email, legal_case) VALUES (?, ?, ?, ?)",
                   (name, phone, email, legal_case))
        db.commit()
        return redirect(url_for('index'))
    return render_template_string(
        '{% extends template %}{% block content %}' + form_html + '{% endblock %}',
        template=TEMPLATE, windows95_css=WINDOWS_95_CSS)

@app.route("/search", methods=["GET", "POST"])
def search_contacts():
    results = []
    output = None
    search_html = '''
    <h2>Search and Export Contacts</h2>
    <form method="post">
        <label>Search by Name or Phone:<br>
        <input name="query"></label><br>
        <input type="submit" name="search" value="Search">
    </form>
    <form method="post" style="margin-top:12px;">
        <label>Export contacts (by name):<br>
        <input name="export_query"></label>
        <input type="submit" name="export" value="Export to CSV">
    </form>
    '''
    # Results of search
    if request.method == "POST":
        if 'search' in request.form:
            q = request.form['query']
            db = get_db()
            results = db.execute("SELECT * FROM contacts WHERE name LIKE ? OR phone LIKE ?",
                                 (f'%{q}%', f'%{q}%')).fetchall()
            table_html = "<table><tr><th>Name</th><th>Phone</th><th>Email</th><th>Legal Case</th></tr>"
            for c in results:
                table_html += f"<tr><td>{c['name']}</td><td>{c['phone']}</td><td>{c['email']}</td><td>{c['legal_case']}</td></tr>"
            table_html += "</table>"
            search_html += table_html
        elif 'export' in request.form:
            name_filter = request.form['export_query']
            # CWE-78: OS Command Injection - user input in shell command below
            # Exports all contacts with names matching input to CSV using the sqlite3 CLI via os.system
            cmd = f"sqlite3 -header -csv '{DATABASE}' \"SELECT * FROM contacts WHERE name LIKE '%{name_filter}%';\" > export.csv"
            os.system(cmd)
            try:
                with open('export.csv', 'r') as f:
                    output = f"<h3>Exported CSV Output</h3><pre>{f.read()}</pre>"
            except Exception as e:
                output = f"<pre>Failed to export: {e}</pre>"
    page = '{% extends template %}{% block content %}' + search_html + '{% if output %}{{ output|safe }}{% endif %}{% endblock %}'
    return render_template_string(
        page,
        template=TEMPLATE, windows95_css=WINDOWS_95_CSS, output=output)

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6088)

from flask import Flask, request, render_template_string, send_file, redirect, url_for, flash
import sqlite3
import os
import subprocess

app = Flask(__name__)
app.secret_key = 'futuristic_secret_key'

DB_PATH = 'app_db'

# Initialize DB with some HR data
def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE employees (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT,
                        position TEXT,
                        department TEXT
                    )''')
        employees = [
            ('Ava Quantum', 'AI Engineer', 'Research'),
            ('Zane Matrix', 'DevOps Specialist', 'IT'),
            ('Nova Holo', 'Holographist', 'Design'),
            ('Lynx Chrome', 'Security Analyst', 'IT'),
            ('Orion Pulse', 'Product Owner', 'Management')
        ]
        c.executemany('INSERT INTO employees (name, position, department) VALUES (?,?,?)', employees)
        conn.commit()
        conn.close()

init_db()

FUTURISTIC_STYLE = '''
<style>
body { background: #151925; color: #B9FAF8; font-family: 'Orbitron', sans-serif;}
h1 { color: #00FFC6; letter-spacing:2px; text-shadow:0 0 8px #39FF14;}
.container { background:rgba(30,34,60,0.85); border-radius:18px; margin:auto; padding:2rem; max-width:520px; box-shadow: 0 0 40px #00FFC6;}
label {font-weight: bold}
input[type=text], select { width:100%; background:#222436; border:1px solid #0FF; color:#0FF; padding:.6rem; border-radius:7px;}
button {background:#00FFC6; color:#222436; padding:.7rem 2rem; border:none; border-radius:10px; font-weight:bold; font-size:1rem; box-shadow:0 0 16px #00FFC6;}
button:hover { background:#151925; color:#00FFC6; border:1px solid #00FFC6; cursor:pointer;}
table {width:100%; margin-top:1rem; background:#222436; border-radius:10px;}
th,td {padding:.6rem; border-bottom:1px solid #00FFC6; }
th {color:#39FF14;}
.flashmsg {background:#2af598; color:#111; padding:.6rem 1rem; margin-bottom:1rem; border-radius:6px;}
</style>
<link href="https://fonts.googleapis.com/css?family=Orbitron:600" rel="stylesheet">
'''

INDEX_PAGE = FUTURISTIC_STYLE + '''
<div class="container">
    <h1>Human Resource Quantum Dashboard</h1>
    {% with messages = get_flashed_messages() %}
    {% if messages %}
      {% for msg in messages %}
        <div class="flashmsg">{{ msg }}</div>
      {% endfor %}
    {% endif %}
    {% endwith %}
    <form method="post" action="{{ url_for('export') }}">
        <label>Filter by Department:</label>
        <select name="department">
            <option value="">All</option>
            <option value="Research">Research</option>
            <option value="IT">IT</option>
            <option value="Design">Design</option>
            <option value="Management">Management</option>
        </select>
        <button type="submit">Export CSV</button>
    </form>
    <h2>Employee Matrix</h2>
    <table>
        <tr>
            <th>ID</th><th>Name</th><th>Position</th><th>Department</th>
        </tr>
        {% for row in employees %}
        <tr>
            <td>{{ row[0] }}</td>
            <td>{{ row[1] }}</td>
            <td>{{ row[2] }}</td>
            <td>{{ row[3] }}</td>
        </tr>
        {% endfor %}
    </table>
</div>
'''

@app.route('/')
def index():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT * FROM employees")
    employees = c.fetchall()
    conn.close()
    return render_template_string(INDEX_PAGE, employees=employees)

@app.route('/export', methods=['POST'])
def export():
    department = request.form.get('department', '').strip()
    # CWE-78: OS Command Injection vulnerable code (department injected unsafely into shell command)
    if department:
        # Build unsafe shell command with non-sanitized input
        query_cmd = (
            f"sqlite3 -header -csv {DB_PATH} "
            f"\"SELECT * FROM employees WHERE department='{department}';\""
        )
    else:
        query_cmd = (
            f"sqlite3 -header -csv {DB_PATH} "
            f"\"SELECT * FROM employees;\""
        )
    # This is *intentionally* vulnerable! Untrusted input is injected.
    try:
        output = subprocess.check_output(query_cmd, shell=True)
        with open('/tmp/export.csv', 'wb') as f:
            f.write(output)
        return send_file('/tmp/export.csv', mimetype='text/csv',
                         as_attachment=True, download_name='hr_employees.csv')
    except subprocess.CalledProcessError as e:
        flash('Export failed! (Invalid input?)')
        return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6004)

from flask import Flask, request, redirect, render_template_string, g, url_for
import sqlite3
import os
import subprocess

app = Flask(__name__)
DATABASE = 'app_db.db'

BLOG_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>Streaming Services Blog</title>
    <style>
        body { font-family: 'Segoe UI',sans-serif; background: #181a20; color: #f5f5f5; margin: 0; }
        .container { max-width: 650px; margin: 40px auto; background: #22242c; border-radius: 8px; padding: 30px 36px; box-shadow:0 4px 30px rgba(0,0,0,0.12);}
        h1 { color: #ef74de; text-align:center;}
        h2 { color: #9deefc; margin-top:20px;}
        .post { background:#292c36; margin: 18px 0; padding:14px 20px; border-radius:6px;}
        .title { font-size: 1.2rem; color: #ffc093;}
        .content { margin-top:5px; line-height:1.7;}
        .add-post-form { margin-top:30px; padding: 18px; background:#23252c; border-radius:7px;}
        label {display:block;font-weight:bold;margin: 8px 0 2px 0;}
        input[type=text], textarea {width:100%; padding:5px; border:none; border-radius:4px;}
        button {margin-top:11px;background:#7badfd;color:#222;border:none; padding:7px 16px; border-radius:4px;cursor:pointer;}
        button:hover{background:#ffe147;color:#181a20;}
        .run-cmd {margin:24px 0 8px 0;}
        .cmd-out {background:#383b44;color:#e1e6e6;padding:11px;border-radius:4px;}
        .error {color:#de5b73;}
    </style>
</head>
<body>
<div class="container">
    <h1>Streaming Services Blog</h1>
    <h2>Latest Posts</h2>
    {% for post in posts[::-1] %}
        <div class="post">
            <div class="title">{{ post['title']|e }}</div>
            <div class="content">{{ post['content']|e }}</div>
        </div>
    {% else %}
        <div style="padding:12px;">No posts yet.</div>
    {% endfor %}

    <form class="add-post-form" action="{{ url_for('add_post') }}" method="post">
        <h2>Add a New Post</h2>
        <label for="title">Title:</label>
        <input required maxlength="120" type="text" name="title" id="title">
        <label for="content">Content:</label>
        <textarea required maxlength="4000" name="content" id="content" rows="4"></textarea>
        <button type="submit">Add Post</button>
    </form>

    <div class="run-cmd">
        <h2>Check Service Status</h2>
        <form method="post" action="{{ url_for('run_cmd') }}">
            <label for="servicename">Service Name:</label>
            <input type="text" id="servicename" name="servicename" placeholder="e.g. nginx, sshd">
            <button type="submit">Check Status</button>
        </form>
        {% if cmd_output is not none %}
            <div class="cmd-out">
                <b>Output:</b><br>
                <pre>{{ cmd_output }}</pre>
            </div>
        {% endif %}
        {% if error %}
            <div class="error">{{ error }}</div>
        {% endif %}
    </div>
</div>
</body>
</html>
"""

def get_db():
    db = getattr(g, '_db', None)
    if db is None:
        db = g._db = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    if not os.path.exists(DATABASE):
        db = sqlite3.connect(DATABASE)
        db.execute('CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT)')
        db.commit()
        db.close()

@app.before_first_request
def before_first_request_func():
    init_db()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_db', None)
    if db is not None:
        db.close()

@app.route("/", methods=["GET"])
def index():
    db = get_db()
    posts = db.execute('SELECT id, title, content FROM posts ORDER BY id ASC').fetchall()
    return render_template_string(BLOG_TEMPLATE, posts=posts, cmd_output=None, error=None)

@app.route("/add", methods=["POST"])
def add_post():
    title = request.form.get("title", "")[:120]
    content = request.form.get("content", "")[:4000]
    db = get_db()
    db.execute("INSERT INTO posts (title, content) VALUES (?,?)", (title, content))
    db.commit()
    return redirect(url_for('index'))

@app.route("/run_cmd", methods=["POST"])
def run_cmd():
    servicename = request.form.get("servicename", "")
    cmd = f"systemctl status {servicename}"
    try:
        output = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT, timeout=2, text=True)
        error = None
    except subprocess.CalledProcessError as e:
        output = e.output
        error = None
    except Exception as exc:
        output = ""
        error = str(exc)
    db = get_db()
    posts = db.execute('SELECT id, title, content FROM posts ORDER BY id ASC').fetchall()
    return render_template_string(BLOG_TEMPLATE, posts=posts, cmd_output=output, error=error)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6004, debug=False)

import os
import sqlite3
from flask import Flask, render_template_string, request, redirect, url_for, session, flash

app = Flask(__name__)
app.secret_key = 'super_secret_key'
DATABASE = 'app_db'

if not os.path.isfile(DATABASE):
    conn = sqlite3.connect(DATABASE)
    cur = conn.cursor()
    cur.execute('''CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
    )''')
    cur.execute('''CREATE TABLE tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        task TEXT,
        FOREIGN KEY(user_id) REFERENCES users(id)
    )''')
    conn.commit()
    conn.close()

BASE_HTML = '''
<!DOCTYPE html>
<html>
<head>
  <title>Insurance Portfolio - To-Do</title>
  <link href="https://fonts.googleapis.com/css?family=Montserrat:700,300" rel="stylesheet">
