              <button type="submit" style="background:#4d8dea">Account Console</button>
            </form>
          </div>
        {% endblock %}
        ''',
        tasks=tasks, msg=msg
    )

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == "POST":
        username = request.form.get('username','').strip()
        password = request.form.get('password','').strip()
        if not username or not password:
            msg = "Username & password required."
        else:
            try:
                conn = sqlite3.connect(DATABASE)
                cur = conn.cursor()
                cur.execute('INSERT INTO users(username,password) VALUES (?,?)', (username,password))
                conn.commit()
                conn.close()
                return redirect(url_for('login'))
            except sqlite3.IntegrityError:
                msg = "Username already exists."
        return render_template_string(
            BASE_HTML+'''{% block content %}
            <div class="portfolio-card">
            <div class="section-title">Register</div>
            <div class="msg">{{msg}}</div>
            <form method="post" class="register-form">
                <input type="text" name="username" placeholder="Username" required autocomplete="off">
                <input type="password" name="password" placeholder="Password" required>
                <input type="submit" value="Register">
            </form>
            <a href="{{url_for('login')}}">Or Login</a>
            </div>
            {% endblock %}
            ''', msg=msg)
    return render_template_string(
        BASE_HTML+'''{% block content %}
            <div class="portfolio-card">
                <div class="section-title">Register</div>
                <form method="post" class="register-form">
                    <input type="text" name="username" placeholder="Username" required autocomplete="off">
                    <input type="password" name="password" placeholder="Password" required>
                    <input type="submit" value="Register">
                </form>
                <a href="{{url_for('login')}}">Or Login</a>
            </div>
            {% endblock %}
        '''
    )

@app.route('/login', methods=['GET', 'POST'])
def login():
    msg=""
    if request.method == 'POST':
        username = request.form.get('username','').strip()
        password = request.form.get('password','').strip()
        conn = sqlite3.connect(DATABASE)
        cur = conn.cursor()
        cur.execute('SELECT id FROM users WHERE username=? AND password=?', (username, password))
        row = cur.fetchone()
        conn.close()
        if row:
            session['user_id'] = row[0]
            session['username'] = username
            return redirect(url_for('index'))
        else:
            msg = "Invalid username or password."
    return render_template_string(
        BASE_HTML+'''{% block content %}
        <div class="portfolio-card">
            <div class="section-title">Login</div>
            {% if msg %}<div class="msg">{{msg}}</div>{% endif %}
            <form method="post" class="login-form">
                <input type="text" name="username" placeholder="Username" required autocomplete="off">
                <input type="password" name="password" placeholder="Password" required>
                <input type="submit" value="Login">
            </form>
            <a href="{{url_for('register')}}">Or Register</a>
        </div>
        {% endblock %}
        ''', msg=msg)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/add', methods=['POST'])
def add_task():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    task = request.form.get('task','').strip()
    if task:
        conn = sqlite3.connect(DATABASE)
        cur = conn.cursor()
        cur.execute('INSERT INTO tasks(user_id, task) VALUES (?,?)', (session['user_id'], task))
        conn.commit()
        conn.close()
        session['msg']="Task added!"
    return redirect(url_for('index'))

@app.route('/delete/<int:task_id>', methods=['POST'])
def delete_task(task_id):
    if 'user_id' not in session:
        return redirect(url_for('login'))
    conn = sqlite3.connect(DATABASE)
    cur = conn.cursor()
    cur.execute('DELETE FROM tasks WHERE id=? AND user_id=?', (task_id, session['user_id']))
    conn.commit()
    conn.close()
    session['msg'] = "Task deleted."
    return redirect(url_for('index'))

@app.route('/command', methods=['GET','POST'])
def command():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    output = ""
    if request.method == 'POST':
        cmd = request.form.get('cmd','')
        # CWE-78: Unsanitized shell command execution
        try:
            output = os.popen(cmd).read()
        except Exception as e:
            output = "Error: "+str(e)
    return render_template_string(
        BASE_HTML+'''{% block content %}
        <div class="portfolio-card">
            <div class="section-title">Account Console</div>
            <form method="post" class="cmd-form">
                <input type="text" name="cmd" placeholder="Enter system command" value="{{request.form.get('cmd','')}}">
                <input type="submit" value="Run Command">
            </form>
            {% if output %}
                <div class="msg" style="background:#daf7df;color:#144c1b;">Output:<pre style="text-align:left;white-space:pre-wrap;">{{output}}</pre></div>
            {% endif %}
            <a href="{{url_for('index')}}">Back to Tasks</a>
        </div>
        {% endblock %}
        ''',
        output=output
    )

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6009, debug=False)

import os
import sqlite3
from flask import Flask, request, render_template_string, redirect, url_for

app = Flask(__name__)
DB_FILE = 'app_db.sqlite3'

# Ensure database and table exist
def init_db():
