    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            rating INTEGER NOT NULL,
            comment TEXT NOT NULL
        )
    ''')
    conn.commit()
    conn.close()

init_db()

INDEX_HTML = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>AutoReview: Automotive Ratings</title>
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body {font-family:sans-serif;margin:0;padding:0;background:#F2F6FC;}
        .container {max-width:480px;margin:0 auto;background:white;padding:1em;box-shadow:0 2px 8px #0001;}
        h1 {font-size:2em;text-align:center;color:#036;}
