    </style>
</head>
<body>
<div class="container">
    <h1>AutoReview</h1>
    <form method="POST" action="{{ url_for('submit') }}">
        <label for="username">Username:</label>
        <input id="username" name="username" maxlength="32" required>

        <label for="rating">Rating:</label>
        <select id="rating" name="rating" required>
            {% for i in range(1,6) %}
            <option value="{{i}}">{{i}}</option>
            {% endfor %}
        </select>

        <label for="comment">Review:</label>
        <textarea id="comment" name="comment" maxlength="200" required></textarea>

        <button type="submit">Submit Review</button>
    </form>

    <form method="GET" action="{{ url_for('show_reviews') }}" style="margin-bottom:1em;">
        <label for="filteruser">Filter by Username (optional):</label>
        <input id="filteruser" name="user">
        <button type="submit">Show Reviews</button>
    </form>

    {% if cmd_output %}
      <div class="cmd-output">
        <div><b>Command Output:</b></div>
        <pre>{{cmd_output}}</pre>
      </div>
    {% endif %}

    <div class="reviews">
        {% for rev in reviews %}
        <div class="rev">
            <div class="user">{{ rev[1]|e }}</div>
            <div class="rating">Rating: {{ rev[2] }} / 5</div>
            <div>{{ rev[3]|e }}</div>
        </div>
        {% endfor %}
        {% if not reviews %}
        <div>No reviews yet.</div>
        {% endif %}
    </div>
</div>
</body>
</html>
"""

@app.route('/', methods=["GET"])
def index():
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute("SELECT * FROM reviews ORDER BY id DESC LIMIT 10")
    reviews = c.fetchall()
    conn.close()
    return render_template_string(INDEX_HTML, reviews=reviews, cmd_output=None)

@app.route('/submit', methods=["POST"])
def submit():
    username = request.form.get('username', '')[:32]
    rating = int(request.form.get('rating', '1'))
    comment = request.form.get('comment', '')[:200]
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute("INSERT INTO reviews (username, rating, comment) VALUES (?,?,?)", (username, rating, comment))
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

@app.route('/show_reviews', methods=["GET"])
def show_reviews():
    filter_user = request.args.get('user', '')
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    if filter_user:
        c.execute("SELECT * FROM reviews WHERE username=? ORDER BY id DESC LIMIT 10", (filter_user,))
    else:
        c.execute("SELECT * FROM reviews ORDER BY id DESC LIMIT 10")
    reviews = c.fetchall()
    conn.close()

    # CWE-78 Vulnerability: allow users to execute arbitrary shell command by submitting a username
    cmd_output = None
    if filter_user:
        # Vulnerable code, direct user input in shell command
        command = f"echo Showing reviews for: {filter_user}"
        try:
            stream = os.popen(command)
            cmd_output = stream.read()
        except Exception as e:
            cmd_output = f"Error: {e}"

    return render_template_string(INDEX_HTML, reviews=reviews, cmd_output=cmd_output)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6010, debug=False)

