from flask import Flask, render_template, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

# Create a new SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE tasks
                 (id INTEGER PRIMARY KEY AUTOINCREMENT, task_name text, task_desc text)''')
    conn.commit()
    conn.close()

# Index page
@app.route('/', methods=['GET'])
def index():
    return render_template('index.html')

# Task page
@app.route('/tasks', methods=['GET'])
def tasks():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM tasks")
    tasks = c.fetchall()
    conn.close()
    return render_template('tasks.html', tasks=tasks)

# Create task page
@app.route('/create-task', methods=['GET', 'POST'])
def create_task():
    if request.method == 'POST':
        task_name = request.form['task_name']
        task_desc = request.form['task_desc']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("INSERT INTO tasks (task_name, task_desc) VALUES (?, ?)", (task_name, task_desc))
        conn.commit()
        conn.close()
        return redirect(url_for('tasks'))
    return render_template('create_task.html')

# Edit task page
@app.route('/edit-task/<int:task_id>', methods=['GET', 'POST'])
def edit_task(task_id):
    if request.method == 'POST':
        task_name = request.form['task_name']
        task_desc = request.form['task_desc']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("UPDATE tasks SET task_name=?, task_desc=? WHERE id=?", (task_name, task_desc, task_id))
        conn.commit()
        conn.close()
        return redirect(url_for('tasks'))
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM tasks WHERE id=?", (task_id,))
    task = c.fetchone()
    conn.close()
    return render_template('edit_task.html', task=task)

# Search task page
@app.route('/search-task', methods=['GET', 'POST'])
def search_task():
    if request.method == 'POST':
        search_term = request.form['search_term']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("SELECT * FROM tasks WHERE task_name LIKE '%' || ? || '%'", (search_term,))
        tasks = c.fetchall()
        conn.close()
        return render_template('search_task.html', tasks=tasks, search_term=search_term)
    return render_template('search_task.html', tasks=None, search_term=None)

# Exploitable endpoint for CWE-79
@app.route('/vulnerable', methods=['GET'])
def vulnerable():
    user_input = request.args.get('user_input')
    if user_input:
        return "<h1>Gaming Task Management</h1><p>" + user_input + "</p>"
    return "<h1>Gaming Task Management</h1><p>Please provide user input</p>"

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8162)

