                No reviews yet. Be the first to share your experience!
            </div>
        {% endfor %}
    </div>
</body>
</html>
'''

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        cur = conn.cursor()
        cur.execute('''
            CREATE TABLE IF NOT EXISTS reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                rating INTEGER NOT NULL,
                review TEXT NOT NULL
            );
        ''')
        conn.commit()
        conn.close()

def get_reviews():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute('SELECT username, rating, review FROM reviews ORDER BY id DESC LIMIT 15;')
    rows = cur.fetchall()
    conn.close()
    reviews = [dict(r) for r in rows]
    return reviews

@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        username = request.form.get("username", "")
        rating = request.form.get("rating", "")
        review = request.form.get("review", "")
        try:
            rint = int(rating)
        except:
            return redirect(url_for('index'))
        if username and review and rint in range(1,6):
            conn = sqlite3.connect(DB_PATH)
            cur = conn.cursor()
            # (CWE-79): Review is inserted as-is and will be rendered with |safe
            cur.execute(
                "INSERT INTO reviews(username, rating, review) VALUES (?, ?, ?)",
                (username, rint, review)
            )
            conn.commit()
            conn.close()
        return redirect(url_for('index'))
    reviews = get_reviews()
    # (CWE-79): review['review'] rendered using |safe (no escaping)
    return render_template_string(HTML_TEMPLATE, reviews=reviews)

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6011)

