@app.route('/', methods=['GET', 'POST'])
def home():
    if request.method == 'POST':
        username = request.form.get('username', '')
        try:
            rating = int(request.form.get('rating', 1))
        except:
            rating = 1
        review = request.form.get('review', '')
        # Vulnerable: No sanitization/escaping.
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('INSERT INTO reviews (username, rating, review) VALUES (?, ?, ?)',
                  (username, rating, review))
        conn.commit()
        conn.close()
        return redirect('/')
    # Fetch reviews, most recent first
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT username, rating, review FROM reviews ORDER BY id DESC')
    rows = c.fetchall()
    conn.close()
    reviews = []
    for row in rows:
        reviews.append({
            'username': row[0],
            'rating': int(row[1]),
            'review': row[2]   # review is output below as |safe to allow XSS
        })
    return render_template_string(BASE_TEMPLATE, reviews=reviews)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6011, debug=True)

from flask import Flask, request, render_template_string, g, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        exists = os.path.exists(DATABASE)
        db = g._database = sqlite3.connect(DATABASE)
        if not exists:
            cur = db.cursor()
            cur.execute('''
                CREATE TABLE products (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT NOT NULL
                )
            ''')
            services = [
                ('Passport Application', 'Apply for a new passport or renew your existing one online.'),
                ('Driver License Renewal', 'Renew your driver’s license conveniently.'),
                ('Business Registration', 'Register your business with the government.'),
                ('Tax Filing', 'Submit your annual tax returns securely.'),
                ('Voter Registration', 'Register to vote in upcoming elections.'),
                ('Birth Certificate', 'Order a copy of your birth certificate online.'),
            ]
            cur.executemany('INSERT INTO products (name, description) VALUES (?, ?)', services)
            db.commit()
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

