@app.route('/', methods=['GET'])
def index():
    db = get_db()
    q = request.args.get('q', '')
    cursor = db.cursor()
    if q:
        # Search case-insensitive
        cursor.execute("SELECT name, description FROM products WHERE name LIKE ? OR description LIKE ?",
                       ('%' + q + '%', '%' + q + '%'))
    else:
        cursor.execute("SELECT name, description FROM products ORDER BY id DESC")
    rows = cursor.fetchall()
    products = [{'name': r[0], 'description': r[1]} for r in rows]
    return render_template_string(BASE_TEMPLATE, products=products, query=q)

@app.route('/add', methods=['GET', 'POST'])
def add():
    error = None
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        desc = request.form.get('description', '').strip()
        if not name or not desc:
            error = "Both name and description are required."
        else:
            # Store in DB directly without sanitization (for CWE-79 demonstration)
            db = get_db()
            db.execute("INSERT INTO products (name, description) VALUES (?, ?)", (name, desc))
            db.commit()
            return redirect(url_for('index'))
    return render_template_string(ADD_TEMPLATE, error=error)

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6013)

