from flask import Flask, request, render_template_string, g, redirect, url_for
import sqlite3
import os

# Configuration
DATABASE = 'app_db'
app = Flask(__name__)

# Minimalist HTML templates with inline CSS
INDEX_PAGE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>E-Commerce Feedback</title>
    <style>
        body { font-family: sans-serif; background: #fff; color: #222; margin:0; padding:0; }
        .container { max-width:480px; margin: 40px auto; padding:24px; background:#fafafa; border-radius:8px; box-shadow:0 2px 8px rgba(0,0,0,0.03);}
        h1 { margin-top:0; font-size:2em; letter-spacing:-1px;}
        form { display:flex; flex-direction:column; gap:10px; }
        textarea { padding:10px; font-size:1em; border:1px solid #ccc; border-radius:4px; }
        button { background:#222; color:#fff; padding:10px; font-size:1em; border:none; border-radius:4px;}
        .feedback-list { margin-top:32px; }
        .msg { padding:12px 0; border-bottom:1px solid #eee;}
        .msg:last-child { border-bottom:none; }
    </style>
</head>
<body>
    <div class="container">
        <h1>Feedback</h1>
        <form method="POST" action="{{ url_for('submit') }}">
            <textarea name="message" rows="3" placeholder="Your thoughts about our shop..." required></textarea>
            <button type="submit">Send</button>
        </form>
        <div class="feedback-list">
            {% for msg in messages %}
                <div class="msg">{{ msg['message']|safe }}</div>
            {% endfor %}
        </div>
    </div>
</body>
</html>
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    if not os.path.exists(DATABASE):
        with sqlite3.connect(DATABASE) as conn:
            c = conn.cursor()
            c.execute('''
                CREATE TABLE feedback (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    message TEXT NOT NULL
                )
            ''')
            conn.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    cur = db.execute('SELECT message FROM feedback ORDER BY id DESC')
    messages = cur.fetchall()
    # Vulnerable to XSS: msg['message'] is rendered with |safe
    return render_template_string(INDEX_PAGE, messages=messages)

@app.route('/submit', methods=['POST'])
def submit():
    message = request.form.get('message', '').strip()
    if message:
        db = get_db()
        db.execute('INSERT INTO feedback (message) VALUES (?)', (message,))
        db.commit()
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6074)

