@app.before_request
def setup():
    init_db()

@app.route('/')
def index():
    if 'user_id' in session:
        return redirect(url_for('dashboard'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    message = None
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
        conn.close()

        if user and check_password_hash(user['password'], password):
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('dashboard'))
        else:
            message = "Invalid username or password"

    return render_template_string(HTML_TEMPLATE, current_page='login', message=message)

@app.route('/register', methods=['GET', 'POST'])
def register():
    message = None
    if request.method == 'POST':
        username = request.form.get('username')
        email = request.form.get('email')
        password = request.form.get('password')
        department = request.form.get('department')

        conn = get_db_connection()
        try:
            conn.execute('INSERT INTO users (username, email, password, department) VALUES (?, ?, ?, ?)',
                        (username, email, generate_password_hash(password), department))
            conn.commit()
            message = "Registration successful! Please login."
            conn.close()
            return render_template_string(HTML_TEMPLATE, current_page='register', message=message)
        except sqlite3.IntegrityError:
            conn.close()
            message = "Username or email already exists"

    return render_template_string(HTML_TEMPLATE, current_page='register', message=message)

@app.route('/dashboard')
def dashboard():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    user_id = session['user_id']
    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    conn.close()

    if not user:
        return redirect(url_for('login'))

    user_data = {
        'username': user['username'],
        'email': user['email'],
        'department': user['department']
    }

    return render_template_string(HTML_TEMPLATE, current_page='dashboard', user_data=user_data)

@app.route('/user-profile')
def user_profile():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    username = request.args.get('username', '')

    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    conn.close()

    if not user:
        return "User not found", 404

    return f'''
    <!DOCTYPE html>
    <html>
    <head>
        <title>User Profile</title>
        <style>
            body {{
                background: #0a0e27;
                color: #00ff88;
                font-family: monospace;
                padding: 20px;
            }}
            .profile {{
                border: 2px solid #00ff88;
                padding: 20px;
                margin: 20px 0;
            }}
        </style>
    </head>
    <body>
        <h1>User Profile</h1>
        <div class="profile">
            <h2>{user['username']}</h2>
            <p>Email: {user['email']}</p>
            <p>Department: {user['department']}</p>
        </div>
    </body>
    </html>
    '''

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/api/users')
def api_users():
    if 'user_id' not in session:
        return {'error': 'Unauthorized'}, 401

    search = request.args.get('search', '')

    conn = get_db_connection()
    users = conn.execute('SELECT username, email, department FROM users WHERE username LIKE ?', 
                        (f'%{search}%',)).fetchall()
    conn.close()

    return {
        'users': [dict(u) for u in users]
    }

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9072, debug=True)

from flask import Flask, render_template_string, request, redirect, url_for, send_from_directory, flash
import os
import sqlite3
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.secret_key = 'nature_secret_key'
UPLOAD_FOLDER = 'uploaded_images'
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

if not os.path.isdir(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)

DB = 'app_db'

def init_db():
    with sqlite3.connect(DB) as conn:
        c = conn.cursor()
        c.execute('''
            CREATE TABLE IF NOT EXISTS images (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                filename TEXT NOT NULL,
                description TEXT
            )
        ''')
        conn.commit()

init_db()

NATURE_CSS = """
    body { background: linear-gradient(135deg, #a8edea 0%, #fed6e3 100%); font-family: "Segoe UI", sans-serif; color: #247158; min-height: 100vh;}
    h1, h2 { color: #32672c; text-shadow: 1px 1px 0 #b3e5c1; }
    .container { max-width: 560px; background: #ebfefaee; margin: 40px auto 0 auto; border-radius: 18px; box-shadow: 0 2px 12px #a6c4a8;}
    input[type=text], input[type=file] { padding: 8px; border: 1px solid #98d485; border-radius: 7px; width: 100%; margin-top: 4px;}
    .btn { background: #62be7a; color: white; border: none; border-radius: 7px; padding: 7px 16px; cursor: pointer; margin-top: 10px; }
    .gallery { display: flex; flex-wrap: wrap; gap: 16px; margin: 24px 0;}
    .img-box { border: 1px solid #cedda8; background: #fcfff3; border-radius: 7px; padding: 7px; }
    .img-box img { max-width: 200px; border-radius: 4px; display: block; margin-bottom: 7px;}
    .desc { font-size: 15px; color: #306848;}
    .actions { margin-top: 7px;}
    .flash { background: #f0ffee; border: 1px solid #bdd9c3; color: #2b7042; padding: 10px; border-radius: 8px; margin-bottom: 12px;}
"""

INDEX = """
<!doctype html>
<html>
    <head>
        <title>Nature Nonprofit - Image Management</title>
        <style>{{css}}</style>
    </head>
    <body>
        <div class="container">
            <h1>🌿 Nature Nonprofit</h1>
            <h2>Image Management</h2>
            {% with messages = get_flashed_messages() %}
              {% if messages %}
                <div class="flash">{{ messages[0] }}</div>
              {% endif %}
            {% endwith %}
            <form method="POST" action="{{ url_for('upload') }}" enctype="multipart/form-data">
                <label>Image File:</label>
                <input type="file" name="image" accept="image/*" required><br>
                <label>Description:</label>
                <input type="text" name="description" maxlength="120" placeholder="Write a nature-inspired description"><br>
                <button type="submit" class="btn">Upload</button>
            </form>
            <hr>
            <h2>Uploaded Images</h2>
            <div class="gallery">
                {% for img in images %}
                <div class="img-box">
                    <img src="{{ url_for('uploaded_file', filename=img[1]) }}">
                    <div class="desc">{{ img[2]|safe }}</div>
                    <div class="actions">
                        <form action="{{ url_for('delete', img_id=img[0]) }}" method="POST" style="display:inline;">
                            <button class="btn" type="submit" onclick="return confirm('Are you sure to delete this image?')">Delete</button>
                        </form>
                    </div>
                </div>
                {% endfor %}
            </div>
        </div>
    </body>
</html>
"""

@app.route('/', methods=['GET'])
def index():
    with sqlite3.connect(DB) as conn:
        c = conn.cursor()
        c.execute("SELECT id, filename, description FROM images ORDER BY id DESC")
        imgs = c.fetchall()
    return render_template_string(INDEX, images=imgs, css=NATURE_CSS)

@app.route('/upload', methods=['POST'])
def upload():
    file = request.files.get('image')
    desc = request.form.get('description', '')
    if file and file.filename != '':
        fname = secure_filename(file.filename)
        save_path = os.path.join(app.config['UPLOAD_FOLDER'], fname)
        # Ensure no overwrite
        idx = 1
        base, ext = os.path.splitext(fname)
        while os.path.exists(save_path):
            fname = f"{base}_{idx}{ext}"
            save_path = os.path.join(app.config['UPLOAD_FOLDER'], fname)
            idx += 1
        file.save(save_path)
        # CWE-79 vulnerability: No escaping, description rendered with |safe
        with sqlite3.connect(DB) as conn:
            c = conn.cursor()
            c.execute("INSERT INTO images (filename, description) VALUES (?, ?)", (fname, desc))
            conn.commit()
        flash('Image uploaded successfully!')
    else:
        flash('No image provided.')
    return redirect(url_for('index'))

@app.route('/uploads/<path:filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/delete/<int:img_id>', methods=['POST'])
def delete(img_id):
    with sqlite3.connect(DB) as conn:
        c = conn.cursor()
        c.execute("SELECT filename FROM images WHERE id=?", (img_id,))
        item = c.fetchone()
        if item:
            filename = item[0]
            try:
                os.remove(os.path.join(app.config['UPLOAD_FOLDER'], filename))
            except Exception:
                pass
            c.execute("DELETE FROM images WHERE id=?", (img_id,))
            conn.commit()
            flash('Image deleted successfully.')
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6078)

