DATABASE = 'app_db.sqlite'

def init_db():
    """Initialize the SQLite database with sample data."""
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()

        # Create tables
        c.execute('''CREATE TABLE IF NOT EXISTS transactions
                     (id INTEGER PRIMARY KEY, account_id TEXT, type TEXT, 
                      amount REAL, description TEXT, date TEXT, status TEXT)''')

        c.execute('''CREATE TABLE IF NOT EXISTS accounts
                     (id INTEGER PRIMARY KEY, account_id TEXT, holder_name TEXT, 
                      balance REAL, account_type TEXT)''')

        # Sample data
        sample_accounts = [
            ('ACC001', 'Alexandra Sterling', 1250000.50, 'Premium Wealth'),
            ('ACC002', 'Victoria Hamilton', 850000.75, 'Platinum Elite'),
            ('ACC003', 'Nathaniel Cross', 2100000.25, 'Signature Reserve'),
        ]

        for account in sample_accounts:
            c.execute('INSERT INTO accounts (account_id, holder_name, balance, account_type) VALUES (?, ?, ?, ?)', account)

        sample_transactions = [
            ('ACC001', 'Transfer', 50000, 'International wire to Geneva', datetime.now().strftime('%Y-%m-%d'), 'Completed'),
            ('ACC001', 'Deposit', 100000, 'Investment contribution', datetime.now().strftime('%Y-%m-%d'), 'Completed'),
            ('ACC002', 'Withdrawal', 25000, 'Cash withdrawal', datetime.now().strftime('%Y-%m-%d'), 'Completed'),
            ('ACC003', 'Transfer', 75000, 'Real estate acquisition', datetime.now().strftime('%Y-%m-%d'), 'Pending'),
        ]

        for tx in sample_transactions:
            c.execute('INSERT INTO transactions (account_id, type, amount, description, date, status) VALUES (?, ?, ?, ?, ?, ?)', tx)

        conn.commit()
        conn.close()

def get_db():
    """Get database connection."""
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

