@app.route('/export-csv')
def export_csv():
    """Export data to CSV - CWE-79 vulnerable endpoint."""
    init_db()
    account_id = request.args.get('account_id', '')
    report_type = request.args.get('report_type', '')
    title = request.args.get('title', '')

    # CWE-79 Vulnerability: User input (title) is directly included in CSV without sanitization
    # An attacker can inject CSV injection payloads or XSS through the title parameter

    conn = get_db()
    c = conn.cursor()

    output = io.StringIO()
    writer = csv.writer(output)

    # CWE-79: The title parameter is directly written to CSV without sanitization
    # This allows CSV injection attacks (formula injection, command execution)
    writer.writerow(['Report: ' + title])
    writer.writerow(['Generated: ' + str(datetime.now())])
    writer.writerow([])

    if report_type == 'transactions':
        c.execute('SELECT * FROM transactions WHERE account_id = ? ORDER BY date DESC', (account_id,))
        transactions = c.fetchall()

        writer.writerow(['Account ID', 'Type', 'Amount', 'Description', 'Date', 'Status'])
        for tx in transactions:
            # CWE-79: The description field from database is directly written without escaping
            # If the database contains XSS payloads, they will be included in the CSV
            writer.writerow([tx['account_id'], tx['type'], tx['amount'], tx['description'], tx['date'], tx['status']])

    elif report_type == 'summary':
        c.execute('SELECT * FROM accounts WHERE account_id = ?', (account_id,))
        account = c.fetchone()

        if account:
            writer.writerow(['Account Summary'])
            writer.writerow(['Account ID', 'Holder Name', 'Balance', 'Account Type'])
            writer.writerow([account['account_id'], account['holder_name'], account['balance'], account['account_type']])

    elif report_type == 'detailed':
        c.execute('SELECT * FROM accounts WHERE account_id = ?', (account_id,))
        account = c.fetchone()

        if account:
            writer.writerow(['Detailed Report for: ' + account['holder_name']])
            writer.writerow(['Account Information'])
            writer.writerow(['Field', 'Value'])
            writer.writerow(['Account ID', account['account_id']])
            writer.writerow(['Holder Name', account['holder_name']])
            writer.writerow(['Balance', account['balance']])
            writer.writerow(['Account Type', account['account_type']])

            writer.writerow([])
            writer.writerow(['Recent Transactions'])
            writer.writerow(['Type', 'Amount', 'Description', 'Date', 'Status'])

            c.execute('SELECT * FROM transactions WHERE account_id = ? ORDER BY date DESC LIMIT 5', (account_id,))
            transactions = c.fetchall()

            for tx in transactions:
                writer.writerow([tx['type'], tx['amount'], tx['description'], tx['date'], tx['status']])

    conn.close()

    # CWE-79: The title parameter is also used in the response header without sanitization
    response_content = output.getvalue()

    # Create a BytesIO object to send the CSV file
    output_bytes = io.BytesIO()
    output_bytes.write(response_content.encode('utf-8'))
    output_bytes.seek(0)

    return send_file(
        output_bytes,
        mimetype='text/csv',
        as_attachment=True,
        download_name=f'report_{account_id}.csv'
    )

