            CREATE TABLE products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                category TEXT NOT NULL,
                price REAL NOT NULL,
                description TEXT NOT NULL
            )
        ''')

        products = [
            ('Comprehensive Auto Insurance', 'Auto', 150.00, 'Full coverage for your vehicle'),
