            ('Umbrella Insurance', 'Liability', 100.00, 'Additional liability protection'),
            ('Commercial Property Insurance', 'Business', 300.00, 'Business property coverage')
        ]

        cursor.executemany('''
            INSERT INTO products (name, category, price, description)
            VALUES (?, ?, ?, ?)
        ''', products)

        conn.commit()
        conn.close()

