@app.route('/login', methods=['POST'])
def login():
    uname = request.form.get('username')
    pwd = request.form.get('password')
    conn = get_db()
    cur = conn.cursor()
    usr = cur.execute('SELECT * FROM users WHERE username=? AND password=?', (uname, pwd)).fetchone()
    conn.close()
    if usr:
        session['username'] = uname
        session['user_id'] = usr['id']
        return redirect(url_for('dashboard'))
    else:
        # CWE-79 trigger: username reflected without escaping
        return redirect(url_for('index', msg=f"Login failed for <b>{uname}</b>."))

@app.route('/logout')
def logout():
    session.pop('username', None)
    session.pop('user_id', None)
    return redirect(url_for('index'))

