def dashboard():
    if 'username' not in session:
        return redirect(url_for('index'))
    conn = get_db()
    cur = conn.cursor()
    files = cur.execute('SELECT * FROM files WHERE user_id=? ORDER BY id DESC', (session['user_id'],)).fetchall()
