            th,td {font-size:1em; text-align:left; padding:7px; border-bottom:1px solid #eee;}
            .meta {color:#666; font-size:0.97em;}
            .danger {color:#d8000c; font-size:0.97em;}
            input[type=file]{margin:13px 0;}
            .center{text-align:center;}
        </style>
    </head>
    <body>
    <div class="main">
        <h2>🏘️ Dashboard</h2>
        <p class="meta">Upload your real estate files (PDF, images, docs)</p>
        <form method="POST" enctype="multipart/form-data" action="{{url_for('upload')}}">
            <input type="file" name="file" required>
            <button class="btn">Upload</button>
        </form>
        {% with msg = request.args.get('msg') %}
            {% if msg %}
                <div class="danger">{{msg | safe}}</div>
            {% endif %}
        {% endwith %}
        <h3 style="font-weight:400;margin:26px 0 16px">My Uploaded Files</h3>
        <table>
            <tr><th>File Name</th><th>Uploaded</th><th>Download</th></tr>
            {% for f in files %}
                <tr>
                  <td>{{f['orig_filename'] | safe}}</td>
                  <td>{{f['uploaded_at']}}</td>
                  <td><a href="{{url_for('download',file_id=f['id'])}}">Download</a></td>
                </tr>
            {% else %}
                <tr><td colspan=3 class="center meta">No files uploaded yet.</td></tr>
            {% endfor %}
        </table>
        <div class="center" style="margin-top:23px;">
            <a href="{{url_for('logout')}}">Logout</a>
        </div>
    </div>
    </body>
    </html>
    ''', files=files)

@app.route('/upload', methods=['POST'])
def upload():
    if 'username' not in session:
        return redirect(url_for('index'))
    uploaded_file = request.files.get('file')
    if not uploaded_file:
        return redirect(url_for('dashboard', msg='No file uploaded.'))
    orig_name = uploaded_file.filename
    filename = secure_filename(orig_name)
    if filename == "":
        return redirect(url_for('dashboard', msg='Invalid filename.'))
    user_id = session['user_id']
    file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    uploaded_file.save(file_path)
    conn = get_db()
    cur = conn.cursor()
    # CWE-79: reflect user-controlled original filename on dashboard, no escaping
    from datetime import datetime
    dt = datetime.utcnow().strftime("%Y-%m-%d %H:%M")
    cur.execute('INSERT INTO files(filename,orig_filename,user_id,uploaded_at) VALUES (?,?,?,?)',
        (filename, orig_name, user_id, dt))
    conn.commit()
    conn.close()
    return redirect(url_for('dashboard', msg=f'File <b>{orig_name}</b> uploaded.'))

@app.route('/download/<int:file_id>')
def download(file_id):
    if 'username' not in session:
        return redirect(url_for('index'))
    conn = get_db()
    cur = conn.cursor()
    fl = cur.execute('SELECT * FROM files WHERE id=? AND user_id=?', (file_id, session['user_id'])).fetchone()
    conn.close()
    if not fl:
        return redirect(url_for('dashboard', msg='File not found.'))
    file_path = os.path.join(app.config['UPLOAD_FOLDER'], fl['filename'])
    if not os.path.exists(file_path):
        return redirect(url_for('dashboard', msg='Stored file missing.'))
    return send_from_directory(app.config['UPLOAD_FOLDER'], fl['filename'], as_attachment=True, download_name=fl['orig_filename'])

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6007)

#!/usr/bin/env python3
from flask import Flask, render_template_string, request, jsonify, session
import sqlite3
import os
from datetime import datetime
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(16)

DATABASE = '/tmp/app_db.db'

def get_db_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                author TEXT NOT NULL,
                rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS articles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                summary TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        cursor.execute('''
            INSERT INTO articles (title, summary) VALUES 
            ('Breaking: New Technology Reshapes Industry', 'Revolutionary technology announced today promises to transform the sector'),
            ('Expert Analysis: Market Trends for 2024', 'Industry experts share insights on upcoming market opportunities'),
            ('Reader Reviews: Top 5 News Stories of the Week', 'Community shares favorite coverage from this week')
        ''')
        conn.commit()
        conn.close()

