                <div id="articles"></div>
            </section>

            <section class="section">
                <h2>Submit Your Review</h2>
                <div id="successMessage" class="success-message" role="status" aria-live="polite">
                    Your review has been submitted successfully!
                </div>
                <div id="errorMessage" class="error-message" role="alert">
                    Please fill in all required fields.
                </div>

                <form id="reviewForm" onsubmit="submitReview(event)">
                    <div class="form-group">
                        <label for="authorInput">Your Name</label>
                        <input 
                            type="text" 
                            id="authorInput" 
                            placeholder="Enter your name" 
                            required
                            aria-required="true"
                            aria-describedby="authorHelp"
                        >
                        <small id="authorHelp" style="color: #999; margin-top: 5px;">Used to identify your review</small>
                    </div>

                    <div class="form-group">
                        <label for="ratingSelect">Rating</label>
                        <select id="ratingSelect" required aria-required="true">
                            <option value="">-- Select a rating --</option>
                            <option value="5">⭐⭐⭐⭐⭐ Excellent</option>
                            <option value="4">⭐⭐⭐⭐ Good</option>
                            <option value="3">⭐⭐⭐ Average</option>
                            <option value="2">⭐⭐ Poor</option>
                            <option value="1">⭐ Very Poor</option>
                        </select>
