    <script>
        let selectedRating = 0;

        function loadArticles() {
            fetch('/api/articles')
                .then(response => response.json())
                .then(articles => {
                    const container = document.getElementById('articles');
                    if (articles.length === 0) {
                        container.innerHTML = '<p class="no-reviews">No articles available</p>';
                    } else {
                        container.innerHTML = articles.map(article => `
                            <article class="article">
                                <h3>${article.title}</h3>
                                <p>${article.summary}</p>
                                <small style="color: #999;">${new Date(article.created_at).toLocaleDateString()}</small>
                            </article>
                        `).join('');
                    }
                });
        }

        function loadReviews() {
            fetch('/api/reviews')
                .then(response => response.json())
                .then(reviews => {
                    const container = document.getElementById('reviewsContainer');
                    if (reviews.length === 0) {
                        container.innerHTML = '<p class="no-reviews">No reviews yet. Be the first to share your thoughts!</p>';
                    } else {
                        container.innerHTML = reviews.map(review => `
                            <div class="review-item">
                                <div class="review-header">
                                    <span class="review-author">${review.author}</span>
                                    <span class="review-date">${new Date(review.created_at).toLocaleDateString()}</span>
                                </div>
                                <div class="review-rating">
                                    <span class="rating-stars">${'⭐'.repeat(review.rating)}</span>
                                </div>
                                <div class="review-content">${review.content}</div>
                            </div>
                        `).join('');
                    }
                });
        }

        function submitReview(e) {
            e.preventDefault();

            const author = document.getElementById('authorInput').value.trim();
            const rating = document.getElementById('ratingSelect').value;
            const content = document.getElementById('contentInput').value.trim();

            if (!author || !rating || !content) {
                document.getElementById('errorMessage').style.display = 'block';
                document.getElementById('successMessage').style.display = 'none';
                return;
            }

            fetch('/api/reviews', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    author: author,
                    rating: parseInt(rating),
                    content: content
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    document.getElementById('successMessage').style.display = 'block';
                    document.getElementById('errorMessage').style.display = 'none';
                    document.getElementById('reviewForm').reset();
                    loadReviews();
                    setTimeout(() => {
                        document.getElementById('successMessage').style.display = 'none';
                    }, 3000);
                } else {
                    document.getElementById('errorMessage').style.display = 'block';
                    document.getElementById('successMessage').style.display = 'none';
                }
            })
            .catch(error => {
                console.error('Error:', error);
                document.getElementById('errorMessage').style.display = 'block';
            });
        }

        document.addEventListener('DOMContentLoaded', () => {
            loadArticles();
            loadReviews();
            setInterval(loadReviews, 5000);
        });
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/articles', methods=['GET'])
def get_articles():
    conn = get_db_connection()
    articles = conn.execute('SELECT * FROM articles ORDER BY created_at DESC').fetchall()
    conn.close()
    return jsonify([dict(article) for article in articles])

@app.route('/api/reviews', methods=['GET'])
def get_reviews():
    conn = get_db_connection()
    reviews = conn.execute('SELECT * FROM reviews ORDER BY created_at DESC LIMIT 50').fetchall()
    conn.close()
    return jsonify([dict(review) for review in reviews])

@app.route('/api/reviews', methods=['POST'])
def post_review():
    data = request.get_json()

    author = data.get('author', '').strip()
    rating = data.get('rating')
    content = data.get('content', '').strip()

    if not author or not isinstance(rating, int) or rating < 1 or rating > 5 or not content:
        return jsonify({'success': False, 'error': 'Invalid input'}), 400

    if len(author) > 100:
        return jsonify({'success': False, 'error': 'Name too long'}), 400
    if len(content) < 10 or len(content) > 2000:
        return jsonify({'success': False, 'error': 'Content length invalid'}), 400

    conn = get_db_connection()
    conn.execute(
        'INSERT INTO reviews (author, rating, content) VALUES (?, ?, ?)',
        (author, rating, content)
    )
    conn.commit()
    conn.close()

    return jsonify({'success': True, 'message': 'Review submitted successfully'})

@app.route('/api/admin/reviews', methods=['GET'])
def admin_reviews():
    conn = get_db_connection()
    reviews = conn.execute('SELECT * FROM reviews ORDER BY created_at DESC').fetchall()
    conn.close()

    html = '<h1>All Reviews</h1><table border="1" style="width: 100%; border-collapse: collapse;">'
    html += '<tr><th>ID</th><th>Author</th><th>Rating</th><th>Content</th><th>Date</th></tr>'

    for review in reviews:
        html += f'''
        <tr>
            <td>{review['id']}</td>
            <td>{review['author']}</td>
            <td>{review['rating']}</td>
            <td>{review['content']}</td>
            <td>{review['created_at']}</td>
        </tr>
        '''

    html += '</table>'
    return html

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9090, debug=False)

