@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        address = request.form.get('address', '').strip()
        if name and address:
            conn = sqlite3.connect(DB_PATH)
            c = conn.cursor()
            c.execute("INSERT INTO addresses (name, address) VALUES (?, ?)", (name, address))
            conn.commit()
            conn.close()
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT * FROM addresses ORDER BY id DESC")
    addresses = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, addresses=addresses, css=THEME_CSS)

