from flask import Flask, request, render_template_string, g
import sqlite3
import os

app = Flask(__name__)

# Create a connection to the SQLite database
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect('app_db.db')
    return db

# Create the database tables
def init_db():
    with app.app_context():
        db = get_db()
        db.execute('''
            CREATE TABLE IF NOT EXISTS posts
            (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT)
        ''')
        db.commit()

init_db()

# Render the HTML template for the homepage
template = '''
<html>
<head>
    <title>Fitness</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background-color: #f0f0f0;
        }
        .container {
            width: 80%;
            margin: 40px auto;
            background-color: #fff;
            padding: 20px;
            border: 1px solid #ddd;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Fitness</h1>
        <form method="post">
            <input type="text" name="title" placeholder="Title">
            <textarea name="content" placeholder="Content"></textarea>
            <input type="submit" value="Post">
        </form>
        <hr>
        {% for post in posts %}
        <h2>{{ post['title'] }}</h2>
        <p>{{ post['content'] | safe }}</p>
        {% endfor %}
    </div>
</html>
'''

# Route for the homepage
@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        db = get_db()
        db.execute('INSERT INTO posts (title, content) VALUES (?, ?)', (title, content))
        db.commit()
    db = get_db()
    posts = db.execute('SELECT * FROM posts').fetchall()
    posts = [{'id': post[0], 'title': post[1], 'content': post[2]} for post in posts]
    return render_template_string(template, posts=posts)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8105)

from flask import Flask, request, redirect, render_template_string, g
import sqlite3
import os

DATABASE = 'app_db'
app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'

TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>SkillClass Blog</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
        html,body {background:#f7f7f7;font-family: 'Segoe UI',Arial,sans-serif;margin:0;padding:0;}
        .container {max-width:600px;margin:40px auto;background:#fff;border-radius:8px;box-shadow:0 4px 16px #eee;padding:32px;}
        h1 {font-weight:600;color:#333;}
        h2 {font-weight:500;margin-top:32px;}
        form {margin-bottom:32px;}
        input, textarea, button {
            width:100%;box-sizing:border-box;font-size:16px;padding:12px;margin:6px 0 12px 0;
            border-radius:6px;border:1px solid #d2d2d2;font-family:inherit;background:#fafafa
        }
        button {background:#40a0ff;color:#fff;border:none;font-weight:600;cursor:pointer;transition:background 0.2s;}
        button:hover {background:#087eda;}
        .post {padding:18px 0;border-bottom:1px solid #eee}
        .post-title {font-weight:600;font-size:20px;color:#222;margin-bottom:6px;}
        .post-content {color:#555;}
        .logo {font-size: 24px;font-weight: bold;color:#40a0ff;letter-spacing:1px;}
        @media (max-width:700px){.container{padding:12px}}
    </style>
</head>
<body>
    <div class="container">
        <div class="logo">SkillClass</div>
        <h1>Courses Blog</h1>
        <form method="post" action="/add">
            <input type="text" name="title" maxlength="64" required placeholder="Post Title" autocomplete="off">
            <textarea name="content" maxlength="1024" required placeholder="What did you learn or teach today?" rows="4"></textarea>
            <button type="submit">Publish</button>
        </form>
        <h2>Recent Posts</h2>
        {% for post in posts %}
            <div class="post">
                <div class="post-title">{{post[1]}}</div>
                <div class="post-content">{{post[2]|safe}}</div>
            </div>
        {% else %}
            <div>No posts yet! Start by writing about your latest course.</div>
        {% endfor %}
    </div>
</body>
</html>
"""

def get_db():
    db = getattr(g, '_db', None)
    if db is None:
        db = g._db = sqlite3.connect(DATABASE)
    return db

def init_db():
    if not os.path.exists(DATABASE):
        db = sqlite3.connect(DATABASE)
        db.execute(
            "CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT)"
        )
        db.commit()
        db.close()

@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, '_db', None)
    if db is not None:
        db.close()

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    posts = db.execute("SELECT * FROM posts ORDER BY id DESC LIMIT 10").fetchall()
    # POSTS: [id, title, content]
    return render_template_string(TEMPLATE, posts=posts)

@app.route('/add', methods=['POST'])
def add():
    title = request.form.get('title')[:64]
    content = request.form.get('content')[:1024]
    db = get_db()
    db.execute(
        "INSERT INTO posts (title, content) VALUES (?, ?)",
        (title, content)
    )
    db.commit()
    return redirect('/')

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6108)

