from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db'

HTML_BASE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>Healthcare QuickPoll</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
        body {{ 
            margin:0; 
            background: #fafbfc; 
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: #283852;
        }}
        .container {{
            max-width:430px; 
            margin:30px auto; 
            background:#fff; 
            padding:30px 32px; 
            border-radius:16px; 
            box-shadow:0 2px 24px 0 #a4b3c23a;
        }}
        h1 {{
            font-size: 2em; 
            margin-top: 0;
            color: #2196d6;
        }}
        label {{
            font-size: 1.2em;
            margin-bottom:10px;
        }}
        .choices {{
            margin: 16px 0 32px 0;
        }}
        .vote-btn {{
            background: #5fbf70; color:#fff; 
            border:none; 
            padding: 12px 0; 
            width:100%; 
            border-radius:8px; 
            font-size: 1.15em;
            font-weight: bold;
            letter-spacing: 0.03em;
            transition: background .17s;
            cursor:pointer;
        }}
        .vote-btn:hover {{
            background:#2196d6;
        }}
        .results {{
            margin:16px 0;
        }}
        .result-bar {{
            height: 16px; border-radius:4px; margin: 4px 0 12px 0; background: #e3eef6; position:relative; overflow:hidden;
        }}
        .bar-fill {{
            background: linear-gradient(90deg, #2196d6 65%, #71e398);
            height:100%; display:inline-block;
        }}
        .success-msg {{
            background: #e5f9ec; 
            color: #219c5c; 
            padding: 10px 18px; 
            border-radius: 5px; 
            margin-bottom: 6px; 
            border: 1px solid #a7ebc1;
        }}
        .footnote {{
            text-align:center; 
            margin-top:32px; 
            color:#aaa; 
            font-size:.98em;
        }}
    </style>
</head>
<body>
    <div class="container">
        {content}
    </div>
    <div class="footnote">Healthcare QuickPoll &copy; 2024</div>
</body>
</html>
"""

POLL_QUESTION = "How important do you think regular health checkups are?"
CHOICES = [
    "Extremely important",
    "Somewhat important",
    "Not very important",
    "Not at all important"
]

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''
            CREATE TABLE votes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                choice TEXT NOT NULL,
                username TEXT
            )
        ''')
        conn.commit()
        conn.close()

@app.route('/', methods=['GET', 'POST'])
def poll():
    msg = ''
    if request.method == 'POST':
        choice = request.form.get('choice')
        username = request.form.get('username', '')[:32]
        if choice in CHOICES:
            conn = sqlite3.connect(DATABASE)
            c = conn.cursor()
            c.execute('INSERT INTO votes (choice, username) VALUES (?, ?)', (choice, username))
            conn.commit()
            conn.close()
            return redirect(url_for('results', username=username))
        else:
            msg = '<div class="success-msg" style="background: #ffecd7; color: #cc6600; border-color: #ffcd9e;">Choose an option.</div>'

    form_html = f'''
    {msg}
    <h1>Healthcare Poll</h1>
    <form method="post" autocomplete="off">
        <label>{POLL_QUESTION}</label>
        <div class="choices">
            {''.join([f'<div><input type="radio" name="choice" value="{c}"> {c}</div>' for c in CHOICES])}
        </div>
        <div style="margin-bottom:12px;">
            <input type="text" name="username" maxlength="32" placeholder="Name (optional)" value="" style="padding:8px; width:calc(100% - 18px); border:1.5px solid #d7e6ef; border-radius:6px; font-size:1em;">
        </div>
        <button type="submit" class="vote-btn">Vote</button>
    </form>
    <div style="text-align:right; margin-top:12px;">
        <a href="{url_for('results')}" style="color:#2196d6;text-decoration:underline;font-size:0.97em;">View Results</a>
    </div>
    '''
    return render_template_string(HTML_BASE.format(content=form_html))

@app.route('/results')
def results():
    username = request.args.get('username', '')
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT choice, COUNT(*) FROM votes GROUP BY choice')
    data = c.fetchall()
    c.execute('SELECT COUNT(*) FROM votes')
    total_votes = c.fetchone()[0]
    conn.close()
    counts = {choice:0 for choice in CHOICES}
    for row in data:
        counts[row[0]] = row[1]
    results_html = ""
    if username:
        # CWE-80: Reflected unsanitized username
        results_html += f'<div class="success-msg">Thank you for voting, <b>{username}</b>!</div>'
    results_html += '<h1>Poll Results</h1>'
    results_html += f"<div style='font-size:1.15em; margin-bottom:16px;'><em>{POLL_QUESTION}</em></div>"
    results_html += f"<div class='results'>"
    for c in CHOICES:
        amount = counts.get(c,0)
        percent = (amount/total_votes*100) if total_votes else 0
        results_html += f'''<div><b>{c}</b> &mdash; {amount} votes ({percent:.1f}%)</div>
        <div class="result-bar"><div class="bar-fill" style="width:{percent:.1f}%;"></div></div>
        '''
    results_html += '</div>'
    results_html += f"<div style='color:#68a892;margin:18px 0 8px 0;'>Total votes: <b>{total_votes}</b></div>"
    results_html += f'<div style="margin-top:16px;"><a href="{url_for("poll")}" style="color:#2196d6; text-decoration:underline;">Back to Poll</a></div>'
    return render_template_string(HTML_BASE.format(content=results_html))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6113)

import os
import sqlite3
from flask import Flask, render_template_string, request, jsonify, redirect, url_for
from datetime import datetime
import json

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def get_db_connection():
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(app.config['DATABASE']):
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_title TEXT NOT NULL,
                reviewer_name TEXT NOT NULL,
                rating INTEGER NOT NULL,
                review_text TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        conn.commit()
        conn.close()

init_db()

