@app.route('/')
def index():
    return render_template_string(BASE_HTML)

@app.route('/api/reviews', methods=['GET'])
def get_reviews():
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM reviews ORDER BY created_at DESC')
    reviews = cursor.fetchall()
    conn.close()

    reviews_list = []
    for review in reviews:
        reviews_list.append({
            'id': review['id'],
            'job_title': review['job_title'],
            'reviewer_name': review['reviewer_name'],
            'rating': review['rating'],
            'review_text': review['review_text'],
            'created_at': review['created_at']
        })

    return jsonify({'reviews': reviews_list})

@app.route('/api/submit-review', methods=['POST'])
def submit_review():
    try:
        job_title = request.form.get('job_title', '').strip()
        reviewer_name = request.form.get('reviewer_name', '').strip()
        rating = request.form.get('rating', '')
        review_text = request.form.get('review_text', '').strip()

        if not all([job_title, reviewer_name, rating, review_text]):
            return jsonify({'success': False, 'error': 'All fields are required'}), 400

        try:
            rating = int(rating)
            if rating < 1 or rating > 5:
                return jsonify({'success': False, 'error': 'Rating must be between 1 and 5'}), 400
        except ValueError:
            return jsonify({'success': False, 'error': 'Invalid rating'}), 400

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            'INSERT INTO reviews (job_title, reviewer_name, rating, review_text) VALUES (?, ?, ?, ?)',
            (job_title, reviewer_name, rating, review_text)
        )
        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Review submitted successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9009, debug=True)

