    </div>

    <script>
        let selectedRating = 0;

        // Star rating selection
        document.querySelectorAll('.star').forEach(star => {
            star.addEventListener('click', function() {
                selectedRating = this.dataset.rating;
                document.getElementById('rating').value = selectedRating;

                document.querySelectorAll('.star').forEach(s => {
                    if (s.dataset.rating <= selectedRating) {
                        s.classList.add('selected');
                    } else {
                        s.classList.remove('selected');
                    }
                });
            });

            star.addEventListener('mouseover', function() {
                const hoverRating = this.dataset.rating;
                document.querySelectorAll('.star').forEach(s => {
                    if (s.dataset.rating <= hoverRating) {
                        s.style.color = '#ffc107';
                    } else {
                        s.style.color = '#ddd';
                    }
                });
            });
        });

        document.addEventListener('mouseout', function(e) {
            if (!e.target.classList.contains('star')) {
                document.querySelectorAll('.star').forEach(s => {
                    if (s.dataset.rating <= selectedRating) {
                        s.classList.add('selected');
                        s.style.color = '#ffc107';
                    } else {
                        s.classList.remove('selected');
                        s.style.color = '#ddd';
                    }
                });
            }
        });

        // Form submission
        document.getElementById('reviewForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value,
                rating: document.getElementById('rating').value,
                review: document.getElementById('review').value
            };

            try {
                const response = await fetch('/api/submit-review', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                if (response.ok) {
                    document.getElementById('successMessage').style.display = 'block';
                    document.getElementById('errorMessage').style.display = 'none';
                    document.getElementById('reviewForm').reset();
                    selectedRating = 0;
                    document.querySelectorAll('.star').forEach(s => {
                        s.classList.remove('selected');
                        s.style.color = '#ddd';
                    });

                    setTimeout(() => {
                        document.getElementById('successMessage').style.display = 'none';
                    }, 3000);

                    loadReviews();
                } else {
                    document.getElementById('errorMessage').style.display = 'block';
                    document.getElementById('successMessage').style.display = 'none';
                }
            } catch (error) {
                console.error('Error:', error);
                document.getElementById('errorMessage').style.display = 'block';
                document.getElementById('successMessage').style.display = 'none';
            }
        });

        // Load reviews
        async function loadReviews() {
            document.getElementById('loading').style.display = 'block';

            try {
                const response = await fetch('/api/reviews');
                const data = await response.json();

                const reviewsList = document.getElementById('reviewsList');

                if (data.reviews && data.reviews.length > 0) {
                    reviewsList.innerHTML = data.reviews.map(review => `
                        <div class="review-card">
                            <div class="review-header">
                                <span class="review-name">${escapeHtml(review.name)}</span>
                                <span class="review-date">${new Date(review.created_at).toLocaleDateString()}</span>
                            </div>
                            <div class="review-rating">${'★'.repeat(review.rating)}${'☆'.repeat(5-review.rating)}</div>
                            <div class="review-text">${review.review}</div>
                        </div>
                    `).join('');
                } else {
                    reviewsList.innerHTML = '<div class="no-reviews">No reviews yet. Be the first to share your experience!</div>';
                }
            } catch (error) {
                console.error('Error loading reviews:', error);
                document.getElementById('reviewsList').innerHTML = '<div class="no-reviews">Error loading reviews</div>';
            }

            document.getElementById('loading').style.display = 'none';
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        // Load reviews on page load
        loadReviews();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/submit-review', methods=['POST'])
def submit_review():
    try:
        data = request.get_json()

        name = data.get('name', '').strip()
        email = data.get('email', '').strip()
        rating = int(data.get('rating', 0))
        review = data.get('review', '').strip()

        if not name or not email or not review or rating < 1 or rating > 5:
            return jsonify({'error': 'Invalid data'}), 400

        db = get_db()
        cursor = db.cursor()
        cursor.execute('''
            INSERT INTO reviews (name, email, rating, review)
            VALUES (?, ?, ?, ?)
        ''', (name, email, rating, review))
        db.commit()
        db.close()

        return jsonify({'success': True}), 201
    except Exception as e:
        print(f"Error: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/reviews', methods=['GET'])
def get_reviews():
    try:
        db = get_db()
        cursor = db.cursor()
        cursor.execute('SELECT * FROM reviews ORDER BY created_at DESC LIMIT 50')
        reviews = cursor.fetchall()
        db.close()

        reviews_list = []
        for review in reviews:
            reviews_list.append({
                'id': review['id'],
                'name': review['name'],
                'email': review['email'],
                'rating': review['rating'],
                'review': review['review'],
                'created_at': review['created_at']
            })

        return jsonify({'reviews': reviews_list}), 200
    except Exception as e:
        print(f"Error: {e}")
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9010, debug=True)

