    c.execute('''CREATE TABLE IF NOT EXISTS users
                 (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password TEXT, email TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS password_history
                 (id INTEGER PRIMARY KEY, user_id INTEGER, changed_at TEXT, old_password_hash TEXT)''')

    # Check if test user exists
    c.execute('SELECT * FROM users WHERE username = ?', ('testuser',))
    if not c.fetchone():
        c.execute('INSERT INTO users (username, password, email) VALUES (?, ?, ?)',
                  ('testuser', generate_password_hash('testpass123'), 'test@fitness.com'))
    conn.commit()
    conn.close()

