                    <div id="historyContainer">
                        <p class="no-history">Loading...</p>
                    </div>
                </div>

                <div style="margin-top: 20px; text-align: center;">
                    <button class="btn btn-secondary" onclick="handleLogout()" style="width: 100%; background-color: #6c757d; border: none; border-radius: 8px; padding: 10px; color: white; font-weight: 600; cursor: pointer;">Logout</button>
                </div>
                {% endif %}
