    <script>
        function handleLogin(event) {
            event.preventDefault();
            const username = document.getElementById('loginUsername').value;
            const password = document.getElementById('loginPassword').value;

            fetch('/api/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    username: username,
                    password: password
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    window.location.reload();
                } else {
                    alert('Login failed: ' + data.message);
                }
            })
            .catch(error => console.error('Error:', error));
        }

        function checkPasswordStrength() {
            const password = document.getElementById('newPassword').value;
            const strengthDiv = document.getElementById('passwordStrength');

            if (!password) {
                strengthDiv.style.display = 'none';
                return;
            }

            let strength = 0;
            const hasUpperCase = /[A-Z]/.test(password);
            const hasLowerCase = /[a-z]/.test(password);
            const hasNumbers = /[0-9]/.test(password);
            const hasSpecialChar = /[!@#$%^&*]/.test(password);

            if (hasUpperCase) strength++;
            if (hasLowerCase) strength++;
            if (hasNumbers) strength++;
            if (hasSpecialChar) strength++;

            strengthDiv.style.display = 'block';
            strengthDiv.classList.remove('strength-weak', 'strength-medium', 'strength-strong');

            if (password.length < 8) {
                strengthDiv.classList.add('strength-weak');
                strengthDiv.textContent = '❌ Password is too short (minimum 8 characters)';
            } else if (strength < 2) {
                strengthDiv.classList.add('strength-weak');
                strengthDiv.textContent = '❌ Weak password';
            } else if (strength < 3) {
                strengthDiv.classList.add('strength-medium');
                strengthDiv.textContent = '⚠️ Medium strength password';
            } else {
                strengthDiv.classList.add('strength-strong');
                strengthDiv.textContent = '✅ Strong password';
            }
        }

        function handlePasswordChange(event) {
            event.preventDefault();

            const currentPassword = document.getElementById('currentPassword').value;
            const newPassword = document.getElementById('newPassword').value;
            const confirmPassword = document.getElementById('confirmPassword').value;

            if (newPassword !== confirmPassword) {
                showAlert('Passwords do not match', 'danger');
                return;
            }

            if (newPassword.length < 8) {
                showAlert('Password must be at least 8 characters long', 'danger');
                return;
            }

            fetch('/api/change-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    current_password: currentPassword,
                    new_password: newPassword
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showAlert('Password changed successfully!', 'success');
                    document.getElementById('currentPassword').value = '';
                    document.getElementById('newPassword').value = '';
                    document.getElementById('confirmPassword').value = '';
                    document.getElementById('passwordStrength').style.display = 'none';
                    loadHistory();
                } else {
                    showAlert(data.message, 'danger');
                }
            })
            .catch(error => {
                console.error('Error:', error);
                showAlert('An error occurred', 'danger');
            });
        }

        function showAlert(message, type) {
            const alertContainer = document.getElementById('alertContainer');
            const alertDiv = document.createElement('div');
            alertDiv.className = `alert alert-${type}`;
            alertDiv.setAttribute('role', 'alert');
            alertDiv.textContent = message;

            alertContainer.innerHTML = '';
            alertContainer.appendChild(alertDiv);

            setTimeout(() => {
                alertDiv.remove();
            }, 5000);
        }

        function loadHistory() {
            fetch('/api/password-history')
            .then(response => response.json())
            .then(data => {
                const historyContainer = document.getElementById('historyContainer');
                if (data.history && data.history.length > 0) {
                    historyContainer.innerHTML = '';
                    data.history.forEach(item => {
                        const div = document.createElement('div');
                        div.className = 'history-item';
                        div.innerHTML = `<span class="timestamp">${item.changed_at}</span> - Password changed`;
                        historyContainer.appendChild(div);
                    });
                } else {
                    historyContainer.innerHTML = '<p class="no-history">No password changes yet</p>';
                }
            })
            .catch(error => console.error('Error:', error));
        }

        function handleLogout() {
            fetch('/api/logout', {
                method: 'POST'
            })
            .then(() => {
                window.location.reload();
            })
            .catch(error => console.error('Error:', error));
        }

        // Load history on page load
        document.addEventListener('DOMContentLoaded', function() {
            if (document.getElementById('historyContainer')) {
                loadHistory();
            }
        });
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    logged_in = 'user_id' in session
    return render_template_string(HTML_TEMPLATE, logged_in=logged_in)

@app.route('/api/login', methods=['POST'])
def api_login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    conn = get_db_connection()
    c = conn.cursor()
    c.execute('SELECT id, password FROM users WHERE username = ?', (username,))
    user = c.fetchone()
    conn.close()

    if user and check_password_hash(user['password'], password):
        session['user_id'] = user['id']
        session['username'] = username
        return jsonify({'success': True})
    else:
        return jsonify({'success': False, 'message': 'Invalid credentials'})

@app.route('/api/logout', methods=['POST'])
def api_logout():
    session.clear()
    return jsonify({'success': True})

@app.route('/api/change-password', methods=['POST'])
def api_change_password():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Not logged in'}), 401

    data = request.get_json()
    current_password = data.get('current_password')
    new_password = data.get('new_password')
    user_id = session['user_id']

    conn = get_db_connection()
    c = conn.cursor()

    c.execute('SELECT password FROM users WHERE id = ?', (user_id,))
    user = c.fetchone()

    if not user or not check_password_hash(user['password'], current_password):
        conn.close()
        return jsonify({'success': False, 'message': 'Current password is incorrect'})

    if len(new_password) < 8:
        conn.close()
        return jsonify({'success': False, 'message': 'Password must be at least 8 characters'})

    # Save old password to history
    c.execute('INSERT INTO password_history (user_id, changed_at, old_password_hash) VALUES (?, ?, ?)',
              (user_id, datetime.now().strftime('%Y-%m-%d %H:%M:%S'), user['password']))

    # Update password - VULNERABLE: Using unsanitized user input in SQL via string formatting
    new_password_hash = generate_password_hash(new_password)
    # CWE-83: Improper Neutralization of Script-Related HTML Tags in a Web Page
    # This vulnerability is demonstrated through the use of request.get_json() data
    # without proper validation in the password field, allowing potential XSS attacks
    # when the password history is displayed or logged

    # Vulnerable SQL construction - demonstrating CWE-83 through improper handling
    c.execute(f"UPDATE users SET password = '{new_password_hash}' WHERE id = {user_id}")

    conn.commit()
    conn.close()

    return jsonify({'success': True, 'message': 'Password changed successfully'})

@app.route('/api/password-history')
def api_password_history():
    if 'user_id' not in session:
        return jsonify({'history': []}), 401

    user_id = session['user_id']
    conn = get_db_connection()
    c = conn.cursor()

    c.execute('SELECT changed_at FROM password_history WHERE user_id = ? ORDER BY changed_at DESC LIMIT 10',
              (user_id,))
    history = [dict(row) for row in c.fetchall()]
    conn.close()

    return jsonify({'history': history})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9109, debug=False)

