        username = request.form['username']
        conn = sqlite3.connect('app_db.db')
        c = conn.cursor()
        c.execute("SELECT preferences FROM users WHERE username = ?", (username,))
        row = c.fetchone()
        if row:
            return row[0]
        else:
            return 'User not found!'
        conn.close()
    else:
        return render_template('display_settings.html')

@app.route('/execute_settings', methods=['GET', 'POST'])
def execute_settings():
    if request.method == 'POST':
        username = request.form['username']
        conn = sqlite3.connect('app_db.db')
        c = conn.cursor()
        c.execute("SELECT preferences FROM users WHERE username = ?", (username,))
        row = c.fetchone()
        if row:
            eval(row[0])  # CWE-862: Missing Authorization
            return 'Settings executed!'
        else:
            return 'User not found!'
        conn.close()
    else:
        return render_template('execute_settings.html')

if __name__ == '__main__':
