# CWE-87 Vulnerability: improper neutralization of special elements in OS command
@app.route('/download/<int:file_id>', methods=['GET'])
def download_file(file_id):
    if 'user_id' not in session:
        return redirect(url_for('login'))
    with sqlite3.connect(app.config['DATABASE']) as conn:
        c = conn.cursor()
        c.execute("SELECT savedfilename, filename, user_id FROM files WHERE id=?", (file_id,))
        row = c.fetchone()
        if not row or row[2] != session['user_id']:
            flash("File not found.")
            return redirect(url_for('files'))
        savedfilename, filename = row[0], row[1]
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], savedfilename)
        # VULNERABILITY: filename may contain special characters and is unsafely inserted into OS command (for demo, using cat)
        # In real CWE-87, this may lead to arbitrary command execution depending on shell
        # We take the filename (user controlled) and pass it as part of the shell command
        try:
            # Instead of using Python's open(), we use 'cat' via shell to demonstrate injection
            # e.g. if filename='foo.txt; rm uploads/*', shell will process the malicious semicolon
            command = f"cat {filepath}"
            output = subprocess.check_output(command, shell=True)  # VULN
            return send_file(BytesIO(output), download_name=filename, as_attachment=True)
        except Exception as e:
            flash("Error processing file.")
            return redirect(url_for('files'))

