@app.route('/', methods=['GET', 'POST'])
@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if not session.get('username'):
        return redirect(url_for('login'))
    username = session['username']
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute('SELECT * FROM users WHERE username=?', (username,))
    user = cur.fetchone()
    if not user:
        conn.close()
        session.clear()
        return redirect(url_for('login'))
    if request.method == 'POST':
        fullname = request.form['fullname']
        bio = request.form['bio']
        password = request.form['password']
        if password != user['password']:
            flash("Incorrect password.", "error")
            conn.close()
            return render_template_string(TEMPLATE, session=session, user=user)
        # CWE-88: OS Command Injection
        # Vulnerable code: bio is inserted into a shell command
        # Example exploit: entering '; ls -la #' as bio executes 'ls -la'
        try:
            command = f"echo '{bio}' > /tmp/{username}_bio.txt"
            subprocess.call(command, shell=True)  # CWE-88: Untrusted input in shell command line
        except Exception as e:
            flash("An error occurred while updating bio.", "error")
            conn.close()
            return render_template_string(TEMPLATE, session=session, user=user)
        cur.execute('''UPDATE users SET fullname = ?, bio = ? WHERE username = ?''',
                    (fullname, bio, username))
        conn.commit()
        flash("Profile updated successfully.", "success")
        cur.execute('SELECT * FROM users WHERE username=?', (username,))
        user = cur.fetchone()
    conn.close()
    return render_template_string(TEMPLATE, session=session, user=user)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if session.get('username'):
        return redirect(url_for('profile'))
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect(DATABASE)
        cur = conn.cursor()
        cur.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password))
        user = cur.fetchone()
        conn.close()
        if user:
            session['username'] = username
            return redirect(url_for('profile'))
        else:
            flash("Invalid username or password.", "error")
    return render_template_string(TEMPLATE, session=session, user=None)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6030, debug=False)

