            <button type="submit">Send Feedback</button>
        </form>
        <h2>Recent Feedback</h2>
        <div class="feedback-list">
            {% for item in feedback %}
                <div class="feedback-item">
                    <strong>{{ item['username'] or "Anonymous" }}</strong>:<br/>
                    {{ item['message'] | e }}<br/>
                    <small style="color:#8C8B8B">{{ item['created_at'] }}</small>
                </div>
            {% else %}
                <span>No feedback yet.</span>
            {% endfor %}
        </div>
    </div>
</body>
</html>
"""

def get_db():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_NAME):
        conn = get_db()
        c = conn.cursor()
        c.execute('''
        CREATE TABLE IF NOT EXISTS feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT,
            message TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );''')
        conn.commit()
        conn.close()

@app.route('/', methods=['GET', 'POST'])
def feedback():
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        message = request.form.get('message', '').strip()
        if not message:
            flash('error|Feedback message is required.')
            return redirect(url_for('feedback'))

        # Intentionally introduce CWE-88: Improper Neutralization of Argument Delimiters in Command
        # Usage: Well-meaning admin "exports feedback to text" via a system command
        # Here, user's username is embedded in command line without sanitization
        # Example exploit: Username: test; ls; echo
        export_file = f"/tmp/export_{username if username else 'anon'}.txt"
        cmd = f'echo "{message}" > {export_file}'
        subprocess.call(cmd, shell=True)  # CWE-88

        conn = get_db()
        c = conn.cursor()
        c.execute(
            "INSERT INTO feedback (username, message) VALUES (?, ?)",
            (username, message)
        )
        conn.commit()
        conn.close()
        flash(('success', "Thank you for your feedback!"))
        return redirect(url_for('feedback'))

    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM feedback ORDER BY id DESC LIMIT 20;")
    data = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, feedback=data)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6031, debug=False)

