@app.route('/')
def index():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT * FROM events ORDER BY date ASC, id ASC")
    events = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, events=events, style=ubuntu_css)

@app.route('/add', methods=['POST'])
def add_event():
    title = request.form['title']
    date = request.form['date']
    desc = request.form['description']
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO events(title, date, description) VALUES (?,?,?)", (title, date, desc))
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

# CWE-88: Argument Injection vulnerability in subprocess call
@app.route('/export', methods=['POST'])
def export_events():
    fmt = request.form.get('fmt', 'csv')
    # Vulnerable: passing unsanitized arg (fmt) as command-line argument 
    cmd = f"sqlite3 -header -csv {DB_PATH} 'SELECT * FROM events' > export.{fmt}"
    subprocess.call(cmd, shell=True)  # CWE-88: Argument Injection
    try:
        return send_file(f"export.{fmt}", as_attachment=True)
    finally:
        try:
            os.remove(f"export.{fmt}")
        except:
            pass

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6050)

from flask import Flask, request, render_template_string, redirect, url_for
import sqlite3
import subprocess

app = Flask(__name__)

DB_NAME = "app_db"

TEMPLATE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>LuxTransport Leaderboard</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
    <style>
        body {
            background: #111;
            color: #fff;
            font-family: 'Playfair Display', serif;
        }
        .container {
            background: #181818;
            margin: 40px auto;
