            border: 1px solid #BFA480;
            margin-right: 8px;
            background: #222;
            color: #fff;
        }
        button {
            padding: 8px 20px;
            font-size: 1em;
            border-radius: 12px;
            border: none;
            background: #BFA480;
            color: #181818;
            cursor: pointer;
            transition: background 0.2s;
        }
        button:hover {
            background: #d1b899;
        }
