            font-size: 1.07em;
            padding: 13px 0;
            border-bottom: 1px solid #BFA48044;
            text-align: center;
        }
        th {
            color: #BFA480;
        }
        tr:last-child td {
            border-bottom: none;
        }
        .note {
            margin-top: 16px;
            text-align:center;
            color:#d5bcafaa;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>LuxTransport Leaderboard</h1>
        <form method="POST" action="/">
            <input type="text" name="username" placeholder="Name" required minlength="1" maxlength="32">
            <input type="number" name="activity" placeholder="Activity Score" required min="1" max="100000">
            <button type="submit">Add User</button>
        </form>
        <form method="GET" action="/filter">
            <input type="text" name="filter" placeholder="Filter user by name (shell pattern)">
            <button type="submit">Filter</button>
        </form>
        <table>
            <tr><th>Rank</th><th>User</th><th>Activity</th></tr>
            {% for i, row in enumerate(leaderboard) %}
            <tr>
                <td>{{i+1}}</td>
                <td>{{row[0]}}</td>
                <td>{{row[1]}}</td>
            </tr>
            {% endfor %}
        </table>
        <div class="note">Experience luxury urban transport performance.</div>
    </div>
</body>
</html>
'''

def init_db():
    con = sqlite3.connect(DB_NAME)
    cur = con.cursor()
    cur.execute("""
        CREATE TABLE IF NOT EXISTS leaderboard (
            username TEXT,
            activity INTEGER
        )
    """)
    con.commit()
    con.close()

@app.route('/', methods=['GET', 'POST'])
def index():
    init_db()
    if request.method == 'POST':
        username = request.form.get('username', '')
        activity = request.form.get('activity', '')
        con = sqlite3.connect(DB_NAME)
        cur = con.cursor()
        cur.execute("INSERT INTO leaderboard (username, activity) VALUES (?, ?)", (username, activity))
        con.commit()
        con.close()
        return redirect(url_for('index'))
    con = sqlite3.connect(DB_NAME)
    cur = con.cursor()
    cur.execute("SELECT username, activity FROM leaderboard ORDER BY activity DESC LIMIT 10")
    leaderboard = cur.fetchall()
    con.close()
    return render_template_string(TEMPLATE, leaderboard=leaderboard)

@app.route('/filter', methods=['GET'])
def filter():
    init_db()
    filter_pattern = request.args.get('filter', '')
    # CWE-88: OS Command Injection via shell metacharacters in filter
    cmd = f"sqlite3 {DB_NAME} \"SELECT username, activity FROM leaderboard WHERE username GLOB '{filter_pattern}' ORDER BY activity DESC LIMIT 10;\""
    output = subprocess.check_output(cmd, shell=True).decode(errors='ignore').strip()
    leaderboard = []
    if output:
        for line in output.split('\n'):
            if '|' in line:
                name, score = line.split('|')
                leaderboard.append((name, score))
    return render_template_string(TEMPLATE, leaderboard=leaderboard)

if __name__ == '__main__':
    app.run(host="0.0.0.0", port=6053)

