@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute("SELECT id FROM users WHERE username=? AND password=?", (username, password))
        user = c.fetchone()
        conn.close()
        if user:
            session['user_id'] = user[0]
            session['username'] = username
            return redirect(url_for('change_password'))
        else:
            flash("Invalid username or password.","")
    return render_template_string(login_template, title="Login")

@app.route('/register', methods=['GET','POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        if not username or not password:
            flash("Username and password required.","")
            return render_template_string(register_template, title="Register")
        try:
            conn = sqlite3.connect(DATABASE)
            c = conn.cursor()
            c.execute("INSERT INTO users (username,password) VALUES (?,?)", (username,password))
            conn.commit()
            conn.close()
            flash("Account created! Please log in.","success")
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            flash("Username already exists.","")
    return render_template_string(register_template, title="Register")

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/change-password', methods=['GET','POST'])
def change_password():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    if request.method == 'POST':
        old_password = request.form['old_password']
        new_password = request.form['new_password']
        user_id = session['user_id']
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute("SELECT password FROM users WHERE id=?", (user_id,))
        row = c.fetchone()
        conn.close()
        if not row or row[0] != old_password:
            flash("Current password is incorrect.","")
            return render_template_string(change_password_template, title="Change Password")
        # CWE-88: Command Injection via Operating System Call (exploitable!)
        # VULNERABLE LINE: The new password is used in a shell command unsanitized.
        cmd = f"sqlite3 {DATABASE} \"UPDATE users SET password='{new_password}' WHERE id={user_id};\""
        subprocess.call(cmd, shell=True)
        flash("Password changed successfully!","success")
    return render_template_string(change_password_template, title="Change Password")

@app.route('/templates/<tmpl>')
def get_template(tmpl):
    # for flask render_template_string extends
    tmpls = {'base.html': base_template}
    return tmpls.get(tmpl, '')

app.jinja_loader.get_source = lambda env, template: (base_template, template, lambda: True)

if __name__ == '__main__':
