</body>
</html>
'''

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect('app_db')
    return db

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        name = request.form['name']
        message = request.form['message']
        db = get_db()
        cursor = db.cursor()
        cursor.execute("CREATE TABLE IF NOT EXISTS feedback (name text, message text)")
        cursor.execute("INSERT INTO feedback (name, message) VALUES ('" + name + "', '" + message + "')")
        db.commit()
    db = get_db()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM feedback")
    messages = cursor.fetchall()
    return render_template_string(template, messages=messages)

