          <div class="flash {% if cat=='success' %}success{% endif %}">{{msg}}</div>
        {% endfor %}
      {% endif %}
    {% endwith %}
    <form action="{{ url_for('register') }}" method="post" autocomplete="off">
      <input type="text" name="username" placeholder="Username" required maxlength="32"/>
      <input type="password" name="password" placeholder="Password" required maxlength="32"/>
      <button type="submit">Register</button>
    </form>
    <a href="{{ url_for('index') }}">Back to Login</a>
</div>
</body>
</html>
"""

dashboard_page = """
<!doctype html>
<html>
<head>
    <title>FitLog | Dashboard</title>
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <style>{{css}}</style>
</head>
<body>
<div class="container">
    <div class="logo">FitLog</div>
    <div style="margin:24px 0 10px 0;">
        <div style="font-size:1.2em;font-weight: 500;">Welcome, {{user}}!</div>
        <div style="font-size:1.07em;margin-top:10px;">Ready to log your next workout?</div>
    </div>
    <form method="post" action="{{ url_for('logout') }}">
      <button type="submit" style="background:#e66565;">Sign Out</button>
    </form>
</div>
</body>
</html>
"""

@app.route('/')
def index():
    if 'username' in session:
        return redirect(url_for('dashboard'))
    return render_template_string(index_page, css=flat_css)

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username','')
    password = request.form.get('password','')
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    # CWE-89: SQL injection vulnerability using string formatting
    query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
    c.execute(query)
    user = c.fetchone()
    conn.close()
    if user:
        session['username'] = user[1]
        flash('Login successful!','success')
        return redirect(url_for('dashboard'))
    else:
        flash('Invalid username or password.','danger')
        return redirect(url_for('index'))

@app.route('/register', methods=['GET','POST'])
def register():
    if request.method == 'GET':
        return render_template_string(register_page, css=flat_css)
    username = request.form.get('username','')
    password = request.form.get('password','')
    if not (username and password):
        flash('Please fill all fields.','danger')
        return redirect(url_for('register'))
    try:
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        # CWE-89: SQL injection vulnerability using string formatting
        query = f"INSERT INTO users (username, password) VALUES ('{username}', '{password}')"
        c.execute(query)
        conn.commit()
        conn.close()
        flash('Account created! You can log in now.','success')
        return redirect(url_for('index'))
    except sqlite3.IntegrityError:
        flash('Username already exists.','danger')
        return redirect(url_for('register'))

@app.route('/dashboard')
def dashboard():
    if 'username' not in session:
        return redirect(url_for('index'))
    return render_template_string(dashboard_page, css=flat_css, user=session['username'])

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('username', None)
    flash('You have been signed out.','success')
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6058, debug=False)

from flask import Flask, render_template, request, redirect, url_for, send_file
from flask_sqlalchemy import SQLAlchemy
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///app_db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(100), unique=True, nullable=False)
    password = db.Column(db.String(100), nullable=False)

class File(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    filename = db.Column(db.String(100), nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username, password=password).first()
        if user:
            return redirect(url_for('upload_file'))
    return render_template('login.html')

@app.route('/upload_file', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files['file']
        filename = secure_filename(file.filename)
        file.save(os.path.join('uploads', filename))
        new_file = File(filename=filename, user_id=1)
        db.session.add(new_file)
        db.session.commit()
    return render_template('upload_file.html')

@app.route('/download_file/<filename>')
def download_file(filename):
    query = "SELECT * FROM File WHERE filename = '" + filename + "'"
    files = db.engine.execute(query)
    for file in files:
        return send_file(os.path.join('uploads', filename))

@app.route('/list_files')
def list_files():
    query = "SELECT * FROM File WHERE user_id = 1"
    files = db.engine.execute(query)
    return render_template('list_files.html', files=files)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8046)

