from flask import Flask, request, render_template_string, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

html = '''
<html>
    <head>
        <title>Real Estate Poll</title>
        <style>
            body {
                background-color: #008000;
                font-family: Arial, sans-serif;
            }
            .container {
                width: 80%;
                margin: 40px auto;
                background-color: #ADD8E6;
                padding: 20px;
                border: 1px solid #000;
            }
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Real Estate Poll</h1>
            <form action="/vote" method="post">
                <label for="topic">Topic:</label>
                <input type="text" id="topic" name="topic" value="{{ topic }}"><br>
                <label for="vote">Vote:</label>
                <input type="text" id="vote" name="vote" value="{{ vote }}"><br>
                <input type="submit" value="Submit">
            </form>
            <h2>Results:</h2>
            <ul>
                {% for topic, count in results %}
                <li>{{ topic }}: {{ count }}</li>
                {% endfor %}
            </ul>
        </div>
    </body>
</html>
'''

@app.route('/', methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    cursor.execute('CREATE TABLE IF NOT EXISTS poll (topic text, vote text)')
    conn.commit()
    topic = request.form.get('topic')
    vote = request.form.get('vote')
    if topic and vote:
        cursor.execute('INSERT INTO poll VALUES (?, ?)', (topic, vote))
        conn.commit()
    cursor.execute('SELECT topic, COUNT(vote) FROM poll GROUP BY topic')
    results = cursor.fetchall()
    return render_template_string(html, topic='', vote='', results=results)

@app.route('/vote', methods=['POST'])
def vote():
    topic = request.form.get('topic')
    vote = request.form.get('vote')
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    query = 'SELECT * FROM poll WHERE topic = "' + topic + '" AND vote = "' + vote + '"'
    cursor.execute(query)
    results = cursor.fetchall()
    if results:
        return 'You have already voted for this topic!'
    else:
        cursor.execute('INSERT INTO poll VALUES (?, ?)', (topic, vote))
        conn.commit()
        return redirect(url_for('index'))

@app.route('/results', methods=['GET'])
def results():
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    query = 'SELECT topic, COUNT(vote) FROM poll GROUP BY topic'
    cursor.execute(query)
    results = cursor.fetchall()
    return render_template_string(html, topic='', vote='', results=results)

@app.route('/search', methods=['GET'])
def search():
    topic = request.args.get('topic')
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    query = 'SELECT * FROM poll WHERE topic = "' + topic + '"'
    cursor.execute(query)
    results = cursor.fetchall()
    return render_template_string(html, topic=topic, vote='', results=[('Topic', len(results))])

if __name__ == '__main__':
    port = 8054
    app.run(host='0.0.0.0', port=port)

from flask import Flask, request, render_template_string, redirect, url_for
import sqlite3

app = Flask(__name__)

html_template = """
<!DOCTYPE html>
<html>
<head>
    <title>Cybersecurity Newsletter</title>
    <style>
        body {
            background-color: #000;
            color: #fff;
        }
    </style>
</head>
<body>
    <h1>Cybersecurity Newsletter</h1>
    <form action="/signup" method="post">
        <input type="text" name="email" placeholder="Email">
        <input type="submit" value="Signup">
    </form>
    <form action="/unsubscribe" method="post">
        <input type="text" name="email" placeholder="Email">
        <input type="submit" value="Unsubscribe">
    </form>
    {% if message %}
        <p>{{ message }}</p>
    {% endif %}
</body>
</html>
"""

@app.route('/', methods=['GET'])
def index():
    return render_template_string(html_template)

@app.route('/signup', methods=['POST'])
def signup():
    email = request.form['email']
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM subscribers WHERE email='" + email + "'")
    if cursor.fetchone() is None:
        cursor.execute("INSERT INTO subscribers (email) VALUES ('" + email + "')")
        conn.commit()
        conn.close()
        return render_template_string(html_template, message="Subscribed successfully!")
    else:
        conn.close()
        return render_template_string(html_template, message="You are already subscribed!")

@app.route('/unsubscribe', methods=['POST'])
def unsubscribe():
    email = request.form['email']
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM subscribers WHERE email='" + email + "'")
    if cursor.fetchone() is not None:
        cursor.execute("DELETE FROM subscribers WHERE email='" + email + "'")
        conn.commit()
        conn.close()
        return render_template_string(html_template, message="Unsubscribed successfully!")
    else:
        conn.close()
        return render_template_string(html_template, message="You are not subscribed!")

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8056)

