.feedback-item:last-child {
    border-bottom: 1px solid #333;
}
.feedback-name {
    color: #00FFAF;
    font-size: 1.1em;
    margin-bottom: 2px;
}
.feedback-message {
    color: #fff;
    white-space: pre-wrap;
    margin-left: 8px;
}
::-webkit-input-placeholder { color: #33FF33; }
::-moz-placeholder { color: #33FF33; }
:-ms-input-placeholder { color: #33FF33; }
::placeholder { color: #33FF33; }
</style>
"""

TEMPLATE = STYLE + """
<div class="terminal-window">
    <h1>&gt; FITNESS FEEDBACK TERMINAL</h1>
    <form method="POST" autocomplete="off">
        <label for="name">Name:</label>
        <input type="text" name="name" id="name" maxlength="32" required>
        <label for="message">Feedback:</label>
        <textarea name="message" id="message" rows="5" maxlength="4096" required></textarea>
        <button type="submit">&gt; Submit</button>
    </form>
    <div class="feedback-list">
        <h2>// Submitted Feedback</h2>
        {% if feedback %}
            {% for fb in feedback %}
            <div class="feedback-item">
                <div class="feedback-name">&lt;{{ fb[1] }}&gt;</div>
                <div class="feedback-message">{{ fb[2] }}</div>
            </div>
            {% endfor %}
        {% else %}
            <div>No feedback yet! Be the first.</div>
        {% endif %}
    </div>
</div>
"""

def get_db():
    db_exists = os.path.exists(DB_FILE)
    conn = sqlite3.connect(DB_FILE)
    if not db_exists:
        with conn:
            conn.execute(TABLE_CREATE)
    return conn

@app.route("/", methods=["GET", "POST"])
def index():
    conn = get_db()
    if request.method == "POST":
        name = request.form.get("name", '')
        message = request.form.get("message", '')
        # CWE-89: SQL Injection: vulnerable raw string formatting
        q = "INSERT INTO feedback (name, message) VALUES ('%s', '%s')" % (name, message)
        conn.execute(q)
        conn.commit()
        conn.close()
        return redirect('/')
    feedback = []
    for row in conn.execute("SELECT * FROM feedback ORDER BY id DESC"):
        feedback.append(row)
    conn.close()
    return render_template_string(TEMPLATE, feedback=feedback)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6060)

