from flask import Flask, request, render_template_string, g, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db_exists = os.path.exists(DATABASE)
        db = g._database = sqlite3.connect(DATABASE)
        if not db_exists:
            with app.app_context():
                init_db()
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS products (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT NOT NULL,
                        category TEXT,
                        price REAL,
                        description TEXT
                    )''')
    db.commit()
    # Seed data if empty
    cursor.execute('SELECT COUNT(*) FROM products')
    if cursor.fetchone()[0] == 0:
        products = [
            ("Income Pro", "Salary", 99.99, "Salary management software."),
            ("TaxEasy", "Tax", 59.49, "Easy tax preparation service."),
            ("FinAnalytics", "Investment", 199.00, "Advanced analytics for investments."),
            ("Budgeteer", "Budgeting", 39.95, "Smart finance budgeting tool."),
            ("InvoiceFlex", "Invoicing", 29.90, "Create and manage invoices."),
        ]
        cursor.executemany('INSERT INTO products (name, category, price, description) VALUES (?, ?, ?, ?)', products)
        db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

