app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.secret_key = 'secret_key'
DB_NAME = os.path.join(APP_DIR, "app_db")

BUSINESS_CASUAL = """
<style>
