TEMPLATE = BUSINESS_CASUAL + """
<header>
    <h1>Lawyer's Image Manager</h1>
    <p>Upload and manage client documents or case images.<br>
    <span style="font-size:0.95em;">Legal Service Portal | Business Casual Edition</span></p>
</header>
<div class="container">
    {% with messages = get_flashed_messages() %}
      {% if messages %}
        <div class="flash">{{ messages[0] }}</div>
      {% endif %}
    {% endwith %}
    <h2>Upload New Image</h2>
    <form method="POST" enctype="multipart/form-data" action="{{ url_for('upload') }}">
        <input type="file" name="image" accept="image/*" required>
        <input type="text" name="description" placeholder="Description" maxlength="120">
        <input type="submit" value="Upload">
    </form>
    <h2>Manage Images</h2>
    <form method="GET" action="{{ url_for('home') }}">
        <input type="text" name="q" placeholder="Search by description..." value="{{ request.args.get('q', '') }}">
        <input type="submit" value="Search">
    </form>
    <table>
        <tr>
            <th>Image</th>
            <th>Description</th>
            <th>Action</th>
        </tr>
        {% for image in images %}
        <tr>
            <td>
                <a href="{{ url_for('get_image', filename=image[1]) }}" target="_blank">
                <img src="{{ url_for('get_image', filename=image[1]) }}" alt="img" style="max-height:45px;">
                </a>
            </td>
            <td>{{ image[2] }}</td>
            <td>
                <a href="{{ url_for('delete_image', image_id=image[0]) }}" onclick="return confirm('Are you sure you want to delete this image?');"><button>Delete</button></a>
            </td>
        </tr>
        {% endfor %}
    </table>
</div>
"""

def init_db():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS images
                 (id INTEGER PRIMARY KEY AUTOINCREMENT, filename TEXT, description TEXT)''')
    conn.commit()
    conn.close()

@app.route('/', methods=['GET'])
def home():
    q = request.args.get('q', '')
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    # CWE-89: UNSAFE direct string formatting in query, exploitable!
    if q:
        query = f"SELECT * FROM images WHERE description LIKE '%{q}%'"
        c.execute(query)
    else:
        c.execute("SELECT * FROM images")
    images = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, images=images)

@app.route('/upload', methods=['POST'])
def upload():
    if 'image' not in request.files:
        flash('No file part')
        return redirect(url_for('home'))
    file = request.files['image']
    if file.filename == '':
        flash('No selected file')
        return redirect(url_for('home'))
    filename = secure_filename(file.filename)
    file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
    description = request.form.get('description', '')
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("INSERT INTO images (filename, description) VALUES (?, ?)", (filename, description))
    conn.commit()
    conn.close()
    return redirect(url_for('home'))

@app.route('/uploads/<filename>')
def get_image(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/delete/<int:image_id>')
def delete_image(image_id):
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT filename FROM images WHERE id = ?", (image_id,))
    row = c.fetchone()
    if row:
        filename = row[0]
        try:
            os.remove(os.path.join(app.config['UPLOAD_FOLDER'], filename))
        except Exception:
            pass
    c.execute("DELETE FROM images WHERE id = ?", (image_id,))
    conn.commit()
    conn.close()
    return redirect(url_for('home'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6070)

