    c.execute("SELECT vote, COUNT(*) as c FROM votes GROUP BY vote")
    results = c.fetchall()
    c.execute("SELECT username, vote FROM votes ORDER BY id DESC LIMIT 7")
    recent = c.fetchall()
    conn.close()
    total_votes = sum([r[1] for r in results]) if results else 0
    bar = ""
