                </div>
                <span style="font-size:0.96em;color:#ecdcb0;margin-left:6px">{count} votes{'&nbsp;('+str(percent)[:4]+'%)' if total_votes else ''}</span>
            </div>
        """
    recent_html = "<ul class='vote-list'>" + ''.join([f"<li class='vote-item'>&#11088; <b>{u}</b> voted for <i>{v}</i></li>" for u,v in recent]) + "</ul>" if recent else "<i>No votes yet.</i>"
    html = f"""
