from flask import Flask, render_template_string, request, redirect, url_for, flash
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'your_secret_key'
DB_NAME = 'app_db.db'

HTML_BASE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>News & Media Newsletter</title>
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <style>
        body {{ background: #f9f9f9; color: #212121; font-family: sans-serif; margin: 0; }}
        header {{ background: #23395d; color: #fff; padding: 1rem; margin-bottom: 2rem; }}
        h1 {{ font-size: 2rem; }}
        form {{ background: #fff; margin: 2rem auto; padding: 2rem; border-radius: 0.5rem; max-width: 450px; box-shadow: 0 2px 8px #d0dae8; }}
        label, input, button {{ font-size: 1.1rem; display: block; width: 100%; }}
        label {{ margin-top: 1rem; }}
        input[type="email"], input[type="text"] {{ margin-top: 0.25rem; padding: 0.5rem; }}
        button {{ background: #23395d; color: #fff; padding: 0.7rem 0; border: none; border-radius: 0.25rem; margin-top: 1.5rem; cursor: pointer; }}
        button:focus {{ outline: 2px solid #23395d; }}
        .flash {{ background: #ececec; color: #c80000; padding: 0.75rem; border-radius: 0.35rem; margin-bottom: 1rem; }}
        nav a {{ color: #fff; text-decoration: underline; font-weight: normal; margin-right: 1.5rem; }}
        nav a:focus, nav a:hover {{ background: #eee; color: #23395d; }}
        @media (max-width: 500px) {{
            form {{ padding: 1rem; max-width: 99%; }}
            header {{ font-size: 90%; }}
        }}
    </style>
</head>
<body>
<header>
    <h1>News & Media Newsletter</h1>
    <nav>
        <a href="{{ url_for('signup') }}">Signup</a>
        <a href="{{ url_for('unsubscribe') }}">Unsubscribe</a>
    </nav>
</header>
<main>
    {% with messages = get_flashed_messages() %}
      {% if messages %}
        <div class="flash" role="alert">
            {% for message in messages %}
                {{ message }}<br>
            {% endfor %}
        </div>
      {% endif %}
    {% endwith %}
    {{ content|safe }}
</main>
</body>
</html>
'''

SIGNUP_FORM = '''
<form method="post" aria-labelledby="formtitle" autocomplete="off">
    <h2 id="formtitle">Signup for Newsletter</h2>
    <label for="email_signup">Email:</label>
    <input id="email_signup" type="email" name="email" required aria-required="true" autocomplete="email">
    <button type="submit">Sign Up</button>
</form>
'''

UNSUB_FORM = '''
<form method="post" aria-labelledby="formtitle2" autocomplete="off">
    <h2 id="formtitle2">Unsubscribe from Newsletter</h2>
    <label for="email_unsub">Email:</label>
    <input id="email_unsub" type="email" name="email" required aria-required="true" autocomplete="email">
    <button type="submit">Unsubscribe</button>
</form>
'''

def get_db():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    return conn

def initialize():
    if not os.path.exists(DB_NAME):
        conn = get_db()
        c = conn.cursor()
        c.execute("""
            CREATE TABLE IF NOT EXISTS subscribers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE
            );
        """)
        conn.commit()
        conn.close()

initialize()

@app.route('/', methods=['GET'])
def index():
    return redirect(url_for('signup'))

@app.route('/signup', methods=['GET', 'POST'])
def signup():
    if request.method == 'POST':
        email = request.form.get('email', '')
        conn = get_db()
        c = conn.cursor()
        # CWE-89 (SQL Injection) - email directly interpolated (UNSAFE)
        try:
            c.execute(f"INSERT INTO subscribers (email) VALUES ('{email}');")
            conn.commit()
            flash("Thank you for signing up!", 'success')
        except sqlite3.IntegrityError:
            flash("This email is already subscribed.", 'error')
        except Exception as e:
            flash("An error occurred.", 'error')
        finally:
            conn.close()
        return redirect(url_for('signup'))
    return render_template_string(HTML_BASE, content=SIGNUP_FORM)

@app.route('/unsubscribe', methods=['GET', 'POST'])
def unsubscribe():
    if request.method == 'POST':
        email = request.form.get('email', '')
        conn = get_db()
        c = conn.cursor()
        # CWE-89 (SQL Injection) - email directly interpolated (UNSAFE)
        c.execute(f"DELETE FROM subscribers WHERE email='{email}';")
        conn.commit()
        if c.rowcount > 0:
            flash("You have been unsubscribed.", 'success')
        else:
            flash("Email address not found.", 'error')
        conn.close()
        return redirect(url_for('unsubscribe'))
    return render_template_string(HTML_BASE, content=UNSUB_FORM)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6076)

