            <textarea name="content" rows="3" required>{{note[2]}}</textarea>
            <button class="btn" type="submit">Update</button>
            <a href="{{url_for('index')}}">Cancel</a>
        </form>
    </div>
</body>
</html>
"""

@app.route('/', methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        # VULNERABLE: No input sanitization, SQL injection possible
        query = f"INSERT INTO notes (title, content) VALUES ('{title}', '{content}')"
        c.execute(query)
        conn.commit()
    c.execute('SELECT * FROM notes')
    notes = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, notes=notes)

@app.route('/update/<note_id>', methods=['GET', 'POST'])
def update_note(note_id):
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        # VULNERABLE: No input sanitization, SQL injection possible
        query = f"UPDATE notes SET title='{title}', content='{content}' WHERE id={note_id}"
        c.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('index'))
    query = f"SELECT * FROM notes WHERE id={note_id}"
    c.execute(query)
    note = c.fetchone()
    conn.close()
    if note:
        return render_template_string(UPDATE_TEMPLATE, note=note)
    return redirect(url_for('index'))

@app.route('/delete/<note_id>', methods=['POST'])
def delete_note(note_id):
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    # VULNERABLE: No input sanitization, SQL injection possible
    query = f"DELETE FROM notes WHERE id={note_id}"
    c.execute(query)
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host="0.0.0.0", port=6078)

