'''

@app.route('/')
def index():
    if 'username' in session:
        return redirect(url_for('inbox'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    html = '''
    {% extends base %}
    {% block content %}
        <div class="title">Login</div>
        <form method="post">
            <label>Username</label>
            <input name="username" maxlength="30" required>
            <label>Password</label>
            <input name="password" type="password" maxlength="30" required>
            <button type="submit">Login</button>
        </form>
        <div style="text-align:center;margin-top:12px;opacity:0.89;">
            New user? <a href="{{ url_for('register') }}" class="link">Register</a>
        </div>
    {% endblock %}
    '''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # VULNERABLE LOGIN QUERY (CWE-89)
        query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
        c.execute(query)
        user = c.fetchone()
        conn.close()
        if user:
            session['username'] = username
            flash('Logged in successfully.')
            return redirect(url_for('inbox'))
        else:
            flash('Invalid credentials.')
    return render_template_string(html, base=BASE_HTML)

@app.route('/register', methods=['GET', 'POST'])
def register():
    html = '''
    {% extends base %}
    {% block content %}
        <div class="title">Register</div>
        <form method="post">
            <label>Username</label>
            <input name="username" maxlength="30" required>
            <label>Password</label>
            <input name="password" type="password" maxlength="30" required>
            <button type="submit">Register</button>
        </form>
        <div style="text-align:center;margin-top:12px;">
            Already have an account? <a href="{{ url_for('login') }}" class="link">Login</a>
        </div>
    {% endblock %}
    '''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        try:
            c.execute("INSERT INTO users (username, password) VALUES (?, ?)", (username, password))
            conn.commit()
            session['username'] = username
            flash('Registration successful. You are now logged in.')
            return redirect(url_for('inbox'))
        except sqlite3.IntegrityError:
            flash('Username already taken.')
        conn.close()
    return render_template_string(html, base=BASE_HTML)

@app.route('/logout')
def logout():
    session.clear()
    flash('Logged out.')
    return redirect(url_for('login'))

@app.route('/inbox')
def inbox():
    if 'username' not in session:
        return redirect(url_for('login'))
    username = session['username']
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT sender, content FROM messages WHERE receiver = ? ORDER BY id DESC", (username,))
    messages = c.fetchall()
    conn.close()
    html = '''
    {% extends base %}
    {% block content %}
        <div class="title">Inbox</div>
        <div style="margin-bottom:19px;">
            <b>Logged in as: </b>{{ username }}<br>
            <a href="{{ url_for('send_message') }}" class="link">Send Message</a>&nbsp;&nbsp;|&nbsp;
            <a href="{{ url_for('logout') }}" class="link">Logout</a>
        </div>
        {% if messages %}
            {% for m in messages %}
                <div class="message-container">
                    <div class="message-header">From: {{ m[0] }}</div>
                    <div>{{ m[1] }}</div>
                </div>
            {% endfor %}
        {% else %}
            <div class="msg">No messages received.</div>
        {% endif %}
    {% endblock %}
    '''
    return render_template_string(html, base=BASE_HTML, messages=messages, username=username)

@app.route('/send', methods=['GET', 'POST'])
def send_message():
    if 'username' not in session:
        return redirect(url_for('login'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT username FROM users WHERE username != ?', (session['username'],))
    users = [row[0] for row in c.fetchall()]
    conn.close()
    html = '''
    {% extends base %}
    {% block content %}
        <div class="title">Send Message</div>
        <div style="margin-bottom:19px;">
            <b>Logged in as: </b>{{ username }}<br>
            <a href="{{ url_for('inbox') }}" class="link">Inbox</a>&nbsp;&nbsp;|&nbsp;
            <a href="{{ url_for('logout') }}" class="link">Logout</a>
        </div>
        <form method="post">
            <label>To</label>
            <select name="receiver" required>
                <option disabled selected value="">-- Select User --</option>
                {% for u in users %}
                    <option value="{{ u }}">{{ u }}</option>
                {% endfor %}
            </select>
            <label>Message</label>
            <textarea name="content" rows="4" maxlength="200" required></textarea>
            <button type="submit">Send</button>
        </form>
    {% endblock %}
    '''
    if request.method == 'POST':
        receiver = request.form['receiver']
        content = request.form['content']
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("INSERT INTO messages (sender, receiver, content) VALUES (?, ?, ?)",
                  (session['username'], receiver, content))
        conn.commit()
        conn.close()
        flash('Message sent.')
        return redirect(url_for('inbox'))
    return render_template_string(html, base=BASE_HTML, users=users, username=session['username'])

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6085, debug=False)

