from flask import Flask, request, render_template_string, redirect, url_for, flash
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'secret_key'

DB_FILE = 'app_db'

TEMPLATE = """
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>Nonprofit Newsletter Signup</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
        body { font-family: Arial, sans-serif; margin: 2em; background: #fefefe; color: #222; }
        header { margin-bottom: 2em; }
        label { display: block; margin-top: 1em; }
        input[type=text], input[type=email] { width: 100%; padding: .5em; font-size: 1em; }
        input[type=submit] { padding: .5em 1.5em; margin: 1em 0; font-size: 1em; background: #17599f; color: #fff; border: none; border-radius: 4px; cursor: pointer;}
        a { color: #17599f; }
        .container { max-width: 29em; margin: auto; background: #fff; border-radius: 8px; box-shadow: 0 2px 12px rgba(0,0,0,0.07);}
        .alerts { margin: 1em 0; padding: .8em; border: 1px solid #d03030; border-radius: 2px; background: #fbebe8; color: #a41c1c; }
    </style>
</head>
<body>
    <div class="container">
    <header>
        <h1 tabindex="0">Nonprofit Newsletter Signup</h1>
        <nav>
            <a href="{{ url_for('index') }}">Signup</a> | 
            <a href="{{ url_for('unsubscribe') }}">Unsubscribe</a>
        </nav>
    </header>
    {% with messages = get_flashed_messages() %}
      {% if messages %}
        <div class="alerts" role="alert">
        {% for message in messages %}
          <div tabindex="0">{{ message }}</div>
        {% endfor %}
        </div>
      {% endif %}
    {% endwith %}
    {% block body %}{% endblock %}
    </div>
</body>
</html>
"""

SIGNUP_BODY = """
{% extends "layout.html" %}
{% block body %}
    <form method="post" action="{{ url_for('index') }}" autocomplete="off" aria-labelledby="signup-label">
        <label id="signup-label" for="email">Email Address</label>
        <input required type="email" name="email" id="email" aria-required="true" autofocus>
        <input type="submit" value="Sign Up">
    </form>
{% endblock %}
"""

UNSUBSCRIBE_BODY = """
{% extends "layout.html" %}
{% block body %}
    <form method="post" action="{{ url_for('unsubscribe') }}" aria-labelledby="unsubscribe-label" autocomplete="off">
        <label id="unsubscribe-label" for="email">Email Address</label>
        <input required type="email" name="email" id="email" aria-required="true">
        <input type="submit" value="Unsubscribe">
    </form>
{% endblock %}
"""

def init_db():
    if not os.path.exists(DB_FILE):
        conn = sqlite3.connect(DB_FILE)
        conn.execute("CREATE TABLE IF NOT EXISTS newsletter (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL)")
        conn.commit()
        conn.close()

@app.before_first_request
def setup():
    init_db()

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        try:
            conn = sqlite3.connect(DB_FILE)
            cur = conn.cursor()
            # CWE-89: SQL Injection (Direct concatenation, NOT parameterized)
            query = "INSERT INTO newsletter (email) VALUES ('%s')" % email
            cur.execute(query)
            conn.commit()
            flash('Successfully signed up for the newsletter!', 'info')
        except sqlite3.IntegrityError:
            flash('This email is already subscribed.', 'error')
        except Exception:
            flash('Could not subscribe your email.', 'error')
        finally:
            conn.close()
        return redirect(url_for('index'))
    return render_template_string(
        '{% include "layout.html" %}' + SIGNUP_BODY,
        )

@app.route('/unsubscribe', methods=['GET', 'POST'])
def unsubscribe():
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        try:
            conn = sqlite3.connect(DB_FILE)
            cur = conn.cursor()
            # CWE-89: SQL Injection (Direct concatenation, NOT parameterized)
            query = "DELETE FROM newsletter WHERE email = '%s'" % email
            cur.execute(query)
            conn.commit()
            if cur.rowcount:
                flash('You have been unsubscribed.', 'info')
            else:
                flash('Email not found.', 'error')
        except Exception:
            flash('Could not unsubscribe your email.', 'error')
        finally:
            conn.close()
        return redirect(url_for('unsubscribe'))
    return render_template_string(
        '{% include "layout.html" %}' + UNSUBSCRIBE_BODY,
        )

@app.route('/_layout')
def layout():  # For template include
    return render_template_string(TEMPLATE)

# for Jinja2: monkeypatch template loader to allow {% include "layout.html" %}
from jinja2 import BaseLoader, TemplateNotFound
class DictLoader(BaseLoader):
    def __init__(self, mapping):
        self.mapping = mapping
    def get_source(self, environment, template):
        try:
            source = self.mapping[template]
            return source, None, lambda: True
        except KeyError:
            raise TemplateNotFound(template)
app.jinja_loader = DictLoader({'layout.html': TEMPLATE})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6010)

from flask import Flask, request, redirect, render_template_string, session, url_for
import sqlite3
import os
import random
import string

app = Flask(__name__)
app.secret_key = ''.join(random.choices(string.ascii_letters+string.digits, k=32))
DATABASE = 'app_db'

if not os.path.exists(DATABASE):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        role TEXT NOT NULL
    )''')
    c.execute('''CREATE TABLE posts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        author_id INTEGER NOT NULL,
        FOREIGN KEY(author_id) REFERENCES users(id)
    )''')
    c.execute('INSERT INTO users (username, password, role) VALUES ("admin", "adminpass", "admin")')
    c.execute('INSERT INTO users (username, password, role) VALUES ("moderator", "modpass", "mod")')
    c.execute('INSERT INTO users (username, password, role) VALUES ("player1", "playerpass", "user")')
    conn.commit()
    conn.close()

