@app.route('/add_user', methods=['POST'])
def add_user():
    if not session.get('username') or session.get('role')!='admin':
        return redirect(url_for('login'))

    username = request.form.get('username','')
    password = request.form.get('password','')
    role = request.form.get('role','user')

    error = None
    # CWE-89: Intentionally vulnerable SQL!
    sql = f"INSERT INTO users (username, password, role) VALUES ('{username}','{password}','{role}')"
    try:
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute(sql)
        conn.commit()
    except sqlite3.IntegrityError:
        error = "Username already exists!"
    except Exception as e:
        error = str(e)
    finally:
        conn.close()
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute("SELECT * FROM users")
    users = c.fetchall()
    conn.close()
    return render(users_tpl, users=users, error=error)

@app.route('/delete_user', methods=['POST'])
def delete_user():
    if not session.get('username') or session.get('role')!='admin':
        return redirect(url_for('login'))
    user_id = request.form.get('user_id','')
    error = None
    # Prevent self-delete admin
    try:
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute("SELECT username FROM users WHERE id=?", (user_id,))
        uname = c.fetchone()
        if uname and uname[0] == "admin":
            raise Exception("Cannot delete main admin user.")
        # CWE-89: vulnerable to SQLi by user_id
        sql = f"DELETE FROM users WHERE id = {user_id}"
        c.execute(sql)
        conn.commit()
    except Exception as e:
        error = str(e)
    finally:
        conn.close()
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute("SELECT * FROM users")
    users = c.fetchall()
    conn.close()
    return render(users_tpl, users=users, error=error)

