@app.route("/", methods=["GET"])
def home():
    username = session.get('username')
    user_files = []
    if username:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        # CWE-89 vulnerability: UNSAFE SQL (concatenation, not binding)
        query = "SELECT filename FROM files WHERE username = '%s'" % username
        rows = c.execute(query).fetchall()
        user_files = [x[0] for x in rows]
        conn.close()
    return render_template_string(html_template, user_files=user_files)

@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username", "")
    password = request.form.get("password", "")
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    # CWE-89 vulnerability: UNSAFE SQL (concatenation, not binding)
    query = "SELECT * FROM users WHERE username = '%s' AND password = '%s'" % (username, password)
    res = c.execute(query).fetchone()
    conn.close()
    if res:
        session['username'] = username
        return redirect(url_for('home'))
    else:
        flash("Invalid credentials", "login")
        return redirect(url_for('home'))

@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for('home'))

@app.route("/upload", methods=["POST"])
def upload():
    if 'username' not in session:
        return redirect(url_for('home'))
    if 'file' not in request.files:
        flash("No file selected.", "upload")
        return redirect(url_for('home'))
    file = request.files['file']
    if file.filename == '':
        flash("No file selected.", "upload")
        return redirect(url_for('home'))
    filename = secure_filename(file.filename)
    save_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    file.save(save_path)
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    # CWE-89 vulnerability: UNSAFE SQL (concatenation, not binding)
    query = "INSERT INTO files (username, filename) VALUES ('%s','%s')" % (session['username'], filename)
    c.execute(query)
    conn.commit()
    conn.close()
    flash("File uploaded.", "upload")
    return redirect(url_for('home'))

@app.route("/download/<filename>")
def download(filename):
    if 'username' not in session:
        return redirect(url_for('home'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    # CWE-89 vulnerability: UNSAFE SQL (concatenation, not binding)
    query = "SELECT * FROM files WHERE username = '%s' AND filename = '%s'" % (session['username'], filename)
    user_file = c.execute(query).fetchone()
    conn.close()
    if user_file and os.path.exists(os.path.join(app.config['UPLOAD_FOLDER'], filename)):
        return send_from_directory(app.config['UPLOAD_FOLDER'], filename, as_attachment=True)
    else:
        flash("File not found.", "upload")
        return redirect(url_for('home'))

@app.route("/delete/<filename>")
def delete_file(filename):
    if 'username' not in session:
        return redirect(url_for('home'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    # CWE-89 vulnerability: UNSAFE SQL (concatenation, not binding)
    query = "DELETE FROM files WHERE username = '%s' AND filename = '%s'" % (session['username'], filename)
    c.execute(query)
    conn.commit()
    conn.close()
    try:
        os.remove(os.path.join(app.config['UPLOAD_FOLDER'], filename))
    except:
        pass
    flash("File deleted.", "delete")
    return redirect(url_for('home'))

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6138, debug=True)

