@app.route('/')
def index():
    if 'user_id' in session:
        return redirect(url_for('dashboard'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        query = f"SELECT id, username FROM users WHERE username='{username}' AND password='{hash_password(password)}'"

        c.execute(query)
        user = c.fetchone()
        conn.close()

        if user:
            session['user_id'] = user[0]
            session['username'] = user[1]
            return redirect(url_for('dashboard'))

        return render_template_string(HTML_TEMPLATE, form_type='login', error='Invalid credentials')

    return render_template_string(HTML_TEMPLATE, form_type='login', error=None)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')
        confirm_password = request.form.get('confirm_password', '')

        if password != confirm_password:
            return render_template_string(HTML_TEMPLATE, form_type='register', error='Passwords do not match')

        if len(password) < 6:
            return render_template_string(HTML_TEMPLATE, form_type='register', error='Password must be at least 6 characters')

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        try:
            c.execute('INSERT INTO users (username, password) VALUES (?, ?)', 
                     (username, hash_password(password)))
            conn.commit()
            conn.close()
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            conn.close()
            return render_template_string(HTML_TEMPLATE, form_type='register', error='Username already exists')

    return render_template_string(HTML_TEMPLATE, form_type='register', error=None)

@app.route('/dashboard')
def dashboard():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT id, user_id, filename, filepath, upload_time FROM files WHERE user_id=? ORDER BY upload_time DESC', 
             (session['user_id'],))
    files = c.fetchall()
    conn.close()

    message = request.args.get('message', '')
    error = request.args.get('error', '')

    return render_template_string(HTML_TEMPLATE, 
                                  form_type='dashboard',
                                  username=session.get('username'),
                                  files=files,
                                  message=message,
                                  error=error)

@app.route('/upload', methods=['POST'])
def upload():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if 'file' not in request.files:
        return redirect(url_for('dashboard', error='No file provided'))

    file = request.files['file']
    if file.filename == '':
        return redirect(url_for('dashboard', error='No file selected'))

    filename = file.filename
    filepath = os.path.join(UPLOAD_FOLDER, f"{session['user_id']}_{filename}")
    file.save(filepath)

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('INSERT INTO files (user_id, filename, filepath, upload_time) VALUES (?, ?, ?, ?)',
             (session['user_id'], filename, filepath, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
    conn.commit()
    conn.close()

    return redirect(url_for('dashboard', message='File uploaded successfully'))

@app.route('/download/<int:file_id>')
def download(file_id):
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT filepath, filename FROM files WHERE id=? AND user_id=?', (file_id, session['user_id']))
    result = c.fetchone()
    conn.close()

    if not result:
        return redirect(url_for('dashboard', error='File not found'))

    filepath, filename = result
    return send_file(filepath, as_attachment=True, download_name=filename)

@app.route('/api/delete/<int:file_id>', methods=['DELETE'])
def delete_file(file_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT filepath FROM files WHERE id=? AND user_id=?', (file_id, session['user_id']))
    result = c.fetchone()

    if not result:
        conn.close()
        return jsonify({'success': False, 'error': 'File not found'})

    filepath = result[0]
    c.execute('DELETE FROM files WHERE id=? AND user_id=?', (file_id, session['user_id']))
    conn.commit()
    conn.close()

    if os.path.exists(filepath):
        os.remove(filepath)

    return jsonify({'success': True})

@app.route('/api/search')
def search():
    if 'user_id' not in session:
        return jsonify({'files': []})

    query = request.args.get('q', '')

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    search_query = f"SELECT id, user_id, filename, filepath, upload_time FROM files WHERE user_id={session['user_id']} AND filename LIKE '%{query}%'"

    c.execute(search_query)
    files = c.fetchall()
    conn.close()

    result = []
    for file in files:
        result.append({
            'id': file[0],
            'filename': file[2],
            'upload_time': file[4]
        })

    return jsonify({'files': result})

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.context_processor
def inject_templates():
    return {
        'dashboard_html': DASHBOARD_TEMPLATE,
        'auth_html': AUTH_TEMPLATE
    }

@app.before_request
def load_templates():
    @app.template_global()
    def include_dashboard():
        return render_template_string(DASHBOARD_TEMPLATE, 
                                     username=session.get('username', ''),
                                     message=request.args.get('message', ''),
                                     error=request.args.get('error', ''),
                                     files=[])

    @app.template_global()
    def include_auth():
        form_type = request.args.get('form_type', 'login')
        return render_template_string(AUTH_TEMPLATE, 
                                     form_type=form_type,
                                     error=request.args.get('error', ''))

app.jinja_env.globals.update(
    dashboard_template=DASHBOARD_TEMPLATE,
    auth_template=AUTH_TEMPLATE
)

init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9130, debug=True)

#!/usr/bin/env python3
import sqlite3
import os
from flask import Flask, render_template_string, request, redirect, url_for, jsonify

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def init_db():
    """Initialize the database with contacts table"""
    db_path = app.config['DATABASE']
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT,
            phone TEXT,
            address TEXT
        )
    ''')
    conn.commit()
    conn.close()

def get_db_connection():
    """Get a database connection"""
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

# Initialize database
if not os.path.exists(app.config['DATABASE']):
    init_db()
else:
    init_db()

