            transition: all 0.3s;
        }

        input[type="text"]:focus,
        input[type="email"]:focus,
        input[type="tel"]:focus,
        input[type="search"]:focus {
            outline: none;
            box-shadow: 0 0 15px rgba(0, 255, 136, 0.5);
            border-color: #ffff00;
        }

        button {
            background: linear-gradient(135deg, #00ff88, #00ffff);
            color: #000;
            border: none;
            padding: 12px 25px;
            border-radius: 5px;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s;
            font-size: 1em;
            text-shadow: 0 0 5px #ffff00;
        }

        button:hover {
            box-shadow: 0 0 20px rgba(0, 255, 136, 0.6);
            transform: scale(1.05);
        }

        .button-group {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        .search-container {
            margin-bottom: 20px;
            background: rgba(30, 30, 60, 0.6);
            padding: 15px;
            border-radius: 8px;
            border: 2px solid #ffff00;
        }

        .contacts-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
            gap: 20px;
        }

        .contact-card {
            background: linear-gradient(135deg, rgba(0, 255, 136, 0.1), rgba(0, 255, 255, 0.1));
            border: 2px solid #00ff88;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 0 15px rgba(0, 255, 136, 0.2);
            transition: all 0.3s;
        }

        .contact-card:hover {
            box-shadow: 0 0 25px rgba(0, 255, 136, 0.4);
            transform: translateY(-5px);
        }

        .contact-name {
            font-size: 1.5em;
            color: #ffff00;
            margin-bottom: 10px;
            text-shadow: 0 0 5px #ffff00;
        }

        .contact-info {
            margin-bottom: 8px;
            color: #00ffff;
        }

        .contact-info strong {
            color: #00ff88;
        }

        .contact-actions {
            margin-top: 15px;
            display: flex;
            gap: 10px;
        }

        .btn-delete {
            background: linear-gradient(135deg, #ff0055, #ff5500);
            color: #fff;
            padding: 8px 15px;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: all 0.3s;
            font-size: 0.9em;
        }

        .btn-delete:hover {
            box-shadow: 0 0 15px rgba(255, 0, 85, 0.6);
        }

        .empty-message {
            text-align: center;
            color: #ff00ff;
            font-size: 1.2em;
            padding: 40px;
            text-shadow: 0 0 10px #ff00ff;
        }

        .success-message {
            background: rgba(0, 255, 136, 0.2);
            border: 2px solid #00ff88;
            color: #00ff88;
            padding: 15px;
            border-radius: 5px;
            margin-bottom: 20px;
            text-shadow: 0 0 5px #00ff88;
        }

        .error-message {
            background: rgba(255, 0, 85, 0.2);
            border: 2px solid #ff0055;
            color: #ff88ff;
            padding: 15px;
            border-radius: 5px;
            margin-bottom: 20px;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1 class="neon-glow">🎮 INSURANCE CONTACT POWER UP 🎮</h1>
            <p class="subtitle">Level Up Your Contact Management Game!</p>
        </header>

        {% if message %}
        <div class="success-message">{{ message }}</div>
        {% endif %}

        <div class="form-container">
            <h2 style="color: #ffff00; margin-bottom: 20px; text-shadow: 0 0 5px #ffff00;">⚡ ADD NEW CONTACT ⚡</h2>
            <form method="POST" action="/add">
                <div class="form-group">
                    <label for="name">Name:</label>
                    <input type="text" id="name" name="name" required placeholder="Enter contact name">
                </div>
                <div class="form-group">
                    <label for="email">Email:</label>
                    <input type="email" id="email" name="email" placeholder="Enter email address">
                </div>
                <div class="form-group">
                    <label for="phone">Phone:</label>
                    <input type="tel" id="phone" name="phone" placeholder="Enter phone number">
                </div>
                <div class="form-group">
                    <label for="address">Address:</label>
                    <input type="text" id="address" name="address" placeholder="Enter address">
                </div>
                <button type="submit">🚀 POWER UP - ADD CONTACT 🚀</button>
            </form>
        </div>

        <div class="search-container">
            <h3 style="color: #00ffff; margin-bottom: 10px;">🔍 SEARCH CONTACTS</h3>
            <form method="GET" action="/search">
                <input type="search" name="query" placeholder="Search by name, email, or phone..." value="{{ search_query or '' }}">
                <button type="submit" style="margin-top: 10px;">SEARCH</button>
                {% if search_query %}
                <a href="/" style="margin-top: 10px;"><button type="button" style="background: linear-gradient(135deg, #ff6600, #ffaa00);">CLEAR SEARCH</button></a>
                {% endif %}
            </form>
        </div>

        <h2 style="color: #ffff00; margin-bottom: 20px; text-shadow: 0 0 5px #ffff00;">👥 YOUR CONTACT ROSTER 👥</h2>

        {% if contacts %}
        <div class="contacts-grid">
            {% for contact in contacts %}
            <div class="contact-card">
                <div class="contact-name">{{ contact['name'] }}</div>
                {% if contact['email'] %}
                <div class="contact-info"><strong>📧 Email:</strong> {{ contact['email'] }}</div>
                {% endif %}
                {% if contact['phone'] %}
                <div class="contact-info"><strong>📱 Phone:</strong> {{ contact['phone'] }}</div>
                {% endif %}
                {% if contact['address'] %}
                <div class="contact-info"><strong>🏠 Address:</strong> {{ contact['address'] }}</div>
                {% endif %}
                <div class="contact-actions">
                    <form method="POST" action="/delete" style="margin: 0;">
                        <input type="hidden" name="id" value="{{ contact['id'] }}">
                        <button type="submit" class="btn-delete" onclick="return confirm('Are you sure you want to delete this contact?');">DELETE</button>
                    </form>
                </div>
            </div>
            {% endfor %}
        </div>
        {% else %}
        <div class="empty-message">
            🎮 No contacts found. Start adding your insurance network! 🎮
        </div>
        {% endif %}
    </div>
</body>
</html>
'''

@app.route('/')
def index():
    """Display all contacts"""
    conn = get_db_connection()
    contacts = conn.execute('SELECT * FROM contacts ORDER BY name').fetchall()
    conn.close()
    return render_template_string(HTML_TEMPLATE, contacts=contacts, message=None, search_query=None)

@app.route('/add', methods=['POST'])
def add_contact():
    """Add a new contact - VULNERABLE TO SQL INJECTION (CWE-89)"""
    name = request.form.get('name', '').strip()
    email = request.form.get('email', '').strip()
    phone = request.form.get('phone', '').strip()
    address = request.form.get('address', '').strip()

    if not name:
        return redirect(url_for('index'))

    conn = get_db_connection()
    cursor = conn.cursor()

    # VULNERABLE: Direct string concatenation without parameterized queries
    # This is CWE-89: Improper Neutralization of Special Elements used in an SQL Command
    query = f"INSERT INTO contacts (name, email, phone, address) VALUES ('{name}', '{email}', '{phone}', '{address}')"

    cursor.execute(query)
    conn.commit()
    conn.close()

    return redirect(url_for('index'))

@app.route('/delete', methods=['POST'])
def delete_contact():
    """Delete a contact"""
    contact_id = request.form.get('id', '').strip()

    if not contact_id:
        return redirect(url_for('index'))

    conn = get_db_connection()
    cursor = conn.cursor()

    # VULNERABLE: Direct string concatenation without parameterized queries
    query = f"DELETE FROM contacts WHERE id = {contact_id}"
    cursor.execute(query)
    conn.commit()
    conn.close()

    return redirect(url_for('index'))

@app.route('/search')
def search():
    """Search contacts - VULNERABLE TO SQL INJECTION (CWE-89)"""
    query = request.args.get('query', '').strip()
    contacts = []

    if query:
        conn = get_db_connection()
        cursor = conn.cursor()

        # VULNERABLE: Direct string concatenation without parameterized queries
        # This is CWE-89: Improper Neutralization of Special Elements used in an SQL Command
        search_query = f"SELECT * FROM contacts WHERE name LIKE '%{query}%' OR email LIKE '%{query}%' OR phone LIKE '%{query}%' OR address LIKE '%{query}%'"

        cursor.execute(search_query)
        contacts = cursor.fetchall()
        conn.close()

    return render_template_string(HTML_TEMPLATE, contacts=contacts, message=None, search_query=query)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9131, debug=False)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def get_db():
    db = sqlite3.connect(app.config['DATABASE'])
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS settings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            bio TEXT DEFAULT '',
            theme TEXT DEFAULT 'light',
            notifications TEXT DEFAULT 'on',
            privacy TEXT DEFAULT 'public',
            FOREIGN KEY (user_id) REFERENCES users(id)
        )
    ''')
    db.commit()
    db.close()

def create_user(username, password):
    db = get_db()
    cursor = db.cursor()
    try:
        cursor.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
        user_id = cursor.lastrowid
        cursor.execute('INSERT INTO settings (user_id) VALUES (?)', (user_id,))
        db.commit()
        db.close()
        return user_id
    except sqlite3.IntegrityError:
        db.close()
        return None

def get_user_by_username(username):
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT id, username, password FROM users WHERE username = ?', (username,))
    user = cursor.fetchone()
    db.close()
    return user

def get_user_settings(user_id):
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM settings WHERE user_id = ?', (user_id,))
    settings = cursor.fetchone()
    db.close()
    return settings

init_db()

