@app.route('/')
def index():
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')

        user = get_user_by_username(username)
        if user and user[2] == password:
            return redirect(url_for('settings', user_id=user[0]))
        else:
            return render_template_string(html_template + login_template, 
                                        page_title='Login',
                                        error='Invalid username or password')

    return render_template_string(html_template + login_template, page_title='Login')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')

        if not username or not password:
            return render_template_string(html_template + register_template,
                                        page_title='Register',
                                        error='Username and password are required')

        user_id = create_user(username, password)
        if user_id:
            return redirect(url_for('settings', user_id=user_id))
        else:
            return render_template_string(html_template + register_template,
                                        page_title='Register',
                                        error='Username already exists')

    return render_template_string(html_template + register_template, page_title='Register')

@app.route('/settings', methods=['GET', 'POST'])
def settings():
    user_id = request.args.get('user_id') or request.form.get('user_id')
    if not user_id:
        return redirect(url_for('login'))

    user_id = int(user_id)

    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT username FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    db.close()

    if not user:
        return redirect(url_for('login'))

    username = user[0]

    if request.method == 'POST':
        bio = request.form.get('bio', '')
        theme = request.form.get('theme', 'light')
        notifications = request.form.get('notifications', 'on')
        privacy = request.form.get('privacy', 'public')

        db = get_db()
        cursor = db.cursor()
        cursor.execute('''
            UPDATE settings 
            SET bio = ?, theme = ?, notifications = ?, privacy = ?
            WHERE user_id = ?
        ''', (bio, theme, notifications, privacy, user_id))
        db.commit()
        db.close()

        user_settings = get_user_settings(user_id)
        return render_template_string(html_template + settings_template,
                                    page_title='Settings',
                                    username=username,
                                    settings=user_settings,
                                    success=True)

    user_settings = get_user_settings(user_id)
    return render_template_string(html_template + settings_template,
                                page_title='Settings',
                                username=username,
                                settings=user_settings)

@app.route('/profile')
def profile():
    user_id = request.args.get('user_id')
    if not user_id:
        return redirect(url_for('login'))

    user_id = int(user_id)

    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT username FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    db.close()

    if not user:
        return redirect(url_for('login'))

    username = user[0]

    profile_view = request.args.get('view', username)

    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT users.id, users.username, settings.bio, settings.theme, settings.privacy FROM users JOIN settings ON users.id = settings.user_id WHERE users.username = ?', (profile_view,))
    profile_user = cursor.fetchone()
    db.close()

    if not profile_user:
        return render_template_string(html_template + profile_template,
                                    page_title='Profile',
                                    username=username,
                                    profile_html='<p>User not found</p>')

    privacy_setting = profile_user[4]

    if privacy_setting == 'private':
        if profile_user[0] != user_id:
            profile_html = '<p>This profile is private.</p>'
        else:
            profile_html = f'<p><strong>Bio:</strong> {profile_user[2]}</p><p><strong>Theme:</strong> {profile_user[3]}</p>'
    elif privacy_setting == 'friends':
        profile_html = '<p>This profile is friends only.</p>'
    else:
        profile_html = f'<p><strong>Bio:</strong> {profile_user[2]}</p><p><strong>Theme:</strong> {profile_user[3]}</p>'

    return render_template_string(html_template + profile_template,
                                page_title='Profile',
                                username=username,
                                profile_html=profile_html)

@app.route('/user', methods=['GET'])
def user_search():
    user_id = request.args.get('user_id')
    search_user = request.args.get('username', '')

    if not user_id:
        return redirect(url_for('login'))

    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT username FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    db.close()

    if not user:
        return redirect(url_for('login'))

    username = user[0]

    if not search_user:
        return redirect(url_for('profile', user_id=user_id))

    query = f"SELECT users.id, users.username, settings.bio, settings.theme, settings.privacy FROM users JOIN settings ON users.id = settings.user_id WHERE users.username LIKE '%{search_user}%'"

    db = get_db()
    cursor = db.cursor()
    try:
        cursor.execute(query)
        results = cursor.fetchall()
        db.close()
    except Exception as e:
        db.close()
        return render_template_string(html_template + profile_template,
                                    page_title='Search',
                                    username=username,
                                    profile_html=f'<p style="color: red;">Error: {str(e)}</p>')

    if not results:
        return render_template_string(html_template + profile_template,
                                    page_title='Search',
                                    username=username,
                                    profile_html='<p>No users found.</p>')

    profile_html = '<h3>Search Results:</h3>'
    for result in results:
        profile_html += f'<p><a href="/profile?user_id={user_id}&view={result[1]}">{result[1]}</a></p>'

    return render_template_string(html_template + profile_template,
                                page_title='Search Results',
                                username=username,
                                profile_html=profile_html)

@app.route('/logout')
def logout():
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9132, debug=True)

from flask import Flask, request, redirect, url_for, render_template, session
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
import sqlite3

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///app_db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

    def __repr__(self):
        return '<User %r>' % self.username

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if request.method == 'POST':
        user_id = request.form['user_id']
        username = request.form['username']
        email = request.form['email']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "UPDATE User SET username = '" + username + "', email = '" + email + "' WHERE id = " + user_id
        cursor.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('profile'))
    elif 'username' in session:
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "SELECT * FROM User WHERE username = '" + session['username'] + "'"
        cursor.execute(query)
        user = cursor.fetchone()
        conn.close()
        return render_template('profile.html', user=user)
    else:
        return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "SELECT * FROM User WHERE username = '" + username + "' AND password = '" + password + "'"
        cursor.execute(query)
        user = cursor.fetchone()
        conn.close()
        if user:
            session['username'] = username
            return redirect(url_for('profile'))
    return render_template('login.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        email = request.form['email']
        password = request.form['password']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "INSERT INTO User (username, email, password) VALUES ('" + username + "', '" + email + "', '" + password + "')"
        cursor.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('login'))
    return render_template('register.html')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8140)

