@app.route('/', methods=['GET', 'POST'])
def login():
    error = ''
    if request.method == 'POST':
        username = request.form.get('username','')
        password = request.form.get('password','')
        conn = get_db()
        c = conn.cursor()
        # Vulnerable login (CWE-89): SQL injection possible!
        query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
        c.execute(query)
        user = c.fetchone()
        conn.close()
        if user:
            session['user_id'] = user[0]
            return redirect(url_for('profile'))
        else:
            error = "Invalid username or password"
    return render_template_string(TEMPLATE_LOGIN, error=error)

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    user_id = session['user_id']
    conn = get_db()
    c = conn.cursor()
    if request.method == 'POST':
        email = request.form.get('email','')
        bio = request.form.get('bio','')
        # Vulnerable update (CWE-89): input not sanitized!
        update_query = f"UPDATE users SET email = '{email}', bio = '{bio}' WHERE id = {user_id}"
        c.execute(update_query)
        conn.commit()
    c.execute(f"SELECT id, username, email, bio FROM users WHERE id = {user_id}")
    row = c.fetchone()
    user = {'id': row[0], 'username': row[1], 'email': row[2], 'bio': row[3]}
    conn.close()
    success = request.method == 'POST'
    return render_template_string(TEMPLATE_PROFILE, user=user, success=success)

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('login'))

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6141, debug=False)

