"""

@app.route('/', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')
        # There's no password field in the database, but for demo, any password is accepted for an existing user
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('SELECT id FROM users WHERE username = ?', (username,))
        row = c.fetchone()
        conn.close()
        if row:
            session['user_id'] = row[0]
            session['username'] = username
            return redirect(url_for('profile'))
        else:
            return render_template_string(LOGIN_PAGE, error="Invalid credentials")
    return render_template_string(LOGIN_PAGE, error=None)

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    user_id = session['user_id']
    success = None
    error = None

    if request.method == 'POST':
        fullname = request.form.get('fullname', '')
        email = request.form.get('email', '')
        address = request.form.get('address', '')

        # VULNERABLE TO SQL INJECTION (CWE-89)
        update_query = (
            f"UPDATE users SET fullname = '{fullname}', email = '{email}', address = '{address}' WHERE id = {user_id}"
        )

        try:
            conn = sqlite3.connect(DB_PATH)
            c = conn.cursor()
            c.execute(update_query)
            conn.commit()
            conn.close()
            success = True
        except sqlite3.Error as e:
            error = "Internal error occurred."
            success = False

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT username, fullname, email, address FROM users WHERE id = ?', (user_id,))
    row = c.fetchone()
    conn.close()
    class User:
        def __init__(self, username, fullname, email, address):
            self.username = username
            self.fullname = fullname
            self.email = email
            self.address = address
    if row:
        user = User(*row)
    else:
        return redirect(url_for('logout'))

    return render_template_string(PROFILE_PAGE, user=user, success=success, error=error)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6143)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db()
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS contacts
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      name TEXT NOT NULL,
                      email TEXT,
                      phone TEXT,
                      address TEXT)''')
        conn.commit()
        conn.close()

