            <label for="address">Address</label>
            <textarea id="address" name="address" rows="3">{{ contact.address or '' }}</textarea>
        </div>

        <button type="submit">Update Contact</button>
    </form>
</div>
{% endblock %}
'''

SEARCH_TEMPLATE = '''
{% extends "base.html" %}

{% block title %}Search Results - Banking Address Book{% endblock %}

{% block content %}
<h2>Search Results for "{{ query }}"</h2>

<div class="search-box">
    <form method="GET" action="{{ url_for('search') }}">
        <input type="text" name="q" placeholder="Search contacts..." value="{{ query }}" required>
        <button type="submit">Search</button>
    </form>
</div>

{% if results %}
<table>
    <thead>
        <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Phone</th>
            <th>Address</th>
            <th>Actions</th>
        </tr>
    </thead>
    <tbody>
        {% for contact in results %}
        <tr>
            <td>{{ contact.name }}</td>
            <td>{{ contact.email }}</td>
            <td>{{ contact.phone }}</td>
            <td>{{ contact.address }}</td>
            <td class="action-links">
                <a href="{{ url_for('edit_contact', id=contact.id) }}">Edit</a>
                <a class="delete" href="{{ url_for('delete_contact', id=contact.id) }}" onclick="return confirm('Are you sure?')">Delete</a>
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>
{% else %}
<div class="empty-state">
    <p>No contacts found matching your search.</p>
</div>
{% endif %}
{% endblock %}
'''

@app.route('/')
def index():
    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT * FROM contacts')
    contacts = c.fetchall()
    conn.close()
    return render_template_string(BASE_TEMPLATE + INDEX_TEMPLATE, contacts=contacts)

@app.route('/add', methods=['GET', 'POST'])
def add_contact():
    if request.method == 'POST':
        name = request.form.get('name')
        email = request.form.get('email')
        phone = request.form.get('phone')
        address = request.form.get('address')

        conn = get_db()
        c = conn.cursor()
        c.execute('INSERT INTO contacts (name, email, phone, address) VALUES (?, ?, ?, ?)',
                  (name, email, phone, address))
        conn.commit()
        conn.close()

        return redirect(url_for('index'))

    return render_template_string(BASE_TEMPLATE + ADD_CONTACT_TEMPLATE)

@app.route('/edit/<int:id>', methods=['GET', 'POST'])
def edit_contact(id):
    conn = get_db()
    c = conn.cursor()

    if request.method == 'POST':
        name = request.form.get('name')
        email = request.form.get('email')
        phone = request.form.get('phone')
        address = request.form.get('address')

        c.execute('UPDATE contacts SET name = ?, email = ?, phone = ?, address = ? WHERE id = ?',
                  (name, email, phone, address, id))
        conn.commit()
        conn.close()

        return redirect(url_for('index'))

    c.execute('SELECT * FROM contacts WHERE id = ?', (id,))
    contact = c.fetchone()
    conn.close()

    if not contact:
        return redirect(url_for('index'))

    return render_template_string(BASE_TEMPLATE + EDIT_CONTACT_TEMPLATE, contact=contact)

@app.route('/delete/<int:id>')
def delete_contact(id):
    conn = get_db()
    c = conn.cursor()
    c.execute('DELETE FROM contacts WHERE id = ?', (id,))
    conn.commit()
    conn.close()

    return redirect(url_for('index'))

@app.route('/search')
def search():
    query = request.args.get('q', '')

    if not query:
        return redirect(url_for('index'))

    conn = get_db()
    c = conn.cursor()
    sql = f"SELECT * FROM contacts WHERE name LIKE '%{query}%' OR email LIKE '%{query}%' OR phone LIKE '%{query}%' OR address LIKE '%{query}%'"
    c.execute(sql)
    results = c.fetchall()
    conn.close()

    return render_template_string(BASE_TEMPLATE + SEARCH_TEMPLATE, results=results, query=query)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9136, debug=True)

