@app.route('/', methods=['GET', 'POST'])
def index():
    success = False
    if request.method == 'POST':
        name = request.form.get('name', '')
        email = request.form.get('email', '')
        message = request.form.get('message', '')
        rating = request.form.get('rating', '5')

        conn = get_db()
        cursor = conn.cursor()

        query = f"INSERT INTO feedback (name, email, message, rating) VALUES ('{name}', '{email}', '{message}', {rating})"
        cursor.execute(query)
        conn.commit()
        conn.close()
        success = True

    conn = get_db()
    cursor = conn.cursor()

    search_query = request.args.get('search', '')
    if search_query:
        query = f"SELECT * FROM feedback WHERE name LIKE '%{search_query}%' OR message LIKE '%{search_query}%' ORDER BY id DESC"
    else:
        query = "SELECT * FROM feedback ORDER BY id DESC"

    cursor.execute(query)
    feedbacks = cursor.fetchall()
    conn.close()

    return render_template_string(html_template, feedbacks=feedbacks, success=success)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9137, debug=False)

