@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        u = request.form['username']
        p = request.form['password']
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        # CWE-89: SQL injection vulnerability here
        query = f"SELECT * FROM users WHERE username = '{u}' AND password = '{p}'"
        user = c.execute(query).fetchone()
        conn.close()
        if user:
            session['username'] = u
            return redirect(url_for('addresses'))
        else:
            flash('Invalid credentials.')
    return render_template_string(LOGIN_PAGE)

@app.route('/addresses', methods=['GET', 'POST'])
def addresses():
    if 'username' not in session:
        return redirect(url_for('login'))
    username = session['username']
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    if request.method == 'POST':
        addr = request.form['address']
        # CWE-89: SQL injection vulnerability here
        ins = f"INSERT INTO addresses (username, address) VALUES ('{username}', '{addr}')"
        try:
            c.execute(ins)
            conn.commit()
            flash("Address saved!")
        except Exception as e:
            flash("Error saving: " + str(e))
    # CWE-89: SQL injection not needed but for consistency using unsafe select
    query = f"SELECT address FROM addresses WHERE username = '{username}'"
    rows = c.execute(query).fetchall()
    addresses = [row[0] for row in rows]
    conn.close()
    return render_template_string(ADDRESS_PAGE, addresses=addresses)

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('index'))

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6146, debug=False)

