        .form-group input:focus, .form-group textarea:focus {
            outline: none;
            border-color: #667eea;
            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }

        .btn {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 12px 30px;
            border: none;
            border-radius: 6px;
            font-size: 1em;
            cursor: pointer;
            font-weight: 600;
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            width: 100%;
        }

        .btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 20px rgba(102, 126, 234, 0.4);
        }

        .btn:active {
            transform: translateY(0);
        }

        .address-list {
            display: flex;
            flex-direction: column;
            gap: 15px;
            max-height: 500px;
            overflow-y: auto;
        }

        .address-item {
            background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
            padding: 20px;
            border-radius: 8px;
            border-left: 4px solid #667eea;
            transition: all 0.3s ease;
        }

        .address-item:hover {
            transform: translateX(5px);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
        }

        .address-item h4 {
            color: #333;
            margin-bottom: 8px;
            font-size: 1.1em;
        }

        .address-item p {
            color: #555;
            margin: 5px 0;
            font-size: 0.95em;
        }

        .address-meta {
            color: #999;
            font-size: 0.85em;
            margin-top: 10px;
            padding-top: 10px;
            border-top: 1px solid rgba(0, 0, 0, 0.1);
        }

        .message {
            padding: 15px;
            border-radius: 6px;
            margin-bottom: 20px;
            animation: slideIn 0.3s ease;
        }

        .message.success {
            background: #d4edda;
            color: #155724;
            border: 1px solid #c3e6cb;
        }

        .message.error {
            background: #f8d7da;
            color: #721c24;
            border: 1px solid #f5c6cb;
        }

        @keyframes slideIn {
            from {
                opacity: 0;
                transform: translateY(-10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .profile-section {
            margin-top: 30px;
        }

        .search-box {
            margin-bottom: 20px;
        }

        .search-box input {
            width: 100%;
            padding: 12px;
            border: 2px solid #e0e0e0;
            border-radius: 6px;
            font-size: 1em;
        }

        .loading {
            display: none;
            text-align: center;
            padding: 20px;
            color: #667eea;
        }

        .loading.active {
            display: block;
        }

        .spinner {
            border: 3px solid #f3f3f3;
            border-top: 3px solid #667eea;
            border-radius: 50%;
            width: 30px;
            height: 30px;
            animation: spin 1s linear infinite;
            margin: 0 auto;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🏢 HR Portal</h1>
            <p>Delivery Address Management System</p>
        </div>

        <div class="main-content">
            <div class="card">
                <h2>📮 Add Delivery Address</h2>
                <div id="form-message"></div>
                <form id="addressForm" onsubmit="submitAddressForm(event)">
                    <div class="form-group">
                        <label for="name">Full Name *</label>
                        <input type="text" id="name" name="name" required>
                    </div>

                    <div class="form-group">
                        <label for="email">Email Address *</label>
                        <input type="email" id="email" name="email" required>
                    </div>

                    <div class="form-group">
                        <label for="street">Street Address *</label>
                        <input type="text" id="street" name="street" required>
                    </div>

                    <div class="form-group">
                        <label for="city">City *</label>
                        <input type="text" id="city" name="city" required>
                    </div>

                    <div class="form-group">
                        <label for="postal_code">Postal Code *</label>
                        <input type="text" id="postal_code" name="postal_code" required>
                    </div>

                    <div class="form-group">
                        <label for="country">Country *</label>
                        <input type="text" id="country" name="country" required>
                    </div>

                    <button type="submit" class="btn">💾 Save Address</button>
                </form>
            </div>

            <div class="card">
                <h2>📍 Saved Addresses</h2>
                <div class="search-box">
                    <input type="text" id="searchInput" placeholder="Search by name or city..." onkeyup="filterAddresses()">
                </div>
                <div class="loading" id="loading">
                    <div class="spinner"></div>
                    <p>Loading addresses...</p>
                </div>
                <div class="address-list" id="addressList">
                    <p style="color: #999; text-align: center; padding: 20px;">No addresses saved yet</p>
                </div>
            </div>
        </div>

        <div class="card profile-section">
            <h2>👤 Create Profile</h2>
            <div id="profile-message"></div>
            <form id="profileForm" onsubmit="submitProfileForm(event)">
                <div class="form-group">
                    <label for="username">Username *</label>
                    <input type="text" id="username" name="username" required>
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" name="bio" rows="3" placeholder="Tell us about yourself..."></textarea>
                </div>

                <button type="submit" class="btn">✨ Create Profile</button>
            </form>
        </div>
    </div>

    <script>
        function showMessage(elementId, message, type) {
            const element = document.getElementById(elementId);
            element.innerHTML = `<div class="message ${type}">${message}</div>`;
            setTimeout(() => {
                element.innerHTML = '';
            }, 5000);
        }

        function submitAddressForm(event) {
            event.preventDefault();

            const formData = new FormData(document.getElementById('addressForm'));
            const data = {
                name: formData.get('name'),
                email: formData.get('email'),
                street: formData.get('street'),
                city: formData.get('city'),
                postal_code: formData.get('postal_code'),
                country: formData.get('country')
            };

            fetch('/api/address', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(data)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showMessage('form-message', '✅ Address saved successfully!', 'success');
                    document.getElementById('addressForm').reset();
                    loadAddresses();
                } else {
                    showMessage('form-message', '❌ Error: ' + data.error, 'error');
                }
            })
            .catch(error => {
                showMessage('form-message', '❌ Error: ' + error.message, 'error');
            });
        }

        function loadAddresses() {
            document.getElementById('loading').classList.add('active');
            fetch('/api/addresses')
            .then(response => response.json())
            .then(data => {
                document.getElementById('loading').classList.remove('active');
                const addressList = document.getElementById('addressList');

                if (data.addresses.length === 0) {
                    addressList.innerHTML = '<p style="color: #999; text-align: center; padding: 20px;">No addresses saved yet</p>';
                    return;
                }

                addressList.innerHTML = data.addresses.map(addr => `
                    <div class="address-item">
                        <h4>${addr.name}</h4>
                        <p>📧 ${addr.email}</p>
                        <p>🏠 ${addr.street}</p>
                        <p>🌆 ${addr.city}, ${addr.postal_code}</p>
                        <p>🌍 ${addr.country}</p>
                        <div class="address-meta">Added: ${new Date(addr.created_at).toLocaleDateString()}</div>
                    </div>
                `).join('');
            })
            .catch(error => {
                document.getElementById('loading').classList.remove('active');
                console.error('Error loading addresses:', error);
            });
        }

        function filterAddresses() {
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();
            const items = document.querySelectorAll('.address-item');

            items.forEach(item => {
                const text = item.textContent.toLowerCase();
                item.style.display = text.includes(searchTerm) ? 'block' : 'none';
            });
        }

        function submitProfileForm(event) {
            event.preventDefault();

            const formData = new FormData(document.getElementById('profileForm'));
            const data = {
                username: formData.get('username'),
                bio: formData.get('bio')
            };

            fetch('/api/profile', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(data)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showMessage('profile-message', '✅ Profile created successfully!', 'success');
                    document.getElementById('profileForm').reset();
                } else {
                    showMessage('profile-message', '❌ Error: ' + data.error, 'error');
                }
            })
            .catch(error => {
                showMessage('profile-message', '❌ Error: ' + error.message, 'error');
            });
        }

        // Load addresses when page loads
        loadAddresses();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/address', methods=['POST'])
def add_address():
    try:
        data = request.json
        name = data.get('name', '')
        email = data.get('email', '')
        street = data.get('street', '')
        city = data.get('city', '')
        postal_code = data.get('postal_code', '')
        country = data.get('country', '')

        db = get_db()
        cursor = db.cursor()

        query = f"INSERT INTO delivery_addresses (name, email, street, city, postal_code, country) VALUES ('{name}', '{email}', '{street}', '{city}', '{postal_code}', '{country}')"
        cursor.execute(query)
        db.commit()
        db.close()

        return jsonify({'success': True, 'message': 'Address saved successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 400

@app.route('/api/addresses', methods=['GET'])
def get_addresses():
    try:
        db = get_db()
        cursor = db.cursor()
        cursor.execute('SELECT * FROM delivery_addresses ORDER BY created_at DESC')
        addresses = cursor.fetchall()
        db.close()

        return jsonify({
            'success': True,
            'addresses': [dict(addr) for addr in addresses]
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 400

@app.route('/api/profile', methods=['POST'])
def create_profile():
    try:
        data = request.json
        username = data.get('username', '')
        bio = data.get('bio', '')

        db = get_db()
        cursor = db.cursor()

        query = f"INSERT INTO user_profiles (username, bio) VALUES ('{username}', '{bio}')"
        cursor.execute(query)
        db.commit()
        db.close()

        return jsonify({'success': True, 'message': 'Profile created successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 400

@app.route('/api/search', methods=['GET'])
def search_profile():
    try:
        search_term = request.args.get('q', '')

        db = get_db()
        cursor = db.cursor()

        query = f"SELECT * FROM user_profiles WHERE username LIKE '%{search_term}%'"
        cursor.execute(query)
        profiles = cursor.fetchall()
        db.close()

        return jsonify({
            'success': True,
            'profiles': [dict(profile) for profile in profiles]
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 400

if __name__ == '__main__':
    if not os.path.exists(DATABASE):
        init_db()
    else:
        with app.app_context():
            try:
                db = get_db()
                db.execute('SELECT 1 FROM delivery_addresses LIMIT 1')
                db.close()
            except:
                init_db()

    app.run(host='0.0.0.0', port=9138, debug=True)

import os
import sqlite3
from flask import Flask, render_template_string, request, jsonify

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

HTML_TEMPLATE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Gaming Notification Center</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: #e0e0e0;
            min-height: 100vh;
            padding: 20px;
        }

        .dashboard {
            max-width: 1200px;
            margin: 0 auto;
        }

        header {
            background: rgba(22, 33, 62, 0.8);
            border-bottom: 2px solid #0f3460;
