            box-shadow: 0 8px 25px rgba(0, 212, 255, 0.2);
            transform: translateX(5px);
        }

        .notification-card.error {
            border-left-color: #ff3333;
        }

        .notification-card.warning {
            border-left-color: #ff9800;
