        .notification-card.success {
            border-left-color: #4caf50;
        }

        .alert-title {
            color: #00d4ff;
            font-size: 1.3em;
            font-weight: bold;
            margin-bottom: 8px;
        }

        .alert-description {
            color: #b0b0b0;
            margin-bottom: 10px;
            line-height: 1.5;
        }

        .alert-meta {
            display: flex;
            justify-content: space-between;
            font-size: 0.85em;
            color: #777;
        }

        .alert-type {
            display: inline-block;
            padding: 3px 10px;
            background: rgba(0, 212, 255, 0.2);
