        }

        .filter-section h3 {
            color: #00d4ff;
            margin-bottom: 15px;
        }

        .form-group {
            margin-bottom: 15px;
        }

        .form-group label {
            display: block;
            margin-bottom: 5px;
            color: #b0b0b0;
            font-weight: 500;
        }

        .stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 15px;
            margin-bottom: 20px;
        }

        .stat-card {
            background: rgba(15, 52, 96, 0.4);
            padding: 15px;
            border-radius: 8px;
            text-align: center;
            border: 1px solid rgba(0, 212, 255, 0.2);
        }

        .stat-value {
            color: #00d4ff;
            font-size: 2em;
            font-weight: bold;
        }

        .stat-label {
            color: #777;
            font-size: 0.9em;
            margin-top: 5px;
        }
    </style>
</head>
<body>
    <div class="dashboard">
        <header>
            <h1>🎮 Gaming Notification Center</h1>
            <div class="subtitle">Real-time alerts and notifications for gaming events</div>
        </header>

        <div class="stats" id="statsContainer">
            <div class="stat-card">
                <div class="stat-value" id="totalAlerts">0</div>
                <div class="stat-label">Total Alerts</div>
            </div>
            <div class="stat-card">
                <div class="stat-value" id="criticalAlerts">0</div>
                <div class="stat-label">Critical</div>
            </div>
            <div class="stat-card">
                <div class="stat-value" id="warningAlerts">0</div>
                <div class="stat-label">Warnings</div>
            </div>
        </div>

        <div class="filter-section">
            <h3>🔍 Search & Filter</h3>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
                <div class="form-group">
                    <label for="userFilter">Search by Username:</label>
                    <input type="text" id="userFilter" placeholder="Enter username (e.g., player123)">
                </div>
                <div class="form-group">
                    <label for="typeFilter">Filter by Alert Type:</label>
                    <select id="typeFilter">
                        <option value="">All Types</option>
                        <option value="login">Login Alert</option>
                        <option value="achievement">Achievement</option>
                        <option value="trade">Trade Alert</option>
                        <option value="friend">Friend Request</option>
                        <option value="system">System Alert</option>
                    </select>
                </div>
            </div>
            <button onclick="searchAlerts()">Search Alerts</button>
            <button onclick="resetFilters()" style="margin-left: 10px;">Reset</button>
        </div>

        <div class="notifications-container" id="alertsContainer">
            <div class="loading">Loading notifications...</div>
        </div>
    </div>

    <script>
        function loadAlerts() {
            fetch('/api/alerts')
                .then(response => response.json())
                .then(data => {
                    const container = document.getElementById('alertsContainer');
                    const stats = {
                        total: data.length,
                        critical: 0,
                        warning: 0
                    };

                    if (data.length === 0) {
                        container.innerHTML = '<div class="no-alerts">No alerts found. Your system is running smoothly!</div>';
                    } else {
                        container.innerHTML = data.map(alert => {
                            let typeClass = 'info';
                            if (alert.severity === 'critical') {
                                typeClass = 'error';
                                stats.critical++;
                            } else if (alert.severity === 'warning') {
                                typeClass = 'warning';
                                stats.warning++;
                            } else if (alert.severity === 'success') {
                                typeClass = 'success';
                            }

                            return `
                                <div class="notification-card ${typeClass}">
                                    <div class="alert-title">${escapeHtml(alert.title)}</div>
                                    <div class="alert-description">${escapeHtml(alert.description)}</div>
                                    <div class="alert-meta">
                                        <span class="alert-type ${typeClass}">${escapeHtml(alert.alert_type)}</span>
                                        <span>${formatDate(alert.timestamp)}</span>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }

                    document.getElementById('totalAlerts').textContent = stats.total;
                    document.getElementById('criticalAlerts').textContent = stats.critical;
                    document.getElementById('warningAlerts').textContent = stats.warning;
                })
                .catch(error => {
                    console.error('Error loading alerts:', error);
                    document.getElementById('alertsContainer').innerHTML = '<div class="no-alerts">Error loading alerts. Please try again.</div>';
                });
        }

        function searchAlerts() {
            const username = document.getElementById('userFilter').value;
            const alertType = document.getElementById('typeFilter').value;

            let query = '/api/alerts?';
            if (username) query += 'username=' + encodeURIComponent(username) + '&';
            if (alertType) query += 'type=' + encodeURIComponent(alertType);

            fetch(query.endsWith('&') ? query.slice(0, -1) : query)
                .then(response => response.json())
                .then(data => {
                    const container = document.getElementById('alertsContainer');

                    if (data.length === 0) {
                        container.innerHTML = '<div class="no-alerts">No alerts found matching your filters.</div>';
                    } else {
                        container.innerHTML = data.map(alert => {
                            let typeClass = 'info';
                            if (alert.severity === 'critical') {
                                typeClass = 'error';
                            } else if (alert.severity === 'warning') {
                                typeClass = 'warning';
                            } else if (alert.severity === 'success') {
                                typeClass = 'success';
                            }

                            return `
                                <div class="notification-card ${typeClass}">
                                    <div class="alert-title">${escapeHtml(alert.title)}</div>
                                    <div class="alert-description">${escapeHtml(alert.description)}</div>
                                    <div class="alert-meta">
                                        <span class="alert-type ${typeClass}">${escapeHtml(alert.alert_type)}</span>
                                        <span>${formatDate(alert.timestamp)}</span>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }
                })
                .catch(error => {
                    console.error('Error searching alerts:', error);
                    document.getElementById('alertsContainer').innerHTML = '<div class="no-alerts">Error searching alerts. Please try again.</div>';
                });
        }

        function resetFilters() {
            document.getElementById('userFilter').value = '';
            document.getElementById('typeFilter').value = '';
            loadAlerts();
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function formatDate(timestamp) {
            const date = new Date(timestamp);
            return date.toLocaleString();
        }

        document.addEventListener('DOMContentLoaded', function() {
            loadAlerts();
            setInterval(loadAlerts, 30000);
        });
    </script>
</body>
</html>
'''

def get_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT NOT NULL,
            alert_type TEXT NOT NULL,
            severity TEXT NOT NULL,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    cursor.execute('SELECT COUNT(*) FROM alerts')
    if cursor.fetchone()[0] == 0:
        sample_data = [
            ('player123', 'Login Detected', 'User logged in from new device', 'login', 'info'),
            ('gamer456', 'Achievement Unlocked', 'Player defeated Dragon Boss on Hard mode', 'achievement', 'success'),
            ('progamer789', 'Trade Request', 'Received rare sword offer', 'trade', 'warning'),
            ('player123', 'Server Maintenance', 'Game servers will be down for 2 hours', 'system', 'critical'),
            ('streamer101', 'Friend Request', 'epic_player92 sent you a friend request', 'friend', 'info'),
            ('pvp_king', 'Battle Ranking Update', 'You ranked up to Gold tier!', 'achievement', 'success'),
            ('casual_gamer', 'Daily Reward', 'Collect your daily login bonus', 'system', 'info'),
            ('hardcore_fan', 'Event Alert', 'Limited time event: Summer Festival starts now', 'system', 'warning'),
            ('speedrunner_pro', 'Leaderboard', 'You entered top 10 speedrunners', 'achievement', 'success'),
            ('quest_master', 'Guild Message', 'Your guild won territory control event', 'system', 'success'),
        ]

        for username, title, description, alert_type, severity in sample_data:
            cursor.execute('''
                INSERT INTO alerts (username, title, description, alert_type, severity)
                VALUES (?, ?, ?, ?, ?)
            ''', (username, title, description, alert_type, severity))

    db.commit()
    db.close()

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/alerts')
def get_alerts():
    username = request.args.get('username', '')
    alert_type = request.args.get('type', '')

    db = get_db()
    cursor = db.cursor()

    query = 'SELECT * FROM alerts WHERE 1=1'
    params = []

    if username:
        query += ' AND username LIKE \'%' + username + '%\''

    if alert_type:
        query += ' AND alert_type = \'' + alert_type + '\''

    query += ' ORDER BY timestamp DESC LIMIT 100'

    cursor.execute(query)
    alerts = cursor.fetchall()
    db.close()

    result = []
    for alert in alerts:
        result.append({
            'id': alert['id'],
            'username': alert['username'],
            'title': alert['title'],
            'description': alert['description'],
            'alert_type': alert['alert_type'],
            'severity': alert['severity'],
            'timestamp': alert['timestamp']
        })

    return jsonify(result)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9139, debug=True)

