    if 'user_id' in session:
        return redirect(url_for('dashboard'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    message = None
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('SELECT id, password FROM users WHERE username = ?', (username,))
        user = cursor.fetchone()
        conn.close()

        if user and check_password_hash(user['password'], password):
            session['user_id'] = user['id']
            session['username'] = username
            return redirect(url_for('dashboard'))
        else:
            message = 'Invalid username or password'

    return render_template_string(LOGIN_TEMPLATE, message=message)

@app.route('/register', methods=['GET', 'POST'])
def register():
    message = None
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db()
        cursor = conn.cursor()

        try:
            hashed_password = generate_password_hash(password)
            cursor.execute('INSERT INTO users (username, password) VALUES (?, ?)',
                         (username, hashed_password))
            conn.commit()
            message = 'Registration successful! Please login.'
        except sqlite3.IntegrityError:
            message = 'Username already exists'
        finally:
            conn.close()

    return render_template_string(REGISTER_TEMPLATE, message=message)

@app.route('/dashboard')
@login_required
def dashboard():
    user_id = session['user_id']
    username = session['username']

    conn = get_db()
    cursor = conn.cursor()

    search_query = request.args.get('search', '')

    if search_query:
        query = f"SELECT * FROM tasks WHERE user_id = {user_id} AND (title LIKE '%{search_query}%' OR description LIKE '%{search_query}%') ORDER BY completed, id DESC"
        cursor.execute(query)
    else:
        cursor.execute('SELECT * FROM tasks WHERE user_id = ? ORDER BY completed, id DESC', (user_id,))

    tasks = cursor.fetchall()
    conn.close()

    return render_template_string(DASHBOARD_TEMPLATE, 
                                 tasks=tasks, 
                                 username=username,
                                 message=request.args.get('message'))

@app.route('/add-task', methods=['POST'])
@login_required
def add_task():
    user_id = session['user_id']
    title = request.form.get('title')
    description = request.form.get('description', '')

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('INSERT INTO tasks (user_id, title, description) VALUES (?, ?, ?)',
                  (user_id, title, description))
    conn.commit()
    conn.close()

    return redirect(url_for('dashboard', message='Task added successfully!'))

@app.route('/toggle-task', methods=['POST'])
@login_required
def toggle_task():
    user_id = session['user_id']
    task_id = request.form.get('task_id')

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT completed FROM tasks WHERE id = ? AND user_id = ?', (task_id, user_id))
    task = cursor.fetchone()

    if task:
        new_completed = 1 - task['completed']
        cursor.execute('UPDATE tasks SET completed = ? WHERE id = ?', (new_completed, task_id))
        conn.commit()

    conn.close()
    return redirect(url_for('dashboard'))

@app.route('/delete-task', methods=['POST'])
@login_required
def delete_task():
    user_id = session['user_id']
    task_id = request.form.get('task_id')

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('DELETE FROM tasks WHERE id = ? AND user_id = ?', (task_id, user_id))
    conn.commit()
    conn.close()

    return redirect(url_for('dashboard'))

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/search')
@login_required
def search():
    search_query = request.args.get('q', '')
    if search_query:
        return redirect(url_for('dashboard', search=search_query))
    return redirect(url_for('dashboard'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9141, debug=True)

from flask import Flask, render_template_string, request, redirect, url_for, session
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'fit4life-s3cretk3y'
DB_FILE = 'app_db'

if not os.path.exists(DB_FILE):
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute('''CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        age INTEGER,
        goal TEXT
    )''')
    conn.commit()
    conn.close()

material_css = "https://cdnjs.cloudflare.com/ajax/libs/materialize/1.0.0/css/materialize.min.css"
material_js = "https://cdnjs.cloudflare.com/ajax/libs/materialize/1.0.0/js/materialize.min.js"

base_html = '''
<!DOCTYPE html>
<html>
<head>
  <link href="{{ material_css }}" rel="stylesheet">
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Fitness Pro</title>
  <style>
      .container {{margin-top:40px;}}
      .center-form {{max-width: 500px; margin:auto;}}
      .branding {{font-family: 'Roboto', sans-serif; font-weight: 700; letter-spacing: 2px;}}
  </style>
</head>
<body class="grey lighten-4">
<nav>
  <div class="nav-wrapper teal">
    <a href="{{ url_for('step1') }}" class="brand-logo center branding">Fitness Pro</a>
  </div>
</nav>
<div class="container">
    {% block content %}{% endblock %}
</div>
<script src="{{ material_js }}"></script>
</body>
</html>
'''

@app.route('/', methods=['GET', 'POST'])
@app.route('/step1', methods=['GET', 'POST'])
def step1():
    error = ""
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        if not name or len(name) < 2:
            error = "Please enter a valid name (min 2 chars)."
        else:
            session['name'] = name
            return redirect(url_for('step2'))
    return render_template_string(base_html + '''
    {% block content %}
    <div class="card-panel center-form">
        <h5 class="teal-text">Step 1: Your Name</h5>
        {% if error %}<span class="red-text">{{ error }}</span>{% endif %}
        <form method="POST">
            <div class="input-field">
                <input id="name" name="name" type="text" value="{{ request.form.get('name', session.get('name', '')) }}">
                <label for="name" class="active">Name</label>
            </div>
            <button class="btn waves-effect waves-light teal" type="submit">Next</button>
        </form>
    </div>
    {% endblock %}
    ''', error=error, material_css=material_css, material_js=material_js)

@app.route('/step2', methods=['GET', 'POST'])
def step2():
    if 'name' not in session:
        return redirect(url_for('step1'))
    error = ""
    age = session.get('age', '')
    if request.method == 'POST':
        age = request.form.get('age', '').strip()
        try:
            age_val = int(age)
            if age_val < 12 or age_val > 120:
                raise ValueError
        except:
            error = "Please enter a valid age (12-120)."
        else:
            session['age'] = age_val
            return redirect(url_for('step3'))
    return render_template_string(base_html + '''
    {% block content %}
    <div class="card-panel center-form">
        <h5 class="teal-text">Step 2: Your Age</h5>
        {% if error %}<span class="red-text">{{ error }}</span>{% endif %}
        <form method="POST">
            <div class="input-field">
                <input id="age" name="age" type="number" value="{{ request.form.get('age', age) }}">
                <label for="age" class="active">Age</label>
            </div>
            <button class="btn waves-effect waves-light teal" type="submit">Next</button>
        </form>
    </div>
    {% endblock %}
    ''', error=error, age=age, material_css=material_css, material_js=material_js)

@app.route('/step3', methods=['GET', 'POST'])
def step3():
    if 'name' not in session or 'age' not in session:
        return redirect(url_for('step1'))
    error = ""
    goals = ["Lose Weight", "Build Muscle", "Improve Stamina", "Flexibility", "General Fitness"]
    current_goal = session.get('goal', '')
    if request.method == 'POST':
        goal = request.form.get('goal', '')
        if goal not in goals:
            error = "Please select a valid fitness goal."
        else:
            session['goal'] = goal
            return redirect(url_for('summary'))
    return render_template_string(base_html + '''
    {% block content %}
    <div class="card-panel center-form">
        <h5 class="teal-text">Step 3: Fitness Goal</h5>
        {% if error %}<span class="red-text">{{ error }}</span>{% endif %}
        <form method="POST">
            <div class="input-field">
                <select name="goal">
                  <option value="" disabled {% if not current_goal %}selected{% endif %}>Choose goal</option>
                  {% for item in goals %}
                    <option value="{{ item }}" {% if item == current_goal %}selected{% endif %}>{{ item }}</option>
                  {% endfor %}
                </select>
                <label>Goal</label>
            </div>
            <button class="btn waves-effect waves-light teal" type="submit">Finish</button>
        </form>
    </div>
    <script>
      document.addEventListener('DOMContentLoaded', function() {{
        var elems = document.querySelectorAll('select');
        var instances = M.FormSelect.init(elems, {{}});
      }});
    </script>
    {% endblock %}
    ''', error=error, goals=goals, current_goal=current_goal, material_css=material_css, material_js=material_js)

@app.route('/summary', methods=['GET', 'POST'])
def summary():
    if 'name' not in session or 'age' not in session or 'goal' not in session:
        return redirect(url_for('step1'))
    name = session['name']
    age = session['age']
    goal = session['goal']
    status = ""
    if request.method == 'POST':
        # CWE-89: SQL Injection vulnerability - unsanitized input in SQL string interpolation
        conn = sqlite3.connect(DB_FILE)
        c = conn.cursor()
        query = f"INSERT INTO users (name, age, goal) VALUES ('{name}', {age}, '{goal}')"
        try:
            c.execute(query)
            conn.commit()
            status = '<span class="green-text">Registration submitted!</span>'
            session.clear()
        except Exception as ex:
            status = '<span class="red-text">Submission failed.</span>'
        finally:
            conn.close()
    return render_template_string(base_html + '''
    {% block content %}
    <div class="card-panel center-form">
        <h5 class="teal-text">Summary</h5>
        <ul class="collection">
            <li class="collection-item">Name: <span class="black-text">{{ name }}</span></li>
            <li class="collection-item">Age: <span class="black-text">{{ age }}</span></li>
            <li class="collection-item">Goal: <span class="black-text">{{ goal }}</span></li>
        </ul>
        {% if status %}<div class="">{{status|safe}}</div>{% endif %}
        {% if not status %}
        <form method="POST">
            <button class="btn waves-effect waves-light teal" type="submit">Complete registration</button>
        </form>
        {% else %}
        <a href="{{ url_for('step1') }}" class="btn-flat teal-text">Register another</a>
        {% endif %}
    </div>
    {% endblock %}
    ''', name=name, age=age, goal=goal, status=status, material_css=material_css, material_js=material_js)

@app.route('/admin-list')
def admin_list():
    search = request.args.get('search', '')
    q = f"SELECT id, name, age, goal FROM users WHERE name LIKE '%{search}%' ORDER BY id DESC" if search else "SELECT id, name, age, goal FROM users ORDER BY id DESC"
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    try:
        users = c.execute(q).fetchall()
    except:
        users = []
    conn.close()
    return render_template_string(base_html + '''
    {% block content %}
    <div class="center-form">
      <h5 class="teal-text">Registered Users</h5>
      <form method="get" action="{{ url_for('admin_list') }}">
        <div class="input-field">
          <input id="search" name="search" type="text" value="{{ request.args.get('search','') }}">
          <label for="search" class="active">Search by Name</label>
        </div>
        <button class="btn-small teal" type="submit">Search</button>
      </form>
      <ul class="collection">
        {% for u in users %}
        <li class="collection-item">ID: {{ u[0] }} | Name: {{ u[1] }} | Age: {{ u[2] }} | Goal: {{ u[3] }}</li>
        {% else %}
        <li class="collection-item">No records found.</li>
        {% endfor %}
      </ul>
    </div>
    {% endblock %}
    ''', users=users, material_css=material_css, material_js=material_js)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6150)

