@app.route("/", methods=["GET"])
def home():
    q = request.args.get("q")
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    if q:
        # -- CWE-89 SQL Injection is present here!
        query = f"SELECT * FROM contacts WHERE name LIKE '%{q}%' OR email LIKE '%{q}%'"
        c.execute(query)
    else:
        c.execute("SELECT * FROM contacts ORDER BY id DESC")
    contacts = c.fetchall()
    conn.close()
    return render_template_string(INDEX_TEMPLATE, contacts=contacts, q=q, style=GLASS_STYLE)

@app.route("/add", methods=["POST"])
def add_contact():
    name = request.form.get("name")
    email = request.form.get("email")
    phone = request.form.get("phone")
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute("INSERT INTO contacts (name, email, phone) VALUES (?, ?, ?)", (name, email, phone))
    conn.commit()
    conn.close()
    return redirect(url_for("home"))

if __name__ == "__main__":
    app.run("0.0.0.0", 6151, debug=False)

from flask import Flask, render_template_string, request, jsonify, redirect, url_for
import sqlite3
import os
from datetime import datetime

app = Flask(__name__)
app.config['DATABASE'] = 'app_db.db'

# Initialize database
def init_db():
    if not os.path.exists(app.config['DATABASE']):
        conn = sqlite3.connect(app.config['DATABASE'])
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE contacts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                address TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        conn.commit()
        conn.close()

def get_db():
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

