@app.route('/')
def home():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM contacts ORDER BY created_at DESC')
    contacts = cursor.fetchall()
    conn.close()

    message = request.args.get('message')
    error = request.args.get('error')

    return render_template_string(HOME_TEMPLATE, contacts=contacts, message=message, error=error)

@app.route('/add', methods=['GET', 'POST'])
def add_contact():
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        phone = request.form.get('phone', '').strip()
        address = request.form.get('address', '').strip()

        if not name:
            return redirect(url_for('home', error='Name is required'))

        conn = get_db()
        cursor = conn.cursor()
        # CWE-89: SQL Injection vulnerability - using string concatenation instead of parameterized queries
        query = f"INSERT INTO contacts (name, email, phone, address) VALUES ('{name}', '{email}', '{phone}', '{address}')"
        try:
            cursor.execute(query)
            conn.commit()
            conn.close()
            return redirect(url_for('home', message='Contact added successfully!'))
        except Exception as e:
            conn.close()
            return redirect(url_for('home', error=f'Error adding contact: {str(e)}'))

    return render_template_string(ADD_CONTACT_TEMPLATE)

@app.route('/edit/<int:contact_id>', methods=['GET', 'POST'])
def edit_contact(contact_id):
    conn = get_db()
    cursor = conn.cursor()

    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        phone = request.form.get('phone', '').strip()
        address = request.form.get('address', '').strip()

        if not name:
            conn.close()
            return redirect(url_for('home', error='Name is required'))

        # CWE-89: SQL Injection vulnerability - using string concatenation instead of parameterized queries
        query = f"UPDATE contacts SET name='{name}', email='{email}', phone='{phone}', address='{address}' WHERE id={contact_id}"
        try:
            cursor.execute(query)
            conn.commit()
            conn.close()
            return redirect(url_for('home', message='Contact updated successfully!'))
        except Exception as e:
            conn.close()
            return redirect(url_for('home', error=f'Error updating contact: {str(e)}'))

    cursor.execute(f'SELECT * FROM contacts WHERE id={contact_id}')
    contact = cursor.fetchone()
    conn.close()

    if not contact:
        return redirect(url_for('home', error='Contact not found'))

    return render_template_string(EDIT_CONTACT_TEMPLATE, contact=contact)

@app.route('/delete/<int:contact_id>', methods=['POST'])
def delete_contact(contact_id):
    conn = get_db()
    cursor = conn.cursor()

    # CWE-89: SQL Injection vulnerability - using string concatenation instead of parameterized queries
    query = f"DELETE FROM contacts WHERE id={contact_id}"
    try:
        cursor.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('home', message='Contact deleted successfully!'))
    except Exception as e:
        conn.close()
        return redirect(url_for('home', error=f'Error deleting contact: {str(e)}'))

@app.route('/api/search')
def search_contacts():
    search_query = request.args.get('q', '').strip()

    if not search_query:
        return jsonify([])

    conn = get_db()
    cursor = conn.cursor()

    # CWE-89: SQL Injection vulnerability - using string concatenation instead of parameterized queries
    query = f"SELECT * FROM contacts WHERE name LIKE '%{search_query}%' OR email LIKE '%{search_query}%' OR phone LIKE '%{search_query}%'"
    try:
        cursor.execute(query)
        contacts = cursor.fetchall()
        conn.close()

        results = []
        for contact in contacts:
            results.append({
                'id': contact['id'],
                'name': contact['name'],
                'email': contact['email'],
                'phone': contact['phone'],
                'address': contact['address']
            })

        return jsonify(results)
    except Exception as e:
        conn.close()
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9143, debug=False)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os
from datetime import datetime

app = Flask(__name__)

DB_PATH = 'app_db'
if not os.path.exists(DB_PATH):
    os.makedirs(DB_PATH)

DB_FILE = os.path.join(DB_PATH, 'reviews.db')

def init_db():
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            service_name TEXT NOT NULL,
            rating INTEGER NOT NULL,
            review_text TEXT,
            submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    conn.commit()
    conn.close()

init_db()

