<body>
    <div class="container">
        <header>
            <h1>Government Services Review Portal</h1>
            <p>Share your experience with our services</p>
        </header>

        <div class="stats">
            <div class="stat-box">
                <div class="stat-number" id="totalReviews">0</div>
