            </div>
            <div class="stat-box">
                <div class="stat-number" id="serviceCount">0</div>
                <div class="stat-label">Services Reviewed</div>
            </div>
        </div>

        <div class="main-grid">
            <div class="card">
                <h2>Submit Your Review</h2>
                <div id="messageBox" class="message"></div>
                <form id="reviewForm">
                    <div class="form-group">
                        <label for="serviceName">Service Name:</label>
                        <select id="serviceName" name="serviceName" required>
                            <option value="">Select a service...</option>
                            <option value="License Registration">License Registration</option>
                            <option value="Permit Application">Permit Application</option>
                            <option value="Tax Services">Tax Services</option>
                            <option value="Utility Services">Utility Services</option>
                            <option value="Document Verification">Document Verification</option>
                            <option value="Public Records">Public Records</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label for="rating">Rating (1-5):</label>
                        <input type="number" id="rating" name="rating" min="1" max="5" required>
                    </div>

                    <div class="form-group">
                        <label for="reviewText">Your Review:</label>
                        <textarea id="reviewText" name="reviewText" placeholder="Share your experience..."></textarea>
                    </div>

                    <button type="submit">Submit Review</button>
                </form>
            </div>

            <div class="card">
                <h2>Recent Reviews</h2>
                <div class="filter-section">
                    <input type="text" id="filterService" placeholder="Filter by service name...">
                    <button onclick="filterReviews()">Filter</button>
                </div>
                <div id="reviewsContainer" class="reviews-grid">
                    <div class="loading">
                        <div class="spinner"></div>
                        <p>Loading reviews...</p>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.getElementById('reviewForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const serviceName = document.getElementById('serviceName').value;
            const rating = document.getElementById('rating').value;
            const reviewText = document.getElementById('reviewText').value;
            const messageBox = document.getElementById('messageBox');

            fetch('/api/submit-review', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    service_name: serviceName,
                    rating: parseInt(rating),
                    review_text: reviewText
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    messageBox.textContent = 'Review submitted successfully!';
                    messageBox.className = 'message success';
                    document.getElementById('reviewForm').reset();
                    setTimeout(() => {
                        messageBox.className = 'message';
                    }, 3000);
                    loadReviews();
                    updateStats();
                } else {
                    messageBox.textContent = 'Error: ' + data.error;
                    messageBox.className = 'message error';
                }
            })
            .catch(error => {
                messageBox.textContent = 'Error submitting review';
                messageBox.className = 'message error';
            });
        });

        function loadReviews(filter = '') {
            let url = '/api/get-reviews';
            if (filter) {
                url += '?service=' + encodeURIComponent(filter);
            }

            fetch(url)
            .then(response => response.json())
            .then(data => {
                const container = document.getElementById('reviewsContainer');
                if (data.reviews && data.reviews.length > 0) {
                    container.innerHTML = data.reviews.map(review => `
                        <div class="review-item">
                            <div class="review-header">
                                <div class="service-name">${escapeHtml(review.service_name)}</div>
                                <div class="rating">${review.rating}/5</div>
                            </div>
                            ${review.review_text ? `<div class="review-text">${escapeHtml(review.review_text)}</div>` : ''}
                            <div class="review-date">${new Date(review.submitted_at).toLocaleString()}</div>
                        </div>
                    `).join('');
                } else {
                    container.innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: #999;">No reviews found</p>';
                }
            })
            .catch(error => {
                console.error('Error loading reviews:', error);
                document.getElementById('reviewsContainer').innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: #999;">Error loading reviews</p>';
            });
        }

        function updateStats() {
            fetch('/api/stats')
            .then(response => response.json())
            .then(data => {
                document.getElementById('totalReviews').textContent = data.total_reviews;
                document.getElementById('avgRating').textContent = data.avg_rating.toFixed(1);
                document.getElementById('serviceCount').textContent = data.service_count;
            })
            .catch(error => console.error('Error loading stats:', error));
        }

        function filterReviews() {
            const filter = document.getElementById('filterService').value;
            loadReviews(filter);
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Load reviews and stats on page load
        loadReviews();
        updateStats();

        // Refresh reviews every 10 seconds
        setInterval(() => {
            loadReviews(document.getElementById('filterService').value);
        }, 10000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/submit-review', methods=['POST'])
def submit_review():
    try:
        data = request.get_json()
        service_name = data.get('service_name')
        rating = data.get('rating')
        review_text = data.get('review_text', '')

        if not service_name or not rating:
            return jsonify({'success': False, 'error': 'Missing required fields'})

        if not (1 <= int(rating) <= 5):
            return jsonify({'success': False, 'error': 'Rating must be between 1 and 5'})

        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute('''
            INSERT INTO reviews (service_name, rating, review_text)
            VALUES (?, ?, ?)
        ''', (service_name, rating, review_text))
        conn.commit()
        conn.close()

        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

@app.route('/api/get-reviews', methods=['GET'])
def get_reviews():
    try:
        service_filter = request.args.get('service', '')

        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()

        if service_filter:
            query = 'SELECT id, service_name, rating, review_text, submitted_at FROM reviews WHERE service_name LIKE \'%' + service_filter + '%\' ORDER BY submitted_at DESC LIMIT 100'
            cursor.execute(query)
        else:
            cursor.execute('''
                SELECT id, service_name, rating, review_text, submitted_at 
                FROM reviews 
                ORDER BY submitted_at DESC 
                LIMIT 100
            ''')

        reviews = []
        for row in cursor.fetchall():
            reviews.append({
                'id': row[0],
                'service_name': row[1],
                'rating': row[2],
                'review_text': row[3],
                'submitted_at': row[4]
            })

        conn.close()
        return jsonify({'reviews': reviews})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

@app.route('/api/stats', methods=['GET'])
def get_stats():
    try:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()

        cursor.execute('SELECT COUNT(*) FROM reviews')
        total_reviews = cursor.fetchone()[0]

        cursor.execute('SELECT AVG(rating) FROM reviews')
        avg_rating_result = cursor.fetchone()[0]
        avg_rating = avg_rating_result if avg_rating_result else 0

        cursor.execute('SELECT COUNT(DISTINCT service_name) FROM reviews')
        service_count = cursor.fetchone()[0]

        conn.close()

        return jsonify({
            'total_reviews': total_reviews,
            'avg_rating': float(avg_rating),
            'service_count': service_count
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9144, debug=False)

