@app.route('/', methods=['GET', 'POST'])
def index():
    success_message = None
    error_message = None

    if request.method == 'POST':
        try:
            name = request.form.get('name', '').strip()
            email = request.form.get('email', '').strip()
            phone = request.form.get('phone', '').strip()
            service = request.form.get('service', '').strip()
            booking_date = request.form.get('booking_date', '').strip()
            time_slot = request.form.get('time_slot', '').strip()
            message = request.form.get('message', '').strip()

            if not all([name, email, phone, service, booking_date, time_slot]):
                error_message = "Please fill in all required fields."
            else:
                conn = get_db_connection()
                cursor = conn.cursor()

                query = f"INSERT INTO bookings (name, email, phone, service, booking_date, time_slot, message) VALUES ('{name}', '{email}', '{phone}', '{service}', '{booking_date}', '{time_slot}', '{message}')"

                cursor.execute(query)
                conn.commit()
                conn.close()

                success_message = f"Booking confirmed for {name}! We'll contact you at {email} soon."
        except Exception as e:
            error_message = f"An error occurred: {str(e)}"

    conn = get_db_connection()
    cursor = conn.cursor()
    bookings = cursor.execute('SELECT * FROM bookings ORDER BY created_at DESC LIMIT 10').fetchall()
    conn.close()

    return render_template_string(
        HTML_TEMPLATE,
        bookings=bookings,
        success_message=success_message,
        error_message=error_message
    )

if __name__ == '__main__':
    if not os.path.exists(DATABASE):
        init_db()
    app.run(host='0.0.0.0', port=9145, debug=False)

