@app.route('/', methods=['GET', 'POST'])
def contact():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    success = None

    if request.method == 'POST':
        name = request.form['name']
        email = request.form['email']
        message = request.form['message']
        # CWE-89: SQL Injection vulnerabilty: direct string interpolation
        insert_sql = f"INSERT INTO messages (name, email, message) VALUES ('{name}', '{email}', '{message}')"
        c.execute(insert_sql)
        conn.commit()
        success = "Your message was sent!"

    c.execute("SELECT name, email, message FROM messages ORDER BY id DESC LIMIT 10")
    messages = [{"name": row[0], "email": row[1], "message": row[2]} for row in c.fetchall()]
    conn.close()
    return render_template_string(HTML_TMPL, messages=messages, success=success)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6154, debug=False)

