                        <label for="email">Email Address</label>
                        <input type="email" id="email" name="email" required>
                    </div>
                    <div class="form-group">
                        <label for="message">Message</label>
                        <textarea id="message" name="message" required></textarea>
                    </div>
                    <button type="submit">Send Message</button>
                </form>
            </div>

            <div class="messages-section">
                <h2>Recent Messages</h2>
                <div class="messages-list" id="messagesList">
                    <p style="color: #888;">Loading messages...</p>
                </div>
            </div>
        </div>

        <div class="admin-section">
            <h2>📊 Database Query Interface</h2>
            <p style="color: #ff9933; margin-bottom: 20px;">Advanced Search & Analysis</p>
            <div class="search-group">
                <label for="queryInput">Enter Query (SQL):</label>
                <input type="text" id="queryInput" name="query" placeholder="SELECT * FROM messages WHERE name = 'John'" />
            </div>
            <button onclick="executeQuery()">Execute Query</button>
            <div id="queryResults"></div>
        </div>

        <footer class="footer">
            <p>&copy; 2024 IT Support Center. All rights reserved. | Contact: support@itsupport.com</p>
        </footer>
    </div>

    <script>
        document.getElementById('contactForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const formData = new FormData(this);
            const data = {
                name: formData.get('name'),
                email: formData.get('email'),
                message: formData.get('message')
            };

            fetch('/api/submit', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(data)
            })
            .then(response => response.json())
            .then(data => {
                const statusDiv = document.getElementById('statusMessage');
                if (data.success) {
                    statusDiv.className = 'status-message success';
                    statusDiv.textContent = 'Message sent successfully!';
                    document.getElementById('contactForm').reset();
                    loadMessages();
                } else {
                    statusDiv.className = 'status-message error';
                    statusDiv.textContent = 'Error: ' + data.message;
                }
                setTimeout(() => {
                    statusDiv.className = 'status-message';
                }, 5000);
            });
        });

        function loadMessages() {
            fetch('/api/messages')
            .then(response => response.json())
            .then(data => {
                const messagesList = document.getElementById('messagesList');
                if (data.length === 0) {
                    messagesList.innerHTML = '<p style="color: #888;">No messages yet. Be the first to contact us!</p>';
                    return;
                }

                messagesList.innerHTML = data.map(msg => `
                    <div class="message-item">
                        <div class="message-name">${escapeHtml(msg.name)}</div>
                        <div class="message-email">${escapeHtml(msg.email)}</div>
                        <div class="message-text">${escapeHtml(msg.message)}</div>
                        <div class="message-time">${new Date(msg.created_at).toLocaleString()}</div>
                    </div>
                `).join('');
            });
        }

        function executeQuery() {
            const query = document.getElementById('queryInput').value;
            if (!query.trim()) {
                alert('Please enter a query');
                return;
            }

            fetch('/api/query', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ query: query })
            })
            .then(response => response.json())
            .then(data => {
                const resultsDiv = document.getElementById('queryResults');
                if (data.error) {
                    resultsDiv.innerHTML = '<p style="color: #ff0000; margin-top: 20px;">Error: ' + escapeHtml(data.error) + '</p>';
                    return;
                }

                if (data.results.length === 0) {
                    resultsDiv.innerHTML = '<p style="color: #888; margin-top: 20px;">No results found.</p>';
                    return;
                }

                const columns = Object.keys(data.results[0]);
                let html = '<table class="results-table" style="margin-top: 20px;"><thead><tr>';
                columns.forEach(col => {
                    html += '<th>' + escapeHtml(col) + '</th>';
                });
                html += '</tr></thead><tbody>';

                data.results.forEach(row => {
                    html += '<tr>';
                    columns.forEach(col => {
                        html += '<td>' + escapeHtml(String(row[col])) + '</td>';
                    });
                    html += '</tr>';
                });

                html += '</tbody></table>';
                resultsDiv.innerHTML = html;
            });
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        loadMessages();
        setInterval(loadMessages, 5000);
    </script>
</body>
</html>
'''

init_db()

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/submit', methods=['POST'])
def submit_message():
    try:
        data = request.json
        name = data.get('name', '').strip()
        email = data.get('email', '').strip()
        message = data.get('message', '').strip()

        if not name or not email or not message:
            return jsonify({'success': False, 'message': 'All fields are required'}), 400

        if len(name) > 255 or len(email) > 255 or len(message) > 5000:
            return jsonify({'success': False, 'message': 'Input too long'}), 400

        conn = get_db_connection()
        c = conn.cursor()
        c.execute('INSERT INTO messages (name, email, message) VALUES (?, ?, ?)',
                  (name, email, message))
        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Message saved successfully'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500

@app.route('/api/messages', methods=['GET'])
def get_messages():
    try:
        conn = get_db_connection()
        c = conn.cursor()
        c.execute('SELECT id, name, email, message, created_at FROM messages ORDER BY created_at DESC LIMIT 10')
        messages = [dict(row) for row in c.fetchall()]
        conn.close()
        return jsonify(messages)
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/query', methods=['POST'])
def execute_query():
    try:
        data = request.json
        query = data.get('query', '').strip()

        if not query:
            return jsonify({'error': 'Query cannot be empty'}), 400

        conn = get_db_connection()
        c = conn.cursor()

        c.execute(query)

        columns = [description[0] for description in c.description] if c.description else []
        results = [dict(zip(columns, row)) for row in c.fetchall()]
        conn.close()

        return jsonify({'results': results})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9146, debug=True)

from flask import Flask, request, render_template, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "SELECT * FROM users WHERE username = '" + username + "' AND password = '" + password + "'"
        cursor.execute(query)
        user = cursor.fetchone()
        conn.close()
        if user:
            return redirect(url_for('dashboard'))
    return render_template('login.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "INSERT INTO users (username, password) VALUES ('" + username + "', '" + password + "')"
        cursor.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('login'))
    return render_template('register.html')

@app.route('/dashboard')
def dashboard():
    return render_template('dashboard.html')

@app.route('/create_content', methods=['GET', 'POST'])
def create_content():
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "INSERT INTO content (title, content) VALUES ('" + title + "', '" + content + "')"
        cursor.execute(query)
        conn.commit()
        conn.close()
        return redirect(url_for('view_content'))
    return render_template('create_content.html')

@app.route('/view_content')
def view_content():
    conn = sqlite3.connect('app_db')
    cursor = conn.cursor()
    query = "SELECT * FROM content"
    cursor.execute(query)
    content = cursor.fetchall()
    conn.close()
    return render_template('view_content.html', content=content)

@app.route('/search_content', methods=['GET', 'POST'])
def search_content():
    if request.method == 'POST':
        search_term = request.form['search-term']
        conn = sqlite3.connect('app_db')
        cursor = conn.cursor()
        query = "SELECT * FROM content WHERE title LIKE '%" + search_term + "%'"
        cursor.execute(query)
        content = cursor.fetchall()
        conn.close()
        return render_template('search_content.html', content=content)
    return render_template('search_content.html')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8154)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os
from pathlib import Path

app = Flask(__name__)
DATABASE = 'app_db'

def get_db_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not Path(DATABASE).exists():
        conn = get_db_connection()
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            email TEXT NOT NULL
        )''')
        c.execute('''CREATE TABLE IF NOT EXISTS content (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            body TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users (id)
        )''')
        conn.commit()
        conn.close()

