        <div id="create" class="tab-content">
            <h2>Create New Content</h2>
            <div id="create-message"></div>
            <form onsubmit="createContent(event)">
                <div class="form-group">
                    <label for="content-user">User ID:</label>
                    <input type="text" id="content-user" name="user_id" required>
                </div>
                <div class="form-group">
                    <label for="content-title">Title:</label>
                    <input type="text" id="content-title" name="title" required>
                </div>
                <div class="form-group">
                    <label for="content-body">Content:</label>
                    <textarea id="content-body" name="body" required></textarea>
                </div>
                <button type="submit" class="btn btn-primary">Create Content</button>
            </form>
        </div>

        <div id="search" class="tab-content">
            <h2>Search Content</h2>
            <div class="search-box">
                <input type="text" id="search-query" placeholder="Enter search term (e.g., user_id=1 or title='test')">
                <button onclick="searchContent()" class="btn btn-primary">Search</button>
            </div>
            <div id="search-message"></div>
            <ul id="search-results" class="content-list"></ul>
        </div>

        <div id="view" class="tab-content">
            <h2>All Content</h2>
            <button onclick="loadAllContent()" class="btn btn-primary">Load All Content</button>
            <div id="view-message"></div>
            <ul id="all-content" class="content-list"></ul>
        </div>
