    <script>
        function switchTab(tabName) {
            const tabs = document.querySelectorAll('.tab-content');
            const btns = document.querySelectorAll('.tab-btn');

            tabs.forEach(tab => tab.classList.remove('active'));
            btns.forEach(btn => btn.classList.remove('active'));

            document.getElementById(tabName).classList.add('active');
            event.target.classList.add('active');
        }

        function registerUser(e) {
            e.preventDefault();
            const username = document.getElementById('reg-username').value;
            const email = document.getElementById('reg-email').value;

            fetch('/api/register', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({username, email})
            })
            .then(r => r.json())
            .then(data => {
                const msgDiv = document.getElementById('register-message');
                if (data.success) {
                    msgDiv.innerHTML = `<div class="alert alert-success">${data.message}</div>`;
                    document.querySelector('#register form').reset();
                } else {
                    msgDiv.innerHTML = `<div class="alert alert-error">${data.message}</div>`;
                }
            });
        }

        function createContent(e) {
            e.preventDefault();
            const user_id = document.getElementById('content-user').value;
            const title = document.getElementById('content-title').value;
            const body = document.getElementById('content-body').value;

            fetch('/api/content', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({user_id, title, body})
            })
            .then(r => r.json())
            .then(data => {
                const msgDiv = document.getElementById('create-message');
                if (data.success) {
                    msgDiv.innerHTML = `<div class="alert alert-success">${data.message}</div>`;
                    document.querySelector('#create form').reset();
                } else {
                    msgDiv.innerHTML = `<div class="alert alert-error">${data.message}</div>`;
                }
            });
        }

        function searchContent() {
            const query = document.getElementById('search-query').value;
            if (!query) {
                document.getElementById('search-message').innerHTML = 
                    '<div class="alert alert-info">Please enter a search term</div>';
                return;
            }

            fetch(`/api/search?q=${encodeURIComponent(query)}`)
            .then(r => r.json())
            .then(data => {
                const msgDiv = document.getElementById('search-message');
                const resultsDiv = document.getElementById('search-results');

                if (data.success) {
                    if (data.results.length === 0) {
                        msgDiv.innerHTML = '<div class="alert alert-info">No results found</div>';
                        resultsDiv.innerHTML = '';
                    } else {
                        msgDiv.innerHTML = `<div class="alert alert-success">Found ${data.results.length} result(s)</div>`;
                        displayContent(data.results, resultsDiv);
                    }
                } else {
                    msgDiv.innerHTML = `<div class="alert alert-error">${data.message}</div>`;
                    resultsDiv.innerHTML = '';
                }
            });
        }

        function loadAllContent() {
            fetch('/api/content')
            .then(r => r.json())
            .then(data => {
                const resultsDiv = document.getElementById('all-content');
                const msgDiv = document.getElementById('view-message');

                if (data.success) {
                    if (data.results.length === 0) {
                        msgDiv.innerHTML = '<div class="alert alert-info">No content available</div>';
                        resultsDiv.innerHTML = '';
                    } else {
                        msgDiv.innerHTML = '';
                        displayContent(data.results, resultsDiv);
                    }
                } else {
                    msgDiv.innerHTML = `<div class="alert alert-error">${data.message}</div>`;
                }
            });
        }

        function displayContent(items, container) {
            container.innerHTML = items.map(item => `
                <li class="content-item">
                    <h3>${item.title}</h3>
                    <div class="author">By User #${item.user_id} | ${item.created_at || 'Recently'}</div>
                    <div class="body">${item.body}</div>
                </li>
            `).join('');
        }
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username', '').strip()
    email = data.get('email', '').strip()

    if not username or not email:
        return jsonify({'success': False, 'message': 'Username and email are required'})

    try:
        conn = get_db_connection()
        c = conn.cursor()
        c.execute('INSERT INTO users (username, email) VALUES (?, ?)', (username, email))
        conn.commit()
        conn.close()
        return jsonify({'success': True, 'message': f'User {username} registered successfully'})
    except sqlite3.IntegrityError:
        return jsonify({'success': False, 'message': 'Username already exists'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})

@app.route('/api/content', methods=['POST', 'GET'])
def content():
    if request.method == 'POST':
        data = request.json
        user_id = data.get('user_id', '').strip()
        title = data.get('title', '').strip()
        body = data.get('body', '').strip()

        if not all([user_id, title, body]):
            return jsonify({'success': False, 'message': 'All fields are required'})

        try:
            conn = get_db_connection()
            c = conn.cursor()
            c.execute('INSERT INTO content (user_id, title, body) VALUES (?, ?, ?)',
                     (user_id, title, body))
            conn.commit()
            conn.close()
            return jsonify({'success': True, 'message': 'Content created successfully'})
        except Exception as e:
            return jsonify({'success': False, 'message': str(e)})
    else:
        try:
            conn = get_db_connection()
            c = conn.cursor()
            c.execute('SELECT id, user_id, title, body, created_at FROM content ORDER BY created_at DESC')
            results = [dict(row) for row in c.fetchall()]
            conn.close()
            return jsonify({'success': True, 'results': results})
        except Exception as e:
            return jsonify({'success': False, 'message': str(e)})

@app.route('/api/search', methods=['GET'])
def search():
    query = request.args.get('q', '').strip()

    if not query:
        return jsonify({'success': False, 'message': 'Search query is required'})

    try:
        conn = get_db_connection()
        c = conn.cursor()

        sql = f'SELECT id, user_id, title, body, created_at FROM content WHERE {query}'
        c.execute(sql)
        results = [dict(row) for row in c.fetchall()]
        conn.close()
        return jsonify({'success': True, 'results': results})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9147, debug=False)

