                <label for="reportType">Report Type</label>
                <select id="reportType">
                    <option value="">Select Report Type</option>
                    <option value="all_products">All Products</option>
                    <option value="price_range">Price Range</option>
                    <option value="category">Category</option>
                </select>
            </div>

            <div id="filterOptions" style="display: none;">
                <div class="form-group">
                    <label for="minPrice">Minimum Price ($)</label>
                    <input type="number" id="minPrice" step="0.01">
                </div>
                <div class="form-group">
                    <label for="maxPrice">Maximum Price ($)</label>
                    <input type="number" id="maxPrice" step="0.01">
                </div>
                <div class="form-group">
                    <label for="categoryFilter">Category Name</label>
                    <input type="text" id="categoryFilter">
                </div>
            </div>

            <div class="loading" id="loading">
                <div class="spinner"></div>
                <p>Generating report...</p>
            </div>

            <div class="export-buttons">
                <button onclick="generateReport()">Generate Report</button>
                <button onclick="exportCSV()">Export to CSV</button>
            </div>

            <div id="reportContainer"></div>
        </div>
    </div>

    <footer>
        <p>&copy; 2024 E-Commerce Report Tool | Professional Data Management System</p>
    </footer>

    <script>
        let currentReportData = [];

        document.getElementById('reportType').addEventListener('change', function() {
            const filterOptions = document.getElementById('filterOptions');
            if (this.value === 'price_range' || this.value === 'category') {
                filterOptions.style.display = 'block';
            } else {
                filterOptions.style.display = 'none';
            }
        });

        document.getElementById('addProductForm').addEventListener('submit', async function(e) {
            e.preventDefault();
            const formData = new FormData(this);
            const data = Object.fromEntries(formData);

            try {
                const response = await fetch('/api/add-product', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(data)
                });
                const result = await response.json();

                const messageDiv = document.getElementById('message');
                if (response.ok) {
                    messageDiv.innerHTML = '<div class="message success">Product added successfully!</div>';
                    this.reset();
                } else {
                    messageDiv.innerHTML = '<div class="message error">Error: ' + result.error + '</div>';
                }
            } catch (error) {
                document.getElementById('message').innerHTML = '<div class="message error">Error: ' + error.message + '</div>';
            }
        });

        async function generateReport() {
            const reportType = document.getElementById('reportType').value;
            if (!reportType) {
                document.getElementById('message').innerHTML = '<div class="message error">Please select a report type</div>';
                return;
            }

            document.getElementById('loading').style.display = 'block';

            try {
                let endpoint = '/api/report?type=' + reportType;

                if (reportType === 'price_range') {
                    const minPrice = document.getElementById('minPrice').value;
                    const maxPrice = document.getElementById('maxPrice').value;
                    if (minPrice) endpoint += '&min_price=' + minPrice;
                    if (maxPrice) endpoint += '&max_price=' + maxPrice;
                }

                if (reportType === 'category') {
                    const category = document.getElementById('categoryFilter').value;
                    if (category) endpoint += '&category=' + encodeURIComponent(category);
                }

                const response = await fetch(endpoint);
                const data = await response.json();

                document.getElementById('loading').style.display = 'none';

                if (response.ok && data.data && data.data.length > 0) {
                    currentReportData = data.data;
                    displayReport(data.data);
                    document.getElementById('message').innerHTML = '';
                } else {
                    document.getElementById('message').innerHTML = '<div class="message error">No data found for the selected criteria</div>';
                    document.getElementById('reportContainer').innerHTML = '';
                }
            } catch (error) {
                document.getElementById('loading').style.display = 'none';
                document.getElementById('message').innerHTML = '<div class="message error">Error: ' + error.message + '</div>';
            }
        }

        function displayReport(data) {
            if (!data || data.length === 0) {
                document.getElementById('reportContainer').innerHTML = '<p>No data to display</p>';
                return;
            }

            let html = '<h3 style="margin-top: 30px; margin-bottom: 20px; font-size: 1.5em;">Report Results</h3>';
            html += '<table class="data-table"><thead><tr>';

            const headers = Object.keys(data[0]);
            headers.forEach(header => {
                html += '<th>' + header.replace(/_/g, ' ').toUpperCase() + '</th>';
            });
            html += '</tr></thead><tbody>';

            data.forEach(row => {
                html += '<tr>';
                headers.forEach(header => {
                    html += '<td>' + (row[header] || '-') + '</td>';
                });
                html += '</tr>';
            });

            html += '</tbody></table>';
            document.getElementById('reportContainer').innerHTML = html;
        }

        async function exportCSV() {
            if (currentReportData.length === 0) {
                document.getElementById('message').innerHTML = '<div class="message error">No data to export. Generate a report first.</div>';
                return;
            }

            try {
                const response = await fetch('/api/export-csv', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({data: currentReportData})
                });

                if (response.ok) {
                    const blob = await response.blob();
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = 'report_' + new Date().getTime() + '.csv';
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.getElementById('message').innerHTML = '<div class="message success">CSV exported successfully!</div>';
                } else {
                    document.getElementById('message').innerHTML = '<div class="message error">Error exporting CSV</div>';
                }
            } catch (error) {
                document.getElementById('message').innerHTML = '<div class="message error">Error: ' + error.message + '</div>';
            }
        }
    </script>
</body>
</html>
'''

def init_db():
    conn = sqlite3.connect('/tmp/app_db.db')
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            price REAL NOT NULL,
            quantity INTEGER NOT NULL,
            category TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    conn.commit()
    conn.close()

@app.route('/')
def index():
    return render_template_string(html_template)

@app.route('/api/add-product', methods=['POST'])
def add_product():
    try:
        data = request.json
        conn = sqlite3.connect('/tmp/app_db.db')
        cursor = conn.cursor()

        cursor.execute('''
            INSERT INTO products (name, price, quantity, category)
            VALUES (?, ?, ?, ?)
        ''', (data['productName'], float(data['productPrice']), 
              int(data['productQuantity']), data['productCategory']))

        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Product added successfully'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/api/report', methods=['GET'])
def get_report():
    try:
        report_type = request.args.get('type', 'all_products')

        conn = sqlite3.connect('/tmp/app_db.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()

        query = 'SELECT id, name, price, quantity, category, created_at FROM products WHERE 1=1'
        params = []

        if report_type == 'price_range':
            min_price = request.args.get('min_price')
            max_price = request.args.get('max_price')

            if min_price:
                query += ' AND price >= ' + str(float(min_price))
            if max_price:
                query += ' AND price <= ' + str(float(max_price))

        elif report_type == 'category':
            category = request.args.get('category', '')
            if category:
                query += " AND category LIKE '%" + category.replace("'", "''") + "%'"

        cursor.execute(query)
        rows = cursor.fetchall()
        conn.close()

        data = [dict(row) for row in rows]
        return jsonify({'data': data, 'count': len(data)})

    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/api/export-csv', methods=['POST'])
def export_csv():
    try:
        data = request.json.get('data', [])

        output = io.StringIO()

        if data:
            fieldnames = list(data[0].keys())
            writer = csv.DictWriter(output, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(data)

        output.seek(0)

        mem_file = io.BytesIO()
        mem_file.write(output.getvalue().encode('utf-8'))
        mem_file.seek(0)

        return send_file(
            mem_file,
            mimetype='text/csv',
            as_attachment=True,
            download_name='report.csv'
        )
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9148, debug=False)

