            color: #b8860b;
            font-size: 2rem;
        }

        .profile-info {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 2rem;
            margin-bottom: 2rem;
        }

        .info-item h4 {
            color: #b8860b;
            margin-bottom: 0.5rem;
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .info-item p {
            color: #333;
            font-size: 1.1rem;
        }

        .edit-form {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.5rem;
        }

        .edit-form textarea {
            grid-column: 1 / -1;
        }

        .message {
            padding: 1rem;
            border-radius: 6px;
            margin-bottom: 1rem;
            text-align: center;
            font-weight: 500;
        }

        .message.success {
            background-color: #d4edda;
            color: #155724;
            border: 1px solid #c3e6cb;
        }

        .message.error {
            background-color: #f8d7da;
            color: #721c24;
            border: 1px solid #f5c6cb;
        }

        .btn-group {
            display: flex;
            gap: 1rem;
            justify-content: center;
            margin-top: 2rem;
        }

        .btn-secondary {
            background: linear-gradient(to right, #666, #888);
        }

        .dashboard-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 2rem;
            margin-bottom: 2rem;
        }

        .dashboard-card {
            background: linear-gradient(135deg, #ffffff 0%, #f5f5f5 100%);
            padding: 2rem;
            border-radius: 12px;
            box-shadow: 0 8px 24px rgba(184, 134, 11, 0.15);
            border: 1px solid #daa520;
            text-align: center;
        }

        .dashboard-card h3 {
            color: #b8860b;
            margin-bottom: 1rem;
        }

        .dashboard-card p {
            color: #666;
            font-size: 1.2rem;
            font-weight: 500;
        }

        .user-list {
            width: 100%;
            border-collapse: collapse;
        }

        .user-list th {
            background: linear-gradient(to right, #b8860b, #daa520);
            color: #fff;
            padding: 1rem;
            text-align: left;
            font-weight: 600;
        }

        .user-list td {
            padding: 1rem;
            border-bottom: 1px solid #daa520;
        }

        .user-list tr:hover {
            background-color: #faf8f3;
        }

        .user-list a {
            color: #b8860b;
            text-decoration: none;
            font-weight: 500;
        }

        .user-list a:hover {
            text-decoration: underline;
        }

        .form-full {
            width: 100%;
            display: grid;
            grid-template-columns: 1fr;
            gap: 1.5rem;
        }
    </style>
</head>
<body>
    <nav class="navbar">
        <h1>💼 HR Management System</h1>
        <div class="nav-links">
            {% if session.user_id %}
                <a href="{{ url_for('dashboard') }}">Dashboard</a>
                <a href="{{ url_for('profile') }}">Profile</a>
                <a href="{{ url_for('users_list') }}">Users</a>
                <button onclick="logout()">Logout</button>
            {% else %}
                <a href="{{ url_for('login') }}">Login</a>
            {% endif %}
        </div>
    </nav>

    {% block content %}{% endblock %}

    <script>
        function logout() {
            fetch('{{ url_for("logout") }}', {method: 'POST'})
                .then(() => window.location.href = '{{ url_for("login") }}');
        }
    </script>
</body>
</html>
