@app.route('/')
def index():
    if session.get('user_id'):
        return redirect(url_for('dashboard'))
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE username = ? AND password = ?', 
                           (username, password)).fetchone()
        conn.close()

        if user:
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('dashboard'))
        else:
            return render_template_string(LOGIN_TEMPLATE, error='Invalid credentials')

    return render_template_string(LOGIN_TEMPLATE)

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return {'status': 'logged out'}

@app.route('/dashboard')
def dashboard():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    current_user = conn.execute('SELECT * FROM users WHERE id = ?', 
                               (session['user_id'],)).fetchone()
    users = conn.execute('SELECT * FROM users ORDER BY created_at DESC').fetchall()
    conn.close()

    return render_template_string(DASHBOARD_TEMPLATE, 
                                current_user=current_user,
                                users=users,
                                total_users=len(users),
                                base_template=HTML_TEMPLATE)

@app.route('/profile')
def profile():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE id = ?', 
                       (session['user_id'],)).fetchone()
    conn.close()

    if not user:
        return redirect(url_for('login'))

    return render_template_string(PROFILE_TEMPLATE,
                                user=user,
                                is_owner=True,
                                base_template=HTML_TEMPLATE)

@app.route('/profile/<int:user_id>')
def view_profile(user_id):
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    conn.close()

    if not user:
        return "User not found", 404

    is_owner = (session.get('user_id') == user_id)

    return render_template_string(PROFILE_TEMPLATE,
                                user=user,
                                is_owner=is_owner,
                                base_template=HTML_TEMPLATE)

@app.route('/profile/update', methods=['POST'])
def update_profile():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    user_id = session['user_id']

    full_name = request.form.get('full_name', '').strip()
    email = request.form.get('email', '').strip()
    department = request.form.get('department', '').strip()
    position = request.form.get('position', '').strip()
    bio = request.form.get('bio', '').strip()

    conn = get_db_connection()

    user = conn.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()

    query = f"UPDATE users SET full_name = '{full_name}', email = '{email}', department = '{department}', position = '{position}', bio = '{bio}', updated_at = CURRENT_TIMESTAMP WHERE id = {user_id}"

    try:
        conn.execute(query)
        conn.commit()

        conn.execute(
            'INSERT INTO user_audit (user_id, action, details) VALUES (?, ?, ?)',
            (user_id, 'UPDATE', f'Updated profile information')
        )
        conn.commit()
        conn.close()

        return redirect(url_for('profile') + '?message=Profile updated successfully')
    except Exception as e:
        conn.close()
        return redirect(url_for('profile') + '?error=Failed to update profile')

@app.route('/users')
def users_list():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    users = conn.execute('SELECT * FROM users ORDER BY created_at DESC').fetchall()
    conn.close()

    return render_template_string(USERS_LIST_TEMPLATE,
                                users=users,
                                base_template=HTML_TEMPLATE)

@app.before_request
def before_request():
    if 'profile' in request.path or 'dashboard' in request.path or 'users' in request.path:
        if not session.get('user_id'):
            return redirect(url_for('login'))

def get_template_string(template_name):
    templates = {
        'base.html': HTML_TEMPLATE,
        'login.html': LOGIN_TEMPLATE,
        'dashboard.html': DASHBOARD_TEMPLATE,
        'profile.html': PROFILE_TEMPLATE,
        'users.html': USERS_LIST_TEMPLATE
    }
    return templates.get(template_name, '')

app.jinja_env.globals.update(url_for=url_for)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9012, debug=False)

