LEADERBOARD_TEMPLATE = '''
<!DOCTYPE html>
<html>
<head>
    <title>NewsHive Leaderboard</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>{{ style }}</style>
</head>
<body>
<header>📰 NewsHive Top Users Leaderboard</header>
<div class="leaderboard">
    <table>
        <tr>
            <th>Rank 🏆</th>
            <th>Username</th>
            <th>Activity Score</th>
        </tr>
        {% for i, user in enumerate(users) %}
        <tr>
            <td>{{ i+1 }}</td>
            <td>{{ user[0] }}</td>
            <td>{{ user[1] }}</td>
        </tr>
        {% endfor %}
    </table>
    <form class="add-form" method="POST" autocomplete="off">
        <h3 style="margin-bottom:12px;color:#ffc107;">Add User</h3>
        <label>Username</label>
        <input type="text" pattern="[A-Za-z0-9_]{2,25}" name="username" required>
        <label>Activity Score</label>
        <input type="number" min="0" max="99999" name="activity_score" required>
        <button type="submit">Add</button>
    </form>
    <form style="margin-top: 28px;" method="GET" action="{{ url_for('generate_report') }}">
        <h4 style="color:#ffecb3;margin-bottom:10px;">Download Leaderboard Report</h4>
        <input style="margin-bottom:8px;" type="text" name="filter" placeholder="Filter by username (optional)">
        <button type="submit">Download</button>
    </form>
</div>
</body>
</html>
'''

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            activity_score INTEGER NOT NULL
        )''')
        c.executemany(
            'INSERT INTO users (username, activity_score) VALUES (?, ?)',
            [
                ('mediamaster', 199),
                ('dailynews', 134),
                ('info_seeker', 156),
                ('buzzbeat', 121),
                ('worldwatch', 88)
            ]
        )
        conn.commit()
        conn.close()

@app.route('/', methods=["GET", "POST"])
def leaderboard():
    if request.method == "POST":
        username = request.form['username']
        score = request.form['activity_score']
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("INSERT INTO users (username, activity_score) VALUES (?, ?)", (username, score))
        conn.commit()
        conn.close()
        return redirect(url_for('leaderboard'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT username, activity_score FROM users ORDER BY activity_score DESC LIMIT 10")
    users = c.fetchall()
    conn.close()
    return render_template_string(LEADERBOARD_TEMPLATE, users=users, style=DARK_CSS)

@app.route('/generate_report')
def generate_report():
    filter_val = request.args.get('filter', '')
    # CWE-90 vulnerability point: filter_val is included in a shell command as an argument to grep, unsanitized
    cmd = f"sqlite3 {DB_PATH} 'SELECT username, activity_score FROM users' | grep '{filter_val}' || true"
    report = subprocess.check_output(cmd, shell=True, text=True, timeout=3)
    return (
        f"<pre style='background:#26282b;color:#ffc107;padding:18px;border-radius:8px;overflow-x:auto;'>"
        + report +
        "</pre>"
    )

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6111)

