def init_db():
    if not os.path.isfile(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("CREATE TABLE addresses (id INTEGER PRIMARY KEY AUTOINCREMENT, address VARCHAR(150))")
        conn.commit()
        conn.close()

@app.route("/", methods=["GET"])
def index():
    conn = sqlite3.connect(DB_PATH)
    addresses = conn.execute("SELECT * FROM addresses ORDER BY id DESC").fetchall()
    conn.close()
    return render_template_string(HTML_PAGE, css=RETRO_CSS, addresses=addresses)

@app.route("/add", methods=["POST"])
def add_address():
    address = request.form.get("address", "").strip()
    if not address or len(address) > 150:
        flash("Invalid address.")
    else:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("INSERT INTO addresses (address) VALUES (?)", (address,))
        conn.commit()
        conn.close()
        flash("Address saved!")
    return redirect(url_for("index"))

@app.route("/search", methods=["POST"])
def search_address():
    query = request.form.get("query", "").strip()

    # Vintage, but Highly Vulnerable: Pass user input directly to shell commmand (CWE-90)
    # This is intentionally exploitable for CWE-90 demonstration!
    cmd = 'sqlite3 "{}" "SELECT * FROM addresses WHERE address LIKE \'%{}%\'"'.format(DB_PATH, query)
    try:
        result = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT, timeout=3)
        result_list = []
        for line in result.decode().splitlines():
            row = line.split('|')
            if len(row) == 2:
                result_list.append((row[0], row[1]))
    except Exception as e:
        flash("Error in search command!")
        result_list = []
    return render_template_string(HTML_PAGE, css=RETRO_CSS, addresses=result_list)

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6011)

