@app.route('/', methods=['GET', 'POST'])
def index():
    conn = get_db()
    if request.method == 'POST':
        title = request.form['title'][:50]
        body = request.form['body'][:200]
        conn.execute('INSERT INTO posts(title, body) VALUES (?, ?)', (title, body))
        conn.commit()
        flash("Content added!")
        return redirect(url_for('index'))
    posts = conn.execute('SELECT title, body FROM posts ORDER BY id DESC').fetchall()
    conn.close()
    return render_template_string(INDEX_HTML, posts=posts)

# VULNERABLE FUNCTION - CWE-90 (LDAP Injection)
@app.route('/preview')
def preview():
    # Simulate a channel preview querying entertainment 'channel' in 'LDAP'
    channel_name = request.args.get('channel', 'Entertainment')
    # Here, direct user input is crafted into an ldapsearch command unsafely =>
    # This is the CWE-90 LDAP Injection: vulnerable code
    # For simplicity, we use subprocess and mock by searching for a string in db file
    base_cmd = f"ldapsearch -x -b 'ou={channel_name},dc=funzone,dc=org' '(objectClass=*)'"
    # For demonstration, we run the injected command, letting users insert command
    try:
        # This is the actual vulnerability: input concatenated into shell command
        result = subprocess.check_output(
            f"echo Simulating: {base_cmd}",
            shell=True,
            stderr=subprocess.STDOUT,
            timeout=2
        )
        # Attempt to mimic extracting user content for the preview
        simulated = subprocess.check_output(
            f"grep '{channel_name}' {DATABASE} || echo 'No entries found.'",
            shell=True,
            stderr=subprocess.STDOUT,
            timeout=2
        )
        simulated = simulated.decode(errors='replace').strip()
    except Exception as e:
        simulated = f'Error running preview: {e}'
    service_status = result.decode(errors='replace').strip() + "\n\n" + simulated
    return render_template_string(PREVIEW_HTML, channel_name=channel_name, service_status=service_status)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6011)

