    # CWE-91: Untrusted data used in SQL command with string formatting in the ORDER BY clause (SQL injection possible via orderby)
    query = f'SELECT username, activity FROM users ORDER BY {orderby} LIMIT 20'
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    try:
        c.execute(query)
        users = c.fetchall()
    except Exception as e:
        users = []
    finally:
        conn.close()
    return render_template_string(LEADERBOARD_TEMPLATE, users=users)

@app.route("/add", methods=["POST"])
def add():
    username = request.form.get("username", "")
    activity = request.form.get("activity", "0")
    if not username or len(username) > 25:
        return redirect(url_for('leaderboard'))
    try:
        activity = int(activity)
    except:
        return redirect(url_for('leaderboard'))
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("INSERT INTO users (username, activity) VALUES (?, ?)", (username, activity))
    conn.commit()
    conn.close()
    return redirect(url_for('leaderboard'))

if __name__ == "__main__":
    if not os.path.isfile(DB_NAME):
        init_db()
