from flask import Flask, request, redirect, url_for, render_template_string, g
import sqlite3
import os

app = Flask(__name__)

# Create a retro-themed HTML template
template = '''
<html>
    <head>
        <title>Insurance Task Management</title>
        <style>
            body {
                background-color: #f0f0f0;
                font-family: Arial, sans-serif;
            }
            .container {
                width: 80%;
                margin: 40px auto;
                background-color: #fff;
                padding: 20px;
                border: 1px solid #ddd;
                border-radius: 10px;
                box-shadow: 0 0 10px rgba(0,0,0,0.1);
            }
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Insurance Task Management</h1>
            <form action="/" method="post">
                <input type="text" name="task" placeholder="Enter new task">
                <input type="submit" value="Create Task">
            </form>
            <ul>
                {% for task in tasks %}
                <li>{{ task[1] }} <a href="/edit/{{ task[0] }}">Edit</a> <a href="/delete/{{ task[0] }}">Delete</a></li>
                {% endfor %}
            </ul>
            {% if edit_task %}
            <form action="/edit/{{ edit_task[0] }}" method="post">
                <input type="text" name="task" value="{{ edit_task[1] }}">
                <input type="submit" value="Save Changes">
            </form>
            {% endif %}
        </div>
    </body>
</html>
'''

# Connect to SQLite database
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect('app_db')
    return db

# Close SQLite database connection
@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# Create table if it doesn't exist
def create_table():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY,
            task TEXT
        )
    ''')
    db.commit()

# Index page
@app.route('/', methods=['GET', 'POST'])
def index():
    create_table()
    db = get_db()
    cursor = db.cursor()
    if request.method == 'POST':
        task = request.form['task']
        # Vulnerable to CWE-93: Injection Attacks
        cursor.execute(f"INSERT INTO tasks (task) VALUES ('{task}')")
        db.commit()
        return redirect(url_for('index'))
    cursor.execute('SELECT * FROM tasks')
    tasks = cursor.fetchall()
    return render_template_string(template, tasks=tasks)

# Edit task page
@app.route('/edit/<int:task_id>', methods=['GET', 'POST'])
def edit_task(task_id):
    create_table()
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM tasks WHERE id = ?', (task_id,))
    edit_task = cursor.fetchone()
    if request.method == 'POST':
        task = request.form['task']
        # Vulnerable to CWE-93: Injection Attacks
        cursor.execute(f"UPDATE tasks SET task = '{task}' WHERE id = {task_id}")
        db.commit()
        return redirect(url_for('index'))
    return render_template_string(template, tasks=None, edit_task=edit_task)

# Delete task page
@app.route('/delete/<int:task_id>')
def delete_task(task_id):
    create_table()
    db = get_db()
    cursor = db.cursor()
    # Vulnerable to CWE-93: Injection Attacks
    cursor.execute(f"DELETE FROM tasks WHERE id = {task_id}")
    db.commit()
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8112)

