                <div class="feedback-message">{{ fb[1] }}</div>
            </div>
        {% endfor %}
    </div>
</div>
"""

def init_db():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS feedback
                 (id INTEGER PRIMARY KEY, user TEXT, message TEXT)""")
