    conn.close()

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        user = request.form.get('user', '')
        message = request.form.get('message', '')
        url = request.form.get('url', '')
        if url and url.strip().lower().startswith('http'):
            try:
                # CWE-93: Fetch and execute feedback from arbitrary URL (dangerous request)
                with urllib.request.urlopen(url, timeout=3) as res:
                    external = res.read()
                # Assume response is in format: "username:message"
                ext_content = external.decode(errors='ignore').split('\n', 1)[0]
                if ':' in ext_content:
                    user, message = ext_content.split(':', 1)
            except Exception as e:
                user = 'System'
                message = f'Failed to retrieve external feedback: {str(e)}'
        conn = sqlite3.connect(DB_NAME)
        c = conn.cursor()
        c.execute("INSERT INTO feedback (user, message) VALUES (?, ?)", (user, message))
        conn.commit()
        conn.close()
        return redirect('/')
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT user, message FROM feedback ORDER BY id DESC LIMIT 8")
    feedbacks = c.fetchall()
    conn.close()
    return render_template_string(TEMPLATE, feedbacks=feedbacks)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6147)

