        db.close()

def setup_db():
    db = sqlite3.connect(DATABASE)
    cur = db.cursor()
    cur.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, email TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS servers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, ip TEXT)")
    # Populate data if empty
    if cur.execute("SELECT COUNT(*) FROM users").fetchone()[0] == 0:
        cur.executemany("INSERT INTO users (username, email) VALUES (?, ?)", [
            ('alice', 'alice@techedge.io'),
            ('bob', 'bob@techedge.io'),
            ('carol', 'carol@techedge.io')
        ])
    if cur.execute("SELECT COUNT(*) FROM servers").fetchone()[0] == 0:
        cur.executemany("INSERT INTO servers (name, ip) VALUES (?, ?)", [
            ('prod-app', '10.0.12.8'),
            ('vpn-gateway', '10.0.12.101'),
        ])
    db.commit()
    db.close()

