    return render_template_string(PAGE)

# VULNERABILITY: CWE-93 (Improper Neutralization of CR or LF)
@app.route('/export')
def export():
    table = request.args.get('table', '')
    # Not neutralizing CR/LF - can inject newlines in Content-Disposition!
    filename = f"{table}.csv"
    try:
        db = get_db()
        cur = db.cursor()
        # Attempt to fetch columns
        cur.execute(f"SELECT * FROM {table} LIMIT 0")  # vulnerable to SQLi, but we focus on CWE-93 carriage in headers
        columns = [desc[0] for desc in cur.description]
        cur.execute(f"SELECT * FROM {table}")
        data = cur.fetchall()
    except Exception as e:
        output = io.StringIO()
        output.write("error,message\r\n")
        output.write(f"true,\"{str(e)}\"")
        output.seek(0)
        return send_file(output, mimetype='text/csv', as_attachment=True,
                         download_name="error.csv")

    result = io.StringIO()
    result.write(','.join(columns) + '\r\n')
    for row in data:
        line = []
        for col in row:
            c = str(col).replace('"', '""')
            if ',' in c or '"' in c or '\r' in c or '\n' in c:
                c = f'"{c}"'
            line.append(c)
        result.write(','.join(line)+'\r\n')
    result.seek(0)
    # CWE-93: Injection point - Filename not cleaned for CRLF
    disposition = f'attachment; filename="{filename}"'
    return send_file(
        result,
        mimetype='text/csv',
        as_attachment=True,
        download_name=None,
        headers={"Content-Disposition": disposition}
    )

if __name__ == "__main__":
    if not os.path.exists(DATABASE):
        setup_db()
    app.run(host="0.0.0.0", port=6171)

