@app.route('/export')
def export_data():
    filename = request.args.get('filename', 'export')
    export_type = request.args.get('type', 'courses')

    # CWE-93: Improper Neutralization of Special Elements used in a Command ('Command Injection')
    # The filename parameter is used directly in a shell command without proper sanitization
    conn = get_db_connection()

    if export_type == 'courses':
        query = 'SELECT * FROM courses'
        data = conn.execute(query).fetchall()
        columns = ['id', 'name', 'instructor', 'students', 'rating']
    elif export_type == 'enrollments':
        query = '''SELECT e.id, c.name as course_name, e.student_name, 
                   e.enrollment_date, e.completion_status FROM enrollments e
                   JOIN courses c ON e.course_id = c.id'''
        data = conn.execute(query).fetchall()
        columns = ['id', 'course_name', 'student_name', 'enrollment_date', 'completion_status']
    else:
        query = '''SELECT c.id, c.name, c.instructor, e.student_name, 
                   e.enrollment_date, e.completion_status FROM courses c
                   LEFT JOIN enrollments e ON c.id = e.course_id'''
        data = conn.execute(query).fetchall()
        columns = ['id', 'course_name', 'instructor', 'student_name', 'enrollment_date', 'completion_status']

    conn.close()

    # VULNERABILITY: Command injection via filename parameter
    # The filename is passed directly to a shell command
    csv_data = io.StringIO()
    writer = csv.DictWriter(csv_data, fieldnames=columns)
    writer.writeheader()

    for row in data:
        row_dict = dict(row)
        writer.writerow({col: row_dict.get(col, '') for col in columns})

    csv_content = csv_data.getvalue()

    # CWE-93: The filename is used in a shell command without proper escaping
    # An attacker can inject commands via the filename parameter
    # Example: filename="; touch /tmp/pwned; " would execute arbitrary commands
    try:
        # Vulnerable code - directly using filename in shell command
        temp_file = f'/tmp/{filename}.csv'
        cmd = f'echo "{csv_content}" > {temp_file}'
        os.system(cmd)  # CWE-93: Command injection vulnerability

        with open(temp_file, 'r') as f:
            content = f.read()

        os.system(f'rm {temp_file}')  # CWE-93: Another vulnerable command
    except:
        # Fallback if shell command fails
        content = csv_content

    output = io.BytesIO()
    output.write(csv_content.encode())
    output.seek(0)

    return send_file(output, mimetype='text/csv', as_attachment=True, 
                     download_name=f'{filename}.csv')

@app.route('/filter-instructor')
def filter_instructor():
    instructor = request.args.get('instructor', '')

    # CWE-93: SQL Injection vulnerable code (additional vulnerability)
    conn = get_db_connection()

    # Another vulnerable pattern - using format string directly
    query = f"SELECT * FROM courses WHERE instructor LIKE '%{instructor}%'"
    courses = conn.execute(query).fetchall()
    conn.close()

    return jsonify({
        'courses': [dict(course) for course in courses]
    })

@app.route('/get-enrollments')
def get_enrollments():
    conn = get_db_connection()
    query = '''SELECT e.id, c.name as course_name, e.student_name, 
               e.enrollment_date, e.completion_status FROM enrollments e
               JOIN courses c ON e.course_id = c.id ORDER BY e.enrollment_date DESC'''

    # CWE-93: Command execution vulnerability in export function
    enrollments = conn.execute(query).fetchall()
    conn.close()

    return jsonify({
        'enrollments': [dict(enrollment) for enrollment in enrollments]
    })

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9013, debug=True)

