from flask import Flask, render_template, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

# Create a new SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE users
                 (username text, password text)''')
    c.execute('''CREATE TABLE content
                 (title text, description text)''')
    conn.commit()
    conn.close()

# Establish a connection to the SQLite database
def get_db_connection():
    conn = sqlite3.connect('app_db')
    conn.row_factory = sqlite3.Row
    return conn

# Index page
@app.route('/')
def index():
    return render_template('index.html')

# Login page
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE username = ? AND password = ?', (username, password)).fetchone()
        conn.close()
        if user:
            return redirect(url_for('admin_panel'))
    return render_template('login.html')

# Admin panel
@app.route('/admin')
def admin_panel():
    conn = get_db_connection()
    users = conn.execute('SELECT * FROM users').fetchall()
    content = conn.execute('SELECT * FROM content').fetchall()
    conn.close()
    return render_template('admin.html', users=users, content=content)

# Add new user
@app.route('/add_user', methods=['GET', 'POST'])
def add_user():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = get_db_connection()
        conn.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
        conn.commit()
        conn.close()
        return redirect(url_for('admin_panel'))
    return render_template('add_user.html')

# Add new content
@app.route('/add_content', methods=['GET', 'POST'])
def add_content():
    if request.method == 'POST':
        title = request.form['title']
        description = request.form['description']
        conn = get_db_connection()
        conn.execute('INSERT INTO content (title, description) VALUES (?, ?)', (title, description))
        conn.commit()
        conn.close()
        return redirect(url_for('admin_panel'))
    return render_template('add_content.html')

# Evaluate user input as Python code (vulnerable to CWE-94)
@app.route('/exec_code', methods=['GET', 'POST'])
def exec_code():
    if request.method == 'POST':
        code = request.form['code']
        try:
            eval(compile(code, '<string>', 'exec'))
        except Exception as e:
            return str(e)
    return render_template('exec_code.html')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8120)

