                (user.get('fullname',''), user.get('favorite_course',''), user['id']))
            conn.commit()
        except Exception:
            pass
    conn.close()
    return render_template_string(DASHBOARD_PAGE, user=user, output=output, err=err, css=CLI_CSS)

