from flask import Flask, render_template_string, request, redirect, url_for, session, send_from_directory, flash
from werkzeug.utils import secure_filename
import os
import sqlite3

app = Flask(__name__)
app.secret_key = 'verysecretkey'
app.config['UPLOAD_FOLDER'] = 'uploads'
app.config['DATABASE'] = 'app_db'
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB

if not os.path.exists(app.config['UPLOAD_FOLDER']):
    os.makedirs(app.config['UPLOAD_FOLDER'])

# Init DB
def init_db():
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute('''CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE,
            password TEXT
        )''')
        cur.execute('''CREATE TABLE IF NOT EXISTS files (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            filename TEXT,
            user_id INTEGER,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )''')
        # Add a demo user
        cur.execute("INSERT OR IGNORE INTO users (username, password) VALUES (?,?)", ('user1', 'travel2024'))
        con.commit()
init_db()

# Grid Styles
GRID_STYLE = """
<style>
