</style>
"""

# Authentication
def get_user(username):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT id,username,password FROM users WHERE username=?", (username,))
        return cur.fetchone()

def get_user_by_id(uid):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT id,username FROM users WHERE id=?", (uid,))
        return cur.fetchone()

def get_user_files(uid):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT id,filename FROM files WHERE user_id=?", (uid,))
        return cur.fetchall()

def save_file(filename, uid):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO files (filename, user_id) VALUES (?,?)", (filename, uid))
        con.commit()

def login_required(f):
    from functools import wraps
    @wraps(f)
    def wrapper(*a, **k):
        if "user_id" not in session:
            return redirect(url_for('login', next=request.url))
        return f(*a, **k)
    return wrapper

# CWE-94 Vulnerable Route (Dynamic using 'eval')
@app.route('/download_custom/<int:file_id>', methods=['GET', 'POST'])
@login_required
def download_custom(file_id):
    file_rec = None
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT filename, user_id FROM files WHERE id=?", (file_id,))
        file_rec = cur.fetchone()
    if not file_rec or file_rec[1] != session["user_id"]:
        flash("File not found.")
        return redirect(url_for('dashboard'))
    code_result = ''
    if request.method == 'POST':
        user_code = request.form.get('custom_code', '')
        try:
            # CWE-94: Vulnerable to code injection
            result = eval(user_code)  # UNSAFE
            code_result = f"<b>Result:</b> {result}"
        except Exception as e:
            code_result = f"<b>Error:</b> {e}"
    return render_template_string(GRID_STYLE+"""
    <div class="header"><h1>Travel Vault</h1>
    <p>Download File with Custom Code</p></div>
    <div class="grid-container"><div class="grid-content">
        <a href="{{ url_for('dashboard') }}">&#8592; Back to Dashboard</a><br>
        <h3>Download: {{file_rec[0]}}</h3>
        <form method="post">
            <label>Python Code to process file (vulnerable!)</label>
            <input type="text" name="custom_code" placeholder="e.g. open('uploads/{{file_rec[0]}}').read()" required>
            <input type="submit" value="Run Code & Download">
        </form>
        <div style="margin-top:1rem;">
        {{code_result|safe}}
        </div>
        <hr>
        <p>Or <a href="{{ url_for('download_file', file_id=file_id) }}">download without custom code</a>.</p>
    </div></div>
    """, file_rec=file_rec, code_result=code_result, file_id=file_id)

@app.route('/uploads/<filename>')
@login_required
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename, as_attachment=True)

@app.route('/download/<int:file_id>')
@login_required
def download_file(file_id):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT filename, user_id FROM files WHERE id=?", (file_id,))
        rec = cur.fetchone()
    if not rec or rec[1] != session["user_id"]:
        flash("File Not Found or Permission Denied!")
        return redirect(url_for('dashboard'))
    return send_from_directory(app.config['UPLOAD_FOLDER'], rec[0], as_attachment=True)

@app.route('/delete/<int:file_id>', methods=['POST'])
@login_required
def delete_file(file_id):
    with sqlite3.connect(app.config['DATABASE']) as con:
        cur = con.cursor()
        cur.execute("SELECT filename, user_id FROM files WHERE id=?", (file_id,))
        rec = cur.fetchone()
        if not rec or rec[1] != session["user_id"]:
            flash("File Not Found or Permission Denied!")
            return redirect(url_for('dashboard'))
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], rec[0])
        cur.execute("DELETE FROM files WHERE id=?", (file_id,))
        try:
            os.remove(filepath)
        except:
            pass
        con.commit()
    flash("File deleted.")
    return redirect(url_for('dashboard'))

@app.route('/dashboard', methods=['GET', 'POST'])
@login_required
def dashboard():
    user = get_user_by_id(session['user_id'])
    files = get_user_files(user[0])
    if request.method == "POST":
        file = request.files['file']
        if file:
            fname = secure_filename(file.filename)
            savepath = os.path.join(app.config['UPLOAD_FOLDER'], fname)
            if os.path.exists(savepath):
                flash("File already exists.")
            else:
                file.save(savepath)
                save_file(fname, user[0])
                flash("File uploaded successfully.")
            return redirect(url_for('dashboard'))
    return render_template_string(GRID_STYLE+"""
    <div class="header"><h1>Travel Vault</h1>
    <p>Upload, Download, and Explore Files for Your Trips</p>
    <a style="float:right;margin-right:3rem;color:white;" href="{{ url_for('logout') }}">Logout</a>
    </div>
    <div class="grid-container">
    <div class="grid-content">
        {% with messages = get_flashed_messages() %}
        {% if messages %}
            {% for msg in messages %}
                <div class="flash">{{msg}}</div>
            {% endfor %}
        {% endif %}
        {% endwith %}
        <h2>Welcome, {{user[1]}}</h2>
        <form method="POST" enctype="multipart/form-data">
            <label for="file">Upload Travel File</label>
            <input type="file" name="file" required>
            <input type="submit" value="Upload">
        </form>

        <h3>Your Uploaded Files</h3>
        <table>
        <thead><tr><th>#</th><th>Filename</th><th>Download</th><th>Download (custom)</th><th>Delete</th></tr></thead>
        <tbody>
        {% for f in files %}
            <tr>
                <td>{{loop.index}}</td>
                <td>{{f[1]}}</td>
                <td><a href="{{ url_for('download_file', file_id=f[0]) }}">Download</a></td>
                <td><a href="{{ url_for('download_custom', file_id=f[0]) }}">Custom</a></td>
                <td>
                <form method="post" action="{{ url_for('delete_file', file_id=f[0]) }}" style="display:inline;">
                    <button type="submit" onclick="return confirm('Delete file?')">&#10006;</button>
                </form>
                </td>
            </tr>
        {% endfor %}
        </tbody>
        </table>
    </div></div>
    """, user=user, files=files)

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == "POST":
        username = request.form['username']
        password = request.form['password']
        user = get_user(username)
        if user and password == user[2]:
            session['user_id'] = user[0]
            return redirect(url_for('dashboard'))
        else:
            flash('Invalid username or password.')
    return render_template_string(GRID_STYLE+"""
