@app.route('/', methods=['GET'])
def index():
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute('SELECT * FROM images ORDER BY id DESC')
    images = c.fetchall()
    conn.close()
    return render_template_string(PORTFOLIO_TEMPLATE, images=images)

@app.route('/upload', methods=['POST'])
def upload():
    if 'file' not in request.files:
        flash('No file part')
        return redirect(url_for('index'))
    file = request.files['file']
    desc = request.form.get('desc', '')
    if file.filename == '':
        flash('No selected file')
        return redirect(url_for('index'))
    filename = file.filename
    savepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    i = 1
    orig = filename
    while os.path.exists(savepath):
        root, ext = os.path.splitext(orig)
        filename = f"{root}_{i}{ext}"
        savepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        i += 1
    file.save(savepath)
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute('INSERT INTO images (filename, description) VALUES (?, ?)', (filename, desc))
    conn.commit()
    conn.close()
    flash('Image uploaded successfully.')
    return redirect(url_for('index'))

@app.route('/delete/<int:image_id>', methods=['POST'])
def delete_image(image_id):
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute('SELECT filename FROM images WHERE id=?', (image_id,))
    row = c.fetchone()
    if row:
        filename = row[0]
        img_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        if os.path.exists(img_path):
            os.remove(img_path)
        c.execute('DELETE FROM images WHERE id=?', (image_id,))
        conn.commit()
    conn.close()
    return redirect(url_for('index'))

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/console', methods=['POST'])
def console():
    # CWE-94: Dangerous use of eval on user input
    conn = sqlite3.connect(DB_FILE)
    c = conn.cursor()
    c.execute('SELECT * FROM images')
    images = c.fetchall()
    conn.close()
    code = request.form.get('code', '')
    try:
        result = eval(code)  # CWE-94: Unrestricted Code Execution
    except Exception as e:
        result = f'Error: {str(e)}'
    return render_template_string(PORTFOLIO_TEMPLATE, images=images, console_result=result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6186, debug=False)

from flask import Flask, request, render_template_string, redirect, url_for
import sqlite3
import os

app = Flask(__name__)
DB_NAME = 'app_db.db'

if not os.path.exists(DB_NAME):
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE tickets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            email TEXT,
            issue TEXT
        )
    ''')
    conn.commit()
    conn.close()

RETRO_CSS = """
body {
    background: #ffe4b5;
    font-family: 'Courier New', Courier, monospace;
    color: #2a2928;
    max-width: 800px;
    margin: 40px auto;
