    border: 5px double #b76e1b;
    padding: 25px;
}

h1, h2 {
    color: #b76e1b;
    letter-spacing: 1.2px;
    text-shadow: 2px 2px #fff0c2;
}

input, textarea, button {
    font-family: inherit;
    background: #fffdee;
    border: 2px solid #b76e1b;
