    font-weight: bold;
    color: #805b23;
}

.ticket {
    border: 2px dotted #888442;
    background: #fff9de;
    margin: 12px 0;
    padding: 10px;
    border-radius: 7px;
}
"""

TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>RetroFinance - Support Tickets</title>
    <style>{{ style }}</style>
</head>
<body>
    <h1>RetroFinance Support Desk</h1>
    <h2>Submit a Support Ticket</h2>
    <form method="POST" action="{{ url_for('submit_ticket') }}">
        <label for="name">Name</label><br>
        <input name="name" type="text" required><br>
        <label for="email">Email</label><br>
        <input name="email" type="email" required><br>
        <label for="issue">Describe your issue:</label><br>
        <textarea name="issue" rows="5" required></textarea><br>
        <button type="submit">Submit Ticket</button>
    </form>
    <br>
    <h2>Ticket Search</h2>
    <form method="POST" action="{{ url_for('search_tickets') }}">
        <label for="filter_code">Filter Tickets (Python code):</label><br>
        <textarea name="filter_code" placeholder="e.g. t['email'].endswith('.com')" rows="3"></textarea><br>
        <button type="submit">Apply Filter</button>
    </form>
    {% if tickets is not none %}
    <h2>Tickets</h2>
        {% for t in tickets %}
        <div class="ticket">
            <b>Name:</b> {{ t['name'] }}<br>
            <b>Email:</b> {{ t['email'] }}<br>
            <b>Issue:</b> {{ t['issue']|e }}
        </div>
        {% endfor %}
    {% endif %}
</body>
</html>
"""

def get_tickets():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM tickets ORDER BY id DESC")
    rows = c.fetchall()
    tickets = [dict(r) for r in rows]
    conn.close()
    return tickets

@app.route('/', methods=['GET'])
def index():
    tickets = get_tickets()
    return render_template_string(TEMPLATE, tickets=tickets, style=RETRO_CSS)

@app.route('/submit_ticket', methods=['POST'])
def submit_ticket():
    name = request.form.get('name', '')
    email = request.form.get('email', '')
    issue = request.form.get('issue', '')
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("INSERT INTO tickets (name, email, issue) VALUES (?, ?, ?)", (name, email, issue))
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

@app.route('/search_tickets', methods=['POST'])
def search_tickets():
    filter_code = request.form.get('filter_code', '')
    tickets = get_tickets()
    if filter_code.strip():
        # CWE-94: Direct use of user-supplied code in eval/exec
        try:
            # User provides an expression to filter tickets: ex: t['email'].endswith('.com')
            filtered = []
            for t in tickets:
                # 't' is each ticket dict
                if eval(filter_code, {}, {'t': t}): 
                    filtered.append(t)
            tickets = filtered
        except Exception:
            tickets = []
    return render_template_string(TEMPLATE, tickets=tickets, style=RETRO_CSS)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6187)

from flask import Flask, request, redirect, render_template_string, g
import sqlite3
import os

app = Flask(__name__)
DATABASE = 'app_db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS addresses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            address TEXT NOT NULL
        )
    ''')
    conn.commit()
    conn.close()

@app.route('/', methods=['GET', 'POST'])
def index():
    db = get_db()
    message = ''
    if request.method == 'POST':
        address = request.form.get('address', '')
        action = request.form.get('action', '')
        if action == 'save':
            db.execute('INSERT INTO addresses (address) VALUES (?)', (address,))
            db.commit()
            message = 'Address saved.'
        elif action == 'process':
            try:
                # CWE-94: Improper Control of Generation of Code ('Code Injection')
                result = str(eval(address))
                message = f"Result: {result}"
            except Exception as e:
                message = f"Error: {e}"
    cursor = db.execute('SELECT address FROM addresses')
    all_addresses = [row[0] for row in cursor.fetchall()]

    return render_template_string('''
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <title>Legal Service Delivery Address Form</title>
        <style>
            body {
                background: #111;
                color: #fff;
