                width:96%;
                font-size:1.2em;
                background:#fff;
                color:#111;
                border:2px solid #fc0;
                border-radius:4px;
                padding:.5em;
                margin-bottom:1em;
            }
            .btn {
                background: #fc0;
                color: #000;
                font-weight:bold;
                border:0; border-radius:4px;
                padding:0.8em 1.8em;
                cursor:pointer;
                font-size:1em;
                margin-right:10px;
            }
            .btn:hover { background:#ff4444; color:#fff; }
            .message {
                margin:18px 0 0 0;
                color:#ff3333;
                font-size:1.1em;
