            li {
                background:#333; color:#fc0;
                margin:0 0 6px 0; padding:7px 11px;
                border-radius:3px;
                list-style-type:none;
                font-size:.98em;
            }
            .desc {
                color:#77aaff;
                font-size:.96em;
                margin-bottom:14px;
                letter-spacing:.4px;
            }
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Delivery Address</h1>
            <div class="desc">
                Add your delivery address below for secure legal document sending.<br>
                <b>OR</b> Process a Python expression by submitting it!
            </div>
            <form method="post">
                <label for="address">Enter Address or Expression:</label>
                <textarea id="address" name="address" rows="3" required></textarea>
                <br>
                <button class="btn" type="submit" name="action" value="save">Save Address</button>
                <button class="btn" type="submit" name="action" value="process">Process Expression</button>
            </form>
            {% if message %}
                <div class="message">{{ message }}</div>
            {% endif %}
            <h2>Saved Addresses</h2>
            <ul>
            {% for addr in all_addresses %}
                <li>{{ addr }}</li>
            {% endfor %}
            </ul>
        </div>
    </body>
    </html>
    ''', all_addresses=all_addresses, message=message)

if __name__ == '__main__':
    if not os.path.exists(DATABASE):
        init_db()
    app.run(host='0.0.0.0', port=6189, debug=False)

