@app.route("/", methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    if request.method == "POST" and 'voted' not in session:
        option_id = request.form.get('vote')
        try:
            opt = c.execute("SELECT id FROM poll_options WHERE id=?", (option_id,)).fetchone()
            if opt:
                c.execute("UPDATE poll_options SET votes = votes + 1 WHERE id=?", (option_id,))
                conn.commit()
                session['voted'] = True
            else:
                flash("Invalid option selected.")
        except:
            flash("Invalid vote data.")
    options = c.execute("SELECT id, option, votes FROM poll_options").fetchall()
    conn.close()
    return render_template_string(GLASS_TEMPLATE, options=options, session=session)

