TEMPLATE = """
<!doctype html>
<html lang="en">
  <head>
    <title>Banking Blog - Newsletter</title>
    <style>
      body { font-family: Arial, sans-serif; max-width: 700px; margin: auto; background: #f8f8f8; }
      h1 { color: #27577D; }
      .newsletter { padding: 24px; background: #fff; border-radius: 12px; box-shadow: 0 0 12px #b0b0cf44; margin-top:32px;}
      input[type=email], input[type=text], input[type=submit] { font-size: 1.07em; margin: 8px 0 20px 0; width: 100%; padding: 8px;}
      form { margin-bottom: 32px;}
      .msg { color:#117E18; padding-bottom:10px;}
      .error { color: #D40422; }
      .codebox {background:#eee; font-family:monospace; padding:5px 10px;}
      .footer {text-align:center; color:#aaa; margin:34px;}
    </style>
  </head>
  <body>
    <h1>Welcome to Secure Bank's Insights Blog</h1>
    <div class="newsletter">
      <h2>Join Our Newsletter</h2>
      {% with messages = get_flashed_messages(with_categories=true) %}
        {% for category, message in messages %}
          <div class="{{category}} msg">{{message}}</div>
        {% endfor %}
      {% endwith %}
      <form action="{{ url_for('signup') }}" method="post">
        <label>Email to sign up:</label>
        <input type="email" required name="email" placeholder="your@email.com" />
        <label>First name:</label>
        <input type="text" required name="fname" placeholder="First Name" />
        <input type="submit" value="Sign Up" />
      </form>

      <h3>Unsubscribe from Newsletter</h3>
      <form action="{{ url_for('unsubscribe') }}" method="post">
