        <input type="email" required name="email" placeholder="your@email.com" />
        <input type="submit" value="Unsubscribe" />
      </form>

      <h4>Subscriber Lookup (for Admins)</h4>
      <form method="post" action="{{ url_for('lookup') }}">
        <label>Enter subscriber email or leave empty to see all:</label>
        <input type="text" name="query" placeholder="any Python code allowed here" />
        <input type="submit" value="Lookup" />
      </form>
      {% if result %}
        <div>
          <b>Results:</b>
          <div class="codebox">{{result|safe}}</div>
        </div>
      {% endif %}
    </div>
    <div class="footer">
      &copy; 2024 Secure Bank Blog
    </div>
  </body>
</html>
"""

def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS subscribers (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        email TEXT UNIQUE NOT NULL,
                        fname TEXT NOT NULL
                    )''')
        conn.commit()
        conn.close()

@app.route('/', methods=['GET'])
def index():
    return render_template_string(TEMPLATE, result=None)

@app.route('/signup', methods=['POST'])
def signup():
    email = request.form.get('email', '').strip()
    fname = request.form.get('fname', '').strip()
    if not email or not fname:
        flash('Email and Name are required.', 'error')
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    try:
        c.execute('INSERT INTO subscribers (email, fname) VALUES (?, ?)', (email, fname))
        conn.commit()
        flash('Signed up for the newsletter successfully!', 'success')
    except sqlite3.IntegrityError:
        flash('This email is already subscribed.', 'error')
    finally:
        conn.close()
    return redirect(url_for('index'))

@app.route('/unsubscribe', methods=['POST'])
def unsubscribe():
    email = request.form.get('email', '').strip()
    if not email:
        flash('Email is required.', 'error')
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('DELETE FROM subscribers WHERE email=?', (email,))
    if c.rowcount > 0:
        flash('You have been unsubscribed.', 'success')
    else:
        flash('Email not found.', 'error')
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

@app.route('/lookup', methods=['POST'])
def lookup():
    query = request.form.get('query', '')
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    result = ''
    # CWE-94 vulnerability: direct usage of input in eval()
    try:
        # The vuln: allows arbitrary Python code execution!
        data = eval(f"""c.execute('SELECT email, fname FROM subscribers').fetchall() {query}""")
        if not data:
            result = 'No matching subscribers found.'
        else:
            if isinstance(data, list):
                result = '<br>'.join([f'{row[0]} ({row[1]})' for row in data])
            else:
                result = str(data)
    except Exception as e:
        result = f'Error: {e}'
    finally:
        conn.close()
    return render_template_string(TEMPLATE, result=result)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6192, debug=False)

