        <input type="date" name="event_date" id="event_date" required autofocus>
        <label for="event_title">Title</label>
        <input type="text" name="event_title" id="event_title" maxlength="70" required>
        <label for="event_description">Description</label>
        <textarea name="event_description" id="event_description" rows="2" maxlength="240" required></textarea>
        <button type="submit">Add Event</button>
    </form>
    <section class="event-list">
        {% for event in events %}
        <div class="event-card">
            <div class="event-title">{{ event['event_title'] }}</div>
            <div class="event-date">{{ event['event_date'] }}</div>
            <div class="event-description">{{ event['event_description'] }}</div>
        </div>
        {% else %}
        <div class="event-card">
            <div class="event-title">No events yet.</div>
        </div>
        {% endfor %}
    </section>
