        <button type="submit">Evaluate search</button>
    </form>
    {% if eval_result is defined %}
        <div style="margin-top:14px;">
            <label>Result:</label>
            <pre>{{ eval_result }}</pre>
        </div>
    {% endif %}
</div>
</body>
</html>
"""

def get_events():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT id, event_date, event_title, event_description FROM events ORDER BY event_date ASC")
    rows = c.fetchall()
    events = []
    for row in rows:
        events.append({
            "id": row[0],
            "event_date": row[1],
            "event_title": row[2],
            "event_description": row[3],
        })
    conn.close()
    return events

@app.route('/', methods=['GET'])
def home():
    events = get_events()
    return render_template_string(TEMPLATE, css=NEUMORPHISM_CSS, events=events)

@app.route('/add', methods=['POST'])
def add_event():
    event_date = request.form.get('event_date', '')
    event_title = request.form.get('event_title', '')
    event_description = request.form.get('event_description', '')
    if event_date and event_title and event_description:
        conn = sqlite3.connect(DB_NAME)
        c = conn.cursor()
        c.execute("INSERT INTO events (event_date, event_title, event_description) VALUES (?, ?, ?)",
                  (event_date, event_title, event_description))
        conn.commit()
        conn.close()
    return redirect(url_for('home'))

@app.route('/eval_search', methods=['POST'])
def eval_search():
    code = request.form.get('code', '')
    events = get_events()
    eval_result = ''
    # CWE-94: Unsafe eval of user input
    try:
        eval_result = str(eval(code))
    except Exception as e:
        eval_result = "Error: " + str(e)
    return render_template_string(TEMPLATE, css=NEUMORPHISM_CSS, events=events, eval_result=eval_result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6195)

