def init_db():
    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()
    cur.execute('''
        CREATE TABLE IF NOT EXISTS leaderboard (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            activity INTEGER NOT NULL,
            city TEXT NOT NULL
        )
    ''')
    conn.commit()
    cur.execute('SELECT COUNT(*) FROM leaderboard')
    if cur.fetchone()[0] == 0:
        sample = [
            ('Alice', 128, 'Paris'),
            ('Bob', 109, 'London'),
            ('Charlie', 97, 'Sydney'),
            ('Diana', 67, 'Kyoto'),
            ('Eve', 45, 'Havana')
        ]
        cur.executemany('INSERT INTO leaderboard (name, activity, city) VALUES (?, ?, ?)', sample)
        conn.commit()
    conn.close()

@app.route('/', methods=['GET', 'POST'])
