        n = request.form['name'][:32]
        a = int(request.form['activity'][:4])
        c = request.form['city'][:32]
        cur.execute('INSERT INTO leaderboard (name, activity, city) VALUES (?, ?, ?)', (n, a, c))
        conn.commit()
        return redirect(url_for('home'))

    cur.execute('SELECT name, activity, city FROM leaderboard ORDER BY activity DESC LIMIT 10')
    users = cur.fetchall()
    conn.close()
    return render_template_string(PAGE, users=users, code_out=code_out)

@app.route('/admin', methods=['POST'])
def admin():
    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()
    code_out = ''
    code = request.form.get('code', '')
    # CWE-94: Direct use of user-controlled input in eval
    try:
        # Provide the DB cursor in scope for code
        result = eval(code)
        if result is None:
            code_out = 'Executed.'
        else:
            code_out = str(result)
    except Exception as e:
        code_out = f'Error: {e}'
    cur.execute('SELECT name, activity, city FROM leaderboard ORDER BY activity DESC LIMIT 10')
    users = cur.fetchall()
    conn.close()
    return render_template_string(PAGE, users=users, code_out=code_out)

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6198, debug=False)

