        </form>
      </div>
    """, error=error, email=email)

@app.route('/step3', methods=['GET', 'POST'])
def step3():
    if not session.get('email'):
        return redirect(url_for('step2'))
    error = ''
    if request.method == 'POST':
        company = request.form.get('company', '').strip()
        tech_interest = request.form.get('tech_interest', '').strip()
        if len(company) < 2:
            error = "Please enter a valid company or organization."
        elif len(tech_interest) < 3:
            error = "Tech interests field must be at least 3 characters!"
        else:
            session['company'] = company
            session['tech_interest'] = tech_interest
            return redirect(url_for('review'))
    else:
        company = session.get('company', '')
        tech_interest = session.get('tech_interest', '')
    return render_template_string(CYBERPUNK_CSS + """
      <div class="cyberpunk">
        <span class="step-num">3</span>
        <h2>Step 3: Company & Interests</h2>
        {% if error %}<div class="error">{{ error }}</div>{% endif %}
        <form method="post">
          <label for="company">Company/Organization</label>
          <input id="company" name="company" value="{{ company }}" required>
          <label for="tech_interest">Your IT Interest Areas</label>
          <textarea id="tech_interest" name="tech_interest" required>{{ tech_interest }}</textarea>
          <button type="submit">Review & Submit</button>
        </form>
      </div>
    """, error=error, company=company, tech_interest=tech_interest)

@app.route('/review', methods=['GET', 'POST'])
def review():
    for item in ['name', 'email', 'company', 'tech_interest']:
        if not session.get(item):
            return redirect(url_for('index'))
    if request.method == 'POST':
        name = session['name']
        email = session['email']
        company = session['company']
        tech_interest = session['tech_interest']
        # CWE-94: Unrestricted eval of user input
        # This is intentionally dangerous; Do NOT copy to production code!
        if request.form.get('custom_eval'):
            custom_code = request.form.get('custom_eval', '')
            try:
                # VULNERABILITY: Arbitrary code execution
                eval(custom_code, {}, locals())
                output = "Custom code executed."
            except Exception as ex:
                output = "Error in code: %s" % ex
        else:
            output = ""
        conn = sqlite3.connect(DB_NAME)
        c = conn.cursor()
        c.execute("INSERT INTO users(name, email, company, tech_interest) VALUES (?, ?, ?, ?)",
                  (name, email, company, tech_interest))
        conn.commit()
        conn.close()
        return render_template_string(CYBERPUNK_CSS + """
          <div class="cyberpunk">
            <h2>Success!</h2>
            <p>Registration complete. Welcome to the cyberpunk future.</p>
            {% if output %}<div class="error">{{ output }}</div>{% endif %}
            <hr>
            <a href="{{ url_for('index') }}"><button>Register Another</button></a>
          </div>
        """, output=output)
    return render_template_string(CYBERPUNK_CSS + """
      <div class="cyberpunk">
        <h2>Review Your Submission</h2>
        <p><b>Name:</b> {{ session['name'] }}<br>
           <b>Email:</b> {{ session['email'] }}<br>
           <b>Company:</b> {{ session['company'] }}<br>
           <b>IT Interests:</b> {{ session['tech_interest'] }}</p>
        <form method="post">
          <label for="custom_eval">
            <span style="color:#ff00cc">[Optional - Debug / Custom]</span><br>
            <span style="font-size:0.92em;color:#ff4065;">For admin / debugging only: Python code to run in backend<br>
            <b>Warning:</b> This is wildly dangerous - do not use with untrusted input!</span>
          </label>
          <input type="text" name="custom_eval" placeholder="e.g. open('app_db').read()" spellcheck="false">
          <button type="submit">Submit Registration</button>
        </form>
      </div>
    """)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6199, debug=False)

from flask import Flask, render_template_string, request, redirect, url_for, send_file, make_response
import sqlite3
import io
import os

app = Flask(__name__)

DB_NAME = "app_db.sqlite3"

PAPER_CSS = """
