    padding: 10px 16px;
    margin-top: 12px;
    cursor: pointer;
}
form {
    background: #f5f3ef;
    padding: 20px;
    margin-bottom: 32px;
    border: 1px solid #ccc;
}
pre {
    background: #ffe;
    padding: 6px;
}
"""

INDEX_HTML = """
<!doctype html>
<html>
  <head>
    <title>E-Commerce Reports</title>
    <style>{{style}}</style>
  </head>
  <body>
    <h1>E-Commerce Reports</h1>
    <div>
      <h2>All Products</h2>
      <table>
        <tr>
          <th>ID</th><th>Name</th><th>Description</th><th>Price</th><th>Stock</th>
        </tr>
        {% for row in products %}
        <tr>
          <td>{{row[0]}}</td>
          <td>{{row[1]}}</td>
          <td>{{row[2]}}</td>
          <td>${{row[3]}}</td>
          <td>{{row[4]}}</td>
        </tr>
        {% endfor %}
      </table>
      <form method="POST" action="{{ url_for('export_csv') }}">
        <h2 style="margin-bottom: 8px;">Export custom report to CSV</h2>
        <label for="fields">Fields (comma separated columns): </label>
        <input type="text" name="fields" value="id, name, price" style="width:300px">
        <br>
        <label for="filter">Filter (Python code, e.g. "row['price'] > 50"): </label><br>
        <input type="text" name="filter" value="" style="width:420px;">
        <br>
        <input type="submit" value="Export CSV" class="btn">
      </form>
      <p style="font-size:14px; color:#777;">
         <b>Example Filter:</b> row['stock'] &lt; 10 <br>
         <b>Fields:</b> id, name, stock
      </p>
      {% if error %}
        <div style="background:#fcc; color:#a00; border:1px solid #a00; padding:8px 14px; margin-top:18px;">
            Error: {{ error }}
        </div>
      {% endif %}
    </div>
  </body>
</html>
"""

def init_db():
    if not os.path.exists(DB_NAME):
        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()
        cur.execute("""
        CREATE TABLE products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            price REAL,
            stock INTEGER
        )
        """)
        products = [
            ("Paper Notebook", "A ruled notebook.", 6.5, 115),
            ("Desk Pen", "Black ink ballpoint.", 1.8, 544),
            ("Graph Paper Pad", "Grid paper pad for sketches.", 5.0, 49),
            ("Fountain Pen", "Elegant writing.", 24.95, 12),
            ("Printer Paper 500pk", "Letter size.", 9.99, 300),
            ("Color Markers (set)", "8 brilliant colors.", 7.75, 61),
        ]
        cur.executemany("INSERT INTO products (name, description, price, stock) VALUES (?, ?, ?, ?)", products)
        conn.commit()
        conn.close()

@app.route('/', methods=['GET'])
def index():
    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()
    products = list(cur.execute("SELECT id, name, description, price, stock FROM products"))
    conn.close()
    return render_template_string(INDEX_HTML, style=PAPER_CSS, products=products, error=None)

@app.route('/export', methods=['POST'])
def export_csv():
    fields = request.form.get("fields", "id, name, price")
    fields_list = [f.strip() for f in fields.split(",") if f.strip()]

    filter_code = request.form.get("filter", "").strip()

    # Build SQL statement -- safely use only whitelisted columns
    valid_cols = {"id", "name", "description", "price", "stock"}
    if not all(col in valid_cols for col in fields_list):
        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()
        products = list(cur.execute("SELECT id, name, description, price, stock FROM products"))
        conn.close()
        return render_template_string(
            INDEX_HTML, style=PAPER_CSS, products=products,
            error="Invalid column specified in fields."
        )

    sql = f"SELECT {', '.join(fields_list)} FROM products"

    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    rows = list(cur.execute(sql))
    conn.close()

    filtered_rows = []

    # CWE-94: Code Injection Vulnerability (eval of user filter code)
    if filter_code:
        for row in rows:
            row_dict = dict(row)
            try:
                # Directly evaluating user-supplied code
                if eval(filter_code, {'row': row_dict}):
                    filtered_rows.append(row)
            except Exception:
                continue
    else:
        filtered_rows = rows

    output = io.StringIO()
    # Write header
    output.write(",".join(fields_list) + "\n")
    for row in filtered_rows:
        vals = [str(row[f]) for f in fields_list]
        output.write(",".join(vals) + "\n")

    resp = make_response(output.getvalue())
    resp.headers['Content-Disposition'] = 'attachment; filename=report.csv'
    resp.headers['Content-type'] = 'text/csv'
    return resp

if __name__ == "__main__":
    init_db()
    app.run(host='0.0.0.0', port=6200)

from flask import Flask, render_template_string, request, redirect, session, url_for, g
import sqlite3
import os

app = Flask(__name__)
app.secret_key = 'supersecretkey'
DATABASE = 'app_db'

if not os.path.exists(DATABASE):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password TEXT)''')
    c.execute('''CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, sender TEXT, receiver TEXT, body TEXT)''')
    conn.commit()
    conn.close()

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/')
def index():
    if 'user' in session:
        return redirect(url_for('inbox'))
    return render_template_string(base_html, page='home', body=login_html)

@app.route('/register', methods=['GET', 'POST'])
def register():
    err = ''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        if not username or not password:
            err = 'Please fill all fields.'
        else:
            try:
                db = get_db()
                db.execute("INSERT INTO users(username, password) VALUES (?, ?)", (username, password))
                db.commit()
                return redirect(url_for('login'))
            except sqlite3.IntegrityError:
                err = 'Username already exists.'
    return render_template_string(base_html, page='register', body=register_html, err=err)

@app.route('/login', methods=['GET','POST'])
def login():
    err = ''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        db = get_db()
        cur = db.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
        user = cur.fetchone()
        if user:
            session['user'] = username
            return redirect(url_for('inbox'))
        else:
            err = 'Invalid credentials.'
    return render_template_string(base_html, page='login', body=login_html, err=err)

@app.route('/logout')
def logout():
    session.pop('user', None)
    return redirect(url_for('index'))

@app.route('/inbox')
def inbox():
    if 'user' not in session:
        return redirect(url_for('login'))
    db = get_db()
    cur = db.execute("SELECT * FROM messages WHERE receiver=?", (session['user'],))
    messages = cur.fetchall()
    return render_template_string(base_html, page='inbox', body=inbox_html, messages=messages, user=session['user'])

@app.route('/send', methods=['GET', 'POST'])
def send():
    if 'user' not in session:
        return redirect(url_for('login'))
    err = ''
    if request.method == 'POST':
        receiver = request.form['receiver']
        body = request.form['body']
        db = get_db()
        cur = db.execute("SELECT * FROM users WHERE username=?", (receiver,))
        if not cur.fetchone():
            err = 'Receiver does not exist.'
        else:
            db.execute("INSERT INTO messages(sender, receiver, body) VALUES (?, ?, ?)",
                       (session['user'], receiver, body))
            db.commit()
            return redirect(url_for('inbox'))
    return render_template_string(base_html, page='send', body=send_html, user=session['user'], err=err)

@app.route('/manage', methods=['GET', 'POST'])
def manage():
    if 'user' not in session:
        return redirect(url_for('login'))
    output = ''
    if request.method == 'POST':
        code = request.form['code']
        try:
            # CWE-94: Eval injection vulnerability
            output = str(eval(code))
        except Exception as e:
            output = "Error: " + str(e)
    return render_template_string(base_html, page='manage', body=manage_html, output=output, user=session['user'])

