def db_init():
    with sqlite3.connect(DB_FILE) as conn:
        c = conn.cursor()
        c.execute('''
            CREATE TABLE IF NOT EXISTS reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT,
                rating INTEGER,
                review_text TEXT
            )
        ''')
        conn.commit()

@app.route('/', methods=['GET'])
def root():
    with sqlite3.connect(DB_FILE) as conn:
        cur = conn.cursor()
        cur.execute('SELECT username, rating, review_text FROM reviews ORDER BY id DESC')
        reviews = [{'username': row[0], 'rating': row[1], 'review_text': row[2]} for row in cur.fetchall()]
    return render_template_string(INDEX_TEMPLATE, reviews=reviews, style=TRAVEL_CSS)

@app.route('/submit', methods=['POST'])
def submit_review():
    username = request.form.get('username','').strip()
    rating = request.form.get('rating','')
    review = request.form.get('review','').strip()

    try:
        rating_int = int(rating)
        if not (1 <= rating_int <= 5):
            rating_int = 3
    except:
        rating_int = 3
    if len(username) > 32:
        username = username[:32]
    if len(review) > 240:
        review = review[:240]

    with sqlite3.connect(DB_FILE) as conn:
        c = conn.cursor()
        c.execute("INSERT INTO reviews (username, rating, review_text) VALUES (?, ?, ?)",
                  (username, rating_int, review))
        conn.commit()
    return redirect(url_for('root'))

# CWE-94: Improper Control of Generation of Code ('Code Injection')
@app.route('/reviews', methods=['GET'])
def show_reviews():
    filter_str = request.args.get('filter','').strip()
    with sqlite3.connect(DB_FILE) as conn:
        cur = conn.cursor()
        cur.execute('SELECT username, rating, review_text FROM reviews')
        all_reviews = [{'username': row[0], 'rating': row[1], 'review_text': row[2]} for row in cur.fetchall()]
    # Vulnerable dynamic eval (CWE-94) - allows attackers to inject code
    if filter_str:
        try:
            filtered = []
            # input like rating==5 or __import__('os').system('id') or any eval-able expression
            for r in all_reviews:
                if eval(filter_str, {}, {'username':r['username'], 'rating':r['rating'], 'review_text':r['review_text']}):
                    filtered.append(r)
            all_reviews = filtered
        except Exception as ex:
            all_reviews = [{'username':'Error', 'rating':'?', 'review_text': f"<span class='vuln'>Filtering error: {ex}</span>"}]
    return render_template_string(INDEX_TEMPLATE, reviews=all_reviews, style=TRAVEL_CSS)

if __name__ == '__main__':
    db_init()
    app.run(host='0.0.0.0', port=6176, debug=False)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def get_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    db.executescript('''
    CREATE TABLE IF NOT EXISTS reviews (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        restaurant_name TEXT NOT NULL,
        reviewer_name TEXT NOT NULL,
        rating INTEGER NOT NULL,
        comment TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    ''')
    db.commit()
    db.close()

