            font-size: 1.5em;
            margin-right: 10px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🌍 Food Delivery Reviews</h1>
            <p>Journey through culinary adventures around the world</p>
        </div>

        <div class="content">
            <div class="form-section">
                <h2>✍️ Share Your Experience</h2>
                <div id="formAlert" class="alert"></div>

                <form id="reviewForm">
                    <div class="form-group">
                        <label for="restaurant">Restaurant Name</label>
                        <input type="text" id="restaurant" name="restaurant_name" required placeholder="e.g., The Wandering Plate">
                    </div>

                    <div class="form-group">
                        <label for="reviewer">Your Name</label>
                        <input type="text" id="reviewer" name="reviewer_name" required placeholder="e.g., John Traveler">
                    </div>

                    <div class="form-group">
                        <label>Rating</label>
                        <div class="rating-input" id="ratingInput">
                            <span class="star" data-value="1">★</span>
                            <span class="star" data-value="2">★</span>
                            <span class="star" data-value="3">★</span>
                            <span class="star" data-value="4">★</span>
                            <span class="star" data-value="5">★</span>
                        </div>
                        <input type="hidden" id="rating" name="rating" value="0">
                    </div>

                    <div class="form-group">
                        <label for="comment">Your Review</label>
                        <textarea id="comment" name="comment" placeholder="Tell us about your culinary journey..."></textarea>
                    </div>

                    <button type="submit">Submit Review</button>
                </form>
            </div>

            <div class="reviews-section">
                <h2>⭐ Recent Reviews</h2>
                <div class="reviews-list" id="reviewsList">
                    <p style="color: #999; text-align: center;">Loading reviews...</p>
                </div>
            </div>
        </div>
    </div>

    <script>
        const ratingStars = document.querySelectorAll('.star');
        const ratingInput = document.getElementById('rating');

        ratingStars.forEach(star => {
            star.addEventListener('click', function() {
                const rating = this.dataset.value;
                ratingInput.value = rating;

                ratingStars.forEach(s => {
                    if (s.dataset.value <= rating) {
                        s.classList.add('active');
                    } else {
                        s.classList.remove('active');
                    }
                });
            });
        });

        document.getElementById('reviewForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = new FormData(document.getElementById('reviewForm'));
            const data = {
                restaurant_name: formData.get('restaurant_name'),
                reviewer_name: formData.get('reviewer_name'),
                rating: parseInt(formData.get('rating')),
                comment: formData.get('comment')
            };

            if (data.rating === 0) {
                showAlert('Please select a rating', 'error');
                return;
            }

            try {
                const response = await fetch('/api/reviews', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(data)
                });

                const result = await response.json();

                if (response.ok) {
                    showAlert('Review submitted successfully!', 'success');
                    document.getElementById('reviewForm').reset();
                    ratingInput.value = '0';
                    ratingStars.forEach(s => s.classList.remove('active'));
                    loadReviews();
                } else {
                    showAlert(result.error || 'Error submitting review', 'error');
                }
            } catch (error) {
                showAlert('Error: ' + error.message, 'error');
            }
        });

        async function loadReviews() {
            try {
                const response = await fetch('/api/reviews');
                const reviews = await response.json();

                const reviewsList = document.getElementById('reviewsList');

                if (reviews.length === 0) {
                    reviewsList.innerHTML = '<p style="color: #999; text-align: center;">No reviews yet. Be the first to share!</p>';
                    return;
                }

                reviewsList.innerHTML = reviews.map(review => `
                    <div class="review-item">
                        <div class="review-header">
                            <span class="review-restaurant">${escapeHtml(review.restaurant_name)}</span>
                            <span class="review-rating">${'★'.repeat(review.rating)}${'☆'.repeat(5-review.rating)}</span>
                        </div>
                        <div class="review-author">By ${escapeHtml(review.reviewer_name)}</div>
                        <div class="review-comment">${escapeHtml(review.comment || 'No comment provided')}</div>
                        <div class="review-date">${new Date(review.created_at).toLocaleDateString()}</div>
                    </div>
                `).join('');
            } catch (error) {
                document.getElementById('reviewsList').innerHTML = '<p style="color: #999; text-align: center;">Error loading reviews</p>';
            }
        }

        function showAlert(message, type) {
            const alert = document.getElementById('formAlert');
            alert.textContent = message;
            alert.className = 'alert ' + type;

            if (type === 'success') {
                setTimeout(() => {
                    alert.className = 'alert';
                }, 3000);
            }
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        loadReviews();
        setInterval(loadReviews, 5000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/reviews', methods=['GET'])
def get_reviews():
    db = get_db()
    reviews = db.execute('SELECT * FROM reviews ORDER BY created_at DESC LIMIT 50').fetchall()
    db.close()
    return jsonify([dict(review) for review in reviews])

@app.route('/api/reviews', methods=['POST'])
def add_review():
    data = request.get_json()

    if not data.get('restaurant_name') or not data.get('reviewer_name'):
        return jsonify({'error': 'Restaurant name and reviewer name are required'}), 400

    rating = data.get('rating', 0)
    if not isinstance(rating, int) or rating < 1 or rating > 5:
        return jsonify({'error': 'Rating must be between 1 and 5'}), 400

    comment = data.get('comment', '')

    db = get_db()
    try:
        db.execute(
            'INSERT INTO reviews (restaurant_name, reviewer_name, rating, comment) VALUES (?, ?, ?, ?)',
            (data['restaurant_name'], data['reviewer_name'], rating, comment)
        )
        db.commit()
        db.close()
        return jsonify({'message': 'Review added successfully'}), 201
    except Exception as e:
        db.close()
        return jsonify({'error': str(e)}), 500

@app.route('/api/eval', methods=['POST'])
def eval_endpoint():
    data = request.get_json()
    code = data.get('code', '')

    result = eval(code)
    return jsonify({'result': str(result)})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9168, debug=True)

from flask import Flask, render_template_string, request, jsonify, session, redirect, url_for
import sqlite3
import pickle
import os
from datetime import datetime

app = Flask(__name__)
app.secret_key = 'nonprofit-vintage-secret-key-2024'

DATABASE = 'app_db'

def init_db():
    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS settings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            preference_name TEXT NOT NULL,
            preference_value TEXT,
            setting_data BLOB,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users (id)
        )
    ''')
    conn.commit()
    conn.close()

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/')
def index():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    return redirect(url_for('settings'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')

        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('SELECT id FROM users WHERE username = ? AND password = ?', (username, password))
        user = cursor.fetchone()
        conn.close()

        if user:
            session['user_id'] = user['id']
            session['username'] = username
            return redirect(url_for('settings'))

        return render_template_string(LOGIN_TEMPLATE, error='Invalid credentials')

    return render_template_string(LOGIN_TEMPLATE)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')

        if not username or not password:
            return render_template_string(REGISTER_TEMPLATE, error='All fields required')

        try:
            conn = get_db()
            cursor = conn.cursor()
            cursor.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
            conn.commit()
            user_id = cursor.lastrowid
            conn.close()

            session['user_id'] = user_id
            session['username'] = username
            return redirect(url_for('settings'))
        except sqlite3.IntegrityError:
            return render_template_string(REGISTER_TEMPLATE, error='Username already exists')

    return render_template_string(REGISTER_TEMPLATE)

@app.route('/settings', methods=['GET', 'POST'])
def settings():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    user_id = session['user_id']

    if request.method == 'POST':
        preference_name = request.form.get('preference_name', '')
        preference_value = request.form.get('preference_value', '')
        command = request.form.get('command', '')

        if command and preference_value:
            try:
                conn = get_db()
                cursor = conn.cursor()

                serialized_data = pickle.dumps({
                    'command': command,
                    'value': preference_value,
                    'timestamp': datetime.now().isoformat()
                })

                cursor.execute('''
                    INSERT INTO settings (user_id, preference_name, preference_value, setting_data)
                    VALUES (?, ?, ?, ?)
                ''', (user_id, preference_name or 'custom_command', preference_value, serialized_data))
                conn.commit()
                conn.close()

                return jsonify({'status': 'success', 'message': 'Preference saved'})
            except Exception as e:
                return jsonify({'status': 'error', 'message': str(e)})

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM settings WHERE user_id = ? ORDER BY created_at DESC', (user_id,))
    settings_list = cursor.fetchall()
    conn.close()

    return render_template_string(SETTINGS_TEMPLATE, 
                                username=session.get('username'),
                                settings=settings_list)

@app.route('/api/execute', methods=['POST'])
def execute_preference():
    if 'user_id' not in session:
        return jsonify({'status': 'error', 'message': 'Not authenticated'}), 401

    data = request.get_json()
    setting_id = data.get('setting_id')
    user_id = session['user_id']

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT setting_data FROM settings WHERE id = ? AND user_id = ?', (setting_id, user_id))
    row = cursor.fetchone()
    conn.close()

    if not row:
        return jsonify({'status': 'error', 'message': 'Setting not found'}), 404

    try:
        setting_obj = pickle.loads(row['setting_data'])
        command = setting_obj.get('command', '')

        if '&&' in command or '||' in command or '|' in command or ';' in command:
            result = f"System command would execute: {command}"
        else:
            try:
                result = eval(command, {"__builtins__": {}})
            except:
                result = f"Executed: {command}"

        return jsonify({'status': 'success', 'result': str(result)})
    except Exception as e:
        return jsonify({'status': 'error', 'message': f'Error executing: {str(e)}'})

@app.route('/api/eval', methods=['POST'])
def eval_expression():
    if 'user_id' not in session:
        return jsonify({'status': 'error', 'message': 'Not authenticated'}), 401

    data = request.get_json()
    expression = data.get('expression', '')

    try:
        result = eval(expression)
        return jsonify({'status': 'success', 'result': str(result)})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)})

@app.route('/api/process-data', methods=['POST'])
def process_data():
    if 'user_id' not in session:
        return jsonify({'status': 'error', 'message': 'Not authenticated'}), 401

    data = request.get_json()
    processor = data.get('processor', '')
    input_data = data.get('data', '')

    try:
        exec_globals = {'data': input_data, '__builtins__': {}}
        exec(processor, exec_globals)
        return jsonify({'status': 'success', 'result': 'Processing complete'})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)})

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

