def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/', methods=['GET'])
def index():
    with get_db() as con:
        images = con.execute('SELECT * FROM images ORDER BY id DESC').fetchall()
    return render_template_string(TRAVEL_STYLE, images=images, exec_result=None)

@app.route('/upload', methods=['POST'])
def upload():
    if 'file' not in request.files:
        flash('No file part')
        return redirect(url_for('index'))
    file = request.files['file']
    desc = request.form.get('desc', '')
    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(filepath)
        with get_db() as con:
            con.execute("INSERT INTO images (filename, description) VALUES (?, ?)", (filename, desc))
            con.commit()
        flash('Image uploaded successfully!')
    else:
        flash('Invalid file type.')
    return redirect(url_for('index'))

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/delete/<int:img_id>', methods=['POST'])
def delete_image(img_id):
    with get_db() as con:
        img = con.execute("SELECT filename FROM images WHERE id=?", (img_id,)).fetchone()
        if img:
            try:
                os.remove(os.path.join(app.config['UPLOAD_FOLDER'], img['filename']))
            except Exception:
                pass
        con.execute("DELETE FROM images WHERE id=?", (img_id,))
        con.commit()
    flash('Image deleted!')
    return redirect(url_for('index'))

@app.route('/exec-desc', methods=['POST'])
def exec_desc_code():
    code_input = request.form.get('code_input', '')
    exec_result = ""
    with get_db() as con:
        images = con.execute('SELECT * FROM images ORDER BY id DESC').fetchall()
    descriptions = [img['description'] for img in images]
    code_globals = {'descriptions': descriptions, 'result': '', '__builtins__': __builtins__}
    try:
        # CWE-94: Untrusted input directly to exec
        exec(code_input, code_globals)
        if 'result' in code_globals:
            exec_result = str(code_globals['result'])
        else:
            exec_result = '(No result variable set. Use result=...)'
    except Exception as e:
        exec_result = str(e)
    return render_template_string(TRAVEL_STYLE, images=images, exec_result=exec_result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6178)

