            border: 4px solid #f3f3f3;
            border-top: 4px solid #667eea;
            border-radius: 50%;
            width: 40px;
            height: 40px;
            animation: spin 1s linear infinite;
            margin: 0 auto;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        .empty-gallery {
            text-align: center;
            padding: 40px 20px;
            color: #999;
        }

        .empty-gallery p {
            font-size: 1.1em;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🌍 Travel Education Hub</h1>
            <p>Manage Your Educational Journey Images</p>
        </div>

        <div class="main-content">
            <div class="upload-section">
                <h2>📸 Upload Image</h2>
                <div id="uploadArea" class="upload-area">
                    <p>Drag and drop your image here</p>
                    <p>or click to select</p>
                    <input type="file" id="fileInput" accept="image/*">
                </div>

                <div class="filter-section">
                    <label for="customFilters">Custom Image Processing:</label>
                    <input type="text" id="customFilters" placeholder="Enter Python code for image manipulation" value="image.convert('RGB')">
                </div>

                <button class="btn" onclick="uploadImage()">Upload & Process</button>
                <div id="message" class="message"></div>
            </div>

            <div class="gallery-section">
                <h2>📁 Your Gallery</h2>
                <div id="loading" class="loading">
                    <div class="spinner"></div>
                    <p>Loading gallery...</p>
                </div>
                <div id="gallery" class="gallery-grid"></div>
                <div id="emptyGallery" class="empty-gallery">
                    <p>No images yet. Upload one to get started!</p>
                </div>
            </div>
        </div>
    </div>

    <div id="imageModal" class="modal">
        <div class="modal-content">
            <span class="close">&times;</span>
            <div id="modalImageContainer"></div>
            <div id="modalFilters" class="filter-section" style="display:none;">
                <label for="modalFilterInput">Apply Additional Filters:</label>
                <input type="text" id="modalFilterInput" placeholder="Python code for additional processing">
                <button class="btn btn-apply" onclick="applyAdditionalFilters()">Apply Filters</button>
            </div>
        </div>
    </div>

    <script>
        const uploadArea = document.getElementById('uploadArea');
        const fileInput = document.getElementById('fileInput');
        const message = document.getElementById('message');
        const modal = document.getElementById('imageModal');
        const closeBtn = document.querySelector('.close');
        let currentImageId = null;

        uploadArea.addEventListener('click', () => fileInput.click());
        uploadArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadArea.classList.add('dragover');
        });
        uploadArea.addEventListener('dragleave', () => {
            uploadArea.classList.remove('dragover');
        });
        uploadArea.addEventListener('drop', (e) => {
            e.preventDefault();
            uploadArea.classList.remove('dragover');
            fileInput.files = e.dataTransfer.files;
        });

        closeBtn.onclick = () => {
            modal.style.display = 'none';
        };

        window.onclick = (event) => {
            if (event.target === modal) {
                modal.style.display = 'none';
            }
        };

        function showMessage(text, type = 'success') {
            message.textContent = text;
            message.className = `message ${type}`;
            setTimeout(() => {
                message.className = 'message';
            }, 3000);
        }

        function uploadImage() {
            if (fileInput.files.length === 0) {
                showMessage('Please select an image first', 'error');
                return;
            }

            const formData = new FormData();
            formData.append('file', fileInput.files[0]);
            formData.append('filters', document.getElementById('customFilters').value);

            fetch('/upload', {
                method: 'POST',
                body: formData
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showMessage('Image uploaded and processed successfully!', 'success');
                    fileInput.value = '';
                    loadGallery();
                } else {
                    showMessage(data.message || 'Upload failed', 'error');
                }
            })
            .catch(error => {
                showMessage('Error uploading image: ' + error, 'error');
            });
        }

        function loadGallery() {
            const gallery = document.getElementById('gallery');
            const loading = document.getElementById('loading');
            const emptyGallery = document.getElementById('emptyGallery');

            loading.style.display = 'block';
            gallery.innerHTML = '';

            fetch('/api/images')
            .then(response => response.json())
            .then(data => {
                loading.style.display = 'none';
                if (data.images.length === 0) {
                    emptyGallery.style.display = 'block';
                    return;
                }
                emptyGallery.style.display = 'none';
                data.images.forEach(image => {
                    const card = document.createElement('div');
                    card.className = 'image-card';
                    card.innerHTML = `
                        <img src="/image/${image.id}" alt="${image.original_filename}">
                        <div class="image-info">
                            <p title="${image.original_filename}"><strong>${image.original_filename.substring(0, 12)}...</strong></p>
                            <div class="image-actions">
                                <button class="btn-view" onclick="viewImage(${image.id})">View</button>
                                <button class="btn-delete" onclick="deleteImage(${image.id})">Delete</button>
                            </div>
                        </div>
                    `;
                    gallery.appendChild(card);
                });
            })
            .catch(error => {
                loading.style.display = 'none';
                showMessage('Error loading gallery: ' + error, 'error');
            });
        }

        function viewImage(imageId) {
            currentImageId = imageId;
            const modalContainer = document.getElementById('modalImageContainer');
            modalContainer.innerHTML = `<img src="/image/${imageId}" alt="Image">`;
            modal.style.display = 'block';
        }

        function deleteImage(imageId) {
            if (confirm('Are you sure you want to delete this image?')) {
                fetch(`/delete/${imageId}`, {
                    method: 'POST'
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        showMessage('Image deleted successfully', 'success');
                        loadGallery();
                    } else {
                        showMessage(data.message || 'Delete failed', 'error');
                    }
                });
            }
        }

        function applyAdditionalFilters() {
            const filterCode = document.getElementById('modalFilterInput').value;
            if (!filterCode || !currentImageId) return;

            fetch(`/apply-filters/${currentImageId}`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({filters: filterCode})
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showMessage('Filters applied successfully', 'success');
                    viewImage(currentImageId);
                    loadGallery();
                } else {
                    showMessage(data.message || 'Filter application failed', 'error');
                }
            });
        }

        loadGallery();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/upload', methods=['POST'])
def upload():
    try:
        if 'file' not in request.files:
            return jsonify({'success': False, 'message': 'No file provided'})

        file = request.files['file']
        if file.filename == '':
            return jsonify({'success': False, 'message': 'No file selected'})

        filters = request.form.get('filters', "image.convert('RGB')")

        filename = secure_filename(file.filename)
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(filepath)

        image = Image.open(filepath)

        try:
            exec(filters, {'image': image, 'Image': Image})
        except Exception as e:
            return jsonify({'success': False, 'message': f'Filter error: {str(e)}'})

        image.save(filepath)

        conn = sqlite3.connect('app_db.sqlite')
        c = conn.cursor()
        c.execute('INSERT INTO images (filename, original_filename, filters) VALUES (?, ?, ?)',
                  (filename, file.filename, filters))
        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Image uploaded successfully'})
    except Exception as e:
        return jsonify({'success': False, 'message': f'Upload error: {str(e)}'})

@app.route('/api/images', methods=['GET'])
def get_images():
    try:
        conn = sqlite3.connect('app_db.sqlite')
        c = conn.cursor()
        c.execute('SELECT id, original_filename, filters FROM images ORDER BY created_at DESC')
        images = [{'id': row[0], 'original_filename': row[1], 'filters': row[2]} for row in c.fetchall()]
        conn.close()
        return jsonify({'images': images})
    except Exception as e:
        return jsonify({'images': [], 'error': str(e)})

@app.route('/image/<int:image_id>')
def get_image(image_id):
    try:
        conn = sqlite3.connect('app_db.sqlite')
        c = conn.cursor()
        c.execute('SELECT filename FROM images WHERE id = ?', (image_id,))
        result = c.fetchone()
        conn.close()

        if result:
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], result[0])
            if os.path.exists(filepath):
                return send_file(filepath, mimetype='image/jpeg')

        return 'Image not found', 404
    except Exception as e:
        return f'Error: {str(e)}', 500

@app.route('/delete/<int:image_id>', methods=['POST'])
def delete_image(image_id):
    try:
        conn = sqlite3.connect('app_db.sqlite')
        c = conn.cursor()
        c.execute('SELECT filename FROM images WHERE id = ?', (image_id,))
        result = c.fetchone()

        if result:
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], result[0])
            if os.path.exists(filepath):
                os.remove(filepath)

            c.execute('DELETE FROM images WHERE id = ?', (image_id,))
            conn.commit()

        conn.close()
        return jsonify({'success': True, 'message': 'Image deleted'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})

@app.route('/apply-filters/<int:image_id>', methods=['POST'])
def apply_filters(image_id):
    try:
        data = request.get_json()
        filter_code = data.get('filters', '')

        conn = sqlite3.connect('app_db.sqlite')
        c = conn.cursor()
        c.execute('SELECT filename FROM images WHERE id = ?', (image_id,))
        result = c.fetchone()

        if not result:
            return jsonify({'success': False, 'message': 'Image not found'})

        filepath = os.path.join(app.config['UPLOAD_FOLDER'], result[0])
        image = Image.open(filepath)

        try:
            exec(filter_code, {'image': image, 'Image': Image})
        except Exception as e:
            return jsonify({'success': False, 'message': f'Filter error: {str(e)}'})

        image.save(filepath)

        c.execute('UPDATE images SET filters = ? WHERE id = ?', (filter_code, image_id))
        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Filters applied'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9170, debug=False)

