@app.route('/', methods=['GET', 'POST'])
def index():
    msg = ''
    if request.method == 'POST':
        message = request.form.get('message', '')
        # CWE-94 (code injection) - UNSAFE
        try:
            eval_result = str(eval(message))
            msg = "Eval result: " + eval_result
        except Exception as e:
            msg = "Error in eval: "+str(e)
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('INSERT INTO feedback (message) VALUES (?)', (message,))
        conn.commit()
        conn.close()
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('SELECT message FROM feedback')
    feedbacks = c.fetchall()
    conn.close()

    template = f"""
    <!DOCTYPE html>
    <html>
    <head>
      <title>Feedback - Cyberpunk Finance</title>
      {CYBERPUNK_STYLE}
    </head>
