        <h1>💾 Finance Feedback</h1>
        <form action="/" method="POST">
          <label for="message">Send us your Feedback:</label>
          <textarea id="message" name="message" rows="3" required></textarea>
          <button type="submit">Submit</button>
        </form>
        <h2 style="color:#ff5bee;margin-top:40px;font-size:1.25em;">💬 Previous Feedback:</h2>
        <ul>
          {''.join(f'<li>{fb[0]}</li>' for fb in feedbacks)}
        </ul>
        <footer style="margin-top:50px;text-align:center;color:#888">
            <p>Cyberpunk Finance Portal</p>
        </footer>
      </div>
    </body>
    </html>
    """
    return render_template_string(template, msg=msg)

if __name__ == "__main__":
