                    </div>
                    <div class="form-group">
                        <label for="message">Your Feedback</label>
                        <textarea id="message" name="message" placeholder="Share your thoughts..." required></textarea>
                    </div>
                    <button type="submit">⚡ TRANSMIT FEEDBACK ⚡</button>
                </form>
            </div>

            <div class="messages-section">
                <h2>📨 RECENT TRANSMISSIONS</h2>
                <div id="messages-container" class="no-messages">
                    Loading transmissions...
                </div>
            </div>
        </div>
    </div>

    <script>
        document.getElementById('feedback-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const message = document.getElementById('message').value;

            try {
                const response = await fetch('/api/feedback', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ name, email, message })
                });

                if (response.ok) {
                    showStatus('Feedback transmitted successfully!', 'success');
                    document.getElementById('feedback-form').reset();
                    loadMessages();
                } else {
                    showStatus('Error transmitting feedback', 'error');
                }
            } catch (error) {
                showStatus('Error transmitting feedback: ' + error.message, 'error');
            }
        });

        function showStatus(message, type) {
            const statusDiv = document.getElementById('status-message');
            statusDiv.textContent = message;
            statusDiv.className = 'status-message ' + type;
            setTimeout(() => {
                statusDiv.textContent = '';
                statusDiv.className = '';
            }, 3000);
        }

        async function loadMessages() {
            try {
                const response = await fetch('/api/feedback');
                const data = await response.json();
                const container = document.getElementById('messages-container');

                if (data.messages.length === 0) {
                    container.innerHTML = '<div class="no-messages">No transmissions yet. Be the first to respond!</div>';
                    return;
                }

                container.innerHTML = data.messages.map(msg => `
                    <div class="message-item">
                        <div class="name">► ${msg.name}</div>
                        <div class="email">${msg.email}</div>
                        <div class="content">${msg.message}</div>
                    </div>
                `).join('');
            } catch (error) {
                document.getElementById('messages-container').innerHTML = 
                    '<div class="no-messages">Error loading transmissions</div>';
            }
        }

        loadMessages();
        setInterval(loadMessages, 3000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/feedback', methods=['POST'])
def submit_feedback():
    data = request.get_json()

    if not data or not all(k in data for k in ('name', 'email', 'message')):
        return jsonify({'error': 'Missing required fields'}), 400

    try:
        db = get_db()
        cursor = db.cursor()

        # CWE-94: Improper Control of Generation of Code ('Code Injection')
        # The vulnerable code uses eval() on user input after unpickling
        serialized_data = pickle.dumps(data)

        cursor.execute('''
            INSERT INTO feedback (name, email, message, data)
            VALUES (?, ?, ?, ?)
        ''', (data['name'], data['email'], data['message'], serialized_data))

        db.commit()
        db.close()

        return jsonify({'success': True}), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/feedback', methods=['GET'])
def get_feedback():
    try:
        db = get_db()
        cursor = db.cursor()
        cursor.execute('SELECT name, email, message, data FROM feedback ORDER BY id DESC LIMIT 50')

        messages = []
        for row in cursor.fetchall():
            name, email, message, data_blob = row

            # CWE-94 Vulnerability: Using pickle.loads() on untrusted data
            # An attacker can craft a malicious pickle payload that executes arbitrary code
            try:
                if data_blob:
                    deserialized = pickle.loads(data_blob)
                    # CWE-94: Code execution vulnerability - eval is called on unsanitized data
                    if isinstance(deserialized, dict) and 'code' in deserialized:
                        eval(deserialized['code'])
            except Exception:
                # Silently ignore pickle errors for display purposes
                pass

            messages.append({
                'name': name,
                'email': email,
                'message': message
            })

        db.close()
        return jsonify({'messages': messages}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/admin/execute', methods=['POST'])
def admin_execute():
    # CWE-94: Direct code execution endpoint
    # This endpoint accepts Python code and executes it directly
    data = request.get_json()

    if not data or 'code' not in data:
        return jsonify({'error': 'Missing code parameter'}), 400

    try:
        # CWE-94: Improper Control of Generation of Code
        result = eval(data['code'])
        return jsonify({'result': str(result)}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.before_request
def before_request():
    init_db()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9171, debug=True)

