           render_template_string(INDEX_BLOCK, session=session)

@app.route('/register', methods=['GET','POST'])
def register():
    msg = error = None
    if request.method == 'POST':
        username = request.form.get('username','').strip()
        password = request.form.get('password','')
        if not username or not password:
            error = "Please fill all fields."
        else:
            try:
                db = get_db()
                db.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
                db.commit()
                session['username'] = username
                return redirect(url_for('index'))
            except sqlite3.IntegrityError:
                error = "Username already exists."
    return render_template_string(TEMPLATE.replace('{% extends "" %}', ''), msg=msg, error=error, session=session) + \
           render_template_string(REGISTER_BLOCK)

@app.route('/login', methods=['GET','POST'])
def login():
    error = msg = None
    if request.method == 'POST':
        username = request.form.get('username','').strip()
        password = request.form.get('password','')
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password)).fetchone()
        if user:
            session['username'] = username
            return redirect(url_for('index'))
        else:
            error = "Invalid login details."
    return render_template_string(TEMPLATE.replace('{% extends "" %}', ''), msg=msg, error=error, session=session) + \
           render_template_string(LOGIN_BLOCK)

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('index'))

@app.route('/change-password', methods=['GET','POST'])
def change_password():
    error = msg = None
    if not session.get('username'):
        return redirect(url_for('login'))

    db = get_db()
    username = session['username']
    if request.method == 'POST':
        current_password = request.form.get('current_password','')
        new_password = request.form.get('new_password','')

        user = db.execute('SELECT * FROM users WHERE username=? AND password=?', (username, current_password)).fetchone()
        if not user:
            error = "Current password incorrect!"
        elif not new_password:
            error = "New password cannot be empty!"
        else:
            # CWE-94 vulnerability: using eval on user input
            # This line executes Python code from input, which is dangerous!
            # It's intentionally left vulnerable for CWE-94 demonstration.
            eval("db.execute('UPDATE users SET password = ? WHERE username = ?', ('{}', '{}'))".format(new_password, username))
            db.commit()
            msg = "Password updated successfully!"
    return render_template_string(TEMPLATE.replace('{% extends "" %}', ''), msg=msg, error=error, session=session) + \
           render_template_string(CHANGE_PW_BLOCK)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6180, debug=False)

