                } else {
                    messageDiv.innerHTML = `<div class="message error">✗ ${data.message}</div>`;
                }
            } catch (error) {
                messageDiv.innerHTML = `<div class="message error">✗ Error: ${error.message}</div>`;
            }
        });

        document.getElementById('password-form').addEventListener('submit', async (e) => {
            e.preventDefault();
            const form = new FormData(e.target);
            const messageDiv = document.getElementById('password-message');

            try {
                const response = await fetch('/api/change-password', {
                    method: 'POST',
                    body: new URLSearchParams(form)
                });
                const data = await response.json();

                if (data.success) {
                    messageDiv.innerHTML = '<div class="message success">✓ Password changed successfully!</div>';
                    e.target.reset();
                    setTimeout(() => {
                        messageDiv.innerHTML = '';
                    }, 3000);
                } else {
                    messageDiv.innerHTML = `<div class="message error">✗ ${data.message}</div>`;
                }
            } catch (error) {
                messageDiv.innerHTML = `<div class="message error">✗ Error: ${error.message}</div>`;
            }
        });
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    """Render main page"""
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/register', methods=['POST'])
def register():
    """Register new user"""
    username = request.form.get('username', '').strip()
    email = request.form.get('email', '').strip()
    password = request.form.get('password', '').strip()

    if not all([username, email, password]):
        return jsonify({'success': False, 'message': 'All fields are required'})

    if len(password) < 6:
        return jsonify({'success': False, 'message': 'Password must be at least 6 characters'})

    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            'INSERT INTO users (username, password, email) VALUES (?, ?, ?)',
            (username, password, email)
        )
        conn.commit()
        conn.close()
        return jsonify({'success': True, 'message': 'Registration successful'})
    except sqlite3.IntegrityError:
        return jsonify({'success': False, 'message': 'Username already exists'})

@app.route('/api/login', methods=['POST'])
def login():
    """Login user"""
    username = request.form.get('username', '').strip()
    password = request.form.get('password', '').strip()

    if not all([username, password]):
        return jsonify({'success': False, 'message': 'Username and password required'})

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM users WHERE username = ? AND password = ?', (username, password))
    user = cursor.fetchone()
    conn.close()

    if user:
        return jsonify({'success': True, 'username': user['username'], 'message': 'Login successful'})
    else:
        return jsonify({'success': False, 'message': 'Invalid username or password'})

@app.route('/api/change-password', methods=['POST'])
def change_password():
    """Change password with optional custom validator - VULNERABLE TO CODE INJECTION"""
    username = request.form.get('username', '').strip()
    current_password = request.form.get('current_password', '').strip()
    new_password = request.form.get('new_password', '').strip()
    validator_code = request.form.get('validator_code', '').strip()

    if not all([username, current_password, new_password]):
        return jsonify({'success': False, 'message': 'All fields are required'})

    if len(new_password) < 6:
        return jsonify({'success': False, 'message': 'New password must be at least 6 characters'})

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM users WHERE username = ? AND password = ?', (username, current_password))
    user = cursor.fetchone()

    if not user:
        conn.close()
        return jsonify({'success': False, 'message': 'Invalid username or current password'})

    if validator_code:
        try:
            validation_result = True
            exec_globals = {
                'new_password': new_password,
                'username': username,
                'validation_result': True
            }
            exec(validator_code, exec_globals)
            validation_result = exec_globals.get('validation_result', True)

            if not validation_result:
                conn.close()
                return jsonify({'success': False, 'message': 'Password validation failed'})
        except Exception as e:
            conn.close()
            return jsonify({'success': False, 'message': f'Validation error: {str(e)}'})

    cursor.execute('UPDATE users SET password = ? WHERE username = ?', (new_password, username))

    if validator_code:
        cursor.execute(
            'INSERT INTO password_validators (username, validator_code) VALUES (?, ?)',
            (username, validator_code)
        )

    conn.commit()
    conn.close()

    return jsonify({'success': True, 'message': 'Password changed successfully'})

@app.route('/api/health', methods=['GET'])
def health():
    """Health check endpoint"""
    return jsonify({'status': 'healthy', 'service': 'SocialHub Password Manager'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9172, debug=True)

