@app.route("/", methods=["GET","POST"])
def index():
    profile_data = None
    if "user" in session:
        if request.method == "POST" and "cmd" in request.form:
            user = session["user"]
            cmd = request.form["cmd"]
            # --- CWE-94: Improper Control of Generation of Code ('Code Injection') ---
            # The following code is vulnerable and allows remote code execution.
            try:
                conn = sqlite3.connect(DATABASE)
                c = conn.cursor()
                c.execute("SELECT username, password FROM users WHERE username=?", (user,))
                db_user = c.fetchone()
                conn.close()
            except Exception:
                db_user = ("<DB ERR>", "<NA>")
            # Intentionally dangerous use of eval(input!), directly injects attacker-controlled code.
            # E.g., Try: __import__('os').popen('id').read()
            context = {'username': db_user[0], 'password': db_user[1]}
            try:
                profile_data = str(eval(cmd, {}, context))
            except Exception as ex:
                profile_data = f"<error: {ex}>"
    return render_template_string(
        INDEX_TMPL,
        futuristic_css=FUTURISTIC_CSS,
        profile_data=profile_data
    )

@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username", "").strip()
    password = request.form.get("password", "")
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute(
        "SELECT * FROM users WHERE username=? AND password=?",
        (username, password),
    )
    user = c.fetchone()
    conn.close()
    if user:
        session["user"] = username
        return redirect(url_for("index"))
    else:
        flash("Login failed. Check username and password.")
        return redirect(url_for("index"))

@app.route("/register", methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        if not username or not password:
            flash("Username and password required.")
            return redirect(url_for("register"))
        try:
            conn = sqlite3.connect(DATABASE)
            c = conn.cursor()
            c.execute(
                "INSERT INTO users (username, password) VALUES (?, ?)",
                (username, password),
            )
            conn.commit()
            conn.close()
        except sqlite3.IntegrityError:
            flash("Username already taken.")
            return redirect(url_for("register"))
        flash("Registration successful. Login now.")
        return redirect(url_for("index"))
    return render_template_string(
        REGISTER_TMPL,
        futuristic_css=FUTURISTIC_CSS
    )

@app.route("/logout", methods=["POST"])
def logout():
    session.pop("user", None)
    flash("You have logged out.")
    return redirect(url_for("index"))

@app.context_processor
def inject_globals():
    return dict(futuristic_css=FUTURISTIC_CSS)

