                        <input type="text" id="login_username" name="username" placeholder="Enter your username" required>
                    </div>
                    <div class="form-group">
                        <label for="login_password">PASSWORD</label>
                        <input type="password" id="login_password" name="password" placeholder="Enter your password" required>
                    </div>
                    <button type="submit" class="btn">INITIATE LOGIN SEQUENCE</button>
                </form>
            </div>

            <div id="register" class="form-content">
                <form method="POST" action="{{ url_for('register') }}" onsubmit="handleRegister(event)">
                    <div class="form-group">
                        <label for="reg_username">USERNAME</label>
                        <input type="text" id="reg_username" name="username" placeholder="Choose a username" required>
                    </div>
                    <div class="form-group">
                        <label for="reg_email">EMAIL</label>
                        <input type="email" id="reg_email" name="email" placeholder="Enter your email" required>
                    </div>
                    <div class="form-group">
                        <label for="reg_password">PASSWORD</label>
                        <input type="password" id="reg_password" name="password" placeholder="Create a password" required>
                    </div>
                    <div class="form-group">
                        <label for="reg_confirm">CONFIRM PASSWORD</label>
                        <input type="password" id="reg_confirm" name="confirm_password" placeholder="Confirm your password" required>
                    </div>
                    <button type="submit" class="btn">CREATE USER ACCOUNT</button>
                </form>
            </div>
            {% endif %}
        </div>
    </div>

    <script>
        function switchTab(tab) {
            document.querySelectorAll('.form-content').forEach(el => el.classList.remove('active'));
            document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
            document.getElementById(tab).classList.add('active');
            event.target.classList.add('active');
        }

        function handleRegister(event) {
            const password = document.getElementById('reg_password').value;
            const confirm = document.getElementById('reg_confirm').value;
            if (password !== confirm) {
                event.preventDefault();
                alert('Passwords do not match!');
            }
        }
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    if 'user_id' in session:
        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        conn.close()
        return render_template_string(HTML_TEMPLATE, current_user=user)
    return render_template_string(HTML_TEMPLATE, current_user=None)

@app.route('/register', methods=['POST'])
def register():
    username = request.form.get('username', '').strip()
    email = request.form.get('email', '').strip()
    password = request.form.get('password', '').strip()
    confirm_password = request.form.get('confirm_password', '').strip()

    if not all([username, email, password, confirm_password]):
        return render_template_string(HTML_TEMPLATE, 
                                    message='All fields are required',
                                    message_type='error')

    if password != confirm_password:
        return render_template_string(HTML_TEMPLATE, 
                                    message='Passwords do not match',
                                    message_type='error')

    if len(password) < 6:
        return render_template_string(HTML_TEMPLATE, 
                                    message='Password must be at least 6 characters',
                                    message_type='error')

    try:
        conn = get_db_connection()
        conn.execute('INSERT INTO users (username, email, password) VALUES (?, ?, ?)',
                    (username, email, password))
        conn.commit()
        conn.close()
        return render_template_string(HTML_TEMPLATE, 
                                    message='Account created successfully! Please login.',
                                    message_type='success')
    except sqlite3.IntegrityError:
        return render_template_string(HTML_TEMPLATE, 
                                    message='Username or email already exists',
                                    message_type='error')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username', '').strip()
    password = request.form.get('password', '').strip()

    if not username or not password:
        return render_template_string(HTML_TEMPLATE, 
                                    message='Username and password are required',
                                    message_type='error')

    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE username = ? AND password = ?',
                       (username, password)).fetchone()
    conn.close()

    if user:
        session['user_id'] = user['id']
        return redirect(url_for('index'))
    else:
        return render_template_string(HTML_TEMPLATE, 
                                    message='Invalid username or password',
                                    message_type='error')

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('user_id', None)
    return redirect(url_for('index'))

@app.route('/api/eval', methods=['POST'])
def eval_endpoint():
    code = request.json.get('code', '')
    try:
        result = eval(code)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/api/execute', methods=['POST'])
def execute_endpoint():
    command = request.json.get('command', '')
    try:
        exec_globals = {}
        exec(command, exec_globals)
        return jsonify({'status': 'executed'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9173, debug=True)

import os
import sqlite3
import pickle
import base64
from flask import Flask, render_template_string, request, jsonify, session
from datetime import datetime, timedelta
import secrets
from functools import wraps

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

DATABASE = '/tmp/app_db.db'

def get_db_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            message TEXT NOT NULL,
            alert_type TEXT DEFAULT 'info',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            is_read INTEGER DEFAULT 0,
            alert_data TEXT,
            FOREIGN KEY (user_id) REFERENCES users (id)
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS user_settings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            preferences TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users (id)
        )
    ''')

    conn.commit()
    conn.close()

def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'Unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated_function

