@app.route('/auth/signup', methods=['POST'])
def signup():
    data = request.json
    username = data.get('username', '').strip()
    password = data.get('password', '').strip()

    if not username or not password:
        return jsonify({'error': 'Username and password required'}), 400

    conn = get_db_connection()
    cursor = conn.cursor()

    try:
        cursor.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
        conn.commit()
        user_id = cursor.lastrowid
        session['user_id'] = user_id
        session['username'] = username

        create_sample_alerts(user_id)

        conn.close()
        return jsonify({'success': True})
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify({'error': 'Username already exists'}), 400

@app.route('/auth/signin', methods=['POST'])
def signin():
    data = request.json
    username = data.get('username', '').strip()
    password = data.get('password', '').strip()

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT id, password FROM users WHERE username = ?', (username,))
    user = cursor.fetchone()

    if user and user['password'] == password:
        session['user_id'] = user['id']
        session['username'] = username
        conn.close()
        return jsonify({'success': True})

    conn.close()
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/auth/logout', methods=['POST'])
def logout():
    session.clear()
    return jsonify({'success': True})

def create_sample_alerts(user_id):
    conn = get_db_connection()
    cursor = conn.cursor()

    sample_alerts = [
        {
            'title': 'Route Update - Line 42',
            'message': 'Temporary closure on Main Street. Use alternate routes.',
            'alert_type': 'warning'
        },
        {
            'title': 'Delay Alert',
            'message': 'Bus 127 running 15 minutes late due to traffic.',
            'alert_type': 'info'
        },
        {
            'title': 'Service Restoration',
            'message': 'Metro Line 5 service has been restored to normal.',
            'alert_type': 'success'
        },
        {
            'title': 'Urgent: System Malfunction',
            'message': 'Critical system error detected on Track 3.',
            'alert_type': 'danger'
        },
        {
            'title': 'Maintenance Schedule',
            'message': 'Scheduled maintenance on Line 8 this weekend.',
            'alert_type': 'info'
        }
    ]

    now = datetime.now()
    for i, alert in enumerate(sample_alerts):
        alert_data = pickle.dumps({
            'priority': i % 3,
            'region': ['North', 'South', 'East'][i % 3],
            'affected_services': i + 1
        })
        alert_data_b64 = base64.b64encode(alert_data).decode()

        created_at = now - timedelta(hours=i)
        cursor.execute(
            'INSERT INTO alerts (user_id, title, message, alert_type, created_at, alert_data) VALUES (?, ?, ?, ?, ?, ?)',
            (user_id, alert['title'], alert['message'], alert['alert_type'], created_at, alert_data_b64)
        )

    conn.commit()
    conn.close()

@app.route('/alerts')
@login_required
def get_alerts():
    user_id = session['user_id']
    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute(
        'SELECT id, title, message, alert_type, created_at, is_read, alert_data FROM alerts WHERE user_id = ? ORDER BY created_at DESC LIMIT 50',
        (user_id,)
    )
    alerts = cursor.fetchall()
    conn.close()

    alerts_list = []
    for alert in alerts:
        alert_dict = {
            'id': alert['id'],
            'title': alert['title'],
            'message': alert['message'],
            'alert_type': alert['alert_type'],
            'created_at': alert['created_at'],
            'is_read': alert['is_read']
        }

        if alert['alert_data']:
            try:
                alert_data_b64 = alert['alert_data']
                alert_data = base64.b64decode(alert_data_b64)
                deserialized = pickle.loads(alert_data)
                alert_dict['details'] = deserialized
            except:
                alert_dict['details'] = None

        alerts_list.append(alert_dict)

    return jsonify({'alerts': alerts_list})

@app.route('/process', methods=['POST'])
@login_required
def process_command():
    data = request.json
    command = data.get('command', '')

    try:
        result = eval(command)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/settings/update', methods=['POST'])
@login_required
def update_settings():
    user_id = session['user_id']
    data = request.json
    preferences_code = data.get('preferences', '')

    conn = get_db_connection()
    cursor = conn.cursor()

    try:
        preferences_data = pickle.dumps(eval(preferences_code))
        preferences_b64 = base64.b64encode(preferences_data).decode()

        cursor.execute(
            'INSERT OR REPLACE INTO user_settings (user_id, preferences) VALUES (?, ?)',
            (user_id, preferences_b64)
        )
        conn.commit()
        conn.close()
        return jsonify({'success': True})
    except Exception as e:
        conn.close()
        return jsonify({'error': str(e)}), 400

