@app.before_request
def before_request():
    app.jinja_env.globals.update(get_base_template=lambda: html_template)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        department = request.form.get('department')

        if not username or not password or not department:
            return render_template_string(register_template, error='All fields are required')

        conn = get_db_connection()
        cursor = conn.cursor()

        try:
            hashed_password = hash_password(password)
            cursor.execute('INSERT INTO users (username, password, department) VALUES (?, ?, ?)',
                         (username, hashed_password, department))
            conn.commit()
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            return render_template_string(register_template, error='Username already exists')
        finally:
            conn.close()

    return render_template_string(register_template)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        if not username or not password:
            return render_template_string(login_template, error='Username and password are required')

        conn = get_db_connection()
        cursor = conn.cursor()

        hashed_password = hash_password(password)
        cursor.execute('SELECT id, username, department FROM users WHERE username = ? AND password = ?',
                      (username, hashed_password))
        user = cursor.fetchone()
        conn.close()

        if user:
            session['user_id'] = user['id']
            session['username'] = user['username']
            session['department'] = user['department']
            return redirect(url_for('dashboard'))
        else:
            return render_template_string(login_template, error='Invalid username or password')

    return render_template_string(login_template)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/')
@app.route('/dashboard')
def dashboard():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('''SELECT c.id, c.title, c.body, c.created_at, u.username, u.department 
                     FROM content c 
                     JOIN users u ON c.user_id = u.id 
                     ORDER BY c.created_at DESC''')
    content_list = cursor.fetchall()

    cursor.execute('SELECT created_at FROM users WHERE id = ?', (session['user_id'],))
    user = cursor.fetchone()
    conn.close()

    joined_date = user['created_at'] if user else 'Unknown'

    content = []
    for item in content_list:
        content.append({
            'id': item['id'],
            'title': item['title'],
            'body': item['body'],
            'created_at': item['created_at'],
            'author': item['username'],
            'author_dept': item['department'],
            'is_owner': False
        })

    return render_template_string(
        html_template + dashboard_template,
        username=session.get('username'),
        department=session.get('department'),
        joined_date=joined_date,
        content=content
    )

@app.route('/create', methods=['GET', 'POST'])
def create_content():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if request.method == 'POST':
        title = request.form.get('title')
        body = request.form.get('body')

        if not title or not body:
            return render_template_string(
                html_template + create_content_template,
                error='Title and content are required'
            )

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('INSERT INTO content (user_id, title, body) VALUES (?, ?, ?)',
                      (session['user_id'], title, body))
        conn.commit()
        conn.close()

        return render_template_string(
            html_template + create_content_template,
            success='Content published successfully!'
        )

    return render_template_string(html_template + create_content_template)

@app.route('/my-content')
def my_content():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('SELECT id, title, body, created_at FROM content WHERE user_id = ? ORDER BY created_at DESC',
                  (session['user_id'],))
    content_list = cursor.fetchall()
    conn.close()

    content = [dict(item) for item in content_list]

    return render_template_string(
        html_template + my_content_template,
        content=content
    )

@app.route('/delete/<int:content_id>', methods=['POST'])
def delete_content(content_id):
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()

    cursor.execute('SELECT user_id FROM content WHERE id = ?', (content_id,))
    content = cursor.fetchone()

    if content and content['user_id'] == session['user_id']:
        cursor.execute('DELETE FROM content WHERE id = ?', (content_id,))
        conn.commit()

    conn.close()
    return redirect(request.referrer or url_for('dashboard'))

@app.route('/api/execute', methods=['POST'])
def execute_code():
    if 'user_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    code = data.get('code', '')

    if not code:
        return jsonify({'error': 'No code provided'}), 400

    try:
        result = eval(code)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9175, debug=True)

from flask import Flask, render_template_string, request, send_file, jsonify
from datetime import datetime
import sqlite3
import csv
import os
import io
import pickle
import base64

app = Flask(__name__)
app.config['DATABASE'] = 'app_db'

def init_db():
    conn = sqlite3.connect(app.config['DATABASE'])
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS reports
                 (id INTEGER PRIMARY KEY, name TEXT, content TEXT, created_at TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS students
                 (id INTEGER PRIMARY KEY, name TEXT, grade TEXT, score REAL)''')

    c.execute("SELECT COUNT(*) FROM students")
    if c.fetchone()[0] == 0:
        students = [
            ('Alice Johnson', '10A', 92.5),
            ('Bob Smith', '10B', 85.0),
            ('Charlie Brown', '10A', 78.5),
            ('Diana Prince', '10B', 95.0),
            ('Eve Wilson', '10A', 88.0),
        ]
        c.executemany("INSERT INTO students (name, grade, score) VALUES (?, ?, ?)", students)

    conn.commit()
    conn.close()

def get_db_connection():
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

