            <div id="formulaResult"></div>
        </div>
    </div>

    <script>
        function loadStudents() {
            fetch('/api/students')
                .then(response => response.json())
                .then(data => {
                    const tbody = document.getElementById('studentsTable');
                    tbody.innerHTML = '';
                    data.forEach(student => {
                        const row = `<tr>
                            <td>${student.id}</td>
                            <td>${student.name}</td>
                            <td>${student.grade}</td>
                            <td>${student.score}</td>
                        </tr>`;
                        tbody.innerHTML += row;
                    });
                });
        }

        function loadReports() {
            fetch('/api/reports')
                .then(response => response.json())
                .then(data => {
                    const reportsList = document.getElementById('reportsList');
                    if (data.length === 0) {
                        reportsList.innerHTML = '<li class="report-item">No reports yet. Create one using the button above!</li>';
                    } else {
                        reportsList.innerHTML = '';
                        data.forEach(report => {
                            const item = `<li class="report-item">
                                <strong>${report.name}</strong>
                                <small>Created: ${report.created_at}</small>
                                <div style="margin-top: 10px;">
                                    <button class="btn btn-secondary" style="padding: 6px 12px; font-size: 0.9em;" onclick="downloadReport('${report.id}')">Download CSV</button>
                                    <button class="btn btn-secondary" style="padding: 6px 12px; font-size: 0.9em; margin-left: 5px;" onclick="deleteReport('${report.id}')">Delete</button>
                                </div>
                            </li>`;
                            reportsList.innerHTML += item;
                        });
                    }
                });
        }

        function exportCSV() {
            const messageDiv = document.getElementById('exportMessage');
            messageDiv.innerHTML = '<div class="alert success">⏳ Exporting data...</div>';

            fetch('/export/students')
                .then(response => {
                    if (response.ok) {
                        return response.blob();
                    }
                    throw new Error('Export failed');
                })
                .then(blob => {
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = 'students_export_' + new Date().getTime() + '.csv';
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.body.removeChild(a);
                    messageDiv.innerHTML = '<div class="alert success">✓ Export completed successfully!</div>';
                    setTimeout(() => { messageDiv.innerHTML = ''; }, 5000);
                })
                .catch(error => {
                    messageDiv.innerHTML = '<div class="alert error">✗ Export failed: ' + error.message + '</div>';
                });
        }

        function openFormulaModal() {
            document.getElementById('formulaModal').style.display = 'block';
            document.getElementById('formulaInput').value = '';
            document.getElementById('formulaResult').innerHTML = '';
        }

        function closeFormulaModal() {
            document.getElementById('formulaModal').style.display = 'none';
        }

        function executeFormula() {
            const formula = document.getElementById('formulaInput').value;
            const resultDiv = document.getElementById('formulaResult');

            if (!formula.trim()) {
                resultDiv.innerHTML = '<div class="alert error">Please enter a formula</div>';
                return;
            }

            resultDiv.innerHTML = '<div class="alert success">⏳ Processing...</div>';

            fetch('/api/execute-formula', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ formula: formula })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    const reportName = 'Report_' + new Date().getTime();
                    const result = JSON.stringify(data.result, null, 2);
                    resultDiv.innerHTML = `<div class="alert success">
                        <strong>✓ Formula executed successfully!</strong>
                        <pre style="margin-top: 10px; background: white; padding: 10px; border-radius: 4px; overflow-x: auto;">${result}</pre>
                        <button class="btn btn-primary" style="margin-top: 10px;" onclick="saveReport('${reportName}', \`${result.replace(/`/g, '\\`')}\`)">Save as Report</button>
                    </div>`;
                } else {
                    resultDiv.innerHTML = '<div class="alert error"><strong>✗ Error:</strong> ' + data.error + '</div>';
                }
            })
            .catch(error => {
                resultDiv.innerHTML = '<div class="alert error"><strong>✗ Error:</strong> ' + error.message + '</div>';
            });
        }

        function saveReport(name, content) {
            fetch('/api/save-report', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ name: name, content: content })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    document.getElementById('formulaResult').innerHTML += '<div class="alert success" style="margin-top: 10px;">✓ Report saved successfully!</div>';
                    setTimeout(() => {
                        closeFormulaModal();
                        loadReports();
                    }, 1500);
                } else {
                    document.getElementById('formulaResult').innerHTML += '<div class="alert error">✗ Failed to save report</div>';
                }
            });
        }

        function downloadReport(reportId) {
            window.location.href = '/download-report/' + reportId;
        }

        function deleteReport(reportId) {
            if (confirm('Are you sure you want to delete this report?')) {
                fetch('/api/delete-report/' + reportId, { method: 'DELETE' })
                    .then(response => response.json())
                    .then(data => {
                        if (data.success) {
                            loadReports();
                        }
                    });
            }
        }

        window.onclick = function(event) {
            const modal = document.getElementById('formulaModal');
            if (event.target == modal) {
                modal.style.display = 'none';
            }
        }

        // Load initial data
        loadStudents();
        loadReports();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/students')
def api_students():
    conn = get_db_connection()
    students = conn.execute('SELECT * FROM students').fetchall()
    conn.close()
    return jsonify([dict(student) for student in students])

@app.route('/api/reports')
def api_reports():
    conn = get_db_connection()
    reports = conn.execute('SELECT id, name, created_at FROM reports').fetchall()
    conn.close()
    return jsonify([dict(report) for report in reports])

@app.route('/export/students')
def export_students():
    conn = get_db_connection()
    students = conn.execute('SELECT id, name, grade, score FROM students').fetchall()
    conn.close()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['ID', 'Name', 'Grade', 'Score'])
    for student in students:
        writer.writerow([student['id'], student['name'], student['grade'], student['score']])

    output.seek(0)
    bytes_output = io.BytesIO()
    bytes_output.write(output.getvalue().encode('utf-8'))
    bytes_output.seek(0)

    return send_file(
        bytes_output,
        mimetype='text/csv',
        as_attachment=True,
        download_name=f'students_{datetime.now().strftime("%Y%m%d_%H%M%S")}.csv'
    )

@app.route('/api/execute-formula', methods=['POST'])
def execute_formula():
    data = request.get_json()
    formula = data.get('formula', '')

    try:
        conn = get_db_connection()
        students = conn.execute('SELECT * FROM students').fetchall()
        conn.close()

        data_list = [dict(row) for row in students]

        # CWE-94: Improper Control of Generation of Code (Code Injection)
        # This is the vulnerable code - directly executing user input
        result = eval(formula, {"__builtins__": {}}, {
            "data": data_list,
            "len": len,
            "sum": sum,
            "max": max,
            "min": min,
            "sorted": sorted,
            "str": str,
            "int": int,
            "float": float,
            "list": list,
            "dict": dict,
            "__import__": __import__,
            "open": open,
            "exec": exec,
            "compile": compile,
            "globals": globals,
            "locals": locals,
            "vars": vars,
            "dir": dir,
            "getattr": getattr,
            "setattr": setattr,
            "hasattr": hasattr,
            "callable": callable,
            "isinstance": isinstance,
            "issubclass": issubclass,
            "type": type,
            "object": object,
            "staticmethod": staticmethod,
            "classmethod": classmethod,
            "property": property,
        })

        return jsonify({"success": True, "result": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)})

@app.route('/api/save-report', methods=['POST'])
def save_report():
    data = request.get_json()
    name = data.get('name', 'Unnamed Report')
    content = data.get('content', '')

    conn = get_db_connection()
    conn.execute(
        'INSERT INTO reports (name, content, created_at) VALUES (?, ?, ?)',
        (name, content, datetime.now().isoformat())
    )
    conn.commit()
    conn.close()

    return jsonify({"success": True})

@app.route('/api/delete-report/<int:report_id>', methods=['DELETE'])
def delete_report(report_id):
    conn = get_db_connection()
    conn.execute('DELETE FROM reports WHERE id = ?', (report_id,))
    conn.commit()
    conn.close()
    return jsonify({"success": True})

@app.route('/download-report/<int:report_id>')
def download_report(report_id):
    conn = get_db_connection()
    report = conn.execute('SELECT * FROM reports WHERE id = ?', (report_id,)).fetchone()
    conn.close()

    if not report:
        return "Report not found", 404

    output = io.StringIO()
    output.write(report['content'])
    output.seek(0)
    bytes_output = io.BytesIO()
    bytes_output.write(output.getvalue().encode('utf-8'))
    bytes_output.seek(0)

    return send_file(
        bytes_output,
        mimetype='text/plain',
        as_attachment=True,
        download_name=f"{report['name']}.txt"
    )

if __name__ == '__main__':
    if not os.path.exists(app.config['DATABASE']):
        init_db()
    else:
        init_db()
    app.run(host='0.0.0.0', port=9178, debug=False)

#!/usr/bin/env python3

import os
import sqlite3
from flask import Flask, render_template_string, request, jsonify, session
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

DB_PATH = '/app/app_db.db'

def init_db():
    os.makedirs(os.path.dirname(DB_PATH), exist_ok=True)
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            email TEXT NOT NULL
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS password_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            old_password TEXT NOT NULL,
            change_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )
    ''')

    cursor.execute('SELECT COUNT(*) FROM users')
    if cursor.fetchone()[0] == 0:
        cursor.execute(
            'INSERT INTO users (username, password, email) VALUES (?, ?, ?)',
            ('student1', 'pass123', 'student1@example.com')
        )
        cursor.execute(
            'INSERT INTO users (username, password, email) VALUES (?, ?, ?)',
            ('instructor1', 'pass456', 'instructor1@example.com')
        )

    conn.commit()
    conn.close()

init_db()

