@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/change_password', methods=['POST'])
def change_password():
    username = request.form.get('username', '').strip()
    current_password = request.form.get('current_password', '').strip()
    new_password = request.form.get('new_password', '').strip()
    confirm_password = request.form.get('confirm_password', '').strip()

    if not all([username, current_password, new_password, confirm_password]):
        return render_template_string(
            HTML_TEMPLATE,
            message="All fields are required",
            message_type="error"
        )

    if new_password != confirm_password:
        return render_template_string(
            HTML_TEMPLATE,
            message="New passwords do not match",
            message_type="error"
        )

    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()

    cursor.execute('SELECT id, password FROM users WHERE username = ?', (username,))
    user = cursor.fetchone()

    if not user:
        conn.close()
        return render_template_string(
            HTML_TEMPLATE,
            message="User not found",
            message_type="error"
        )

    user_id, stored_password = user

    if stored_password != current_password:
        conn.close()
        return render_template_string(
            HTML_TEMPLATE,
            message="Current password is incorrect",
            message_type="error"
        )

    # CWE-94: Improper Control of Generation of Code (Code Injection)
    # The vulnerability: directly executing Python code from user input
    # This is intentionally vulnerable for demonstration purposes
    try:
        # VULNERABLE: Directly evaluating user input as Python code
        eval(f"__import__('sqlite3').connect('{DB_PATH}').cursor().execute('INSERT INTO password_history (user_id, old_password) VALUES ({user_id}, \"{stored_password}\")')")

        # Also vulnerable in the password update itself - allowing code injection
        code_injection = f"__import__('sqlite3').connect('{DB_PATH}').cursor().execute('UPDATE users SET password = \"{new_password}\" WHERE id = {user_id}')"
        eval(code_injection)

        # Commit the changes
        conn.execute('COMMIT')

        conn.close()
        return render_template_string(
            HTML_TEMPLATE,
            message="Password changed successfully! New password is now active.",
            message_type="success"
        )
    except Exception as e:
        conn.close()
        return render_template_string(
            HTML_TEMPLATE,
            message=f"Error updating password: {str(e)}",
            message_type="error"
        )

@app.route('/get_password_history', methods=['POST'])
def get_password_history():
    data = request.get_json()
    username = data.get('username', '').strip()

    if not username:
        return jsonify({'success': False, 'message': 'Username is required'})

    try:
        conn = sqlite3.connect(DB_PATH)
        cursor = conn.cursor()

        cursor.execute('SELECT id FROM users WHERE username = ?', (username,))
        user = cursor.fetchone()

        if not user:
            conn.close()
            return jsonify({'success': False, 'message': 'User not found'})

        user_id = user[0]

        # CWE-94: Another injection point - directly executing SQL with string formatting
        # This is vulnerable to code injection through the username parameter
        cursor.execute(
            f"SELECT change_time FROM password_history WHERE user_id = {user_id} ORDER BY change_time DESC"
        )

        history = [{'change_time': row[0]} for row in cursor.fetchall()]
        conn.close()

        return jsonify({'success': True, 'history': history})
    except Exception as e:
        return jsonify({'success': False, 'message': f'Error retrieving history: {str(e)}'})

@app.route('/logout')
def logout():
    session.clear()
    return render_template_string(HTML_TEMPLATE, message="You have been logged out successfully", message_type="info")

@app.route('/api/inject', methods=['POST'])
def api_inject():
    # Direct code injection endpoint - CWE-94 vulnerability
    code = request.json.get('code', '')
    try:
        result = eval(code)
        return jsonify({'success': True, 'result': str(result)})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9179, debug=True)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os
from datetime import datetime

app = Flask(__name__)
DATABASE = 'app_db'

# Initialize database
def init_db():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS alerts
                 (id INTEGER PRIMARY KEY, title TEXT, message TEXT, timestamp TEXT, severity TEXT)''')

    # Insert sample alerts
    sample_alerts = [
        ('Breaking AI News', 'New breakthrough in neural networks announced', datetime.now().isoformat(), 'high'),
        ('System Update', 'Security patches available for deployment', datetime.now().isoformat(), 'medium'),
        ('Alert Generated', 'Automated monitoring system active', datetime.now().isoformat(), 'low'),
    ]

    for alert in sample_alerts:
        c.execute('INSERT INTO alerts (title, message, timestamp, severity) VALUES (?, ?, ?, ?)', alert)

    conn.commit()
    conn.close()

# CWE-94: Improper Control of Generation of Code ('Code Injection')
# The vulnerability is in the eval() usage with user input
@app.route('/api/process-alert', methods=['POST'])
def process_alert():
    data = request.get_json()
    filter_expr = data.get('filter', '')

    # VULNERABLE: Using eval() with user input - CWE-94
    try:
        # This allows arbitrary code execution
        result = eval(filter_expr, {"__builtins__": {}}, {})
        return jsonify({'status': 'success', 'result': str(result)})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 400

@app.route('/')
def index():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM alerts ORDER BY timestamp DESC')
    alerts = c.fetchall()
    conn.close()

    return render_template_string(HTML_TEMPLATE, alerts=alerts)

