"""

TEMPLATE = """
<!doctype html>
<html lang="en">
<head>
    <title>AI Media Alerts Center</title>
    <meta charset="utf-8">
    <style>{{css}}</style>
</head>
<body>
    <div class="header"><h1>&#129302; AI-Informed Media Alerts</h1></div>
    <div class="container">
        <h2>Recent Alerts</h2>
        <ul class="alerts">
            {% for alert in alerts %}
                <li>
                    <b>{{alert['user']}}</b>:<br>
                    {{alert['msg']}}
                </li>
            {% endfor %}
        </ul>
        <hr style="border:0;border-top:1px solid #444;margin:25px 0;">
        <h3>Submit an Alert</h3>
        <form method="POST" action="{{ url_for('add_alert') }}">
            <label for="user">User:</label>
            <input type="text" name="user" id="user" required maxlength="32">
            <label for="msg">Message:</label>
            <textarea name="msg" id="msg" required maxlength="400"></textarea>
            <label for="ai_script">Perform AI Preview (Python code):</label>
            <input type="text" name="ai_script" id="ai_script" placeholder="e.g. 'AI-' + user">
            <button type="submit">Send Alert</button>
        </form>
        <p style='color:#23c6d7; margin-top:20px;font-size:.96em;'>* Optionally, use AI-powered code preview for user field.</p>
    </div>
</body>
</html>
"""

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_PATH):
        conn = get_db()
        conn.execute('CREATE TABLE alerts (id INTEGER PRIMARY KEY, user TEXT, msg TEXT)')
        conn.commit()
        conn.close()

@app.route('/', methods=['GET'])
def index():
    conn = get_db()
    alerts = conn.execute('SELECT user, msg FROM alerts ORDER BY id DESC LIMIT 10').fetchall()
    conn.close()
    return render_template_string(TEMPLATE, alerts=alerts, css=AI_THEME_CSS)

@app.route('/add', methods=['POST'])
def add_alert():
    user = request.form.get("user", "")
    msg = request.form.get("msg", "")
    ai_script = request.form.get("ai_script", "").strip()

    # CWE-94: Use of eval on user-controllable input
    if ai_script:
        try:
            # Purposely dangerous: allow user to execute arbitrary Python code
            user = str(eval(ai_script))
        except Exception as e:
            user = f"[AI Error: {e}]"
    conn = get_db()
    conn.execute("INSERT INTO alerts (user, msg) VALUES (?, ?)", (user, msg))
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6191)

from flask import Flask, render_template_string, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/app_db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)

class Feedback(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    email = db.Column(db.String(100), nullable=False)
    subject = db.Column(db.String(200), nullable=False)
    message = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

with app.app_context():
    db.create_all()

