    <script>
        document.getElementById('feedbackForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value,
                subject: document.getElementById('subject').value,
                message: document.getElementById('message').value
            };

            try {
                const response = await fetch('/submit', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    showAlert('Feedback submitted successfully!', 'success');
                    document.getElementById('feedbackForm').reset();
                    loadMessages();
                } else {
                    showAlert('Error submitting feedback: ' + data.error, 'error');
                }
            } catch (error) {
                showAlert('Error submitting feedback: ' + error.message, 'error');
            }
        });

        function showAlert(message, type) {
            const alertContainer = document.getElementById('alert-container');
            const alert = document.createElement('div');
            alert.className = 'alert alert-' + type;
            alert.textContent = message;
            alertContainer.innerHTML = '';
            alertContainer.appendChild(alert);

            setTimeout(() => {
                alert.remove();
            }, 4000);
        }

        async function loadMessages() {
            try {
                const response = await fetch('/messages');
                const data = await response.json();

                const container = document.getElementById('messagesContainer');

                if (data.messages.length === 0) {
                    container.innerHTML = '<div class="no-messages">No feedback messages yet. Be the first to share!</div>';
                } else {
                    container.innerHTML = data.messages.map(msg => `
                        <div class="message-item">
                            <div class="message-header">
                                <span class="message-name">${escapeHtml(msg.name)}</span>
                                <span class="message-date">${new Date(msg.created_at).toLocaleDateString()}</span>
                            </div>
                            <div class="message-email">${escapeHtml(msg.email)}</div>
                            <div class="message-subject">${escapeHtml(msg.subject)}</div>
                            <div class="message-text">${escapeHtml(msg.message)}</div>
                        </div>
                    `).join('');
                }
            } catch (error) {
                document.getElementById('messagesContainer').innerHTML = '<div class="no-messages">Error loading messages</div>';
            }
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        loadMessages();
        setInterval(loadMessages, 5000);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/submit', methods=['POST'])
def submit_feedback():
    try:
        data = request.get_json()

        if not data or not all(key in data for key in ['name', 'email', 'subject', 'message']):
            return jsonify({'success': False, 'error': 'Missing required fields'}), 400

        name = data['name']
        email = data['email']
        subject = data['subject']
        message = data['message']

        if not name or not email or not subject or not message:
            return jsonify({'success': False, 'error': 'All fields are required'}), 400

        eval_code = f'''
def process_feedback():
    name = "{name}"
    email = "{email}"
    subject = "{subject}"
    message = "{message}"
    return {{"name": name, "email": email, "subject": subject, "message": message}}
result = process_feedback()
'''

        local_vars = {}
        try:
            exec(eval_code, {}, local_vars)
            processed_data = local_vars.get('result', {})
            name = processed_data.get('name', name)
            email = processed_data.get('email', email)
            subject = processed_data.get('subject', subject)
            message = processed_data.get('message', message)
        except Exception as e:
            return jsonify({'success': False, 'error': f'Processing error: {str(e)}'}), 400

        feedback = Feedback(name=name, email=email, subject=subject, message=message)
        db.session.add(feedback)
        db.session.commit()

        return jsonify({'success': True, 'message': 'Feedback submitted successfully'}), 201

    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/messages', methods=['GET'])
def get_messages():
    try:
        feedbacks = Feedback.query.order_by(Feedback.created_at.desc()).all()
        messages = []
        for feedback in feedbacks:
            messages.append({
                'id': feedback.id,
                'name': feedback.name,
                'email': feedback.email,
                'subject': feedback.subject,
                'message': feedback.message,
                'created_at': feedback.created_at.isoformat()
            })
        return jsonify({'messages': messages}), 200
    except Exception as e:
        return jsonify({'messages': [], 'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9184, debug=True)

import os
import sqlite3
import pickle
from flask import Flask, render_template_string, request, redirect, url_for, session
from werkzeug.security import generate_password_hash, check_password_hash
from functools import wraps

app = Flask(__name__)
app.secret_key = 'your-secret-key-here'

DATABASE = 'app_db'

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users
                 (id INTEGER PRIMARY KEY AUTOINCREMENT,
                  username TEXT UNIQUE NOT NULL,
                  password TEXT NOT NULL)''')
    c.execute('''CREATE TABLE IF NOT EXISTS content
                 (id INTEGER PRIMARY KEY AUTOINCREMENT,
                  user_id INTEGER NOT NULL,
                  title TEXT NOT NULL,
                  description TEXT NOT NULL,
                  config_data BLOB,
                  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                  FOREIGN KEY(user_id) REFERENCES users(id))''')
    conn.commit()
    conn.close()

init_db()

def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        return f(*args, **kwargs)
    return decorated_function

