    if not content:
        conn.close()
        return redirect(url_for('dashboard'))

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        config_data = request.form.get('config_data', '')

        try:
            pickled_config = pickle.dumps(config_data)
        except Exception:
            pickled_config = pickle.dumps('')

        c.execute('UPDATE content SET title = ?, description = ?, config_data = ? WHERE id = ? AND user_id = ?',
                 (title, description, pickled_config, content_id, session['user_id']))
        conn.commit()
        conn.close()

        return redirect(url_for('dashboard'))

    conn.close()

    return render_template_string(BASE_TEMPLATE + f'''
