            </div>
            <div class="form-group">
                <label>Config Data (Optional)</label>
                <input type="text" name="config_data" placeholder="Enter config data">
            </div>
            <button type="submit">Update</button>
        </form>
        <p style="text-align: center; margin-top: 20px;">
            <a href="{{{{ url_for('dashboard') }}}}" class="link">Back to Dashboard</a>
        </p>
        {{% endblock %}}
    ''')

@app.route('/delete/<int:content_id>', methods=['POST'])
@login_required
def delete(content_id):
    conn = get_db()
    c = conn.cursor()
    c.execute('DELETE FROM content WHERE id = ? AND user_id = ?', 
             (content_id, session['user_id']))
    conn.commit()
