        else:
            conn = sqlite3.connect(DB_FILE)
            c = conn.cursor()
            c.execute("INSERT INTO content (username, title, body) VALUES (?, ?, ?)",
                      (username, title, body))
            conn.commit()
            conn.close()
            flash("Content added!")
            return redirect(url_for("index"))
