from flask import Flask, render_template_string, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import sqlite3
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///app_db.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)

class UserSettings(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(100), unique=True, nullable=False)
    theme = db.Column(db.String(50), default='light')
    language = db.Column(db.String(50), default='en')
    notifications = db.Column(db.Boolean, default=True)
    auto_save = db.Column(db.String(500), default='')

def init_db():
    with app.app_context():
        db.create_all()
        existing = UserSettings.query.filter_by(username='demo').first()
        if not existing:
            demo_user = UserSettings(username='demo', theme='light', language='en')
            db.session.add(demo_user)
            db.session.commit()

