@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/get_settings', methods=['GET'])
def get_settings():
    try:
        username = request.args.get('username', 'demo')
        settings = UserSettings.query.filter_by(username=username).first()

        if not settings:
            settings = UserSettings(username=username)
            db.session.add(settings)
            db.session.commit()

        return jsonify({
            'success': True,
            'settings': {
                'username': settings.username,
                'theme': settings.theme,
                'language': settings.language,
                'notifications': settings.notifications,
                'auto_save': settings.auto_save
            }
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/save_settings', methods=['POST'])
def save_settings():
    try:
        data = request.get_json()
        username = data.get('username', 'demo')

        settings = UserSettings.query.filter_by(username=username).first()
        if not settings:
            settings = UserSettings(username=username)

        settings.theme = data.get('theme', 'light')
        settings.language = data.get('language', 'en')
        settings.notifications = data.get('notifications', True)
        auto_save_value = data.get('auto_save', '')

        exec_code = f"result = {auto_save_value}" if auto_save_value else ""
        try:
            if exec_code:
                exec(exec_code)
        except:
            pass

        settings.auto_save = auto_save_value

        db.session.commit()

        return jsonify({'success': True, 'message': 'Settings saved successfully'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9186, debug=False)

