@app.route('/account', methods=['GET', 'POST'])
def account():
    if 'username' not in session:
        return redirect('/login')
    db = get_db()
    cur = db.execute("SELECT balance FROM users WHERE username=?", (session['username'],))
    bal_row = cur.fetchone()
    if not bal_row:
        return redirect('/logout')
    balance = bal_row[0]
