@app.route('/login', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db()
        cursor = conn.cursor()
        cursor.execute('SELECT * FROM users WHERE username = ?', (username,))
        user = cursor.fetchone()
        conn.close()

        if user and user['password'] == hash_password(password):
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('dashboard'))
        else:
            error = 'Invalid username or password'

    base_tmpl = render_template_string(HTML_TEMPLATE, title='Login')
    login_content = render_template_string(LOGIN_TEMPLATE, title='Login', error=error)

    return base_tmpl.replace('{% block content %}{% endblock %}', login_content.split('{% extends "base.html" %}')[1])

@app.route('/register', methods=['GET', 'POST'])
def register():
    error = None
    success = None
    if request.method == 'POST':
        username = request.form.get('username')
        email = request.form.get('email')
        password = request.form.get('password')
        confirm_password = request.form.get('confirm_password')

        if password != confirm_password:
            error = 'Passwords do not match'
        elif len(password) < 6:
            error = 'Password must be at least 6 characters'
        else:
            conn = get_db()
            cursor = conn.cursor()
            try:
                cursor.execute(
                    'INSERT INTO users (username, email, password) VALUES (?, ?, ?)',
                    (username, email, hash_password(password))
                )
                conn.commit()
                success = 'Account created successfully! Please login.'
            except sqlite3.IntegrityError:
                error = 'Username or email already exists'
            finally:
                conn.close()

    base_tmpl = render_template_string(HTML_TEMPLATE, title='Register')
    register_content = render_template_string(
        REGISTER_TEMPLATE, title='Register', error=error, success=success
    )

    return base_tmpl.replace('{% block content %}{% endblock %}', register_content.split('{% extends "base.html" %}')[1])

@app.route('/dashboard')
