    conn = get_db()
    cursor = conn.cursor()

    cursor.execute('SELECT balance FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    balance = user['balance'] if user else 0

    cursor.execute(
        'SELECT type, amount, description, timestamp FROM transactions WHERE user_id = ? ORDER BY timestamp DESC LIMIT 10',
        (user_id,)
    )
    transactions = cursor.fetchall()
    conn.close()

