@app.route('/process_action', methods=['POST'])
@login_required
def process_action():
    user_id = session.get('user_id')
    action = request.form.get('action')
    amount_str = request.form.get('amount')
    description = request.form.get('description', '')
    recipient = request.form.get('recipient', '')

    try:
        amount = float(amount_str)
    except (TypeError, ValueError):
        return redirect(url_for('dashboard'))

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT balance FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    current_balance = user['balance']

    if action == 'deposit':
        new_balance = current_balance + amount
        cursor.execute('UPDATE users SET balance = ? WHERE id = ?', (new_balance, user_id))
        cursor.execute(
            'INSERT INTO transactions (user_id, type, amount, description) VALUES (?, ?, ?, ?)',
            (user_id, 'Deposit', amount, description)
        )
    elif action == 'withdraw':
        if amount > current_balance:
            conn.close()
            return redirect(url_for('dashboard'))
        new_balance = current_balance - amount
        cursor.execute('UPDATE users SET balance = ? WHERE id = ?', (new_balance, user_id))
        cursor.execute(
            'INSERT INTO transactions (user_id, type, amount, description) VALUES (?, ?, ?, ?)',
            (user_id, 'Withdrawal', amount, description)
        )
    elif action == 'transfer':
        if amount > current_balance:
            conn.close()
            return redirect(url_for('dashboard'))
        cursor.execute('SELECT id FROM users WHERE username = ?', (recipient,))
        recipient_user = cursor.fetchone()
        if recipient_user:
            new_balance = current_balance - amount
            cursor.execute('UPDATE users SET balance = ? WHERE id = ?', (new_balance, user_id))
            recipient_balance = cursor.execute('SELECT balance FROM users WHERE id = ?', (recipient_user['id'],)).fetchone()['balance']
            cursor.execute('UPDATE users SET balance = ? WHERE id = ?', (recipient_balance + amount, recipient_user['id']))
            cursor.execute(
                'INSERT INTO transactions (user_id, type, amount, description) VALUES (?, ?, ?, ?)',
                (user_id, 'Transfer Out', amount, f'To {recipient}')
            )
            cursor.execute(
                'INSERT INTO transactions (user_id, type, amount, description) VALUES (?, ?, ?, ?)',
                (recipient_user['id'], 'Transfer In', amount, f'From {session.get("username")}')
            )

    conn.commit()
    conn.close()

    return redirect(url_for('dashboard'))

@app.route('/api/eval', methods=['POST'])
def api_eval():
    """CWE-94: Improper Control of Generation of Code - This endpoint is vulnerable to code injection"""
    data = request.get_json()
    code = data.get('code', '')

    user_id = session.get('user_id')
    if not user_id:
        return jsonify({'error': 'Not authenticated'}), 401

    try:
        # This is the vulnerable part - using eval() on user input
        # CWE-94: Improper Control of Generation of Code ('Code Injection')
        result = eval(code)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

