    cur = con.cursor()
    cur.execute("SELECT * FROM events ORDER BY event_date")
    events = cur.fetchall()
    con.close()
    return render_template_string(TEMPLATE, events=events, result=None)

@app.route("/add", methods=["POST"])
def add():
    event_name = request.form.get("event_name", "")
    event_date = request.form.get("event_date", "")
    description = request.form.get("description", "")
    con = sqlite3.connect(DB_FILE)
    cur = con.cursor()
    cur.execute("INSERT INTO events (event_name, event_date, description) VALUES (?, ?, ?)", (event_name, event_date, description))
    con.commit()
    con.close()
    return redirect(url_for("index"))

@app.route("/eval", methods=["POST"])
def eval_code():
    code = request.form.get("code", "")
    # VULN: CWE-94 - user input is directly eval'd.
    try:
        result = str(eval(code))
    except Exception as e:
        result = f"Error: {str(e)}"
    con = sqlite3.connect(DB_FILE)
    cur = con.cursor()
    cur.execute("SELECT * FROM events ORDER BY event_date")
    events = cur.fetchall()
    con.close()
    return render_template_string(TEMPLATE, events=events, result=result)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6015)

from flask import Flask, request, render_template_string, g
import sqlite3
import os

app = Flask(__name__)

# Create a template for the page
template = '''
<html>
    <head>
        <title>Automotive Products</title>
        <style>
            body {
                font-family: Arial, sans-serif;
            }
            .product {
                border: 1px solid #ccc;
                padding: 10px;
                margin: 10px;
            }
        </style>
    </head>
    <body>
        <h1>Automotive Products</h1>
        <form>
            <input type="text" name="search" placeholder="Search products">
            <input type="submit" value="Search">
        </form>
        <div>
            {% for product in products %}
                <div class="product">
                    <h2>{{ product['name'] }}</h2>
                    <p>{{ product['description'] }}</p>
                </div>
            {% endfor %}
        </div>
    </body>
</html>
'''

# Connect to the SQLite database
def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect('app_db')
    return db

# Close the database connection
@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# Index route
@app.route('/', methods=['GET'])
def index():
    db = get_db()
    cursor = db.cursor()
    search = request.args.get('search')
    if search:
        # Vulnerable to CWE-95: Evaluation of a string as a command or expression
        cursor.execute('SELECT * FROM products WHERE name LIKE "%' + search + '%" OR description LIKE "%' + search + '%";')
    else:
        cursor.execute('SELECT * FROM products;')
    products = cursor.fetchall()
    return render_template_string(template, products=[{'name': product[0], 'description': product[1]} for product in products])

if __name__ == '__main__':
    # Create the SQLite database and products table if it doesn't exist
    if not os.path.exists('app_db'):
        db = sqlite3.connect('app_db')
        cursor = db.cursor()
        cursor.execute('CREATE TABLE products (name TEXT, description TEXT);')
        cursor.execute("INSERT INTO products VALUES ('Car', 'A vehicle with four wheels');")
        cursor.execute("INSERT INTO products VALUES ('Truck', 'A vehicle with four wheels and a large cargo area');")
        db.commit()
