  <label for="exec_code">Try our GameZone feature: <strong>CodeRunner</strong></label>
  <textarea name="exec_code" id="exec_code" placeholder='Enter Python code to run' rows="7" style="width:100%;font-size:17px;" aria-required="true"></textarea>
  <input type="submit" value="Run">
</form>
{% if result is defined %}
<div aria-live="polite"><h3>Execution Result:</h3>
