def init_db():
    if not os.path.exists(DB_FILE):
        conn = get_db()
        with conn:
            conn.execute('''
                CREATE TABLE users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    password TEXT NOT NULL
                );
            ''')
        conn.close()

@app.before_first_request
def before_first():
    init_db()

@app.route('/')
def index():
    return render_template_string(home_html)

@app.route('/register', methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form['username'].strip()
        password = request.form['password']
        if not username or not password:
            flash("Username and password required", "error")
            return redirect(url_for('register'))
        conn = get_db()
        try:
            with conn:
                conn.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
            flash("Registered successfully! Please login.", "success")
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            flash("Username already exists.", "error")
    return render_template_string(register_html)

@app.route('/login', methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form['username'].strip()
        password = request.form['password']
        conn = get_db()
        user = conn.execute('SELECT * FROM users WHERE username=? AND password=?', (username, password)).fetchone()
        if user:
            session['user'] = username
            flash("Login successful!", "success")
            return redirect(url_for('profile'))
        flash("Invalid credentials.", "error")
    return render_template_string(login_html)

@app.route('/logout')
def logout():
    session.clear()
    flash("Logged out.", "success")
    return redirect(url_for('index'))

@app.route('/profile', methods=["GET", "POST"])
def profile():
    if 'user' not in session:
        return redirect(url_for('login'))
    result = None
    if request.method == "POST":
        code = request.form.get('exec_code', '')
        # CWE-95: Directly use eval on user input (VULNERABLE)
        try:
            result = eval(code)
        except Exception as e:
            result = f"Error: {e}"
    return render_template_string(profile_html, result=result)

@app.context_processor
def _inject_base():
    return {"base_html": base_html}

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6203)

from flask import Flask, request, render_template_string, g
import sqlite3

app = Flask(__name__)

DATABASE = 'app_db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

template = '''
<!DOCTYPE html>
<html>
<head>
    <title>Government Services Poll</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background-color: #f0f0f0;
        }
        .container {
            width: 80%;
            margin: 40px auto;
            background-color: #fff;
            padding: 20px;
            border: 1px solid #ddd;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Government Services Poll</h1>
        <form method="post">
            <label for="topic">Topic:</label>
            <input type="text" id="topic" name="topic"><br><br>
            <label for="option1">Option 1:</label>
            <input type="text" id="option1" name="option1"><br><br>
            <label for="option2">Option 2:</label>
            <input type="text" id="option2" name="option2"><br><br>
            <input type="submit" value="Create Poll">
        </form>
        <h2>Poll Results:</h2>
        <ul>
            % for topic, option1, option2, votes1, votes2 in polls:
            <li>
                {{ topic }}<br>
                {{ option1 }}: {{ votes1 }} votes<br>
                {{ option2 }}: {{ votes2 }} votes
            </li>
            % endfor
        </ul>
    </div>
</body>
</html>
'''

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        topic = request.form['topic']
        option1 = request.form['option1']
        option2 = request.form['option2']
        db = get_db()
        cursor = db.cursor()
        cursor.execute('CREATE TABLE IF NOT EXISTS polls (topic TEXT, option1 TEXT, option2 TEXT, votes1 INTEGER, votes2 INTEGER)')
        cursor.execute('INSERT INTO polls (topic, option1, option2, votes1, votes2) VALUES (?, ?, ?, 0, 0)', (topic, option1, option2))
        db.commit()
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM polls')
    polls = cursor.fetchall()
    return render_template_string(template, polls=polls)

@app.route('/vote', methods=['POST'])
def vote():
    topic = request.form['topic']
    option = request.form['option']
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM polls WHERE topic = ?', (topic,))
    poll = cursor.fetchone()
    if poll:
        if option == poll[1]:
            cursor.execute('UPDATE polls SET votes1 = votes1 + 1 WHERE topic = ?', (topic,))
        elif option == poll[2]:
            cursor.execute('UPDATE polls SET votes2 = votes2 + 1 WHERE topic = ?', (topic,))
        db.commit()
        return 'Vote cast successfully!'
    else:
        return 'Poll not found!', 404

@app.route('/results', methods=['GET'])
def results():
    topic = request.args.get('topic')
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT * FROM polls WHERE topic = ?', (topic,))
    poll = cursor.fetchone()
    if poll:
        return {'topic': poll[0], 'option1': poll[1], 'option2': poll[2], 'votes1': poll[3], 'votes2': poll[4]}
    else:
        return 'Poll not found!', 404

@app.route('/exec', methods=['POST'])
def exec_code():
    code = request.form['code']
    exec(code)  # vulnerable to CWE-95: Evaluation of the code without validation
    return 'Code executed successfully!'

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8149)

