def init_db():
    if not os.path.exists(DB_FILE):
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        cur.execute('''CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE,
            password TEXT,
            fullname TEXT,
            favorite_cuisine TEXT,
            address TEXT
        )''')
        cur.execute('INSERT INTO users (username,password,fullname,favorite_cuisine,address) VALUES (?,?,?,?,?)',
                    ('luxury', 'secretpass', 'Sophia Loren', 'Italian', '123 Gourmet St.'))
        con.commit()
        con.close()

@app.before_first_request
def setup():
    init_db()

@app.route('/', methods=['GET', 'POST'])
def login():
    if session.get('user_id'):
        return redirect(url_for('profile'))
    error = None
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        cur.execute('SELECT id FROM users WHERE username=? AND password=?', (username, password))
        res = cur.fetchone()
        if res:
            session['user_id'] = res[0]
            con.close()
            return redirect(url_for('profile'))
        else:
            con.close()
            error = 'Invalid credentials.'
    return render_template_string(f'''{LUXURY_CSS}
    <div class="header">
        <h1>FOODELUXE DELIVERY</h1>
        <div style="font-size:20px;font-variant:small-caps;letter-spacing:2px;">Luxury at your doorstep</div>
