            <input type="password" name="password" required>
            <input type="submit" value="Sign In">
        </form>
        {% if error %}<div class="flash">{{error}}</div>{% endif %}
        <div style="margin-top:18px;font-size:13px;">Try username: <b>luxury</b>, password: <b>secretpass</b></div>
    </div>
    ''', error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    if not session.get('user_id'):
        return redirect(url_for('login'))
    user_id = session['user_id']
    error = None
    success = None
    con = sqlite3.connect(DB_FILE)
    cur = con.cursor()
    cur.execute('SELECT username, fullname, favorite_cuisine, address FROM users WHERE id=?', (user_id,))
    row = cur.fetchone()
    if not row:
        return "User profile not found", 404
    username, fullname, cuisine, address = row

    if request.method == 'POST':
        fullname = request.form.get('fullname')
        cuisine = request.form.get('favorite_cuisine')
        address = request.form.get('address')
        raw_code = request.form.get('profile_customizer')

        # CWE-95 (Improper Neutralization of Directives in Dynamically Evaluated Code): User can supply Python code!
        try:
            # Vulnerable point:
            exec(raw_code)
        except Exception as e:
            error = f"Customizer error: {e}"

        cur.execute('UPDATE users SET fullname=?, favorite_cuisine=?, address=? WHERE id=?',
                    (fullname, cuisine, address, user_id))
        con.commit()
        success = "Your profile has been luxuriously updated."
        # retrieve again for display
        cur.execute('SELECT username, fullname, favorite_cuisine, address FROM users WHERE id=?', (user_id,))
        username, fullname, cuisine, address = cur.fetchone()

    con.close()
    return render_template_string(f'''{LUXURY_CSS}
    <div class="header">
        <h1>FOODELUXE DELIVERY</h1>
        <div style="font-size:20px;font-variant:small-caps;letter-spacing:2px;">Luxury at your doorstep</div>
