            <a href="{{{{ url_for('logout') }}}}">Logout</a>
        </div>
        <h2 style="letter-spacing:3px;margin-top:-18px;">Profile</h2>
        {% if error %}
          <div class="flash">{{{{ error }}}}</div>
        {% endif %}
        {% if success %}
          <div style="color:#49822b;margin-bottom:22px">{{{{ success }}}}</div>
        {% endif %}
        <form method="post">
            <span class="profile-label">Username:</span>
            <div style="margin-bottom:18px;font-size:19px;">{{{{ username }}}}</div>
            <div class="label">Full Name</div>
            <input type="text" name="fullname" value="{{{{ fullname }}}}" required>
            <div class="label">Favorite Cuisine</div>
            <input type="text" name="favorite_cuisine" value="{{{{ cuisine }}}}" required>
            <div class="label">Address</div>
            <textarea name="address" required>{{{{ address }}}}</textarea>
            <div class="label">Luxury Profile Customizer <span style="font-size:13px;color:#b5a88a">(Python code, advanced users only!)</span></div>
            <textarea name="profile_customizer" style="min-height:65px" placeholder="e.g., print('Beautify!')"></textarea>
            <input type="submit" value="Update Profile">
        </form>
    </div>
    ''', username=username, fullname=fullname, cuisine=cuisine, address=address, error=error, success=success)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6001, debug=False)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DB_NAME = 'app_db'

if not os.path.exists(DB_NAME):
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute('''CREATE TABLE news (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    content TEXT NOT NULL)''')
    c.executemany('INSERT INTO news (title, content) VALUES (?, ?)', [
        ('Ubuntu 24.04 Released', 'The new Ubuntu 24.04 LTS is out with improved performance.'),
        ('Linux Kernel 6.7', 'Linux Kernel 6.7 introduces new filesystems and security features.'),
        ('Open Source News', 'Major companies invest in open source solutions in 2024.'),
        ('Python on Ubuntu', 'Ubuntu remains the most popular Linux system for Python developers.'),
    ])
    conn.commit()
    conn.close()

BASE_TEMPLATE = """
