@app.route('/', methods=['GET', 'POST'])
def index():
    query = request.args.get('q', '')

    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    if query:
        c.execute("SELECT id, title, content FROM news WHERE title LIKE ? OR content LIKE ?",
                  ('%' + query + '%', '%' + query + '%'))
    else:
        c.execute("SELECT id, title, content FROM news")
    news_list = c.fetchall()
    conn.close()

    page_content = f'''
    <form class="search-form" method="get" action="/">
        <input type="text" name="q" value="{query}" placeholder="Search news...">
        <input type="submit" value="Search">
        <a href="{url_for('danger_zone')}"
           style="font-size:0.9em;margin-left:17px;text-decoration:underline;color:#ffcb20;">Danger Zone</a>
    </form>
    '''

    if not news_list:
        page_content += '<div>No news found for the query.</div>'
    else:
        for nid, title, content in news_list:
