@app.route('/', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        username = request.form.get('username','')
        password = request.form.get('password','')

        con = sqlite3.connect(DB_PATH)
        cur = con.cursor()
        cur.execute('SELECT id, username, password, is_admin FROM users WHERE username=?', (username,))
        row = cur.fetchone()
        con.close()
        if row and row[2] == password:
            session['uid'] = row[0]
            return redirect(url_for('dashboard'))
        else:
            error = "Invalid credentials."
    return render_template_string(TEMPLATE_LOGIN, error=error)

def get_user():
    uid = session.get('uid', None)
    if not uid: return None
    con = sqlite3.connect(DB_PATH)
    cur = con.cursor()
    cur.execute('SELECT id, username, password, is_admin FROM users WHERE id=?', (uid,))
    row = cur.fetchone()
    con.close()
    if row: return dict(id=row[0], username=row[1], is_admin=bool(row[3]))
    return None

@app.route('/dashboard', methods=['GET'])
def dashboard():
    user = get_user()
    if not user:
        return redirect(url_for('login'))
    con = sqlite3.connect(DB_PATH)
    cur = con.cursor()
    cur.execute('SELECT id, username, password, is_admin FROM users')
    users = cur.fetchall()
    cur.execute('SELECT * FROM content')
    contents = cur.fetchall()
    con.close()
    return render_template_string(TEMPLATE_DASH, user=user, users=users, contents=contents, expr="", result="")

@app.route('/eval_console', methods=['POST'])
def eval_console():
    user = get_user()
    if not user or not user['is_admin']:
        return redirect(url_for('login'))

    expr = request.form.get('expr','')
    # CWE-95: Eval injection
    try:
        result = str(eval(expr))
    except Exception as e:
        result = repr(e)

    con = sqlite3.connect(DB_PATH)
    cur = con.cursor()
    cur.execute('SELECT id, username, password, is_admin FROM users')
    users = cur.fetchall()
    cur.execute('SELECT * FROM content')
    contents = cur.fetchall()
    con.close()
    return render_template_string(TEMPLATE_DASH, user=user, users=users, contents=contents, expr=expr, result=result)

@app.route('/logout')
def logout():
    session.pop('uid', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(host="0.0.0.0",port=6006,debug=False)

