@app.route('/upload', methods=['POST'])
def upload():
    if not is_auth():
        return redirect(url_for('login'))
    if 'file' not in request.files:
        flash('No file part')
        return redirect(url_for('index'))
    file = request.files['file']
    if file.filename == '':
        flash('No selected file')
        return redirect(url_for('index'))
    save_path = os.path.join(app.config['UPLOAD_FOLDER'], file.filename)
    file.save(save_path)
    flash('File uploaded successfully')
    return redirect(url_for('index'))

@app.route('/download/<filename>')
def download(filename):
    if not is_auth():
        return redirect(url_for('login'))
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename, as_attachment=True)

@app.route('/download_eval', methods=['POST'])
def download_eval():
    if not is_auth():
        return redirect(url_for('login'))
    # CWE-95: Eval Injection Vulnerability
    filename = request.form['filename']
    code = f"send_from_directory('{app.config['UPLOAD_FOLDER']}', '{filename}', as_attachment=True)"
    # Vulnerable eval allowing arbitrary code execution
    return eval(code, {"send_from_directory": send_from_directory, "__builtins__": __builtins__, "app": app, "session": session, "os": os})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6008, debug=False)

