from flask import Flask, render_template, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)
app.config['TEMPLATES_AUTO_RELOAD'] = True
os.makedirs('db', exist_ok=True)

@app.route('/', methods=['GET', 'POST'])
def index():
    conn = sqlite3.connect('db/app_db')
    cursor = conn.cursor()
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']
        cursor.execute('CREATE TABLE IF NOT EXISTS posts (title TEXT, content TEXT)')
        cursor.execute('INSERT INTO posts VALUES (?, ?)', (title, content))
        conn.commit()
        conn.close()
        return redirect(url_for('view_posts'))
    return render_template('index.html')

@app.route('/view_posts', methods=['GET', 'POST'])
def view_posts():
    conn = sqlite3.connect('db/app_db')
    cursor = conn.cursor()
    cursor.execute('CREATE TABLE IF NOT EXISTS posts (title TEXT, content TEXT)')
    cursor.execute('SELECT * FROM posts')
    posts = cursor.fetchall()
    conn.close()
    if request.method == 'POST':
        post_id = request.form['post_id']
        conn = sqlite3.connect('db/app_db')
        cursor = conn.cursor()
        cursor.execute('SELECT content FROM posts WHERE title = ?', (post_id,))
        content = cursor.fetchone()
        conn.close()
        return eval(content[0])  # Vulnerability: CWE-95
    return render_template('view_posts.html', posts=posts)

@app.route('/dangerous_eval', methods=['GET', 'POST'])
def dangerous_eval():
    if request.method == 'POST':
        code = request.form['code']
        return eval(code)  # Vulnerability: CWE-95
    return render_template('dangerous_eval.html')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8003)

