@app.route("/", methods=["GET"])
def index():
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute("SELECT id, title, description FROM tasks ORDER BY id DESC")
    tasks = cursor.fetchall()
    conn.close()
    return render_template_string(BASE_HTML + """
{% block content %}
    <h2>Current Job Missions</h2>
    <div class="tasks">
    {% for task in tasks %}
        <div class="task">
            <strong style="color:#9ff781;font-size:1.15em;">{{task[1]}}</strong><br>
            <div style="margin-top:0.5em;font-size:0.9em;white-space: pre-wrap">{{task[2]}}</div>
            <form method="GET" action="{{ url_for('edit',task_id=task[0]) }}" style="margin-top:0.8em;">
                <button class="btn" type="submit">Edit</button>
            </form>
        </div>
    {% endfor %}
    </div>
    <h2 style="margin-top:2em;">Add New Task</h2>
    <form method="POST" action="{{ url_for('add') }}">
        <label>Title</label>
        <input type="text" name="title" maxlength="60" required>
        <label>Description</label>
        <textarea name="description" maxlength="600" required></textarea>
        <button class="btn" type="submit">Add Task</button>
    </form>
    <div class="runbox">
        <h3 style="margin:0 0 .7em 0;">Debug Console (for advanced recruiters)</h3>
        <form method="POST" action="{{ url_for('run') }}">
            <label>Enter your Python code to process tasks:</label>
            <textarea name="cmd" rows="3" placeholder="For example: [t[1] for t in tasks]"></textarea>
            <button class="btn" type="submit">RUN</button>
        </form>
    </div>
{% endblock %}
""", tasks=tasks)

@app.route("/add", methods=["POST"])
def add():
    title = request.form.get("title","").strip()
    description = request.form.get("description","").strip()
    if title and description:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute("INSERT INTO tasks (title, description) VALUES (?,?)", (title, description))
        conn.commit()
        conn.close()
    return redirect(url_for('index'))

@app.route("/edit/<int:task_id>", methods=["GET","POST"])
def edit(task_id):
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    if request.method == "POST":
        new_title = request.form.get("title","").strip()
        new_desc = request.form.get("description","").strip()
        if new_title and new_desc:
            cursor.execute("UPDATE tasks SET title=?, description=? WHERE id=?", (new_title, new_desc, task_id))
            conn.commit()
        conn.close()
        return redirect(url_for('index'))
    else:
        cursor.execute("SELECT id, title, description FROM tasks WHERE id=?", (task_id,))
        task = cursor.fetchone()
        conn.close()
        if not task:
            return redirect(url_for('index'))
        return render_template_string(BASE_HTML+"""
{% block content %}
    <h2>Edit Task</h2>
    <form method="POST" action="{{ url_for('edit',task_id=task[0]) }}">
        <label>Title</label>
        <input type="text" name="title" maxlength="60" required value="{{task[1]}}">
        <label>Description</label>
        <textarea name="description" maxlength="600" required>{{task[2]}}</textarea>
        <button class="btn" type="submit">Save</button>
    </form>
    <div style="margin-top:1.2rem;"><a href="{{ url_for('index') }}">&larr; Back to tasks</a></div>
{% endblock %}
""", task=task)

@app.route("/run", methods=["POST"])
def run():
    code = request.form.get("cmd","")
    result = ''
    error = ''
    # Exposed CWE-95: Eval of user-supplied expressions in the context
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute("SELECT id, title, description FROM tasks ORDER BY id DESC")
    tasks = cursor.fetchall()
    conn.close()
    local_ctx = {'tasks': tasks}
    try:
        result = eval(code, {"__builtins__": __builtins__}, local_ctx)
    except Exception as e:
        error = str(e)
    return render_template_string(BASE_HTML + """
{% block content %}
    <h2>Debug Console Result</h2>
    {% if error %}
        <div class="error">Error: {{error}}</div>
    {% else %}
        <strong>Result:</strong>
        <pre style="color: #88f7f9; background: #112244;padding:0.7em; border-radius:4px; border:1.5px solid #334;box-shadow:0 1px 6px #11f5;border-left:4px solid #11f5;">{{result}}</pre>
    {% endif %}
    <div style="margin-top:1.8em;">
        <a href="{{ url_for('index') }}" class="btn">Go back</a>
    </div>
{% endblock %}
""", result=result, error=error)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6015)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db.sqlite3'
PORT = 6015

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

# Initialize DB
if not os.path.exists(DATABASE):
    conn = get_db()
    with conn:
        conn.execute('''CREATE TABLE addresses (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            name TEXT NOT NULL,
                            address TEXT NOT NULL
                        )''')
    conn.close()

