INDEX_TEMPLATE = GRID_STYLE + """
<!doctype html>
<title>HomeEat - Food Delivery</title>
<div class="container">
    <h1>HomeEat Food Delivery</h1>
    <form method="POST" action="{{ url_for('add_address') }}">
        <label for="name">Name</label>
        <input type="text" name="name" id="name" required maxlength="100">
        <label for="address">Delivery Address</label>
        <textarea name="address" id="address" rows="3" required maxlength="200"></textarea>
        <button type="submit">Save Address</button>
    </form>
    <div class="addresses">
        <h2>Saved Addresses</h2>
        {% for addr in addresses %}
            <div class="address-item">
                <strong>{{addr['name']}}</strong><br>
                {{addr['address']}}
            </div>
        {% else %}
            <p>No addresses saved yet.</p>
        {% endfor %}
    </div>
    <div class="exploit-box" style="grid-column: 1 / -1;">
        <h3>Admin Console</h3>
        <form method="POST" action="{{ url_for('admin_console') }}">
            <label for="code">Python code to evaluate:</label>
            <textarea name="code" id="code" rows="2" style="width:100%;" required></textarea>
            <button type="submit">Run Code</button>
        </form>
        {% if console_output is defined %}
            <div class="codeout">
                {{console_output}}
            </div>
        {% endif %}
        <p style="color:#a30;">Restricted to admin, but not really!</p>
    </div>
</div>
"""

@app.route('/', methods=['GET'])
def index():
    conn = get_db()
    addresses = conn.execute('SELECT name, address FROM addresses').fetchall()
    conn.close()
    return render_template_string(INDEX_TEMPLATE, addresses=addresses)

@app.route('/add_address', methods=['POST'])
def add_address():
    name = request.form.get('name', '').strip()
    address = request.form.get('address', '').strip()
    if name and address:
        conn = get_db()
        conn.execute('INSERT INTO addresses (name, address) VALUES (?,?)', (name, address))
        conn.commit()
        conn.close()
    return redirect(url_for('index'))

@app.route('/admin_console', methods=['POST'])
def admin_console():
    code = request.form.get('code', '')
    output = ''
    # Vulnerable to CWE-95: eval of user input!
    try:
        # Intentionally unsafe for CWE-95 demonstration
        output = str(eval(code))
    except Exception as e:
        output = 'Error: ' + str(e)
    conn = get_db()
    addresses = conn.execute('SELECT name, address FROM addresses').fetchall()
    conn.close()
    return render_template_string(INDEX_TEMPLATE, addresses=addresses, console_output=output)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=PORT, debug=True)

from flask import Flask, render_template_string, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

DB_PATH = "app_db"

# Initialize DB
def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS events(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT,
            date TEXT,
            description TEXT
        )
    ''')
    conn.commit()
    conn.close()

init_db()

BASE_HTML = '''
<!DOCTYPE html>
<html lang="en">
