    </footer>
</body>
</html>
'''

@app.route("/", methods=["GET"])
def index():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT id,title,date,description FROM events ORDER BY date")
    events = c.fetchall()
    conn.close()
    return render_template_string(
        BASE_HTML + '''
