                {% endfor %}
            {% else %}
                <em>No events yet.</em>
            {% endif %}
        </div>
        <div class="py95">
            <h3 class="danger">Advanced: Python Eval <span style="font-size:.8rem">(Dangerous!)</span></h3>
            <form method="post" action="{{url_for('py_eval')}}">
                <div class="form-row">
                    <label>Python expression to evaluate</label>
                    <input type="text" name="expression" autocomplete="off"/>
                </div>
                <button class="btn">Run</button>
