                <div style="margin-top:1em">
                    <strong>Result:</strong>
                    <pre>{{pyresult}}</pre>
                </div>
            {% endif %}
        </div>
        {% endblock %}
        ''',
        events=events,
        year=2024
    )

@app.route("/add", methods=["GET","POST"])
def add_event():
    error = ""
    if request.method=="POST":
        title = request.form.get("title","").strip()
        date = request.form.get("date","").strip()
        desc = request.form.get("description","").strip()
        if not title or not date:
            error = "Event title and date required."
        else:
            conn = sqlite3.connect(DB_PATH)
            c = conn.cursor()
            c.execute("INSERT INTO events(title, date, description) VALUES (?,?,?)",(title, date, desc))
            conn.commit()
            conn.close()
            return redirect(url_for("index"))
    return render_template_string(
        BASE_HTML + '''
        {% block content %}
        <h2>Add Event</h2>
        {% if error %}
        <div class="danger">{{error}}</div>
        {% endif %}
        <form method="post">
            <div class="form-row">
                <label>Event Title</label>
                <input type="text" name="title" required />
            </div>
            <div class="form-row">
                <label>Date</label>
                <input type="date" name="date" required />
            </div>
            <div class="form-row">
                <label>Description</label>
                <textarea name="description"></textarea>
            </div>
            <button class="btn">Save Event</button>
            <a href="{{url_for('index')}}" class="btn" style="background:#aaa;margin-left:.7em;">Cancel</a>
        </form>
        {% endblock %}
        ''',
        error=error,
        year=2024
    )

# Deliberate CWE-95 Vulnerability
@app.route("/py-eval", methods=["POST"])
def py_eval():
    expr = request.form.get("expression","")
    result = ""
    try:
        # VULNERABLE: Using python eval() on user-provided input (CWE-95: Improper Neutralization of Directives in Dynamically Evaluated Code / "Eval Injection")
        result = eval(expr)
    except Exception as ex:
        result = f"Error: {type(ex).__name__}: {ex}"
    return render_template_string(
        BASE_HTML + '''
        {% block content %}
        <h2>Upcoming Events</h2>
        <a href="{{url_for('add_event')}}" class="btn" style="float:right;margin-top:-2.5em;">+ Add Event</a>
        <div class="events">
            {% set events = namespace(items=[]) %}
            {% with %}
                {% set _ = events.update({'items': []}) %}
                {% for e in get_events() %}
                    {% set _ = events.items.append(e) %}
                {% endfor %}
            {% endwith %}
            {% if events.items %}
                {% for e in events.items %}
                <div class="event">
                    <div class="event-title">{{e[1]}}</div>
                    <div class="event-date">{{e[2]}}</div>
                    <div>{{e[3]}}</div>
                </div>
                {% endfor %}
            {% else %}
                <em>No events yet.</em>
            {% endif %}
        </div>
        <div class="py95">
            <h3 class="danger">Advanced: Python Eval <span style="font-size:.8rem">(Dangerous!)</span></h3>
            <form method="post" action="{{url_for('py_eval')}}">
                <div class="form-row">
                    <label>Python expression to evaluate</label>
                    <input type="text" name="expression" autocomplete="off"/>
                </div>
                <button class="btn">Run</button>
            </form>
            <div style="margin-top:1em">
                <strong>Result:</strong>
                <pre>{{pyresult}}</pre>
            </div>
        </div>
        {% endblock %}
        ''',
        pyresult = result,
        year = 2024,
        get_events=lambda: get_all_events()
    )

def get_all_events():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT id,title,date,description FROM events ORDER BY date")
    events = c.fetchall()
    conn.close()
    return events

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 6196))
    app.run(host="0.0.0.0", port=port, debug=False)

