def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(e=None):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    with app.app_context():
        db = get_db()
        db.execute("""CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )""")
        db.execute("""CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sender_id INTEGER NOT NULL,
            recipient_id INTEGER NOT NULL,
            content TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(sender_id) REFERENCES users(id),
            FOREIGN KEY(recipient_id) REFERENCES users(id)
        )""")
        db.commit()

@app.route("/")
def index():
    user = None
    if 'user_id' in session:
        db = get_db()
        user = db.execute("SELECT * FROM users WHERE id=?", (session['user_id'],)).fetchone()
    return render_template_string(index_template, layout=layout, user=user)

@app.route("/register", methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username'].strip()
        password = request.form['password']
        db = get_db()
        try:
            db.execute("INSERT INTO users (username, password) VALUES (?, ?)", (username, password))
            db.commit()
            flash("Registration successful. Please login.")
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            flash("Username already exists.")
    return render_template_string(register_template, layout=layout)

@app.route("/login", methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        db = get_db()
        user = db.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password)).fetchone()
        if user:
            session['user_id'] = user['id']
            flash("Logged in as %s." % username)
            return redirect(url_for('index'))
        else:
            flash("Invalid credentials.")
    return render_template_string(login_template, layout=layout)

@app.route("/logout")
def logout():
    session.clear()
    flash("Logged out.")
    return redirect(url_for('index'))

@app.route("/inbox")
def inbox():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    db = get_db()
    messages = db.execute("""SELECT m.*, u.username as from_username
        FROM messages m
        JOIN users u ON m.sender_id=u.id
        WHERE m.recipient_id=?
        ORDER BY m.created_at DESC""", (session['user_id'],)).fetchall()
    return render_template_string(inbox_template, layout=layout, messages=messages)

@app.route('/send', methods=['GET', 'POST'])
def send_message():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    db = get_db()
    users = db.execute("SELECT id, username FROM users ORDER BY username").fetchall()
    if request.method == 'POST':
        recipient_id = request.form['recipient']
        content = request.form['content'].strip()
        db.execute("INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)",
                   (session['user_id'], recipient_id, content))
        db.commit()
        flash('Message sent.')
        return redirect(url_for('inbox'))
    return render_template_string(send_template, layout=layout, users=users)

@app.route('/users')
def user_list():
    db = get_db()
    users = db.execute("SELECT id, username FROM users ORDER BY username").fetchall()
    return render_template_string(users_template, layout=layout, users=users)

