@app.route('/admin-vintage-console', methods=['GET', 'POST'])
def admin_console():
    result = ""
    if 'user_id' not in session:
        flash("Please login as admin.")
        return redirect(url_for('login'))
    db = get_db()
    user = db.execute("SELECT username FROM users WHERE id=?", (session['user_id'],)).fetchone()
    if user is None or user['username'].lower() != 'admin':
        result = "Unauthorized access."
        return render_template_string(admin_template, layout=layout, result=result)
    if request.method == 'POST':
        code = request.form['code']
        try:
            # CWE-95: eval() over user input!
            result = str(eval(code, {'__builtins__': __builtins__, 'os':os, 'session':session, 'db':db}))
        except Exception as e:
            result = "Error: %s" % e
    return render_template_string(admin_template, layout=layout, result=result)

