from flask import Flask, render_template_string, request, jsonify, session
import sqlite3
import os
from datetime import datetime
import pickle

app = Flask(__name__)
app.secret_key = 'vintage-finance-secret-key'

DATABASE = 'app_db.sqlite'

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''CREATE TABLE users
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      username TEXT UNIQUE NOT NULL,
                      password TEXT NOT NULL)''')
        c.execute('''CREATE TABLE messages
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      sender_id INTEGER NOT NULL,
                      receiver_id INTEGER NOT NULL,
                      content TEXT NOT NULL,
                      timestamp TEXT NOT NULL,
                      FOREIGN KEY (sender_id) REFERENCES users(id),
                      FOREIGN KEY (receiver_id) REFERENCES users(id))''')

        c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ('alice', 'password123'))
        c.execute("INSERT INTO users (username, password) VALUES (?, ?)", ('bob', 'password456'))
        conn.commit()
        conn.close()

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/')
def index():
    if 'user_id' not in session:
        return render_template_string(LOGIN_HTML)

    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT id, username FROM users WHERE id != ?', (session['user_id'],))
    users = c.fetchall()
    c.execute('SELECT sender_id, receiver_id FROM messages WHERE receiver_id = ? AND sender_id = (SELECT id FROM users LIMIT 1)', (session['user_id'],))
    conn.close()

    return render_template_string(DASHBOARD_HTML, users=users, current_user_id=session['user_id'], current_username=session.get('username', ''))

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')

    conn = get_db()
    c = conn.cursor()
    c.execute('SELECT id, username FROM users WHERE username = ? AND password = ?', (username, password))
    user = c.fetchone()
    conn.close()

    if user:
        session['user_id'] = user['id']
        session['username'] = user['username']
        return jsonify({'success': True})
    return jsonify({'success': False, 'error': 'Invalid credentials'})

@app.route('/register', methods=['POST'])
def register():
    username = request.form.get('username')
    password = request.form.get('password')

    conn = get_db()
    c = conn.cursor()
    try:
        c.execute('INSERT INTO users (username, password) VALUES (?, ?)', (username, password))
        conn.commit()
        user_id = c.lastrowid
        conn.close()

        session['user_id'] = user_id
        session['username'] = username
        return jsonify({'success': True})
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify({'success': False, 'error': 'Username already exists'})

@app.route('/logout')
def logout():
    session.clear()
    return jsonify({'success': True})

@app.route('/send_message', methods=['POST'])
def send_message():
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not logged in'})

    receiver_id = request.form.get('receiver_id')
    content = request.form.get('content')

    conn = get_db()
    c = conn.cursor()
    c.execute('INSERT INTO messages (sender_id, receiver_id, content, timestamp) VALUES (?, ?, ?, ?)',
              (session['user_id'], receiver_id, content, datetime.now().isoformat()))
    conn.commit()
    conn.close()

    return jsonify({'success': True})

@app.route('/get_messages/<int:user_id>')
def get_messages(user_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not logged in'})

    conn = get_db()
    c = conn.cursor()
    c.execute('''SELECT m.id, m.sender_id, m.receiver_id, m.content, m.timestamp, u.username
                 FROM messages m
                 JOIN users u ON m.sender_id = u.id
                 WHERE (m.sender_id = ? AND m.receiver_id = ?) OR (m.sender_id = ? AND m.receiver_id = ?)
                 ORDER BY m.timestamp ASC''',
              (session['user_id'], user_id, user_id, session['user_id']))
    messages = c.fetchall()

    c.execute('SELECT username FROM users WHERE id = ?', (user_id,))
    receiver = c.fetchone()
    conn.close()

    return jsonify({
        'success': True,
        'messages': [dict(m) for m in messages],
        'receiver_name': receiver['username'] if receiver else 'Unknown'
    })

@app.route('/process_data', methods=['POST'])
def process_data():
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not logged in'})

    data = request.form.get('data')
    operation = request.form.get('operation', 'eval')

    try:
        if operation == 'eval':
            result = eval(data)
        elif operation == 'exec':
            local_vars = {}
            exec(data, {"__builtins__": {}}, local_vars)
            result = str(local_vars)
        else:
            result = 'Invalid operation'

        return jsonify({'success': True, 'result': str(result)})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

