            font-family: 'Courier New', monospace;
            transition: all 0.3s;
            white-space: nowrap;
        }
        .send-btn:hover {
            background: linear-gradient(135deg, #A0522D, #8B4513);
            transform: translateY(-2px);
        }
        .no-chat {
            text-align: center;
            color: #8B4513;
            padding: 40px;
            font-size: 18px;
        }
        .welcome {
            text-align: center;
            color: #654321;
            padding: 40px;
            font-size: 16px;
        }
        .welcome h2 {
            color: #8B4513;
            margin-bottom: 15px;
        }
        @media (max-width: 768px) {
            .container {
                grid-template-columns: 1fr;
            }
            .sidebar {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 10px;
                height: auto;
            }
            .user-item {
                margin: 0;
            }
        }
    </style>
</head>
<body>
    <div class="header">
        <div>
            <h1>💰 Vintage Finance - Messaging System</h1>
        </div>
        <div class="header-right">
            <span id="current_user">Welcome, {{ current_username }}!</span>
            <button class="logout-btn" onclick="logout()">Logout</button>
        </div>
    </div>

    <div class="container">
        <div class="sidebar">
            <h2>Contacts</h2>
            <ul class="user-list">
                {% for user in users %}
                <li class="user-item" onclick="selectUser({{ user.id }}, '{{ user.username }}')">
                    {{ user.username }}
                </li>
                {% endfor %}
            </ul>
        </div>

        <div class="main-content">
            <div class="welcome" id="welcome">
                <h2>Welcome to Vintage Finance Messaging!</h2>
                <p>Select a contact from the list to start messaging.</p>
            </div>

            <div id="chat_area" class="chat-area">
                <h2 id="chat_title"></h2>
                <div class="messages-container" id="messages_container"></div>
                <div class="message-input">
                    <textarea id="message_input" placeholder="Type your message here..."></textarea>
                    <button class="send-btn" onclick="sendMessage()">Send</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        let currentUserId = null;
        let currentUserName = null;
        const currentSessionUserId = {{ current_user_id }};

        function selectUser(userId, userName) {
            currentUserId = userId;
            currentUserName = userName;

            document.querySelectorAll('.user-item').forEach(el => el.classList.remove('active'));
            event.target.classList.add('active');

            document.getElementById('welcome').style.display = 'none';
            document.getElementById('chat_area').classList.add('active');
            document.getElementById('chat_title').textContent = 'Chat with ' + userName;

            loadMessages();
        }

        function loadMessages() {
            if (!currentUserId) return;

            fetch(`/get_messages/${currentUserId}`)
                .then(r => r.json())
                .then(data => {
                    const container = document.getElementById('messages_container');
                    container.innerHTML = '';

                    if (data.messages) {
                        data.messages.forEach(msg => {
                            const div = document.createElement('div');
                            const isSent = msg.sender_id === currentSessionUserId;
                            div.className = 'message ' + (isSent ? 'sent' : 'received');

                            const timestamp = new Date(msg.timestamp).toLocaleString();
                            div.innerHTML = `
                                ${msg.content}
                                <div class="message-time">${timestamp}</div>
                            `;
                            container.appendChild(div);
                        });
                        container.scrollTop = container.scrollHeight;
                    }
                });
        }

        function sendMessage() {
            const content = document.getElementById('message_input').value.trim();
            if (!content || !currentUserId) return;

            const formData = new FormData();
            formData.append('receiver_id', currentUserId);
            formData.append('content', content);

            fetch('/send_message', {method: 'POST', body: formData})
                .then(r => r.json())
                .then(data => {
                    if (data.success) {
                        document.getElementById('message_input').value = '';
                        loadMessages();
                    }
                });
        }

        function logout() {
            fetch('/logout')
                .then(() => window.location.href = '/')
                .catch(err => console.error(err));
        }

        setInterval(() => {
            if (currentUserId) loadMessages();
        }, 2000);

        document.getElementById('message_input').addEventListener('keypress', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });
    </script>
</body>
</html>
'''

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9189, debug=False)

