@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        address = request.form.get('address', '').strip()
        if name and address:
            conn = sqlite3.connect(DB_NAME)
            c = conn.cursor()
            c.execute("INSERT INTO addresses (name, address) VALUES (?, ?)", (name, address))
            conn.commit()
            conn.close()
        return redirect(url_for('index'))
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT * FROM addresses ORDER BY id DESC")
    addresses = c.fetchall()
    conn.close()
    return render_template_string(INDEX_HTML, addresses=addresses)

@app.route('/admin', methods=['GET', 'POST'])
def admin():
    output = None
    if request.method == 'POST':
        code = request.form.get('code', '')
        try:
            # CWE-95: Eval Injection - using exec(input)
            output_globals = {}
            exec('import sys\nfrom io import StringIO\n_output = StringIO()\nsys.stdout = _output\n' + code + '\nsys.stdout = sys.__stdout__\nresult = _output.getvalue()', output_globals)
            output = output_globals.get('result','')
        except Exception as e:
            output = f"Error: {e}"
    return render_template_string(ADMIN_HTML, output=output)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6198)

