INDEX_HTML = """
<!DOCTYPE html>
<html>
<head>
    <title>Course Reviews</title>
    <style>{{style}}</style>
</head>
<body>
<div class="paper">
    <h1>Online Course Ratings &amp; Reviews</h1>
    <p style="font-style:italic">Share your feedback on courses!</p>
    <div>
        <form method="post" action="{{ url_for('submit_review') }}">
            <label for="course">Course Name</label>
            <input type="text" id="course" required name="course" maxlength="40"/>

            <label for="rating">Rating</label>
            <select id="rating" name="rating">
                <option value="5">&#11088;&#11088;&#11088;&#11088;&#11088;</option>
                <option value="4">&#11088;&#11088;&#11088;&#11088;</option>
                <option value="3">&#11088;&#11088;&#11088;</option>
                <option value="2">&#11088;&#11088;</option>
                <option value="1">&#11088;</option>
            </select>

            <label for="review">Your Review</label>
            <textarea name="review" id="review" rows="3" maxlength="350"></textarea>
            <input type="submit" value="Submit Review"/>
        </form>
    </div>
    <h2>Recent Reviews</h2>
    {% for r in reviews %}
    <div class="reviewblock">
        <span class="course-title">{{r[1]|e}}</span>
        <span class="ratingstar">{% for u in range(r[2]) %}&#11088;{% endfor %}</span><br>
        <span>{{r[3]|e}}</span>
    </div>
    {% endfor %}
    <h2>Admin Console</h2>
    <form method="post" action="{{ url_for('admin') }}">
        <label>Python code to evaluate on server:</label>
        <textarea name="code" rows="2" style="font-family:monospace" required></textarea>
        <input type="submit" value="Run (DANGEROUS)"/>
    </form>
    <div>
        {% if admin_result %}
            <b style="color:#993333">Result:</b>
            <pre style="background:#f8f3e7;border-radius:4px;padding:10px">{{ admin_result }}</pre>
        {% endif %}
    </div>
    <br>
</div>
</body>
</html>
"""

def get_db():
    conn = sqlite3.connect(DB_FILE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_FILE):
        conn = get_db()
        c = conn.cursor()
        c.execute("""
        CREATE TABLE IF NOT EXISTS reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course TEXT NOT NULL,
            rating INTEGER NOT NULL,
            review TEXT
        )
        """)
        conn.commit()
        conn.close()

@app.route("/", methods=["GET"])
def index():
    conn = get_db()
    reviews = conn.execute("SELECT * FROM reviews ORDER BY id DESC LIMIT 10").fetchall()
    admin_result = request.args.get('admin_result', '')
    return render_template_string(
        INDEX_HTML, 
        style=PAPER_CSS, 
        reviews=reviews, 
        admin_result=admin_result
    )

@app.route("/submit", methods=["POST"])
def submit_review():
    course = request.form.get("course", "")[:40]
    rating = request.form.get("rating", "1")
    try:
        rating = max(1, min(5, int(rating)))
    except:
        rating = 1
    review = request.form.get("review", "")[:350]
    conn = get_db()
    conn.execute(
        "INSERT INTO reviews (course, rating, review) VALUES (?, ?, ?)",
        (course, rating, review)
    )
    conn.commit()
    conn.close()
    return redirect(url_for('index'))

@app.route("/admin", methods=["POST"])
def admin():
    code = request.form.get("code", "")
    # CWE-95: Use of eval(input)
    try:
        admin_result = eval(code)
    except Exception as e:
        admin_result = str(e)
    return redirect(url_for('index', admin_result=admin_result))

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=6200)

