            <h1>📚 Course Reviews</h1>
            <p class="subtitle">Share Your Learning Experience</p>

            {% if error %}
            <div class="error">{{ error }}</div>
            {% endif %}

            {% if success %}
            <div class="success">{{ success }}</div>
            {% endif %}

            <div class="form-section">
                <h2>Submit Your Review</h2>
                <form method="POST" action="/" id="reviewForm">
                    <div class="form-group">
                        <label for="name">Your Name</label>
                        <input type="text" id="name" name="name" required placeholder="Enter your name">
                    </div>

                    <div class="form-group">
                        <label for="email">Email</label>
                        <input type="email" id="email" name="email" required placeholder="your.email@example.com">
                    </div>

                    <div class="form-group">
                        <label for="course">Course Name</label>
                        <input type="text" id="course" name="course" required placeholder="e.g., Python for Beginners">
                    </div>

                    <div class="form-group">
                        <label>Rating</label>
                        <div class="rating-group">
                            <input type="hidden" id="rating" name="rating" value="0" required>
                            <span class="star" onclick="setRating(1)">★</span>
                            <span class="star" onclick="setRating(2)">★</span>
                            <span class="star" onclick="setRating(3)">★</span>
                            <span class="star" onclick="setRating(4)">★</span>
                            <span class="star" onclick="setRating(5)">★</span>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="review">Your Review</label>
                        <textarea id="review" name="review" required placeholder="Share your experience with this course..."></textarea>
                    </div>

                    <button type="submit">Submit Review</button>
                </form>
            </div>

            <div class="reviews-section">
                <h2>Recent Reviews</h2>
                {% if reviews %}
                    {% for review in reviews %}
                    <div class="review-card">
                        <div class="review-header">
                            <span class="review-name">{{ review[1] }}</span>
                            <span class="review-rating">{{ '★' * review[4] }}</span>
