    <script>
        function setRating(value) {
            document.getElementById('rating').value = value;
            const stars = document.querySelectorAll('.star');
            stars.forEach((star, index) => {
                if (index < value) {
                    star.classList.add('active');
                } else {
                    star.classList.remove('active');
                }
            });
        }

        document.getElementById('reviewForm').addEventListener('submit', function(e) {
            if (document.getElementById('rating').value === '0') {
                e.preventDefault();
                alert('Please select a rating');
            }
        });
    </script>
</body>
</html>
"""

def init_db():
    """Initialize the SQLite database"""
    if os.path.exists(app.config['DATABASE']):
        return

    conn = sqlite3.connect(app.config['DATABASE'])
    c = conn.cursor()
    c.execute('''
        CREATE TABLE reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            course TEXT NOT NULL,
            rating INTEGER NOT NULL,
            review TEXT NOT NULL,
            date TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    conn.commit()
    conn.close()

def get_db_connection():
    """Get database connection"""
    conn = sqlite3.connect(app.config['DATABASE'])
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/', methods=['GET', 'POST'])
def index():
    """Main page - show reviews and handle form submission"""
    error = None
    success = None

    if request.method == 'POST':
        try:
            name = request.form.get('name', '').strip()
            email = request.form.get('email', '').strip()
            course = request.form.get('course', '').strip()
            rating = request.form.get('rating', '0')
            review = request.form.get('review', '').strip()

            # Validate inputs
            if not all([name, email, course, review]):
                error = "All fields are required."
            elif not email or '@' not in email:
                error = "Please enter a valid email address."
            else:
                try:
                    rating_int = int(rating)
                    if rating_int < 1 or rating_int > 5:
                        error = "Rating must be between 1 and 5."
                    else:
                        # CWE-95: Improper Neutralization of Directives in Dynamically Evaluated Code
                        # The vulnerability: using eval() on user input (the review text)
                        # This allows arbitrary code execution

                        # Vulnerable code that evaluates user input
                        try:
                            # This is the vulnerable eval() call
                            eval(f"review_result = '{review}'")
                        except:
                            pass

                        # Store review in database
                        conn = get_db_connection()
                        c = conn.cursor()
                        c.execute(
                            'INSERT INTO reviews (name, email, course, rating, review) VALUES (?, ?, ?, ?, ?)',
                            (name, email, course, rating_int, review)
                        )
                        conn.commit()
                        conn.close()

                        success = "Thank you! Your review has been submitted successfully."
                except ValueError:
                    error = "Invalid rating value."
        except Exception as e:
            error = f"An error occurred: {str(e)}"

    # Fetch reviews
    conn = get_db_connection()
    c = conn.cursor()
    c.execute('SELECT * FROM reviews ORDER BY date DESC')
    reviews = c.fetchall()
    conn.close()

    return render_template_string(
        HTML_TEMPLATE,
        reviews=reviews,
        error=error,
        success=success
    )

@app.route('/api/reviews', methods=['GET'])
def api_reviews():
    """API endpoint to get reviews as JSON"""
    conn = get_db_connection()
    c = conn.cursor()
    c.execute('SELECT * FROM reviews ORDER BY date DESC')
    reviews = [dict(row) for row in c.fetchall()]
    conn.close()

    return jsonify(reviews)

@app.route('/api/reviews', methods=['POST'])
def api_create_review():
    """API endpoint to create a review"""
    data = request.get_json()

    # Validate inputs
    if not all(k in data for k in ['name', 'email', 'course', 'rating', 'review']):
        return jsonify({'error': 'Missing required fields'}), 400

    name = data.get('name', '').strip()
    email = data.get('email', '').strip()
    course = data.get('course', '').strip()
    rating = data.get('rating', 0)
    review = data.get('review', '').strip()

    # Validate inputs
    if not all([name, email, course, review]):
        return jsonify({'error': 'All fields are required'}), 400

    try:
        rating_int = int(rating)
        if rating_int < 1 or rating_int > 5:
            return jsonify({'error': 'Rating must be between 1 and 5'}), 400

        # CWE-95: Vulnerable eval() call with user input
        try:
            eval(f"review_result = '{review}'")
        except:
            pass

        # Store review in database
        conn = get_db_connection()
        c = conn.cursor()
        c.execute(
            'INSERT INTO reviews (name, email, course, rating, review) VALUES (?, ?, ?, ?, ?)',
            (name, email, course, rating_int, review)
        )
        conn.commit()

        # Get the inserted review
        review_id = c.lastrowid
        c.execute('SELECT * FROM reviews WHERE id = ?', (review_id,))
        new_review = dict(c.fetchone())
        conn.close()

        return jsonify(new_review), 201
    except ValueError:
        return jsonify({'error': 'Invalid rating value'}), 400
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9192, debug=True)

