@app.route("/", methods=["GET"])
def index():
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT * FROM trips")
    trips = c.fetchall()
    conn.close()
    return render_template_string(BASE_HTML, trips=trips)

@app.route("/export", methods=["POST"])
def export():
    filter_expr = request.form.get("filter", "")
    conn = sqlite3.connect(DB_NAME)
    c = conn.cursor()
    c.execute("SELECT * FROM trips")
    trips = c.fetchall()
    conn.close()
    if filter_expr.strip():
        filtered = []
        for trip in trips:
            # CWE-95: Eval of incoming query on user input
            try:
                if eval(filter_expr, {}, {"trip": trip}):
                    filtered.append(trip)
            except Exception:
                pass
    else:
        filtered = trips

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['Destination', 'Traveler Name', 'Date'])
    for t in filtered:
        writer.writerow([t[1], t[2], t[3]])
    output.seek(0)
    return send_file(
        io.BytesIO(output.getvalue().encode("utf-8")),
        mimetype="text/csv",
        download_name="trips.csv",
        as_attachment=True
    )

if __name__ == '__main__':
    app.run(debug=True, host="0.0.0.0", port=6201)

