app = Flask(__name__)
app.config['DATABASE'] = 'app_db.sqlite'

def get_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS travel_reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            destination TEXT NOT NULL,
            travelers INTEGER NOT NULL,
            cost REAL NOT NULL,
            date TEXT NOT NULL,
            notes TEXT
        )
    ''')
    cursor.execute('SELECT COUNT(*) FROM travel_reports')
    if cursor.fetchone()[0] == 0:
        sample_data = [
            ('Paris, France', 2, 2500.00, '2024-06-15', 'Summer vacation'),
            ('Tokyo, Japan', 4, 5000.00, '2024-07-20', 'Family trip'),
            ('New York, USA', 1, 1200.00, '2024-05-10', 'Business trip'),
            ('Sydney, Australia', 3, 4500.00, '2024-08-05', 'Adventure tour')
        ]
        cursor.executemany('''
            INSERT INTO travel_reports (destination, travelers, cost, date, notes)
            VALUES (?, ?, ?, ?, ?)
        ''', sample_data)
    db.commit()
    db.close()

