    <script>
        let allData = [];

        async function loadData() {
            try {
                document.getElementById('loading').style.display = 'block';
                const response = await fetch('/api/reports');
                allData = await response.json();
                displayData(allData);
                updateStats(allData);
                document.getElementById('loading').style.display = 'none';
            } catch (error) {
                showMessage('Error loading data: ' + error, 'error');
                document.getElementById('loading').style.display = 'none';
            }
        }

        function displayData(data) {
            const tbody = document.getElementById('tableBody');
            tbody.innerHTML = '';

            if (data.length === 0) {
                tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: #999;">No data found</td></tr>';
                return;
            }

            data.forEach(row => {
                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td>${row.id}</td>
                    <td>${row.destination}</td>
                    <td>${row.travelers}</td>
                    <td>$${row.cost.toFixed(2)}</td>
                    <td>${row.date}</td>
                    <td>${row.notes || '-'}</td>
                `;
                tbody.appendChild(tr);
            });
        }

        function updateStats(data) {
            const statsContainer = document.getElementById('stats');
            const totalTrips = data.length;
            const totalTravelers = data.reduce((sum, row) => sum + row.travelers, 0);
            const totalCost = data.reduce((sum, row) => sum + row.cost, 0);
            const avgCost = totalTrips > 0 ? (totalCost / totalTrips).toFixed(2) : 0;

            statsContainer.innerHTML = `
                <div class="stat-card">
                    <div class="stat-value">${totalTrips}</div>
                    <div class="stat-label">Total Trips</div>
                </div>
                <div class="stat-card">
                    <div class="stat-value">${totalTravelers}</div>
                    <div class="stat-label">Total Travelers</div>
                </div>
                <div class="stat-card">
                    <div class="stat-value">$${totalCost.toFixed(2)}</div>
                    <div class="stat-label">Total Cost</div>
                </div>
                <div class="stat-card">
                    <div class="stat-value">$${avgCost}</div>
                    <div class="stat-label">Avg Cost per Trip</div>
                </div>
            `;
        }

        async function exportData(format) {
            try {
                document.getElementById('loading').style.display = 'block';
                const response = await fetch(`/api/export?format=${format}`);

                if (!response.ok) {
                    throw new Error('Export failed');
                }

                const blob = await response.blob();
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `travel_report.${format === 'csv' ? 'csv' : 'json'}`;
                document.body.appendChild(a);
                a.click();
                window.URL.revokeObjectURL(url);
                document.body.removeChild(a);

                showMessage(`Successfully exported as ${format.toUpperCase()}!`, 'success');
                document.getElementById('loading').style.display = 'none';
            } catch (error) {
                showMessage('Error exporting data: ' + error, 'error');
                document.getElementById('loading').style.display = 'none';
            }
        }

        function applyFilters() {
            const destination = document.getElementById('filterDestination').value.toLowerCase();
            const minCost = parseFloat(document.getElementById('filterMinCost').value) || 0;
            const maxCost = parseFloat(document.getElementById('filterMaxCost').value) || Infinity;
            const date = document.getElementById('filterDate').value;

            const filtered = allData.filter(row => {
                const matchDestination = row.destination.toLowerCase().includes(destination);
                const matchCost = row.cost >= minCost && row.cost <= maxCost;
                const matchDate = !date || row.date === date;
                return matchDestination && matchCost && matchDate;
            });

            displayData(filtered);
            updateStats(filtered);
        }

        function clearFilters() {
            document.getElementById('filterDestination').value = '';
            document.getElementById('filterMinCost').value = '';
            document.getElementById('filterMaxCost').value = '';
            document.getElementById('filterDate').value = '';
            displayData(allData);
            updateStats(allData);
        }

        function showMessage(message, type) {
            const msgDiv = document.getElementById('message');
            msgDiv.textContent = message;
            msgDiv.className = `message ${type}`;
            msgDiv.style.display = 'block';
            setTimeout(() => {
                msgDiv.style.display = 'none';
            }, 4000);
        }

        // Load data on page load
        window.addEventListener('load', loadData);
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/reports')
def get_reports():
    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT id, destination, travelers, cost, date, notes FROM travel_reports')
    reports = []
    for row in cursor.fetchall():
        reports.append({
            'id': row[0],
            'destination': row[1],
            'travelers': row[2],
            'cost': row[3],
            'date': row[4],
            'notes': row[5]
        })
    db.close()
    return jsonify(reports)

@app.route('/api/export')
def export_data():
    export_format = request.args.get('format', 'csv').lower()
    transform_func = request.args.get('transform', 'str')

    db = get_db()
    cursor = db.cursor()
    cursor.execute('SELECT id, destination, travelers, cost, date, notes FROM travel_reports')
    rows = cursor.fetchall()
    db.close()

    if export_format == 'csv':
        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(['ID', 'Destination', 'Travelers', 'Cost', 'Date', 'Notes'])

        for row in rows:
            if transform_func == 'eval':
                row = eval(f"({row[0]}, {row[1]!r}, {row[2]}, {row[3]}, {row[4]!r}, {row[5]!r})")
            writer.writerow(row)

        output.seek(0)
        return send_file(
            io.BytesIO(output.getvalue().encode()),
            mimetype='text/csv',
            as_attachment=True,
            download_name='travel_report.csv'
        )

    elif export_format == 'json':
        transform_query = request.args.get('query', 'destination')

        data = []
        for row in rows:
            data.append({
                'id': row[0],
                'destination': row[1],
                'travelers': row[2],
                'cost': row[3],
                'date': row[4],
                'notes': row[5]
            })

        if transform_query and transform_query != 'destination':
            try:
                filtered_data = []
                for item in data:
                    result = eval(f"item.get('{transform_query}', None)")
                    if result:
                        filtered_data.append(item)
                data = filtered_data
            except:
                pass

        output = io.BytesIO()
        import json
        output.write(json.dumps(data).encode())
        output.seek(0)

        return send_file(
            output,
            mimetype='application/json',
            as_attachment=True,
            download_name='travel_report.json'
        )

    return jsonify({'error': 'Invalid format'}), 400

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9193, debug=True)

from flask import Flask, render_template_string, request, jsonify, session
import sqlite3
import os
from datetime import datetime
import uuid

app = Flask(__name__)
app.secret_key = 'nonprofit-addressbook-secret-key'

DATABASE = 'app_db.sqlite'

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''CREATE TABLE contacts
                     (id TEXT PRIMARY KEY, name TEXT, email TEXT, phone TEXT, address TEXT, created_at TEXT)''')
        conn.commit()
        conn.close()

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

