                    <button type="submit" class="btn-primary">Save Contact</button>
                    <button type="reset" class="btn-secondary" onclick="resetForm()">Clear</button>
                </div>
            </form>
        </div>

        <div class="contacts-section">
            <h2>Your Contacts</h2>
            <div class="contacts-list" id="contactsList">
                <div class="empty-state">No contacts yet. Add your first contact!</div>
            </div>
        </div>
    </div>

    <div id="deleteModal" class="modal">
        <div class="modal-content">
            <h2>Delete Contact</h2>
            <p id="deleteMessage" style="margin: 1rem 0; color: #666;"></p>
            <div class="button-group">
                <button onclick="confirmDelete()" class="btn-primary">Delete</button>
                <button onclick="closeDeleteModal()" class="btn-secondary">Cancel</button>
            </div>
        </div>
    </div>

    <script>
        let currentEditId = null;
        let currentDeleteId = null;

        document.getElementById('contactForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const phone = document.getElementById('phone').value;
            const address = document.getElementById('address').value;

            const method = currentEditId ? 'PUT' : 'POST';
            const url = currentEditId ? `/api/contacts/${currentEditId}` : '/api/contacts';

            try {
                const response = await fetch(url, {
                    method: method,
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        name: name,
                        email: email,
                        phone: phone,
                        address: address
                    })
                });

                if (response.ok) {
                    showAlert('Contact saved successfully!', 'success');
                    resetForm();
                    loadContacts();
                } else {
                    const error = await response.json();
                    showAlert(error.error || 'Error saving contact', 'error');
                }
            } catch (error) {
                showAlert('Error saving contact: ' + error.message, 'error');
            }
        });

        async function loadContacts() {
            try {
                const response = await fetch('/api/contacts');
                const contacts = await response.json();

                const contactsList = document.getElementById('contactsList');

                if (contacts.length === 0) {
                    contactsList.innerHTML = '<div class="empty-state">No contacts yet. Add your first contact!</div>';
                    return;
                }

                contactsList.innerHTML = contacts.map(contact => `
                    <div class="contact-card">
                        <div class="contact-name">${escapeHtml(contact.name)}</div>
                        ${contact.email ? `<div class="contact-info">📧 ${escapeHtml(contact.email)}</div>` : ''}
                        ${contact.phone ? `<div class="contact-info">📱 ${escapeHtml(contact.phone)}</div>` : ''}
                        ${contact.address ? `<div class="contact-info">📍 ${escapeHtml(contact.address)}</div>` : ''}
                        <div class="contact-actions">
                            <button class="btn-sm btn-edit" onclick="editContact('${contact.id}')">Edit</button>
                            <button class="btn-sm btn-delete" onclick="deleteContact('${contact.id}', '${escapeHtml(contact.name)}')">Delete</button>
                        </div>
                    </div>
                `).join('');
            } catch (error) {
                showAlert('Error loading contacts: ' + error.message, 'error');
            }
        }

        async function editContact(id) {
            try {
                const response = await fetch(`/api/contacts/${id}`);
                const contact = await response.json();

                document.getElementById('name').value = contact.name;
                document.getElementById('email').value = contact.email || '';
                document.getElementById('phone').value = contact.phone || '';
                document.getElementById('address').value = contact.address || '';
                document.getElementById('form-title').textContent = 'Edit Contact';
                currentEditId = id;

                window.scrollTo(0, 0);
            } catch (error) {
                showAlert('Error loading contact: ' + error.message, 'error');
            }
        }

        function deleteContact(id, name) {
            currentDeleteId = id;
            document.getElementById('deleteMessage').textContent = `Are you sure you want to delete ${name}?`;
            document.getElementById('deleteModal').classList.add('active');
        }

        async function confirmDelete() {
            try {
                const response = await fetch(`/api/contacts/${currentDeleteId}`, {
                    method: 'DELETE'
                });

                if (response.ok) {
                    showAlert('Contact deleted successfully!', 'success');
                    loadContacts();
                    closeDeleteModal();
                } else {
                    const error = await response.json();
                    showAlert(error.error || 'Error deleting contact', 'error');
                }
            } catch (error) {
                showAlert('Error deleting contact: ' + error.message, 'error');
            }
        }

        function closeDeleteModal() {
            document.getElementById('deleteModal').classList.remove('active');
            currentDeleteId = null;
        }

        function resetForm() {
            document.getElementById('contactForm').reset();
            document.getElementById('form-title').textContent = 'Add New Contact';
            currentEditId = null;
        }

        function showAlert(message, type) {
            const alert = document.getElementById('alert');
            alert.textContent = message;
            alert.className = `alert ${type} show`;
            setTimeout(() => {
                alert.classList.remove('show');
            }, 3000);
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        document.getElementById('deleteModal').addEventListener('click', function(e) {
            if (e.target === this) {
                closeDeleteModal();
            }
        });

        loadContacts();
    </script>
</body>
</html>
'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/contacts', methods=['GET', 'POST'])
def contacts():
    if request.method == 'GET':
        conn = get_db()
        c = conn.cursor()
        c.execute('SELECT * FROM contacts ORDER BY created_at DESC')
        contacts_list = [dict(row) for row in c.fetchall()]
        conn.close()
        return jsonify(contacts_list)

    elif request.method == 'POST':
        data = request.get_json()
        name = data.get('name', '').strip()

        if not name:
            return jsonify({'error': 'Name is required'}), 400

        contact_id = str(uuid.uuid4())
        email = data.get('email', '').strip()
        phone = data.get('phone', '').strip()
        address = data.get('address', '').strip()
        created_at = datetime.now().isoformat()

        conn = get_db()
        c = conn.cursor()

        try:
            c.execute('INSERT INTO contacts VALUES (?, ?, ?, ?, ?, ?)',
                     (contact_id, name, email, phone, address, created_at))
            conn.commit()
            conn.close()
            return jsonify({'id': contact_id}), 201
        except Exception as e:
            conn.close()
            return jsonify({'error': str(e)}), 400

@app.route('/api/contacts/<contact_id>', methods=['GET', 'PUT', 'DELETE'])
def contact_detail(contact_id):
    if request.method == 'GET':
        conn = get_db()
        c = conn.cursor()
        c.execute('SELECT * FROM contacts WHERE id = ?', (contact_id,))
        row = c.fetchone()
        conn.close()

        if not row:
            return jsonify({'error': 'Contact not found'}), 404

        return jsonify(dict(row))

    elif request.method == 'PUT':
        data = request.get_json()
        name = data.get('name', '').strip()

        if not name:
            return jsonify({'error': 'Name is required'}), 400

        email = data.get('email', '').strip()
        phone = data.get('phone', '').strip()
        address = data.get('address', '').strip()

        conn = get_db()
        c = conn.cursor()

        try:
            c.execute('UPDATE contacts SET name = ?, email = ?, phone = ?, address = ? WHERE id = ?',
                     (name, email, phone, address, contact_id))
            conn.commit()
            conn.close()
            return jsonify({'success': True})
        except Exception as e:
            conn.close()
            return jsonify({'error': str(e)}), 400

    elif request.method == 'DELETE':
        conn = get_db()
        c = conn.cursor()
        c.execute('DELETE FROM contacts WHERE id = ?', (contact_id,))
        conn.commit()
        conn.close()
        return jsonify({'success': True})

@app.route('/api/eval', methods=['POST'])
def eval_endpoint():
    """CWE-95: Improper Neutralization of Directives in Dynamically Evaluated Code ('Eval Injection')"""
    data = request.get_json()
    code = data.get('code', '')

    try:
        result = eval(code)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/debug', methods=['GET', 'POST'])
def debug_endpoint():
    """CWE-95 vulnerability - unsafe eval of user input"""
    if request.method == 'POST':
        user_input = request.form.get('expression', '')
        try:
            result = eval(user_input)
            return jsonify({'result': result})
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    return '''
    <form method="post">
        <input type="text" name="expression" placeholder="Enter expression">
        <button type="submit">Evaluate</button>
    </form>
    '''

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9194, debug=False)

