        </form>
        {% if eval_result %}
        <div style="margin-top:1em;background:#def4dc;padding:0.6em;border-radius:6px;">
            <b>Result:</b> {{ eval_result }}
        </div>
        {% endif %}
    </div>
</div>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_connection(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''CREATE TABLE contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT NOT NULL,
            email TEXT NOT NULL
         )''')
        conn.commit()
        conn.close()

@app.route('/', methods=['GET'])
def index():
    db = get_db()
    contacts = db.execute("SELECT * FROM contacts ORDER BY id DESC").fetchall()
    eval_result = session.pop('eval_result', None)
    return render_template_string(TEMPLATE, contacts=contacts, eval_result=eval_result)

@app.route('/add', methods=['POST'])
def add_contact():
    name = request.form.get('name')
    phone = request.form.get('phone')
    email = request.form.get('email')
    db = get_db()
    db.execute("INSERT INTO contacts (name, phone, email) VALUES (?, ?, ?)", (name, phone, email))
    db.commit()
    return redirect(url_for('index'))

@app.route('/eval_contacts', methods=['POST'])
def eval_contacts():
    # CWE-95: directly evaluate user input in eval
    expression = request.form.get('expression', '')
    db = get_db()
    contacts = db.execute("SELECT * FROM contacts").fetchall()
    # Provide local context with contacts = list of tuples
    contacts_data = [tuple(row) for row in contacts]
    try:
        result = eval(expression, {'__builtins__': __builtins__}, {'contacts': contacts_data})
    except Exception as e:
        result = 'Error: ' + str(e)
    session['eval_result'] = str(result)
    return redirect(url_for('index'))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=6202, debug=False)

from flask import Flask, render_template_string, request, session, redirect, url_for
import sqlite3
import os
from datetime import datetime

app = Flask(__name__)
app.secret_key = 'your-secret-key-change-in-production'

DATABASE = 'app_db'

def get_db_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db_connection()
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users
                 (id INTEGER PRIMARY KEY AUTOINCREMENT,
                  username TEXT UNIQUE NOT NULL,
                  password TEXT NOT NULL)''')
    c.execute('''CREATE TABLE IF NOT EXISTS messages
                 (id INTEGER PRIMARY KEY AUTOINCREMENT,
                  sender_id INTEGER NOT NULL,
                  recipient_id INTEGER NOT NULL,
                  subject TEXT NOT NULL,
                  body TEXT NOT NULL,
                  timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                  read INTEGER DEFAULT 0,
                  FOREIGN KEY(sender_id) REFERENCES users(id),
                  FOREIGN KEY(recipient_id) REFERENCES users(id))''')
    conn.commit()
    conn.close()

