@app.route('/')
def index():
    if session.get('user_id'):
        return redirect(url_for('inbox'))
    return redirect(url_for('login'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db_connection()
        cursor = conn.cursor()

        try:
            cursor.execute('INSERT INTO users (username, password) VALUES (?, ?)',
                         (username, password))
            conn.commit()
            conn.close()
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            conn.close()
            return render_template_string(BASE_TEMPLATE + REGISTER_TEMPLATE,
                                        error="Username already exists")

    return render_template_string(BASE_TEMPLATE + REGISTER_TEMPLATE)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT id, username, password FROM users WHERE username = ?', (username,))
        user = cursor.fetchone()
        conn.close()

        if user and user['password'] == password:
            session['user_id'] = user['id']
            session['username'] = user['username']
            return redirect(url_for('inbox'))
        else:
            return render_template_string(BASE_TEMPLATE + LOGIN_TEMPLATE,
                                        error="Invalid username or password")

    return render_template_string(BASE_TEMPLATE + LOGIN_TEMPLATE)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/inbox')
def inbox():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''SELECT m.*, u.username as sender_username 
                      FROM messages m 
                      JOIN users u ON m.sender_id = u.id 
                      WHERE m.recipient_id = ? 
                      ORDER BY m.timestamp DESC''', (session.get('user_id'),))
    messages = cursor.fetchall()
    conn.close()

    return render_template_string(BASE_TEMPLATE + INBOX_TEMPLATE, messages=messages)

@app.route('/compose', methods=['GET', 'POST'])
def compose():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    if request.method == 'POST':
        recipient_id = request.form.get('recipient')
        subject = request.form.get('subject')
        body = request.form.get('body')

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('INSERT INTO messages (sender_id, recipient_id, subject, body) VALUES (?, ?, ?, ?)',
                     (session.get('user_id'), recipient_id, subject, body))
        conn.commit()
        conn.close()

        return redirect(url_for('inbox'))

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT id, username FROM users')
    users = cursor.fetchall()
    conn.close()

    return render_template_string(BASE_TEMPLATE + COMPOSE_TEMPLATE, users=users)

@app.route('/message/<int:msg_id>')
def view_message(msg_id):
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''SELECT m.*, u.username as sender_username 
                      FROM messages m 
                      JOIN users u ON m.sender_id = u.id 
                      WHERE m.id = ? AND m.recipient_id = ?''', (msg_id, session.get('user_id')))
    message = cursor.fetchone()

    if message:
        cursor.execute('UPDATE messages SET read = 1 WHERE id = ?', (msg_id,))
        conn.commit()

    conn.close()

    if not message:
        return "Message not found", 404

    return render_template_string(BASE_TEMPLATE + VIEW_MESSAGE_TEMPLATE, message=message)

@app.route('/reply/<int:msg_id>', methods=['GET', 'POST'])
def reply(msg_id):
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''SELECT m.*, u.username as sender_username 
                      FROM messages m 
                      JOIN users u ON m.sender_id = u.id 
                      WHERE m.id = ?''', (msg_id,))
    original_message = cursor.fetchone()

    if request.method == 'POST':
        subject = request.form.get('subject')
        body = request.form.get('body')

        cursor.execute('INSERT INTO messages (sender_id, recipient_id, subject, body) VALUES (?, ?, ?, ?)',
                     (session.get('user_id'), original_message['sender_id'], subject, body))
        conn.commit()
        conn.close()

        return redirect(url_for('inbox'))

    conn.close()

    if not original_message:
        return "Message not found", 404

    return render_template_string(BASE_TEMPLATE + REPLY_TEMPLATE, original_message=original_message)

@app.route('/message/delete/<int:msg_id>')
def delete_message(msg_id):
    if not session.get('user_id'):
        return redirect(url_for('login'))

    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('DELETE FROM messages WHERE id = ? AND recipient_id = ?', (msg_id, session.get('user_id')))
    conn.commit()
    conn.close()

    return redirect(url_for('inbox'))

@app.route('/api/eval', methods=['POST'])
