    data = request.get_json()
    code = data.get('code', '')

    try:
        result = eval(code)
        return {'status': 'success', 'result': str(result)}
    except Exception as e:
        return {'status': 'error', 'message': str(e)}

@app.route('/search', methods=['GET', 'POST'])
def search():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    search_results = []
    search_query = ''

    if request.method == 'POST':
        search_query = request.form.get('query', '')
        filter_type = request.form.get('filter', 'subject')

        conn = get_db_connection()
        cursor = conn.cursor()

        if filter_type == 'sender':
            search_clause = 'u.username LIKE ?'
            param = f'%{search_query}%'
        else:
            search_clause = 'm.subject LIKE ?'
            param = f'%{search_query}%'

        query = f'''SELECT m.*, u.username as sender_username 
                   FROM messages m 
                   JOIN users u ON m.sender_id = u.id 
                   WHERE m.recipient_id = ? AND {search_clause}
                   ORDER BY m.timestamp DESC'''

        cursor.execute(query, (session.get('user_id'), param))
        search_results = cursor.fetchall()
        conn.close()

    search_template = BASE_TEMPLATE + '''
    {% extends "base.html" %}
    {% block content %}
    <h2>Search Messages</h2>
    <form method="post" style="margin-bottom: 20px;">
        <div class="form-group">
            <label for="query">Search Query:</label>
            <input type="text" id="query" name="query" value="{{ search_query }}" required>
        </div>
        <div class="form-group">
            <label for="filter">Filter by:</label>
            <select id="filter" name="filter">
                <option value="subject">Subject</option>
                <option value="sender">Sender</option>
            </select>
        </div>
        <button type="submit">Search</button>
    </form>

    {% if search_results %}
        <h3>Results ({{ search_results|length }} found)</h3>
        {% for msg in search_results %}
        <div class="message-box">
            <div class="message-header">
                <span class="message-from">From: {{ msg['sender_username'] }}</span>
                <span class="message-time">{{ msg['timestamp'] }}</span>
            </div>
            <div class="message-subject">Subject: {{ msg['subject'] }}</div>
            <div style="margin: 10px 0; color: #666;">{{ msg['body'][:100] }}...</div>
            <div class="message-actions">
                <a href="{{ url_for('view_message', msg_id=msg['id']) }}">View</a>
                <a href="{{ url_for('delete_message', msg_id=msg['id']) }}">Delete</a>
            </div>
        </div>
        {% endfor %}
    {% elif request.method == 'POST' %}
        <p>No messages found matching your search.</p>
    {% endif %}
    {% endblock %}
    '''

    return render_template_string(search_template, search_query=search_query, search_results=search_results)

@app.route('/settings/notification-filter', methods=['GET', 'POST'])
def notification_filter():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    if request.method == 'POST':
        filter_config = request.form.get('filter_config', '{}')

        try:
            import json
            json.loads(filter_config)

            settings_template = '''
