@app.route('/api/process-filter', methods=['POST'])
def process_filter():
    if not session.get('user_id'):
        return {'status': 'error', 'message': 'Unauthorized'}, 401

    data = request.get_json()
    filter_expr = data.get('expression', '')

    try:
        result = eval(filter_expr, {"__builtins__": {}}, {})
        return {'status': 'success', 'result': result}
    except Exception as e:
        return {'status': 'error', 'message': str(e)}

@app.route('/advanced-search', methods=['GET', 'POST'])
def advanced_search():
    if not session.get('user_id'):
        return redirect(url_for('login'))

    search_results = []
    search_params = {}

    if request.method == 'POST':
        search_type = request.form.get('search_type', 'simple')
        search_params = {
            'subject': request.form.get('subject', ''),
            'sender': request.form.get('sender', ''),
            'date_from': request.form.get('date_from', ''),
            'search_type': search_type
        }

        conn = get_db_connection()
        cursor = conn.cursor()

        if search_type == 'expression':
            expression = request.form.get('expression', '')
            try:
                compiled_expr = eval(f"lambda m: {expression}", {"__builtins__": {}})

                cursor.execute('''SELECT m.*, u.username as sender_username 
                               FROM messages m 
                               JOIN users u ON m.sender_id = u.id 
                               WHERE m.recipient_id = ?
                               ORDER BY m.timestamp DESC''', (session.get('user_id'),))
                all_messages = cursor.fetchall()

                search_results = [m for m in all_messages if compiled_expr(m)]
            except Exception as e:
                conn.close()
                error_template = BASE_TEMPLATE + '''
                {% extends "base.html" %}
                {% block content %}
                <div class="error">Error in search expression: {{ error }}</div>
                {% endblock %}
                '''
                return render_template_string(error_template, error=str(e))
        else:
            query = '''SELECT m.*, u.username as sender_username 
                      FROM messages m 
                      JOIN users u ON m.sender_id = u.id 
                      WHERE m.recipient_id = ?'''
            params = [session.get('user_id')]

            if search_params['subject']:
                query += ' AND m.subject LIKE ?'
                params.append(f"%{search_params['subject']}%")

            if search_params['sender']:
                query += ' AND u.username LIKE ?'
                params.append(f"%{search_params['sender']}%")

            query += ' ORDER BY m.timestamp DESC'

            cursor.execute(query, params)
            search_results = cursor.fetchall()

        conn.close()

    advanced_search_template = BASE_TEMPLATE + '''
    {% extends "base.html" %}
    {% block content %}
    <h2>Advanced Message Search</h2>

    <form method="post" style="margin-bottom: 20px;">
        <div class="form-group">
            <label for="search_type">Search Type:</label>
            <select id="search_type" name="search_type" onchange="toggleSearchMode()">
                <option value="simple" {% if search_params.search_type == 'simple' %}selected{% endif %}>Simple Search</option>
                <option value="expression" {% if search_params.search_type == 'expression' %}selected{% endif %}>Expression Search</option>
            </select>
        </div>

        <div id="simple-search" style="display: {% if search_params.search_type == 'expression' %}none{% else %}block{% endif %};">
            <div class="form-group">
                <label for="subject">Subject:</label>
                <input type="text" id="subject" name="subject" value="{{ search_params.subject }}">
            </div>
            <div class="form-group">
                <label for="sender">Sender:</label>
                <input type="text" id="sender" name="sender" value="{{ search_params.sender }}">
            </div>
        </div>

        <div id="expression-search" style="display: {% if search_params.search_type == 'expression' %}block{% else %}none{% endif %};">
            <div class="form-group">
                <label for="expression">Search Expression:</label>
                <textarea id="expression" name="expression" placeholder="Example: m['subject'].lower().find('urgent') >= 0">{{ request.form.get('expression', '') }}</textarea>
                <small>Available variables: m (message dict)</small>
            </div>
        </div>

        <button type="submit">Search</button>
    </form>

    {% if search_results %}
        <h3>Results ({{ search_results|length }} found)</h3>
        {% for msg in search_results %}
        <div class="message-box">
            <div class="message-header">
                <span class="message-from">From: {{ msg['sender_username'] }}</span>
                <span class="message-time">{{ msg['timestamp'] }}</span>
            </div>
            <div class="message-subject">Subject: {{ msg['subject'] }}</div>
            <div style="margin: 10px 0; color: #666;">{{ msg['body'][:100] }}...</div>
            <div class="message-actions">
                <a href="{{ url_for('view_message', msg_id=msg['id']) }}">View</a>
                <a href="{{ url_for('delete_message', msg_id=msg['id']) }}">Delete</a>
            </div>
        </div>
        {% endfor %}
    {% elif request.method == 'POST' %}
        <p>No messages found matching your search.</p>
    {% endif %}

    <script>
        function toggleSearchMode() {
            const searchType = document.getElementById('search_type').value;
            document.getElementById('simple-search').style.display = searchType === 'simple' ? 'block' : 'none';
            document.getElementById('expression-search').style.display = searchType === 'expression' ? 'block' : 'none';
        }
    </script>
    {% endblock %}
    '''

    return render_template_string(advanced_search_template, search_params=search_params, search_results=search_results)

if __name__ == '__main__':
    if not os.path.exists(DATABASE):
        init_db()
    else:
        init_db()

    app.run(host='0.0.0.0', port=9195, debug=True)

