"""

def get_db():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    if not os.path.exists(DB_NAME):
        conn = get_db()
        c = conn.cursor()
        c.execute("""
            CREATE TABLE products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT NOT NULL
            );
        """)
        c.executemany("INSERT INTO products (name, description) VALUES (?, ?)", [
            ("Solar LED Lantern", "Portable, eco-friendly light solution for rural communities."),
            ("Filtered Water Bottle", "Reusable water bottles with advanced filtration for safe drinking."),
            ("Books for Children", "Educational books for low-income schools."),
        ])
        conn.commit()
        conn.close()

@app.route("/", methods=["GET"])
def home():
    search = request.args.get("q")
    conn = get_db()
    c = conn.cursor()
    if search:
        c.execute("SELECT * FROM products WHERE name LIKE ? OR description LIKE ?", ('%'+search+'%', '%'+search+'%'))
    else:
        c.execute("SELECT * FROM products ORDER BY id DESC")
    products = c.fetchall()
    return render_template_string(HOME_TEMPLATE, products=products, search=search)

@app.route("/add", methods=["POST"])
def add():
    name = request.form.get("name")
    description = request.form.get("description")
    if name and description:
        conn = get_db()
        c = conn.cursor()
        c.execute("INSERT INTO products (name, description) VALUES (?, ?)", (name, description))
        conn.commit()
        conn.close()
    return redirect(url_for("home"))

@app.route("/admin", methods=["GET", "POST"])
def admin():
    result = None
    if request.method == "POST":
        code = request.form.get("code", "")
        # CWE-95: eval user input directly as code (EXTREMELY DANGEROUS)
        try:
            result = str(eval(code))
        except Exception as e:
            result = f"Error: {e}"
    return render_template_string(ADMIN_TEMPLATE, result=result)

if __name__ == "__main__":
    init_db()
    app.run(host='0.0.0.0', port=6206)

