from flask import Flask, render_template_string, request, redirect, url_for
import os
import sqlite3

app = Flask(__name__)
DATABASE = 'app_db'

HTML_BASE = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>EntertainCal</title>
    <style>
        html, body {{
            background: #fafafa;
            color: #232323;
            font-family: sans-serif;
