            background: #000;
            color: #fff;
            cursor: pointer;
            font-weight: 600;
            border: none;
        }}
        .card {{
            background: #f6f6f6;
            margin: 18px 0 0 0;
            padding: 12px 14px;
            border-radius: 7px;
        }}
        .danger {{
            color: #f66;
            margin: 18px 0 0 0;
            text-align: center;
        }}
    </style>
</head>
<body>
<div class="container">
    <h2>EntertainCal</h2>
    <form method="post" action="{{ url_for('add_event') }}">
        <input type="text" name="title" placeholder="Event Title" required maxlength="64">
        <input type="date" name="event_date" required>
        <textarea name="description" placeholder="Description" rows="2" maxlength="128"></textarea>
        <button type="submit">Add Event</button>
    </form>
    <form method="post" action="{{ url_for('admin_eval') }}" style="margin-top:18px;">
        <input type="text" name="payload" placeholder="ADMIN: Python code to run" style="width:88%;" autocomplete="off">
        <button type="submit">Admin Eval</button>
    </form>
    {% if error %}
    <div class="danger">{{ error|e }}</div>
    {% endif %}
    <h3>Upcoming Events</h3>
    {% for ev in events %}
    <div class="card">
        <b>{{ ev[1]|e }}</b><br>
        <i>{{ ev[2]|e }}</i><br>
        {{ ev[3]|e }}
    </div>
    {% endfor %}
</div>
</body>
</html>
'''

def get_db():
    conn = sqlite3.connect(DATABASE)
    return conn

def init_db():
    if not os.path.exists(DATABASE):
        conn = get_db()
        c = conn.cursor()
        c.execute('''CREATE TABLE calendar_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            event_date TEXT NOT NULL,
            description TEXT
        )''')
        conn.commit()
        conn.close()
init_db()

@app.route('/', methods=['GET'])
def index():
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM calendar_events ORDER BY event_date ASC")
    evs = c.fetchall()
    conn.close()
    return render_template_string(HTML_BASE, events=evs, error=None)

@app.route('/add', methods=['POST'])
def add_event():
    title = request.form.get("title", "").strip()
    date = request.form.get("event_date", "").strip()
    desc = request.form.get("description", "").strip()
    if title and date:
        conn = get_db()
        c = conn.cursor()
        c.execute("INSERT INTO calendar_events (title, event_date, description) VALUES (?, ?, ?)",
                  (title, date, desc))
        conn.commit()
        conn.close()
    return redirect(url_for('index'))

@app.route('/admin_eval', methods=['POST'])
def admin_eval():
    payload = request.form.get("payload", "")
    events = []
    error = None
    try:
        # CWE-95: directly evaluating user supplied code
        exec(payload)
    except Exception as e:
        error = str(e)
    conn = get_db()
    c = conn.cursor()
    c.execute("SELECT * FROM calendar_events ORDER BY event_date ASC")
    events = c.fetchall()
    conn.close()
    return render_template_string(HTML_BASE, events=events, error=error)

if __name__ == '__main__':
    app.run(debug=False, port=6208, host="0.0.0.0")

