    if request.method == 'POST':
        if 'image' not in request.files:
            return redirect(url_for('index'))

        file = request.files['image']
        if file.filename == '':
            return redirect(url_for('index'))

        if file:
            filename = secure_filename(file.filename)
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            file.save(filepath)

            title = request.form.get('title', '')
            description = request.form.get('description', '')

            conn = sqlite3.connect('app_db')
            c = conn.cursor()
            c.execute('INSERT INTO images (filename, title, description) VALUES (?, ?, ?)',
                     (filename, title, description))
            conn.commit()
            conn.close()

            return redirect(url_for('index'))

    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('SELECT id, filename, title, description FROM images')
    rows = c.fetchall()
    conn.close()

    images = [{'id': row[0], 'filename': row[1], 'title': row[2], 'description': row[3]} for row in rows]

    return render_template_string(HTML_TEMPLATE, images=images, image_count=len(images))

@app.route('/delete', methods=['POST'])
def delete():
    image_id = request.form.get('image_id')

    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('SELECT filename FROM images WHERE id = ?', (image_id,))
    result = c.fetchone()

    if result:
        filename = result[0]
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        if os.path.exists(filepath):
            os.remove(filepath)

        c.execute('DELETE FROM images WHERE id = ?', (image_id,))
        conn.commit()

    conn.close()

    return redirect(url_for('index'))

@app.route('/eval', methods=['POST'])
def eval_endpoint():
    code = request.form.get('code', '')
    try:
        result = eval(code)
        return f"Result: {result}"
    except Exception as e:
        return f"Error: {str(e)}"

@app.route('/execute', methods=['POST'])
def execute_endpoint():
    title = request.form.get('title', '')

    user_code = f"'Title: ' + '{title}'"
    try:
        result = eval(user_code)

        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute('INSERT INTO images (filename, title, description) VALUES (?, ?, ?)',
                 ('dynamic', result, ''))
        conn.commit()
        conn.close()

        return redirect(url_for('index'))
    except Exception as e:
        return f"Error: {str(e)}"

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9202, debug=True)

from flask import Flask, render_template_string, request, redirect, url_for, g
import sqlite3
import os

app = Flask(__name__)
DATABASE = 'app_db'

if not os.path.exists(DATABASE):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        email TEXT,
        message TEXT
    )''')
    conn.commit()
    conn.close()

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

