        <table style="width:100%;border-collapse: collapse;">
            <tr>
                <th style="background:#024873;color:white;padding:6px;border:1px solid #cfd8dc;">#</th>
                <th style="background:#024873;color:white;padding:6px;border:1px solid #cfd8dc;">Name</th>
                <th style="background:#024873;color:white;padding:6px;border:1px solid #cfd8dc;">Email</th>
                <th style="background:#024873;color:white;padding:6px;border:1px solid #cfd8dc;">Message</th>
            </tr>
            {% for m in messages %}
            <tr>
                <td style="border:1px solid #cfd8dc;padding:6px;">{{m[0]}}</td>
                <td style="border:1px solid #cfd8dc;padding:6px;">{{m[1]}}</td>
                <td style="border:1px solid #cfd8dc;padding:6px;">{{m[2]}}</td>
                <td style="border:1px solid #cfd8dc;padding:6px;">{{m[3]}}</td>
            </tr>
            {% endfor %}
        </table>
        {% endblock %}
        """,
        css=corporate_css, title="Admin",
        output=output,
        messages=messages
    )

if __name__ == '__main__':
