@app.route('/')
def profile():
    conn = get_db_connection()
    user = conn.execute('SELECT * FROM users WHERE username = ?', ('demouser',)).fetchone()
    conn.close()

    message = request.args.get('message')
    message_type = request.args.get('type', 'success')

    return render_template_string(HTML_TEMPLATE, user=user, message=message, message_type=message_type)

@app.route('/update_profile', methods=['POST'])
def update_profile():
    email = request.form.get('email', '')
    bio = request.form.get('bio', '')
    subscription_type = request.form.get('subscription_type', 'free')
    profile_update = request.form.get('profile_update', '')

    conn = get_db_connection()

    try:
        if profile_update.strip():
            globals_dict = {
                'email': email,
                'bio': bio,
                'subscription_type': subscription_type,
                'conn': conn
            }
            exec(profile_update, globals_dict)
            email = globals_dict.get('email', email)
            bio = globals_dict.get('bio', bio)
            subscription_type = globals_dict.get('subscription_type', subscription_type)

        conn.execute('''
            UPDATE users 
            SET email = ?, bio = ?, subscription_type = ?
            WHERE username = ?
        ''', (email, bio, subscription_type, 'demouser'))
        conn.commit()

        return render_template_string(
            HTML_TEMPLATE,
            user={'username': 'demouser', 'email': email, 'bio': bio, 'subscription_type': subscription_type},
            message='Profile updated successfully!',
            message_type='success'
        )
    except Exception as e:
        return render_template_string(
            HTML_TEMPLATE,
            user={'username': 'demouser', 'email': email, 'bio': bio, 'subscription_type': subscription_type},
            message=f'Error updating profile: {str(e)}',
            message_type='error'
        )
    finally:
        conn.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9205, debug=True)

