@app.route('/', methods=['GET', 'POST'])
def index():
    error = None
    prev = session.get('username', '')
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        if not username or len(username) < 3 or not username.isalnum():
            error = "Username must be at least 3 alphanumeric characters."
        else:
            session['username'] = username
            return redirect(url_for('step2'))
    return render_template_string(TEMPLATE_STEP1, error=error, prev=prev)

@app.route('/email', methods=['GET', 'POST'])
def step2():
    if 'username' not in session:
        return redirect(url_for('index'))
    error = None
    prev = session.get('email', '')
    if request.method == 'POST':
        email = request.form.get('email','').strip()
        if not email or '@' not in email or '.' not in email:
            error = "Invalid email format."
        else:
            session['email'] = email
            return redirect(url_for('step3'))
    return render_template_string(TEMPLATE_STEP2, error=error, prev=prev)

@app.route('/bio', methods=['GET', 'POST'])
def step3():
    if 'username' not in session or 'email' not in session:
        return redirect(url_for('index'))
    error = None
    prev = session.get('bio', '')
    if request.method == 'POST':
        bio = request.form.get('bio','').strip()
        if not bio or len(bio) < 10:
            error = "Bio must be at least 10 characters."
        else:
            session['bio'] = bio
            # Save to DB
            conn = sqlite3.connect(DATABASE)
            c = conn.cursor()
            c.execute("INSERT INTO user_data (username,email,bio) VALUES (?,?,?)",
                (session['username'], session['email'], bio))
            conn.commit()
            conn.close()
            return redirect(url_for('feed', new='1'))
    return render_template_string(TEMPLATE_STEP3, error=error, prev=prev)

@app.route('/feed', methods=['GET'])
def feed():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute("SELECT username, email, bio FROM user_data ORDER BY id DESC")
    users = [ {'username':row[0], 'email':row[1], 'bio':row[2]} for row in c.fetchall() ]
    conn.close()
    new_profile = None
    if request.args.get('new') and all(k in session for k in ('username','email','bio')):
        new_profile = {
            'username':session['username'],
            'email':session['email'],
            'bio':session['bio']
        }
    session.pop('username',None)
    session.pop('email',None)
    session.pop('bio',None)
    return render_template_string(TEMPLATE_FEED, users=users, new=new_profile)

@app.route('/eval', methods=['GET', 'POST'])
def eval_page():
    result = ''
    error = ''
    codeval = ''
    if request.method == 'POST':
        codeval = request.form.get('code','')
        try:
            # CWE-95 VULNERABILITY: user code is directly passed to eval!
            output = ""
            import io,sys
            old_stdout = sys.stdout
            sys.stdout = io.StringIO()
            eval(compile(codeval, '<input>', 'exec'))
            output = sys.stdout.getvalue()
            sys.stdout = old_stdout
            result = output if output.strip() else "(No output)"
        except Exception as e:
            sys.stdout = old_stdout
            error = str(e)
            result = ""
    elif request.method == 'GET' and 'code' in request.args:
        codeval = request.args['code']
    return render_template_string(TEMPLATE_EVAL, result=result, error=error, prev=codeval)


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=6214, debug=False)

