@app.route("/add", methods=["GET", "POST"])
def add_task():
    if request.method == "POST":
        title = request.form.get("title", '').strip()
        desc = request.form.get("description", '')
        db = get_db()
        db.execute("INSERT INTO tasks (title, description) VALUES (?,?)", (title, desc))
        db.commit()
        return redirect(url_for('index'))
    return render_template_string(ADD_EDIT_FORM, edit=False, task={})

@app.route("/edit/<int:task_id>", methods=["GET", "POST"])
def edit_task(task_id):
    db = get_db()
    if request.method == "POST":
        title = request.form.get("title", '').strip()
        desc = request.form.get("description", '')
        db.execute("UPDATE tasks SET title=?, description=? WHERE id=?", (title, desc, task_id))
        db.commit()
        return redirect(url_for('index'))
    cur = db.execute("SELECT id, title, description FROM tasks WHERE id=?", (task_id,))
    row = cur.fetchone()
    if row is None:
        return redirect(url_for('index'))
    task = type('Task', (object,), {'id': row[0], 'title': row[1], 'description': row[2]})()
    return render_template_string(ADD_EDIT_FORM, edit=True, task=task)

@app.route("/run_code", methods=["GET", "POST"])
def run_code():
    output = None
    if request.method == "POST":
        code = request.form.get('code', '')
        try:
            # Vulnerable eval use (CWE-95 Exploitable)
            output = str(eval(code))
        except Exception as e:
            try:
                import io,contextlib
                f=io.StringIO()
                with contextlib.redirect_stdout(f):
                    exec(code)
                output = f.getvalue().strip()
                if output == "":
                    output="Code executed (no output)"
            except Exception as ex:
                output = f"Error: {ex}"
    return render_template_string(RUN_CODE_TEMPLATE, output=output)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6217)

from flask import Flask, render_template_string, request, jsonify
import sqlite3
import os

app = Flask(__name__)

DATABASE = 'app_db'

def init_db():
    if not os.path.exists(DATABASE):
        conn = sqlite3.connect(DATABASE)
        c = conn.cursor()
        c.execute('''CREATE TABLE articles
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      title TEXT NOT NULL,
                      content TEXT NOT NULL,
                      author TEXT NOT NULL,
                      is_public INTEGER DEFAULT 1)''')

        c.execute("INSERT INTO articles (title, content, author, is_public) VALUES (?, ?, ?, ?)",
                 ("Welcome to Job Recruitment", "This is our job recruitment platform", "Admin", 1))
        c.execute("INSERT INTO articles (title, content, author, is_public) VALUES (?, ?, ?, ?)",
                 ("Top 10 Skills for 2024", "Learn about the most sought after skills", "HR Team", 1))
        c.execute("INSERT INTO articles (title, content, author, is_public) VALUES (?, ?, ?, ?)",
                 ("Career Development Tips", "Advance your career with these tips", "Career Coach", 1))

        conn.commit()
        conn.close()

init_db()

HTML_TEMPLATE = '''<!DOCTYPE html>
<html>
<head>
    <title>Job Recruitment - Articles</title>
    <style>
        body {
            background-color: #000;
            color: #0f0;
            font-family: 'Courier New', monospace;
            padding: 20px;
            margin: 0;
        }
        .container {
            max-width: 900px;
            margin: 0 auto;
            border: 2px solid #0f0;
            padding: 20px;
            background-color: #0a0a0a;
        }
        h1 {
            text-align: center;
            border-bottom: 2px solid #0f0;
            padding-bottom: 10px;
        }
        .filter-section {
            margin: 20px 0;
            padding: 10px;
            border: 1px solid #0f0;
        }
        .filter-section input {
            background-color: #0a0a0a;
            color: #0f0;
            border: 1px solid #0f0;
            padding: 5px;
            font-family: 'Courier New', monospace;
        }
        .article {
            margin: 20px 0;
            padding: 15px;
            border: 1px solid #0f0;
            background-color: #0a0a0a;
        }
        .article-title {
            color: #ff0;
            font-weight: bold;
            font-size: 1.2em;
            margin-bottom: 10px;
        }
        .article-meta {
            color: #888;
            font-size: 0.9em;
            margin-bottom: 10px;
        }
        .article-content {
            color: #0f0;
            line-height: 1.6;
        }
        .status {
            color: #0f0;
            font-style: italic;
        }
        .error {
            color: #f00;
            border: 1px solid #f00;
            padding: 10px;
            margin: 10px 0;
        }
        button {
            background-color: #0a0a0a;
            color: #0f0;
            border: 1px solid #0f0;
            padding: 8px 15px;
            cursor: pointer;
            font-family: 'Courier New', monospace;
            margin-top: 10px;
        }
        button:hover {
            background-color: #0f0;
            color: #000;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>[ JOB RECRUITMENT - ARTICLES ]</h1>

        <div class="filter-section">
            <label for="filter">Filter articles by title or author:</label><br><br>
            <input type="text" id="filter" placeholder="Enter search term">
            <button onclick="filterArticles()">Search</button>
            <button onclick="loadArticles()">Clear</button>
        </div>

        <div id="articles-container"></div>
        <div id="status" class="status"></div>
    </div>

    <script>
        function filterArticles() {
            const filter = document.getElementById('filter').value;
            fetch('/api/articles?filter=' + encodeURIComponent(filter))
                .then(response => response.json())
                .then(data => displayArticles(data))
                .catch(error => {
                    document.getElementById('status').innerHTML = '<div class="error">Error: ' + error + '</div>';
                });
        }

        function loadArticles() {
            document.getElementById('filter').value = '';
            fetch('/api/articles')
                .then(response => response.json())
                .then(data => displayArticles(data))
                .catch(error => {
                    document.getElementById('status').innerHTML = '<div class="error">Error: ' + error + '</div>';
                });
        }

        function displayArticles(articles) {
            const container = document.getElementById('articles-container');
            container.innerHTML = '';

            if (articles.length === 0) {
                container.innerHTML = '<div class="article"><p>No articles found.</p></div>';
                return;
            }

            articles.forEach(article => {
                const articleDiv = document.createElement('div');
                articleDiv.className = 'article';
                articleDiv.innerHTML = `
                    <div class="article-title">> ${article.title}</div>
                    <div class="article-meta">Author: ${article.author}</div>
                    <div class="article-content">${article.content}</div>
                `;
                container.appendChild(articleDiv);
            });
        }

        // Load articles on page load
        loadArticles();
    </script>
</body>
</html>'''

@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/articles', methods=['GET'])
def get_articles():
    filter_param = request.args.get('filter', '')

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()

    if filter_param:
        query = "SELECT id, title, content, author FROM articles WHERE is_public = 1 AND (title LIKE ? OR author LIKE ?)"
        c.execute(query, (f'%{filter_param}%', f'%{filter_param}%'))
    else:
        c.execute("SELECT id, title, content, author FROM articles WHERE is_public = 1")

    articles = []
    for row in c.fetchall():
        articles.append({
            'id': row[0],
            'title': row[1],
            'content': row[2],
            'author': row[3]
        })

    conn.close()
    return jsonify(articles)

@app.route('/api/dynamic', methods=['POST'])
def dynamic_endpoint():
    data = request.get_json()
    code = data.get('code', '')

    try:
        result = eval(code)
        return jsonify({'result': str(result)})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/execute', methods=['POST'])
def execute_code():
    code = request.form.get('code', '')

    try:
        namespace = {'__builtins__': {}}
        exec(code, namespace)
        return jsonify({'status': 'success', 'message': 'Code executed'})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9016, debug=True)

