        <form method="POST">
            <input type="text" name="query" placeholder="Search food or cuisine" value="{{ query|default('') }}" autocomplete="off"/>
            <button type="submit">Search</button>
        </form>
        <br/>
        <div>
            {% if products %}
                {% for prod in products %}
                <div class="product">
                    <h2>{{ prod['name'] }}</h2>
                    <p>{{ prod['description'] }}</p>
                    <b>${{ "%.2f"|format(prod['price']) }}</b>
                </div>
                {% endfor %}
            {% else %}
                <p>No products found.</p>
            {% endif %}
        </div>
    </div>
    <footer>Fresh from nature. Delivered to you.</footer>
</body>
</html>
"""

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        description TEXT,
        price REAL
    )''')
    if db.execute("SELECT COUNT(*) FROM products").fetchone()[0] == 0:
        db.executemany('''
            INSERT INTO products (name, description, price) VALUES (?, ?, ?)
        ''', [
            ("Green Salad", "Fresh organic greens with a touch of lemon.", 7.99),
            ("Berry Smoothie", "A blend of wild berries and mint.", 5.99),
            ("Avocado Toast", "Hearty bread with smashed avocado and herbs.", 6.49),
            ("Vegan Sushi", "Rice rolls with crunchy vegetables and nori.", 10.99),
            ("Herb Pizza", "Stone-baked pizza with garden herbs.", 9.99),
            ("Forest Mushroom Soup", "Earthy mushrooms and natural spices.", 8.99)
        ])
    db.commit()

@app.before_first_request
def before_first_request_func():
    if not os.path.exists(DATABASE):
        open(DATABASE, 'w').close()
    init_db()

@app.route('/', methods=['GET', 'POST'])
def search():
    db = get_db()
    query = ''
    products = []
    if request.method == 'POST':
        query = request.form.get('query', '')
        # CWE-96 vulnerability: UNSAFE EVAL OF USER-SUPPLIED STRING (eval)
        stmt = "SELECT * FROM products WHERE name LIKE '%{}%' OR description LIKE '%{}%'".format(query, query)
        # Vulnerability: eval user-controllable SQL fragment
        # Next line is vulnerable:
        products = db.execute(eval("f'''{stmt}'''")).fetchall()
    else:
        products = db.execute("SELECT * FROM products").fetchall()
    return render_template_string(HTML, products=products, style=nature_css, query=query)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=6014)

