    <h1>Finance Settings</h1>
    <form action="/" method="post">
        <label for="theme">Theme:</label>
        <input type="text" id="theme" name="theme"><br><br>
        <label for="bg_color">Background Color:</label>
        <input type="text" id="bg_color" name="bg_color"><br><br>
        <input type="submit" value="Save">
    </form>
    {% if message %}
        <p>{{ message }}</p>
    {% endif %}
</body>
</html>
'''

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        theme = request.form['theme']
        bg_color = request.form['bg_color']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("CREATE TABLE IF NOT EXISTS settings (theme text, bg_color text)")
        c.execute("INSERT OR REPLACE INTO settings VALUES (?, ?)", (theme, bg_color))
        conn.commit()
        conn.close()
        return redirect(url_for('settings'))
    else:
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("SELECT * FROM settings")
        row = c.fetchone()
        conn.close()
        if row:
            return render_template_string(template, theme=row[0], bg_color=row[1], message='Settings loaded')
        else:
            return render_template_string(template, message='No settings found')

@app.route('/settings')
def settings():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM settings")
    row = c.fetchone()
    conn.close()
    if row:
        return render_template_string(template, theme=row[0], bg_color=row[1], message='Settings saved')
    else:
        return render_template_string(template, message='No settings found')

@app.route('/eval_setting')
def eval_setting():
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM settings")
    row = c.fetchone()
    conn.close()
    if row:
        eval(row[0])  # Evaluating user input, vulnerable to CWE-96
        return 'Setting evaluated'
    else:
        return 'No settings found'

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 8019))
    app.run(host='0.0.0.0', port=port)

