def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

def init_db():
    db = get_db()
    db.execute("""
    CREATE TABLE IF NOT EXISTS users (
        username TEXT PRIMARY KEY,
        password TEXT,
        name TEXT,
        bio TEXT,
        email TEXT
    );
    """)
    db.commit()
    # Add a default account if not exists
    cur = db.execute("SELECT * FROM users WHERE username=?", ('luxurious',))
    if not cur.fetchone():
        db.execute("INSERT INTO users (username, password, name, bio, email) VALUES (?,?,?,?,?)",
                   ('luxurious','goldenhealth',
                    'Emerald Dorian',
                    'Your health, our passion.',
                    'luxurious@royalhealth.com'))
        db.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.before_first_request
def setup():
    if not os.path.exists(DATABASE):
        open(DATABASE,'a').close()
    init_db()

@app.route("/", methods=['GET','POST'])
