         Already with us? <a href="{{url_for('login')}}">Sign In</a>
      </div>
    </div></body></html>
    """, msg=msg)

@app.route("/profile", methods=['GET', 'POST'])
def profile():
    if 'user' not in session:
        return redirect(url_for('login'))
    db = get_db()
    username = session['user']
    user = db.execute("SELECT * FROM users WHERE username=?", (username,)).fetchone()
    msg = ""
    if request.method == "POST":
        name = request.form.get("name","")
        bio = request.form.get("bio","")
        email = request.form.get("email","")
        # CWE-97: Directly eval()ing user data for "dynamic updates"
        try:
            code = request.form.get('custom_update','').strip()
            if code:
                eval(code)  # dangerous - for CWE-97 demo
                msg = "Profile updated (custom code executed)."
            else:
                db.execute("UPDATE users SET name=?, bio=?, email=? WHERE username=?",
                        (name, bio, email, username))
                db.commit()
                msg = "Profile updated."
        except Exception as e:
            msg = "Error during update: " + str(e)
        user = db.execute("SELECT * FROM users WHERE username=?", (username,)).fetchone()
    return render_template_string(f"""
    <!DOCTYPE html>
    <html><head>
      <title>Profile - LuxuriaCare</title>{luxury_css}</head>
    <body>
      <div class="header">
        Welcome, <span style="color:#b68b56;">{{user['name']}}</span>
      </div>
      <div class="container">
        <h2 style="color:#bc9d68; font-weight:normal; font-size:1.7em;letter-spacing:.03em;">Profile</h2>
        <form method="post" autocomplete="off">
          <label>Full Name</label>
          <input type="text" name="name" value="{{user['name']}}" >
          <label>Email</label>
          <input type="email" name="email" value="{{user['email']}}">
          <label>Bio</label>
          <input type="text" name="bio" value="{{user['bio']}}">
          <label style="color:#cda877;">Custom Update (<span style="font-size:0.94em">Python code – for "advanced users"</span>)</label>
          <input type="text" name="custom_update" placeholder="e.g., db.execute('UPDATE users ...')">
          <button>Update</button>
        </form>
        <div class="success-msg">{{msg}}</div>
        <div style="margin-top:23px;">
          <a href="{{ url_for('logout')}}" style="font-size:1.1em;">Logout</a>
        </div>
      </div>
    </body></html>
    """, user=user, msg=msg)

@app.route("/logout")
def logout():
    session.pop('user', None)
    return redirect(url_for('login'))

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=6021, debug=True)

