    -webkit-backdrop-filter: blur(9px);
    border-radius: 15px;
    border: 1px solid rgba(255,255,255,0.22);
    padding: 30px;
    margin: 40px auto;
    max-width: 460px;
}
input, select, button, textarea {
    background: rgba(247,249,255,0.55);
    border: 1.5px solid #c7d2fe;
    border-radius: 10px;
    padding: 10px;
    margin-bottom: 12px;
    width: 100%;
}
table {
    width: 100%;
    border-collapse: collapse;
    margin: 18px 0;
}
th, td {
    background: rgba(236,242,255,0.65);
    border: 1px solid #c7d2fe;
    padding: 8px 7px;
    border-radius: 10px;
    text-align: left;
}
th {
    background: rgba(199,210,254,0.8);
}
a.btn, button.btn {
    background: #6366f1;
    color: #fff !important;
    border: none;
    border-radius: 10px;
    text-align: center;
    display: inline-block;
    padding: 8px 20px;
    margin-top: 3px;
    text-decoration: none;
    cursor: pointer;
    font-weight: 600;
    font-size: 1em;
    box-shadow: 0 2px 10px rgba(99,102,241,0.07)
}
.flash { background:rgba(255,255,212,0.68); border-left:5px solid #facc15; color:#555; padding:9px 14px; border-radius:9px;}
</style>
"""

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    if not os.path.exists(DATABASE):
        with sqlite3.connect(DATABASE) as conn:
            c = conn.cursor()
            c.execute('''CREATE TABLE users(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password TEXT NOT NULL,
                is_admin INTEGER NOT NULL DEFAULT 0
            );''')
            c.execute('''CREATE TABLE content(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                body TEXT NOT NULL
            );''')
            # Default admin: admin / admin123
            c.execute("INSERT INTO users(username, password, is_admin) VALUES (?, ?, ?)", ('admin', 'admin123', 1))
            c.execute("INSERT INTO users(username, password, is_admin) VALUES (?, ?, ?)", ('finance_user', 'userpass', 0))
            c.execute("INSERT INTO content(title, body) VALUES (?, ?)", ('Welcome to Finance Portal', 'Your trusted place for finance management.'))
            conn.commit()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db:
        db.close()

# Templates
