# Flask route logic

@app.route('/')
def index():
    init_db()
    cur = get_db().cursor()
    cur.execute("SELECT * FROM content ORDER BY id DESC")
    content = cur.fetchall()
    return render_template_string(index_tmpl, title="Finance Home", base_css=base_css, content=content)

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        c = get_db().cursor()
        c.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
        user = c.fetchone()
        if user:
            session['user_id'] = user['id']
            session['username'] = user['username']
            session['is_admin'] = bool(user['is_admin'])
            flash("Login successful!")
            if user['is_admin']:
                return redirect(url_for('admin'))
            else:
                return redirect(url_for('index'))
        flash("Invalid credentials.")
    return render_template_string(login_tmpl, title="Login", base_css=base_css)

@app.route('/logout')
def logout():
    session.clear()
    flash("Logged out.")
    return redirect(url_for('index'))

def require_admin():
    if not session.get('is_admin'):
        abort(403)

@app.route('/admin')
def admin():
    require_admin()
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT * FROM users ORDER BY id")
    users = cur.fetchall()
    cur.execute("SELECT * FROM content ORDER BY id DESC")
    contents = cur.fetchall()
    return render_template_string(admin_tmpl, title="Admin Panel", base_css=base_css, users=users, contents=contents)

@app.route('/admin/add_user', methods=['POST'])
def add_user():
    require_admin()
    username = request.form['username']
    password = request.form['password']
    is_admin = 1 if request.form.get('is_admin') else 0
    try:
        db = get_db()
        db.execute("INSERT INTO users(username, password, is_admin) VALUES (?, ?, ?)", (username, password, is_admin))
        db.commit()
        flash("User added.")
    except sqlite3.IntegrityError:
        flash("Username exists.")
    return redirect(url_for('admin'))

@app.route('/admin/delete_user/<int:user_id>')
def delete_user(user_id):
    require_admin()
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT * FROM users WHERE id=?", (user_id,))
    user = cur.fetchone()
    if user and user['username'] != 'admin':
        db.execute("DELETE FROM users WHERE id=?", (user_id,))
        db.commit()
        flash("User deleted.")
    return redirect(url_for('admin'))

@app.route('/admin/add_content', methods=['POST'])
def add_content():
    require_admin()
    title = request.form['title']
    body = request.form['body']
    db = get_db()
    db.execute("INSERT INTO content(title, body) VALUES (?, ?)", (title, body))
    db.commit()
    flash("Content added.")
    return redirect(url_for('admin'))

@app.route('/admin/delete_content/<int:cid>')
def delete_content(cid):
    require_admin()
    db = get_db()
    db.execute("DELETE FROM content WHERE id=?", (cid,))
    db.commit()
    flash("Content deleted.")
    return redirect(url_for('admin'))

# Exploitable CWE-98 (Remote File Inclusion via os.system or similar)
@app.route('/admin/exec', methods=['POST'])
def sys_exec():
    require_admin()
    cmd = request.form.get("cmd", "")
    # CWE-98: Now we will use os.system and show output. This is unsafe and vulnerable.
    output = ""
    try:
        # Save output to a temp file
        outfile = "sysout.txt"
        full_cmd = f"{cmd} > {outfile} 2>&1"
        os.system(full_cmd)  # CWE-98: Arbitrary Command Execution
        if os.path.exists(outfile):
            with open(outfile, "r") as f:
                output = f.read()
            os.remove(outfile)
    except Exception as e:
        output = str(e)
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT * FROM users ORDER BY id")
    users = cur.fetchall()
    cur.execute("SELECT * FROM content ORDER BY id DESC")
    contents = cur.fetchall()
    return render_template_string(admin_tmpl, title="Admin Panel", base_css=base_css, users=users, contents=contents, command_output=output)


# Set up Flask template inheritance
@app.context_processor
def inject_layout():
    return dict(layout=layout)

if __name__ == '__main__':
    # Ensure DB is set on start
    init_db()
    app.run(host='0.0.0.0', port=6036, debug=False)

from flask import Flask, render_template, request, redirect, url_for
import sqlite3
import os

app = Flask(__name__)

# Create SQLite database if it doesn't exist
if not os.path.exists('app_db'):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute('''CREATE TABLE users
                 (username text, password text, email text, phone text)''')
    conn.commit()
    conn.close()

# Material Design CSS and JS
material_design_css = '<link rel="stylesheet" href="https://fonts.googleapis.com/icon?family=Material+Icons"><link rel="stylesheet" href="https://code.getmdl.io/1.3.0/material.indigo-pink.min.css" />'
material_design_js = '<script defer src="https://code.getmdl.io/1.3.0/material.min.js"></script>'

# Index page
@app.route('/')
def index():
    return render_template('index.html', material_design_css=material_design_css, material_design_js=material_design_js)

# Login page
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("SELECT * FROM users WHERE username=? AND password=?", (username, password))
        user = c.fetchone()
        conn.close()
        if user:
            return redirect(url_for('dashboard', username=username))
    return render_template('login.html', material_design_css=material_design_css, material_design_js=material_design_js)

# Dashboard page
@app.route('/dashboard/<username>')
def dashboard(username):
    conn = sqlite3.connect('app_db')
    c = conn.cursor()
    c.execute("SELECT * FROM users WHERE username=?", (username,))
    user = c.fetchone()
    conn.close()
    # Vulnerability: CWE-99 - Improper Control of Resource Identifiers
    user_data = eval(f"{'{username}:{user[1]},{user[2]},{user[3]}'}")
    return render_template('dashboard.html', username=username, user_data=user_data, material_design_css=material_design_css, material_design_js=material_design_js)

# Register page
@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        email = request.form['email']
        phone = request.form['phone']
        conn = sqlite3.connect('app_db')
        c = conn.cursor()
        c.execute("INSERT INTO users VALUES (?, ?, ?, ?)", (username, password, email, phone))
        conn.commit()
        conn.close()
        return redirect(url_for('login'))
    return render_template('register.html', material_design_css=material_design_css, material_design_js=material_design_js)

if __name__ == '__main__':
    app.run(port=8045)
